{"command":"mkdir -p /workspace/src && cd /workspace/src && cat > config.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// OptType describes the kind of a configuration option.
type OptType int

const (
	OptString OptType = iota
	OptList
	OptBool
	OptInt
	OptEnum
)

// ConfigOption holds the static description and the runtime value of one option.
type ConfigOption struct {
	Name        string
	Section     string
	Type        OptType
	Default     string
	DefaultList []string
	Min, Max    int
	EnumValues  []string
	Dep         string
	Doc         []string

	// runtime state
	Value       string   // raw string value for string/bool/int/enum
	List        []string // value for list options
	UserComment string
	set         bool
	boolVal     bool
	intVal      int
}

// Obsolete tags: produce an "has become obsolete" warning.
var obsoleteTags = map[string]bool{
	"USE_WINDOWS_ENCODING": true, "DETAILS_AT_TOP": true, "SYMBOL_CACHE_SIZE": true,
	"SHOW_DIRECTORIES": true, "HTML_ALIGN_MEMBERS": true, "XML_SCHEMA": true, "XML_DTD": true,
	"USE_INLINE_TREES": true, "MAX_DOT_GRAPH_WIDTH": true, "MAX_DOT_GRAPH_HEIGHT": true,
	"CGI_NAME": true, "CGI_URL": true, "DOC_URL": true, "DOC_ABSPATH": true, "BIN_ABSPATH": true,
	"EXT_DOC_PATHS": true, "MSCGEN_PATH": true, "PERL_PATH": true, "DOT_TRANSPARENT": true,
	"TCL_SUBST": true, "FORMULA_TRANSPARENT": true, "LATEX_SOURCE_CODE": true, "RTF_SOURCE_CODE": true,
	"DOCBOOK_PROGRAMLISTING": true, "CLASS_DIAGRAMS": true, "HTML_TIMESTAMP": true, "LATEX_TIMESTAMP": true,
	"COLS_IN_ALPHA_INDEX": true, "DOT_FONTNAME": true, "DOT_FONTSIZE": true,
}

// Disabled tags: options of features not compiled in.
var disabledTags = map[string]bool{
	"CLANG_ASSISTED_PARSING": true, "CLANG_ADD_INC_PATHS": true, "CLANG_OPTIONS": true, "CLANG_DATABASE_PATH": true,
}

// Config is the full set of options.
type Config struct {
	opts       []*ConfigOption
	byName     map[string]*ConfigOption
	includeDir []string
	// obsolete/compat state
	classDiagramsSet bool
	classDiagrams    string
	htmlTimestamp    string
	latexTimestamp   string
	htmlTimestampSet bool
	latexTimestampSet bool
	trailingComment  string
	updateMode       bool
	compareMode      bool
	noEnv            bool
	fileName         string
}

func newConfig() *Config {
	c := &Config{byName: map[string]*ConfigOption{}}
	for _, o := range configOptions {
		n := *o
		n.List = append([]string(nil), o.DefaultList...)
		if n.Type != OptList {
			n.Value = o.Default
		}
		c.opts = append(c.opts, &n)
		c.byName[n.Name] = &n
	}
	return c
}

func (c *Config) get(name string) *ConfigOption {
	o := c.byName[name]
	if o == nil {
		panic("unknown option " + name)
	}
	return o
}

func (c *Config) Str(name string) string  { return c.get(name).Value }
func (c *Config) List(name string) []string { return c.get(name).List }
func (c *Config) Bool(name string) bool    { return c.get(name).boolVal }
func (c *Config) Int(name string) int      { return c.get(name).intVal }
func (c *Config) Enum(name string) string  { return c.get(name).Value }
func (c *Config) SetBool(name string, v bool) {
	o := c.get(name)
	o.boolVal = v
	if v {
		o.Value = "YES"
	} else {
		o.Value = "NO"
	}
}
func (c *Config) SetStr(name, v string)  { c.get(name).Value = v }
func (c *Config) SetInt(name string, v int) { o := c.get(name); o.intVal = v; o.Value = strconv.Itoa(v) }
func (c *Config) SetList(name string, v []string) { c.get(name).List = v }

// ---------------------------------------------------------------------------
// Parsing

type cfgLexer struct {
	cfg      *Config
	data     []byte
	pos      int
	line     int
	fileName string
}

func configWarn(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "warning: "+format+"\n", args...)
}

func configErr(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "error: "+format+"\n", args...)
}

// parseFile reads and parses a configuration file. Returns false on fatal error.
func (c *Config) parseFile(fileName string, update bool) bool {
	var data []byte
	var err error
	if fileName == "-" {
		data, err = readAllStdin()
	} else {
		data, err = os.ReadFile(fileName)
	}
	if err != nil {
		return false
	}
	c.fileName = fileName
	c.updateMode = update
	return c.parseData(data, fileName)
}

func (c *Config) parseData(data []byte, fileName string) bool {
	lx := &cfgLexer{cfg: c, data: data, line: 1, fileName: fileName}
	return lx.run()
}

func isTagChar(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || b == '_'
}

func (lx *cfgLexer) peek(off int) byte {
	if lx.pos+off < len(lx.data) {
		return lx.data[lx.pos+off]
	}
	return 0
}

func (lx *cfgLexer) atEnd() bool { return lx.pos >= len(lx.data) }

// skipToEOL skips everything up to (not including) the newline.
func (lx *cfgLexer) skipToEOL() {
	for !lx.atEnd() && lx.data[lx.pos] != '\n' {
		lx.pos++
	}
}

func (lx *cfgLexer) run() bool {
	c := lx.cfg
	for !lx.atEnd() {
		ch := lx.data[lx.pos]
		switch {
		case ch == '\n':
			lx.line++
			lx.pos++
		case ch == ' ' || ch == '\t' || ch == '\r':
			lx.pos++
		case ch == '#' && lx.peek(1) == '#':
			start := lx.pos
			lx.skipToEOL()
			text := string(lx.data[start:lx.pos])
			if !lx.atEnd() {
				text += "\n"
				lx.pos++
				lx.line++
			}
			c.trailingComment += text
		case ch == '#':
			lx.skipToEOL()
		case ch == '@' && strings.HasPrefix(string(lx.data[lx.pos:min(lx.pos+13, len(lx.data))]), "@INCLUDE_PATH") && lx.matchAssign(13) == 1:
			lx.pos += lx.assignLen
			var lst []string
			lx.readList(&lst, "@INCLUDE_PATH", false)
			c.includeDir = append(c.includeDir, lst...)
		case ch == '@' && strings.HasPrefix(string(lx.data[lx.pos:min(lx.pos+8, len(lx.data))]), "@INCLUDE") && lx.matchAssign(8) == 1:
			lx.pos += lx.assignLen
			name, _ := lx.readString("@INCLUDE")
			if !lx.doInclude(name) {
				return false
			}
		case isTagChar(ch):
			start := lx.pos
			for !lx.atEnd() && isTagChar(lx.data[lx.pos]) {
				lx.pos++
			}
			name := string(lx.data[start:lx.pos])
			kind := lx.matchAssign(0)
			if kind == 0 {
				configWarn("ignoring unknown tag '%s' at line %d, file %s", name, lx.line, lx.fileName)
				continue
			}
			lx.pos += lx.assignLen
			lx.handleTag(name, kind == 2)
		default:
			configWarn("ignoring unknown character '%c' at line %d, file %s", ch, lx.line, lx.fileName)
			lx.pos++
		}
	}
	return true
}

// matchAssign checks whether, after `off` bytes, optional blanks followed by '=' (1) or '+=' (2) follow.
// Sets lx.assignLen to the total length consumed (from lx.pos).
func (lx *cfgLexer) matchAssign(off int) int {
	p := lx.pos + off
	for p < len(lx.data) && (lx.data[p] == ' ' || lx.data[p] == '\t') {
		p++
	}
	if p < len(lx.data) && lx.data[p] == '=' {
		lx.assignLen = p + 1 - lx.pos
		return 1
	}
	if p+1 < len(lx.data) && lx.data[p] == '+' && lx.data[p+1] == '=' {
		lx.assignLen = p + 2 - lx.pos
		return 2
	}
	return 0
}

func (lx *cfgLexer) handleTag(name string, append bool) {
	c := lx.cfg
	opt := c.byName[name]
	if opt == nil {
		if obsoleteTags[name] {
			if c.updateMode {
				configWarn("Tag '%s' at line %d of file '%s' has become obsolete.\n         This tag has been removed.", name, lx.line, lx.fileName)
			} else {
				configWarn("Tag '%s' at line %d of file '%s' has become obsolete.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\"", name, lx.line, lx.fileName)
			}
			// some obsolete options are still interpreted
			val, _ := lx.readString(name)
			switch name {
			case "CLASS_DIAGRAMS":
				c.classDiagramsSet = true
				c.classDiagrams = val
			case "HTML_TIMESTAMP":
				c.htmlTimestampSet = true
				c.htmlTimestamp = val
			case "LATEX_TIMESTAMP":
				c.latexTimestampSet = true
				c.latexTimestamp = val
			}
			return
		}
		if disabledTags[name] {
			if c.updateMode {
				configWarn("Tag '%s' at line %d of file '%s' belongs to an option that was not enabled at compile time.\n         This tag has been removed.", name, lx.line, lx.fileName)
			} else {
				configWarn("Tag '%s' at line %d of file '%s' belongs to an option that was not enabled at compile time.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\", or recompile doxygen with this feature enabled.", name, lx.line, lx.fileName)
			}
			lx.skipToEOL()
			return
		}
		if append {
			configWarn("ignoring unsupported tag '%s +=' at line %d, file %s", name, lx.line, lx.fileName)
		} else {
			configWarn("ignoring unsupported tag '%s' at line %d, file %s", name, lx.line, lx.fileName)
		}
		lx.skipToEOL()
		return
	}
	if append && opt.Type != OptList {
		configWarn("operator += not supported for '%s +='. Ignoring line at line %d, file %s", name, lx.line, lx.fileName)
		lx.skipToEOL()
		return
	}
	// attach pending user comments
	if c.trailingComment != "" {
		opt.UserComment += c.trailingComment
		c.trailingComment = ""
	}
	opt.set = true
	if opt.Type == OptList {
		if !append {
			opt.List = nil
		}
		lx.readList(&opt.List, name, true)
		return
	}
	val, _ := lx.readString(name)
	opt.Value = val
	if name == "DOXYFILE_ENCODING" {
		// the configuration file is converted to UTF-8 while reading
		opt.Value = "UTF-8"
	}
}

// readString reads a string value up to the end of the line.
func (lx *cfgLexer) readString(tag string) (string, string) {
	var sb strings.Builder
	var raw strings.Builder
	startLine := lx.line
	_ = startLine
	for !lx.atEnd() {
		ch := lx.data[lx.pos]
		if ch == '\n' {
			break
		}
		if ch == '\r' {
			lx.pos++
			continue
		}
		if ch == '\\' {
			// continuation?
			p := lx.pos + 1
			for p < len(lx.data) && (lx.data[p] == ' ' || lx.data[p] == '\t') {
				p++
			}
			if p < len(lx.data) && lx.data[p] == '\n' {
				lx.pos = p + 1
				lx.line++
				sb.WriteByte(' ')
				raw.WriteByte(' ')
				continue
			}
			if lx.peek(1) == '"' {
				sb.WriteByte('"')
				raw.WriteString("\\\"")
				lx.pos += 2
				continue
			}
			if lx.peek(1) != 0 && lx.peek(1) != '\n' {
				sb.WriteByte('\\')
				sb.WriteByte(lx.peek(1))
				raw.WriteByte('\\')
				raw.WriteByte(lx.peek(1))
				lx.pos += 2
				continue
			}
			sb.WriteByte('\\')
			raw.WriteByte('\\')
			lx.pos++
			continue
		}
		if ch == '#' {
			lx.skipToEOL()
			break
		}
		if ch == '"' {
			raw.WriteByte('"')
			lx.pos++
			for !lx.atEnd() {
				q := lx.data[lx.pos]
				if q == '\n' {
					break
				}
				if q == '\\' && lx.peek(1) == '"' {
					sb.WriteByte('"')
					raw.WriteString("\\\"")
					lx.pos += 2
					continue
				}
				if q == '"' {
					raw.WriteByte('"')
					lx.pos++
					goto next
				}
				sb.WriteByte(q)
				raw.WriteByte(q)
				lx.pos++
			}
			// unterminated: newline ends the string
			break
		}
		sb.WriteByte(ch)
		raw.WriteByte(ch)
		lx.pos++
	next:
	}
	rawStr := strings.TrimSpace(raw.String())
	if !properlyQuoted(rawStr) {
		configWarn("Invalid value for '%s' tag at line %d, file %s: Value '%s' is not properly quoted", tag, lx.line, lx.fileName, rawStr)
	}
	// consume newline
	if !lx.atEnd() && lx.data[lx.pos] == '\n' {
		lx.pos++
		lx.line++
	}
	return sb.String(), rawStr
}

// properlyQuoted checks that unescaped quotes only appear as a matching pair enclosing the value.
func properlyQuoted(raw string) bool {
	var positions []int
	for i := 0; i < len(raw); i++ {
		if raw[i] == '\\' && i+1 < len(raw) {
			i++
			continue
		}
		if raw[i] == '"' {
			positions = append(positions, i)
		}
	}
	if len(positions) == 0 {
		return true
	}
	if len(positions) == 2 && positions[0] == 0 && positions[1] == len(raw)-1 {
		return true
	}
	return false
}

// readList reads a list value up to the end of the line.
func (lx *cfgLexer) readList(list *[]string, tag string, warn bool) {
	var elem strings.Builder
	var raw strings.Builder
	quoted := false
	badSep := false
	unterminated := false
	push := func() {
		if elem.Len() > 0 {
			s := elem.String()
			if quoted && !strings.ContainsAny(s, " \t") {
				s += " "
			}
			*list = append(*list, s)
			elem.Reset()
			quoted = false
		}
	}
	afterQuote := false
	for !lx.atEnd() {
		ch := lx.data[lx.pos]
		if ch == '\n' {
			break
		}
		if ch == '\r' {
			lx.pos++
			continue
		}
		if ch == '\\' {
			p := lx.pos + 1
			for p < len(lx.data) && (lx.data[p] == ' ' || lx.data[p] == '\t') {
				p++
			}
			if p < len(lx.data) && lx.data[p] == '\n' {
				lx.pos = p + 1
				lx.line++
				raw.WriteByte(' ')
				push()
				afterQuote = false
				continue
			}
			if afterQuote {
				badSep = true
				push()
				afterQuote = false
			}
			if lx.peek(1) == '"' {
				elem.WriteByte('"')
				raw.WriteString("\\\"")
				lx.pos += 2
				continue
			}
			if lx.peek(1) != 0 && lx.peek(1) != '\n' {
				elem.WriteByte('\\')
				elem.WriteByte(lx.peek(1))
				raw.WriteByte('\\')
				raw.WriteByte(lx.peek(1))
				lx.pos += 2
				continue
			}
			elem.WriteByte('\\')
			raw.WriteByte('\\')
			lx.pos++
			continue
		}
		if ch == '#' {
			lx.skipToEOL()
			break
		}
		if ch == ' ' || ch == '\t' || ch == ',' {
			raw.WriteByte(ch)
			push()
			afterQuote = false
			lx.pos++
			continue
		}
		if ch == '"' {
			if afterQuote {
				push()
			}
			raw.WriteByte('"')
			lx.pos++
			closed := false
			for !lx.atEnd() {
				q := lx.data[lx.pos]
				if q == '\n' {
					break
				}
				if q == '\\' && lx.peek(1) == '"' {
					elem.WriteByte('"')
					raw.WriteString("\\\"")
					lx.pos += 2
					continue
				}
				if q == '"' {
					raw.WriteByte('"')
					lx.pos++
					closed = true
					break
				}
				elem.WriteByte(q)
				raw.WriteByte(q)
				lx.pos++
			}
			quoted = true
			afterQuote = true
			if !closed {
				unterminated = true
				break
			}
			continue
		}
		if afterQuote {
			badSep = true
			push()
			afterQuote = false
		}
		elem.WriteByte(ch)
		raw.WriteByte(ch)
		lx.pos++
	}
	push()
	rawStr := strings.TrimSpace(raw.String())
	if warn {
		if unterminated {
			configWarn("Invalid value for '%s' tag at line %d, file %s: Values in list '%s' are not properly quoted", tag, lx.line, lx.fileName, rawStr)
		} else if badSep {
			configWarn("Invalid value for '%s' tag at line %d, file %s: Values in list '%s' are not properly space or comma separated", tag, lx.line, lx.fileName, rawStr)
		}
	}
	if !lx.atEnd() && lx.data[lx.pos] == '\n' {
		lx.pos++
		lx.line++
	}
}

func (lx *cfgLexer) doInclude(name string) bool {
	c := lx.cfg
	name = strings.TrimSpace(name)
	var data []byte
	var err error
	found := ""
	if fileExists(name) {
		found = name
	} else {
		for _, d := range c.includeDir {
			p := filepath.Join(d, name)
			if fileExists(p) {
				found = p
				break
			}
		}
	}
	if found == "" {
		configErr("@INCLUDE = %s: not found!", name)
		fmt.Fprintln(os.Stderr, "Exiting...")
		return false
	}
	data, err = os.ReadFile(found)
	if err != nil {
		configErr("@INCLUDE = %s: not found!", name)
		fmt.Fprintln(os.Stderr, "Exiting...")
		return false
	}
	sub := &cfgLexer{cfg: c, data: data, line: 1, fileName: found}
	return sub.run()
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// ---------------------------------------------------------------------------
// Post processing

var envVarRe = regexp.MustCompile(`\$\(([a-z_A-Z0-9.-]+)\)`)
var envVarRe2 = regexp.MustCompile(`\$\(([a-z_A-Z0-9.-]+)\(([a-z_A-Z0-9.-]+)\)\)`)

func substEnvVarsInString(s string) string {
	if s == "" {
		return s
	}
	// CMake style $(ENV{VAR}) is not supported; handle $(VAR) and $(VAR(x))
	s = envVarRe2.ReplaceAllStringFunc(s, func(m string) string {
		sm := envVarRe2.FindStringSubmatch(m)
		return os.Getenv(sm[1])
	})
	s = envVarRe.ReplaceAllStringFunc(s, func(m string) string {
		sm := envVarRe.FindStringSubmatch(m)
		return os.Getenv(sm[1])
	})
	return strings.TrimSpace(s)
}

func substEnvVarsInStrList(sl []string) []string {
	var out []string
	for _, s := range sl {
		wasQuoted := strings.ContainsAny(s, " \t")
		r := substEnvVarsInString(s)
		if !wasQuoted {
			for _, f := range strings.Fields(r) {
				out = append(out, f)
			}
		} else if r != "" {
			out = append(out, r)
		}
	}
	return out
}

func (c *Config) substituteEnvironmentVars() {
	for _, o := range c.opts {
		switch o.Type {
		case OptList:
			o.List = substEnvVarsInStrList(o.List)
		default:
			o.Value = substEnvVarsInString(o.Value)
		}
	}
}

// convertStrToVal converts the string representations of bool/int/enum options into values.
func (o *ConfigOption) convertStrToVal(quiet bool) {
	switch o.Type {
	case OptBool:
		v := strings.TrimSpace(o.Value)
		lv := strings.ToLower(v)
		switch lv {
		case "yes", "true", "1":
			o.boolVal = true
		case "no", "false", "0":
			o.boolVal = false
		case "":
			o.boolVal = o.Default == "YES"
			o.Value = o.Default
		default:
			if !quiet {
				configWarn("argument '%s' for option %s is not a valid boolean value\nUsing the default: %s!", v, o.Name, o.Default)
			}
			o.boolVal = o.Default == "YES"
			o.Value = o.Default
		}
	case OptInt:
		v := strings.TrimSpace(o.Value)
		if v == "" {
			o.intVal, _ = strconv.Atoi(o.Default)
			o.Value = o.Default
			return
		}
		n, err := strconv.Atoi(v)
		if err != nil || n < o.Min || n > o.Max {
			if !quiet {
				configWarn("argument '%s' for option %s is not a valid number in the range [%d..%d]!\nUsing the default: %s!", v, o.Name, o.Min, o.Max, o.Default)
			}
			o.intVal, _ = strconv.Atoi(o.Default)
			o.Value = o.Default
			return
		}
		o.intVal = n
	case OptEnum:
		v := strings.TrimSpace(o.Value)
		if v == "" {
			o.Value = o.Default
			return
		}
		for _, e := range o.EnumValues {
			if strings.EqualFold(e, v) {
				o.Value = e
				return
			}
		}
		if !quiet {
			configWarn("argument '%s' for option %s is not a valid enum value\nUsing the default: %s!", v, o.Name, o.Default)
		}
		o.Value = o.Default
	}
}

// postProcess performs environment substitution and value conversion.
func (c *Config) postProcess(compare bool, noEnv bool) {
	if !noEnv {
		c.substituteEnvironmentVars()
	}
	for _, o := range c.opts {
		if o.Type == OptInt || o.Type == OptEnum {
			o.convertStrToVal(false)
		}
	}
	// handle obsolete options that map onto new ones
	if c.htmlTimestampSet || c.latexTimestampSet {
		v := c.htmlTimestamp
		if !c.htmlTimestampSet {
			v = c.latexTimestamp
		}
		ts := c.get("TIMESTAMP")
		if isTrueStr(v) {
			ts.Value = "YES"
		}
		ts.set = true
	}
	if c.classDiagramsSet {
		if !isTrueStr(c.classDiagrams) {
			configWarn("Changing CLASS_GRAPH option to TEXT because obsolete option CLASS_DIAGRAM was found and set to NO.")
			c.get("CLASS_GRAPH").Value = "TEXT"
		}
	}
	// empty string values get their defaults
	for _, o := range c.opts {
		if o.Type == OptString && strings.TrimSpace(o.Value) == "" && o.Default != "" {
			switch o.Name {
			case "PROJECT_NAME", "OUTPUT_DIRECTORY", "HTML_OUTPUT", "LATEX_OUTPUT", "RTF_OUTPUT", "MAN_OUTPUT", "XML_OUTPUT", "DOCBOOK_OUTPUT", "SQLITE3_OUTPUT", "HTML_FILE_EXTENSION", "LATEX_CMD_NAME", "MAKEINDEX_CMD_NAME", "LATEX_MAKEINDEX_CMD", "WARN_FORMAT", "WARN_LINE_FORMAT", "MAN_EXTENSION", "PERLMOD_MAKEVAR_PREFIX", "INPUT_ENCODING", "DOXYFILE_ENCODING", "FORMULA_MACROFILE", "DOT_PATH", "MATHJAX_RELPATH", "HTML_HEADER", "HTML_FOOTER", "HTML_STYLESHEET":
			}
		}
	}
}

func isTrueStr(v string) bool {
	switch strings.ToLower(strings.TrimSpace(v)) {
	case "yes", "true", "1":
		return true
	}
	return false
}

// ---------------------------------------------------------------------------
// Writing

func writeStringValue(sb *strings.Builder, s string) {
	needsEscaping := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' || c == ',' || c == '\n' || c == '\t' || c == '"' || c == '#' {
			needsEscaping = true
			break
		}
	}
	if needsEscaping {
		sb.WriteByte('"')
		for i := 0; i < len(s); i++ {
			if s[i] == ' ' && i+1 == len(s) {
				break // skip inserted space at the end
			}
			if s[i] == '"' {
				sb.WriteByte('\\')
			}
			sb.WriteByte(s[i])
		}
		sb.WriteByte('"')
	} else {
		sb.WriteString(s)
	}
}

func (o *ConfigOption) writeValue(sb *strings.Builder) {
	fmt.Fprintf(sb, "%-23s=", o.Name)
	switch o.Type {
	case OptList:
		first := true
		for _, v := range o.List {
			if first {
				sb.WriteByte(' ')
			} else {
				sb.WriteString(" \\\n")
				sb.WriteString(strings.Repeat(" ", 25))
			}
			writeStringValue(sb, v)
			first = false
		}
		sb.WriteByte('\n')
	default:
		if o.Value != "" {
			sb.WriteByte(' ')
			writeStringValue(sb, o.Value)
		}
		sb.WriteByte('\n')
	}
}

func (o *ConfigOption) isDefault() bool {
	switch o.Type {
	case OptList:
		if len(o.List) != len(o.DefaultList) {
			return false
		}
		for i := range o.List {
			if o.List[i] != o.DefaultList[i] {
				return false
			}
		}
		return true
	case OptBool:
		return o.boolVal == (o.Default == "YES")
	case OptInt:
		d, _ := strconv.Atoi(o.Default)
		return o.intVal == d
	default:
		return o.Value == o.Default
	}
}

// writeTemplate writes the configuration in Doxyfile format.
func (c *Config) writeTemplate(short bool, compare bool) string {
	var sb strings.Builder
	if compare {
		sb.WriteString("# Difference with default Doxyfile " + versionString() + "\n")
	} else {
		sb.WriteString("# Doxyfile " + doxyVersion + "\n\n")
		if !short {
			for _, h := range configTemplateHeader {
				sb.WriteString(h + "\n")
			}
			sb.WriteString("\n")
		}
	}
	section := ""
	for _, o := range c.opts {
		if compare {
			if o.Type == OptBool {
				o.convertStrToVal(false)
			}
			if o.isDefault() || o.Name == "DOXYFILE_ENCODING" {
				continue
			}
		}
		if o.Section != section && !compare {
			section = o.Section
			sb.WriteString("#---------------------------------------------------------------------------\n")
			sb.WriteString("# " + section + "\n")
			sb.WriteString("#---------------------------------------------------------------------------\n")
			if !short {
				sb.WriteString("\n")
			}
		}
		if !short && !compare {
			for _, d := range o.Doc {
				sb.WriteString(d + "\n")
			}
			sb.WriteString("\n")
			if o.UserComment != "" {
				sb.WriteString(o.UserComment)
				sb.WriteString("\n")
			}
		} else if o.UserComment != "" && !compare {
			sb.WriteString(o.UserComment)
		}
		o.writeValue(&sb)
		if !short && !compare {
			sb.WriteString("\n")
		}
	}
	if c.trailingComment != "" && !compare {
		if short {
			sb.WriteString("\n")
		}
		sb.WriteString(c.trailingComment)
	}
	return sb.String()
}

// sortedKeys helper
func sortedKeys(m map[string]bool) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}
EOF
