			format := strings.ToLower(args[i+1])
			switch format {
			case "rtf":
				if i+2 >= len(args) {
					errExit(1, "error: option \"-w rtf\" is missing a style sheet file name\n")
				}
				f, ok := openOutputFile(args[i+2])
				if ok {
					f.WriteString(resRtfStyle)
					if f != os.Stdout {
						f.Close()
					}
				} else {
					errExit(1, "error: error opening RTF style sheet file %s!\n", args[i+2])
				}
				cleanUpAndExit(0)
			case "html":
				if i+4 >= len(args) {
					errExit(1, "error: option \"-w html\" does not have enough arguments\n")
				}
				cfg := newConfig()
				if i+5 < len(args) {
					if !cfg.parseFile(args[i+5], false) {
						errExit(1, "error: file '%s' not found or could not be opened\nExiting...\n", args[i+5])
					}
				}
				cfg.postProcess(false, false)
				cfg.checkAndCorrect(true)
				writeFileOrExit(args[i+2], resHtmlHeader)
				writeFileOrExit(args[i+3], resHtmlFooter)
				writeFileOrExit(args[i+4], replaceColorMarkers(resDoxygenCssTmpl, cfg))
				cleanUpAndExit(0)
			case "latex":
				if i+4 >= len(args) {
					errExit(1, "error: option \"-w latex\" does not have enough arguments\n")
				}
				cfg := newConfig()
				if i+5 < len(args) {
					if !cfg.parseFile(args[i+5], false) {
						errExit(1, "error: file '%s' not found or could not be opened\nExiting...\n", args[i+5])
					}
				}
				cfg.postProcess(false, false)
				cfg.checkAndCorrect(true)
				writeFileOrExit(args[i+2], resLatexHeader)
				writeFileOrExit(args[i+3], resLatexFooter)
				writeFileOrExit(args[i+4], resDoxygenSty)
				cleanUpAndExit(0)
			default:
				errExit(1, "error: Illegal format specifier \"%s\": should be one of rtf, html or latex\n", args[i+1])
			}
		case a == "-m":
			// dump symbol map (ignored)
		case a == "-v" || a == "-V":
			fmt.Fprintf(stdout, "%s\n", versionString())
			if a == "-V" {
				fmt.Fprintf(stdout, "    with sqlite3 3.42.0.\n")
			}
			cleanUpAndExit(0)
		case a == "--help" || a == "-h" || a == "-?":
			usage(prog)
			cleanUpAndExit(0)
		case a == "-b":
			// unbuffered output
		case a == "-c":
			if i+1 >= len(args) {
				fmt.Fprintf(stdout, "option \"-c\" is missing the file name to read\n")
				devUsage()
				cleanUpAndExit(1)
			}
			i++
			// comment block processing: not supported in this implementation
			cleanUpAndExit(0)
		case a == "-q":
			quiet = true
		case a == "-":
			// config from stdin: handled below
			goto done
		default:
			fmt.Fprintf(os.Stderr, "error: Unknown option \"%s\"\n", a)
			usage(prog)
			cleanUpAndExit(1)
		}
		i++
	}
done:
	rest := args[i:]

	if genLayout {
		writeDefaultLayoutFile(layoutName)
		cleanUpAndExit(0)
	}

