	configName = ""
	if len(rest) > 0 {
		configName = rest[0]
	} else if i < len(args) && args[i] == "-" {
		configName = "-"
	}
	if configName == "" {
		if fileExists("Doxyfile") || updateConfig || diffList {
			configName = "Doxyfile"
		} else if fileExists("doxyfile") {
			configName = "doxyfile"
		} else {
			if fileExists("Doxyfile") || fileExists("doxyfile") {
				configName = "Doxyfile"
			} else {
				fmt.Fprintf(os.Stderr, "error: Doxyfile not found and no input file specified!\n")
				usage(prog)
				cleanUpAndExit(1)
			}
		}
	}
	if configName != "-" {
		st, err := os.Stat(configName)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: configuration file %s not found!\n", configName)
			usage(prog)
			cleanUpAndExit(1)
		}
		_ = st
	}

	cfg := newConfig()
	if !cfg.parseFile(configName, updateConfig) {
		if diffList || updateConfig {
			errExit(1, "")
		}
		errExit(1, "error: could not open or read configuration file %s!\nExiting...\n", configName)
	}

	if updateConfig {
		// write the updated file (bak copy first)
		if configName != "-" {
			data, _ := os.ReadFile(configName)
			os.WriteFile(configName+".bak", data, 0644)
		}
		cfg.updateObsolete()
		if configName == "-" {
			stdout.WriteString(cfg.writeTemplate(shortList, false))
		} else {
			f, err := os.Create(configName)
			if err != nil {
				errExit(1, "error: Cannot open file %s for writing\n", configName)
			}
			f.WriteString(cfg.writeTemplate(shortList, false))
			f.Close()
			fmt.Fprintf(stdout, "\n\nConfiguration file '%s' updated.\n\n", configName)
		}
