	cfg.postProcess(false, false)
	if quiet {
		cfg.SetBool("QUIET", true)
	}
	runDoxygen(cfg, configName)
	cleanUpAndExit(0)
}

func writeFileOrExit(name string, content string) {
	f, ok := openOutputFile(name)
	if !ok {
		errExit(1, "error: Cannot open file %s for writing\n", name)
	}
	f.WriteString(content)
	if f != os.Stdout {
		f.Close()
	}
}

func writeDefaultLayoutFile(name string) {
	f, ok := openOutputFile(name)
	if !ok {
		errExit(1, "error: Failed to open file %s for writing!\n", name)
	}
	f.WriteString(resLayoutDefault)
	if f != os.Stdout {
		f.Close()
	}
}
