func hsl2rgb(h, s, l float64) (float64, float64, float64) {
	r, g, b := l, l, l
	var v float64
	if l <= 0.5 {
		v = l * (1.0 + s)
	} else {
		v = l + s - l*s
	}
	if v > 0 {
		m := l + l - v
		sv := (v - m) / v
		h *= 6.0
		sextant := int(h)
		fract := h - float64(sextant)
		vsf := v * sv * fract
		mid1 := m + vsf
		mid2 := v - vsf
		switch sextant {
