			}
			flush()
			if lx.peek(1) == '"' {
				sb.WriteByte('"')
				raw.WriteString("\\\\\\"")
				lx.pos += 2
				continue
			}
			if lx.peek(1) != 0 && lx.peek(1) != '\\n' {
				sb.WriteByte('\\\\')
				sb.WriteByte(lx.peek(1))
				raw.WriteByte('\\\\')
				raw.WriteByte(lx.peek(1))
				lx.pos += 2
				continue
			}
			sb.WriteByte('\\\\')
			raw.WriteByte('\\\\')
			lx.pos++
			continue
		}
		if ch == '#' {
			lx.skipToEOL()
			break
		}
		if ch == '"' {
			flush()
			raw.WriteByte('"')
			lx.pos++
			closed := false
			for !lx.atEnd() {
				q := lx.data[lx.pos]
				if q == '\\n' {
					break
				}
				if q == '\\\\' && lx.peek(1) == '"' {
					sb.WriteByte('"')
					raw.WriteString("\\\\\\"")
					lx.pos += 2
					continue
				}
				if q == '"' {
					raw.WriteByte('"')
					lx.pos++
					closed = true
					break
				}
				sb.WriteByte(q)
				raw.WriteByte(q)
				lx.pos++
			}
			if !closed {
				break
			}
			continue
		}
		flush()
		sb.WriteByte(ch)
		raw.WriteByte(ch)
		lx.pos++
	}
	rawStr := strings.TrimSpace(raw.String())
	if !properlyQuoted(rawStr) {
		configWarn("Invalid value for '%s' tag at line %d, file %s: Value '%s' is not properly quoted", tag, lx.line, lx.fileName, rawStr)
	}
	// consume newline
	if !lx.atEnd() && lx.data[lx.pos] == '\\n' {
		lx.pos++
		lx.line++
	}
	return sb.String(), rawStr
}

