package main

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// wildcardToRegex converts a shell style wildcard pattern into an anchored regular expression.
func wildcardToRegex(pat string) string {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(pat); i++ {
		c := pat[i]
		switch c {
		case '*':
			sb.WriteString(".*")
		case '?':
			sb.WriteString(".")
		case '[':
			// character class: copy until ']'
			j := strings.IndexByte(pat[i:], ']')
			if j < 0 {
				sb.WriteString(`\[`)
			} else {
				cls := pat[i : i+j+1]
				if strings.HasPrefix(cls, "[!") {
					cls = "[^" + cls[2:]
				}
				sb.WriteString(cls)
				i += j
			}
		case '.', '+', '(', ')', '{', '}', '^', '$', '|', '\\':
			sb.WriteByte('\\')
			sb.WriteByte(c)
		default:
			sb.WriteByte(c)
		}
	}
	sb.WriteString("$")
	return sb.String()
}

var wildcardCache = map[string]*regexp.Regexp{}

func wildcardRegex(pat string, caseSense bool) *regexp.Regexp {
	key := pat
	if !caseSense {
		key = "(?i)" + pat
	}
	if re, ok := wildcardCache[key]; ok {
		return re
	}
	rs := wildcardToRegex(pat)
	if !caseSense {
		rs = "(?i)" + rs
	}
	re, err := regexp.Compile(rs)
	if err != nil {
		re = nil
	}
	wildcardCache[key] = re
	return re
}

// patternMatch checks whether the file matches one of the patterns.
func patternMatch(absPath string, patList []string, caseSense bool) bool {
	if len(patList) == 0 {
		return false
	}
	fn := filepath.Base(absPath)
	for _, pattern := range patList {
		if pattern == "" {
			continue
		}
		if i := strings.IndexByte(pattern, '='); i >= 0 {
			pattern = pattern[:i]
		}
		re := wildcardRegex(pattern, caseSense)
		if re == nil {
			continue
		}
		if re.MatchString(fn) || re.MatchString(absPath) {
			return true
		}
	}
	return false
}

func absPath(p string) string {
	a, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return a
}

// InputFile is a discovered source file.
type InputFile struct {
	Path string // absolute path
	Name string // file name
	Dir  string // absolute dir with trailing slash
}

