	}
	entries, err := os.ReadDir(absDir)
	if err != nil {
		return
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		names = append(names, e.Name())
	}
	sort.Strings(names)
	for _, name := range names {
		full := filepath.Join(absDir, name)
		if exclSet != nil && exclSet[full] {
			continue
		}
		st, err := os.Stat(full)
		if err != nil {
			if errorIfNotExist {
				warnUncond("source '%s' is not a readable file or directory... skipping.", full)
			}
			continue
		}
		if !st.IsDir() {
