				}
				if resultSet != nil {
					resultSet[full] = true
				}
				if killSet != nil {
					killSet[full] = true
				}
			}
		} else if recursive && (exclPatList == nil || !patternMatch(full, exclPatList, d.caseSense)) && name[0] != '.' {
