func (d *Doxygen) readFileOrDirectory(s string, exclSet map[string]bool, patList, exclPatList []string, result *[]string, resultSet map[string]bool, recursive bool, errorIfNotExist bool, killSet map[string]bool, paths map[string]bool, quiet bool) {
