	}
	st, err := os.Stat(s)
	if err != nil {
		if errorIfNotExist {
			warnUncond("source '%s' is not a readable file or directory... skipping.", s)
		}
		return
	}
	full := absPath(s)
	if exclSet != nil && exclSet[full] {
		return
	}
	if st.IsDir() {
		d.readDir(s, exclSet, patList, exclPatList, result, resultSet, errorIfNotExist, recursive, killSet, paths, quiet)
		return
	}
	if killSet != nil && killSet[full] {
		return
	}
	if paths != nil {
		paths[filepath.Dir(full)] = true
	}
	if result != nil {
		*result = append(*result, full)
	}
	if resultSet != nil {
		resultSet[full] = true
	}
	if killSet != nil {
		killSet[full] = true
	}
}
EOF
