package main

import (
	"os"
	"path/filepath"
	"strings"
)

// Doxygen holds the global state of a documentation run.
type Doxygen struct {
	cfg         *Config
	caseSense   bool
	outputDir   string
	htmlDir     string
	latexDir    string
	inputFiles  []string
	inputPaths  map[string]bool
	exclSet     map[string]bool
	includeFiles map[string]bool
	exampleFiles []string
	imageFiles   []string
	dotFiles     []string
	mscFiles     []string
	diaFiles     []string
	pumlFiles    []string

	// parsed entities
	files      []*FileDef
	classes    []*ClassDef
	namespaces []*NamespaceDef
	pages      []*PageDef
	groups     []*GroupDef
	mainPage   *PageDef
	classMap   map[string]*ClassDef
	nsMap      map[string]*NamespaceDef
	fileMap    map[string]*FileDef
	allMembers []*MemberDef
	globalNs   *NamespaceDef
	dirs       []*DirDef

	// index data
	indexList *IndexList
	projectName string
	typeLookupMisses int
	symbolLookupMisses int
	symbolLookupHits int
}

func runDoxygen(cfg *Config, configName string) {
	d := &Doxygen{cfg: cfg}
	d.classMap = map[string]*ClassDef{}
	d.nsMap = map[string]*NamespaceDef{}
	d.fileMap = map[string]*FileDef{}
	cfg.checkAndCorrect(false)
	d.adjustConfiguration()
	d.parseInput()
	d.generateOutput()
}

func (d *Doxygen) adjustConfiguration() {
	cfg := d.cfg
	quietMode = cfg.Bool("QUIET")
	warnFormat = cfg.Str("WARN_FORMAT")
	warnLineFmt = cfg.Str("WARN_LINE_FORMAT")
	warnIfUndoc = cfg.Bool("WARN_IF_UNDOCUMENTED")
	warnIfDocErr = cfg.Bool("WARN_IF_DOC_ERROR")
	warnNoParam = cfg.Bool("WARN_NO_PARAMDOC")
	warnAsError = cfg.Enum("WARN_AS_ERROR")
	if cfg.Bool("EXTRACT_ALL") {
		warnIfUndoc = false
	}
	if lf := cfg.Str("WARN_LOGFILE"); lf != "" {
		if lf == "-" {
			warnLogFile = os.Stdout
		} else {
