	for _, g := range []struct{ flag, opt string }{{"GENERATE_DOCBOOK", "DOCBOOK_OUTPUT"}, {"GENERATE_RTF", "RTF_OUTPUT"}, {"GENERATE_XML", "XML_OUTPUT"}, {"GENERATE_MAN", "MAN_OUTPUT"}} {
		if cfg.Bool(g.flag) {
			dir := cfg.Str(g.opt)
			if !filepath.IsAbs(dir) {
				dir = filepath.Join(outDir, dir)
			}
			if err := os.MkdirAll(dir, 0755); err != nil {
				termMsg("Could not create output directory %s\n", dir)
			}
		}
	}

	// gather input files
	exclPatterns := cfg.List("EXCLUDE_PATTERNS")
	filePatterns := cfg.List("FILE_PATTERNS")
	recursive := cfg.Bool("RECURSIVE")

	msg("Searching for include files...\n")
	d.includeFiles = map[string]bool{}
	killSet := map[string]bool{}
	for _, s := range cfg.List("INCLUDE_PATH") {
		pats := cfg.List("INCLUDE_FILE_PATTERNS")
		if len(pats) == 0 {
			pats = filePatterns
		}
		d.readFileOrDirectory(s, nil, pats, exclPatterns, nil, d.includeFiles, recursive, false, killSet, nil, true)
	}
	msg("Searching for example files...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("EXAMPLE_PATH") {
		d.readFileOrDirectory(s, nil, cfg.List("EXAMPLE_PATTERNS"), nil, &d.exampleFiles, nil, cfg.Bool("EXAMPLE_RECURSIVE"), false, killSet, nil, true)
	}
	msg("Searching for images...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("IMAGE_PATH") {
		d.readFileOrDirectory(s, nil, nil, nil, &d.imageFiles, nil, false, false, killSet, nil, true)
	}
	msg("Searching for dot files...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("DOTFILE_DIRS") {
		d.readFileOrDirectory(s, nil, nil, nil, &d.dotFiles, nil, false, false, killSet, nil, true)
	}
	msg("Searching for msc files...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("MSCFILE_DIRS") {
		d.readFileOrDirectory(s, nil, nil, nil, &d.mscFiles, nil, false, false, killSet, nil, true)
	}
	msg("Searching for dia files...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("DIAFILE_DIRS") {
		d.readFileOrDirectory(s, nil, nil, nil, &d.diaFiles, nil, false, false, killSet, nil, true)
	}
	msg("Searching for plantuml files...\n")
	killSet = map[string]bool{}
	for _, s := range cfg.List("PLANTUML_INCLUDE_PATH") {
		d.readFileOrDirectory(s, nil, nil, nil, &d.pumlFiles, nil, false, false, killSet, nil, true)
	}
	msg("Searching for files to exclude\n")
	d.exclSet = map[string]bool{}
	for _, s := range cfg.List("EXCLUDE") {
		d.readFileOrDirectory(s, nil, filePatterns, nil, nil, d.exclSet, recursive, false, nil, nil, true)
	}

	msg("Searching INPUT for files to process...\n")
	killSet = map[string]bool{}
	d.inputPaths = map[string]bool{}
	for _, s := range cfg.List("INPUT") {
		path := s
		if path == "" {
			continue
		}
		d.readFileOrDirectory(path, d.exclSet, filePatterns, exclPatterns, &d.inputFiles, nil, recursive, true, killSet, d.inputPaths, false)
	}
	// sort input files for predictable ordering
	sortStringsCI(d.inputFiles)
	if len(d.inputFiles) == 0 {
		warnUncond("No files to be processed, please check your settings, in particular INPUT, FILE_PATTERNS, and RECURSIVE")
	}

	msg("Reading and parsing tag files\n")
	// (tag files are not supported)

	// create file definitions
	for _, f := range d.inputFiles {
		fd := newFileDef(d, f)
		d.files = append(d.files, fd)
		d.fileMap[f] = fd
	}

	msg("Parsing files\n")
	for _, fd := range d.files {
