	msg("Generating file index...\n")
	d.generateFileIndex(html, latex)
	msg("Generating file member index...\n")
	d.generateFileMemberIndex(html, latex)
	msg("Generating example index...\n")
	msg("finalizing index lists...\n")
	if genHtml {
		html.finalize()
	}
	if genLatex {
		latex.finalize()
	}
	msg("writing tag file...\n")
	if tf := cfg.Str("GENERATE_TAGFILE"); tf != "" {
		d.writeTagFile(tf)
	}
	msg("Running plantuml with JAVA...\n")
	if cfg.Int("LOOKUP_CACHE_SIZE") >= 0 {
		size := 1 << (16 + cfg.Int("LOOKUP_CACHE_SIZE"))
		msg("type lookup cache used %d/%d hits=%d misses=%d\n", d.typeLookupMisses, size, 0, d.typeLookupMisses)
