}

var punct3 = []string{"<<=", ">>=", "...", "->*", "<=>"}
var punct2 = []string{"::", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "##", ".*"}

// Tokenizer converts preprocessed C/C++ source into tokens, keeping documentation comments.
type Tokenizer struct {
	src   []byte
	pos   int
	line  int
	toks  []Token
	lang  string
