func tokenizeSource(src []byte, lang string) []Token {
	t := &Tokenizer{src: src, line: 1, lang: lang}
	t.run()
	return t.toks
}

func (t *Tokenizer) peek(off int) byte {
	if t.pos+off < len(t.src) {
		return t.src[t.pos+off]
	}
	return 0
}

func isIdentStart(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}
func isIdentChar(c byte) bool { return isIdentStart(c) || (c >= '0' && c <= '9') }
func isDigit(c byte) bool     { return c >= '0' && c <= '9' }

func (t *Tokenizer) run() {
	src := t.src
	for t.pos < len(src) {
		c := src[t.pos]
		switch {
		case c == '\n':
			t.line++
			t.pos++
		case c == ' ' || c == '\t' || c == '\r' || c == '\f' || c == '\v':
			t.pos++
		case c == '/' && t.peek(1) == '/':
			t.lineComment()
		case c == '/' && t.peek(1) == '*':
			t.blockComment()
		case c == '#' && t.atLineStart():
			t.preprocLine()
		case c == '"' || (c == 'R' && t.peek(1) == '"'):
			t.stringLit()
		case c == '\'':
			t.charLit()
		case isDigit(c) || (c == '.' && isDigit(t.peek(1))):
			t.number()
