		if c == '\\' && t.peek(1) == '\r' && t.peek(2) == '\n' {
			t.pos += 3
			t.line++
			continue
		}
		if c == '\n' {
			break
		}
		if c == '/' && t.peek(1) == '*' {
			// block comment inside directive
