func (t *Tokenizer) onlyWhitespaceBetween(last *Token, line int) bool {
	return true
}

func (t *Tokenizer) blockComment() {
	start := t.pos
	startLine := t.line
	end := strings.Index(string(t.src[t.pos+2:]), "*/")
