	if end < 0 {
		text = string(t.src[t.pos:])
		t.pos = len(t.src)
	} else {
		text = string(t.src[t.pos : t.pos+2+end+2])
		t.pos += 2 + end + 2
	}
	t.line += strings.Count(text, "\n")
