		return
	}
	after := false
	if strings.HasPrefix(body, "<") {
		after = true
		body = body[1:]
	}
	t.toks = append(t.toks, Token{Kind: TokDocComment, Text: body, Line: startLine, EndLine: t.line, After: after, Qt: qt})
