			t.pos = p + idx + len(endSeq)
		}
		text := string(t.src[start:t.pos])
		t.line += strings.Count(text, "\n")
		t.toks = append(t.toks, Token{Kind: TokString, Text: text, Line: startLine, EndLine: t.line})
		return
	}
	// skip prefix
	for t.pos < len(t.src) && t.src[t.pos] != '"' {
		t.pos++
	}
	t.pos++
	for t.pos < len(t.src) {
		c := t.src[t.pos]
		if c == '\\' {
			if t.peek(1) == '\n' {
				t.line++
			}
			t.pos += 2
			continue
		}
		if c == '"' {
			t.pos++
			break
		}
		if c == '\n' {
			// unterminated string
			break
		}
		t.pos++
	}
	t.toks = append(t.toks, Token{Kind: TokString, Text: string(t.src[start:t.pos]), Line: startLine, EndLine: t.line})
}

func (t *Tokenizer) charLit() {
	start := t.pos
	t.pos++
	for t.pos < len(t.src) {
		c := t.src[t.pos]
		if c == '\\' {
			t.pos += 2
			continue
		}
		if c == '\'' {
			t.pos++
			break
		}
		if c == '\n' {
			break
		}
		t.pos++
	}
	t.toks = append(t.toks, Token{Kind: TokChar, Text: string(t.src[start:t.pos]), Line: t.line, EndLine: t.line})
}

func (t *Tokenizer) number() {
	start := t.pos
	for t.pos < len(t.src) {
		c := t.src[t.pos]
		if isIdentChar(c) || c == '.' || c == '\'' {
			t.pos++
			continue
		}
		if (c == '+' || c == '-') && t.pos > start && (t.src[t.pos-1] == 'e' || t.src[t.pos-1] == 'E' || t.src[t.pos-1] == 'p' || t.src[t.pos-1] == 'P') {
			t.pos++
			continue
		}
		break
	}
	t.toks = append(t.toks, Token{Kind: TokNumber, Text: string(t.src[start:t.pos]), Line: t.line, EndLine: t.line})
}

func (t *Tokenizer) punct() {
	rest := t.src[t.pos:]
	for _, p := range punct3 {
		if len(rest) >= 3 && string(rest[:3]) == p {
			t.toks = append(t.toks, Token{Kind: TokPunct, Text: p, Line: t.line, EndLine: t.line})
			t.pos += 3
			return
		}
	}
	for _, p := range punct2 {
		if len(rest) >= 2 && string(rest[:2]) == p {
			t.toks = append(t.toks, Token{Kind: TokPunct, Text: p, Line: t.line, EndLine: t.line})
			t.pos += 2
			return
		}
	}
	t.toks = append(t.toks, Token{Kind: TokPunct, Text: string(rest[:1]), Line: t.line, EndLine: t.line})
	t.pos++
}
