		value = def[i+1:]
	}
	m := &Macro{Name: name, Value: value, Predef: true}
	if j := strings.IndexByte(name, '('); j >= 0 {
		args := strings.TrimSuffix(name[j+1:], ")")
		m.Name = name[:j]
		m.HasArgs = true
		for _, a := range strings.Split(args, ",") {
			a = strings.TrimSpace(a)
			if a != "" {
				m.Params = append(m.Params, a)
			}
		}
	}
	p.macros[m.Name] = m
}

// ppLine represents a logical line (with continuations joined).
type ppLine struct {
	text      string
	line      int
	nlines    int // number of physical lines consumed
	directive bool
}

// splitLogicalLines splits the source into logical lines, tracking comments so that
// '#' inside comments is not treated as a directive.
func splitLogicalLines(src string) []ppLine {
	var lines []ppLine
	i := 0
	line := 1
	n := len(src)
	inBlockComment := false
	for i < n {
		start := i
		startLine := line
		// find end of logical line
		j := i
		inStr := byte(0)
		lineComment := false
		for j < n {
			c := src[j]
			if inBlockComment {
				if c == '*' && j+1 < n && src[j+1] == '/' {
					inBlockComment = false
					j += 2
					continue
				}
				if c == '\n' {
					break
				}
				j++
				continue
			}
			if lineComment {
				if c == '\n' {
					break
				}
				j++
				continue
			}
			if inStr != 0 {
				if c == '\\' && j+1 < n {
					j += 2
					continue
				}
				if c == inStr || c == '\n' {
					inStr = 0
					if c == '\n' {
						break
					}
				}
				j++
				continue
			}
			if c == '"' || c == '\'' {
				inStr = c
				j++
				continue
			}
			if c == '/' && j+1 < n && src[j+1] == '*' {
				inBlockComment = true
				j += 2
				continue
			}
			if c == '/' && j+1 < n && src[j+1] == '/' {
				lineComment = true
				j += 2
				continue
			}
			if c == '\\' && j+1 < n && src[j+1] == '\n' {
				j += 2
				line++
				continue
			}
			if c == '\\' && j+2 < n && src[j+1] == '\r' && src[j+2] == '\n' {
				j += 3
				line++
				continue
			}
			if c == '\n' {
				break
			}
			j++
		}
		text := src[start:j]
		if j < n {
			j++ // newline
		}
		line++
		pl := ppLine{text: text, line: startLine, nlines: line - startLine}
		trimmed := strings.TrimLeft(text, " \t")
		if strings.HasPrefix(trimmed, "#") && !strings.HasPrefix(strings.TrimLeft(src[start:], " \t"), "#") == false {
			// check that the '#' is not within a comment: the directive must start the logical line
			pl.directive = true
		}
		lines = append(lines, pl)
		i = j
	}
	return lines
}

// stripComments removes comments from a directive line.
func stripComments(s string) string {
	var sb strings.Builder
	i := 0
	for i < len(s) {
		if strings.HasPrefix(s[i:], "/*") {
			e := strings.Index(s[i+2:], "*/")
			if e < 0 {
				break
			}
			i += 2 + e + 2
			sb.WriteByte(' ')
			continue
		}
		if strings.HasPrefix(s[i:], "//") {
			break
		}
		if s[i] == '"' {
			j := i + 1
			for j < len(s) && s[j] != '"' {
				if s[j] == '\\' {
					j++
				}
				j++
			}
			if j < len(s) {
				j++
			}
			sb.WriteString(s[i:j])
			i = j
			continue
		}
		sb.WriteByte(s[i])
		i++
	}
	return sb.String()
}

type condState struct {
	active     bool // this branch is active
	parentOn   bool // enclosing region active
	taken      bool // some branch already taken
	elseSeen   bool
}

// process runs the preprocessor over the source and returns the processed text with
// inactive regions blanked (line structure preserved) and the list of #define macros found.
func (p *Preprocessor) process(src string, fileName string) (string, []*Macro) {
	p.defines = nil
	lines := splitLogicalLines(src)
	var out strings.Builder
	var stack []condState
	active := func() bool {
		if len(stack) == 0 {
			return true
		}
		return stack[len(stack)-1].active
	}
	for _, pl := range lines {
		trimmed := strings.TrimLeft(pl.text, " \t")
		isDirective := strings.HasPrefix(trimmed, "#")
		if isDirective {
			body := strings.TrimSpace(stripComments(trimmed[1:]))
			// directive keyword
			kw := body
			rest := ""
			for i := 0; i < len(body); i++ {
				if !isIdentChar(body[i]) {
					kw = body[:i]
					rest = strings.TrimSpace(body[i:])
					break
				}
			}
			switch kw {
			case "if":
				v := false
				if active() {
					v = p.evalExpr(rest) != 0
				}
				stack = append(stack, condState{active: active() && v, parentOn: active(), taken: v})
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "ifdef":
				v := false
				if active() {
					_, v = p.macros[firstIdent(rest)]
				}
				stack = append(stack, condState{active: active() && v, parentOn: active(), taken: v})
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "ifndef":
				v := false
				if active() {
					_, def := p.macros[firstIdent(rest)]
					v = !def
				}
				stack = append(stack, condState{active: active() && v, parentOn: active(), taken: v})
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "elif":
				if len(stack) > 0 {
					top := &stack[len(stack)-1]
					if top.parentOn && !top.taken {
						v := p.evalExpr(rest) != 0
						top.active = v
						if v {
							top.taken = true
						}
					} else {
						top.active = false
					}
				}
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "else":
				if len(stack) > 0 {
					top := &stack[len(stack)-1]
					top.active = top.parentOn && !top.taken
					top.taken = true
					top.elseSeen = true
				}
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "endif":
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			}
			if !active() {
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			}
			switch kw {
			case "define":
				m := p.parseDefine(rest, pl.line, fileName)
				if m != nil {
					p.macros[m.Name] = m
					p.defines = append(p.defines, m)
				}
				// keep the define line for the scanner (as a preprocessor token)
				out.WriteString(pl.text)
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "undef":
				delete(p.macros, firstIdent(rest))
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			case "include", "import", "include_next":
				out.WriteString(pl.text)
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			default:
				out.WriteString(strings.Repeat("\n", pl.nlines))
				continue
			}
		}
		if active() {
			out.WriteString(pl.text)
		} else {
			// keep newlines inside the inactive text to preserve line numbers
		}
		out.WriteString(strings.Repeat("\n", pl.nlines))
	}
	return out.String(), p.defines
}

func firstIdent(s string) string {
	s = strings.TrimSpace(s)
	i := 0
	for i < len(s) && isIdentChar(s[i]) {
		i++
	}
	return s[:i]
}

func (p *Preprocessor) parseDefine(rest string, line int, file string) *Macro {
	name := firstIdent(rest)
	if name == "" {
		return nil
	}
	m := &Macro{Name: name, Line: line, File: file}
	r := rest[len(name):]
	if strings.HasPrefix(r, "(") {
		e := strings.IndexByte(r, ')')
		if e < 0 {
			return nil
		}
		m.HasArgs = true
		for _, a := range strings.Split(r[1:e], ",") {
			a = strings.TrimSpace(a)
			if a == "..." {
				m.Variadic = true
			}
			if a != "" {
				m.Params = append(m.Params, a)
			}
		}
		r = r[e+1:]
	}
	m.Value = strings.TrimSpace(r)
	return m
}

// ---------------------------------------------------------------------------
// Expression evaluation for #if

type exprParser struct {
	toks []string
	pos  int
	p    *Preprocessor
}

func tokenizeExpr(s string) []string {
	var toks []string
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t':
			i++
		case isIdentStart(c):
			j := i
			for j < len(s) && isIdentChar(s[j]) {
				j++
			}
			toks = append(toks, s[i:j])
			i = j
		case isDigit(c):
			j := i
			for j < len(s) && (isIdentChar(s[j]) || s[j] == '\'') {
				j++
			}
			toks = append(toks, s[i:j])
			i = j
		case c == '\'':
			j := i + 1
			for j < len(s) && s[j] != '\'' {
				if s[j] == '\\' {
					j++
				}
				j++
			}
			if j < len(s) {
				j++
			}
			toks = append(toks, s[i:j])
			i = j
		default:
			for _, op := range []string{"<<", ">>", "<=", ">=", "==", "!=", "&&", "||"} {
				if strings.HasPrefix(s[i:], op) {
					toks = append(toks, op)
					i += 2
					goto next
				}
			}
			toks = append(toks, string(c))
			i++
		next:
		}
	}
	return toks
}

func (p *Preprocessor) evalExpr(s string) int64 {
	// expand defined() first, then macros, then evaluate
	toks := tokenizeExpr(s)
	toks = p.expandExprTokens(toks, 0)
	ep := &exprParser{toks: toks, p: p}
	v := ep.parseTernary()
	return v
}

func (p *Preprocessor) expandExprTokens(toks []string, depth int) []string {
	if depth > 20 {
		return toks
	}
	var out []string
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		if t == "defined" {
			name := ""
			if i+1 < len(toks) && toks[i+1] == "(" {
				if i+2 < len(toks) {
					name = toks[i+2]
				}
				i += 3
			} else if i+1 < len(toks) {
				name = toks[i+1]
				i++
			}
			if _, ok := p.macros[name]; ok {
				out = append(out, "1")
			} else {
				out = append(out, "0")
			}
			continue
		}
		if t == "__has_include" || t == "__has_include_next" || t == "__has_cpp_attribute" || t == "__has_builtin" || t == "__has_feature" || t == "__has_attribute" {
			// skip ( ... )
			depthP := 0
			j := i + 1
			for j < len(toks) {
				if toks[j] == "(" {
					depthP++
				} else if toks[j] == ")" {
					depthP--
					if depthP == 0 {
						break
					}
				}
				j++
			}
			i = j
			out = append(out, "0")
			continue
		}
		if isIdentStart(t[0]) {
			if m, ok := p.macros[t]; ok && !m.HasArgs {
				sub := tokenizeExpr(m.Value)
				sub = p.expandExprTokens(sub, depth+1)
				out = append(out, sub...)
				continue
			}
			if m, ok := p.macros[t]; ok && m.HasArgs && i+1 < len(toks) && toks[i+1] == "(" {
				// function-like macro: skip args, treat as 0 (simplistic)
				depthP := 0
				j := i + 1
				for j < len(toks) {
					if toks[j] == "(" {
						depthP++
					} else if toks[j] == ")" {
						depthP--
						if depthP == 0 {
							break
						}
					}
					j++
				}
				i = j
				out = append(out, "0")
				continue
			}
			if t == "true" {
				out = append(out, "1")
				continue
			}
			out = append(out, "0")
			continue
		}
		out = append(out, t)
	}
	return out
}

func (e *exprParser) peek() string {
	if e.pos < len(e.toks) {
		return e.toks[e.pos]
	}
	return ""
}
func (e *exprParser) next() string {
	t := e.peek()
	e.pos++
	return t
}

func (e *exprParser) parseTernary() int64 {
	c := e.parseBinary(0)
	if e.peek() == "?" {
		e.next()
		a := e.parseTernary()
		if e.peek() == ":" {
			e.next()
		}
		b := e.parseTernary()
		if c != 0 {
			return a
		}
		return b
	}
	return c
}

var binPrec = map[string]int{"||": 1, "&&": 2, "|": 3, "^": 4, "&": 5, "==": 6, "!=": 6, "<": 7, ">": 7, "<=": 7, ">=": 7, "<<": 8, ">>": 8, "+": 9, "-": 9, "*": 10, "/": 10, "%": 10}

func (e *exprParser) parseBinary(minPrec int) int64 {
	lhs := e.parseUnary()
	for {
		op := e.peek()
		prec, ok := binPrec[op]
		if !ok || prec < minPrec {
			return lhs
		}
		e.next()
		rhs := e.parseBinary(prec + 1)
		switch op {
		case "||":
			lhs = b2i(lhs != 0 || rhs != 0)
		case "&&":
			lhs = b2i(lhs != 0 && rhs != 0)
		case "|":
			lhs |= rhs
		case "^":
			lhs ^= rhs
		case "&":
			lhs &= rhs
		case "==":
			lhs = b2i(lhs == rhs)
		case "!=":
			lhs = b2i(lhs != rhs)
		case "<":
			lhs = b2i(lhs < rhs)
		case ">":
			lhs = b2i(lhs > rhs)
		case "<=":
			lhs = b2i(lhs <= rhs)
		case ">=":
			lhs = b2i(lhs >= rhs)
		case "<<":
			lhs <<= uint64(rhs) & 63
		case ">>":
			lhs >>= uint64(rhs) & 63
		case "+":
			lhs += rhs
		case "-":
			lhs -= rhs
		case "*":
			lhs *= rhs
		case "/":
			if rhs != 0 {
				lhs /= rhs
			} else {
				lhs = 0
			}
		case "%":
			if rhs != 0 {
				lhs %= rhs
			} else {
				lhs = 0
			}
		}
	}
}

func b2i(b bool) int64 {
	if b {
		return 1
	}
	return 0
}

func (e *exprParser) parseUnary() int64 {
	t := e.peek()
	switch t {
	case "!":
		e.next()
		return b2i(e.parseUnary() == 0)
	case "~":
		e.next()
		return ^e.parseUnary()
	case "-":
		e.next()
		return -e.parseUnary()
	case "+":
		e.next()
		return e.parseUnary()
	case "(":
		e.next()
		v := e.parseTernary()
		if e.peek() == ")" {
			e.next()
		}
		return v
	case "":
		return 0
	}
	e.next()
	if len(t) > 0 && isDigit(t[0]) {
		return parseIntLiteral(t)
	}
	if len(t) > 0 && t[0] == '\'' {
		if len(t) >= 3 {
			return int64(t[1])
		}
		return 0
	}
	return 0
}

func parseIntLiteral(t string) int64 {
	t = strings.ReplaceAll(t, "'", "")
	t = strings.TrimRight(t, "uUlLzZ")
	base := 10
	s := t
	if strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X") {
		base = 16
		s = t[2:]
	} else if strings.HasPrefix(t, "0b") || strings.HasPrefix(t, "0B") {
		base = 2
		s = t[2:]
	} else if len(t) > 1 && t[0] == '0' {
		base = 8
		s = t[1:]
	}
	v, err := strconv.ParseInt(s, base, 64)
	if err != nil {
		u, err2 := strconv.ParseUint(s, base, 64)
		if err2 != nil {
			return 0
		}
		return int64(u)
	}
	return v
}
