package main

import (
	"path/filepath"
	"strings"
)

// CParser parses C/C++ token streams into Entry trees.
type CParser struct {
	d        *Doxygen
	toks     []Token
	pos      int
	file     string
	root     *Entry
	lang     string
	pendingDocs []Token
	lastEntry *Entry // last declaration (for trailing docs)
	defines  []*Macro
}

func (d *Doxygen) parseFile(fd *FileDef) {
	cfg := d.cfg
	src, err := readFileBytes(fd.File)
	if err != nil {
		warnUncond("Cannot open file %s", fd.File)
		return
	}
	// strip BOM
	if len(src) >= 3 && src[0] == 0xEF && src[1] == 0xBB && src[2] == 0xBF {
		src = src[3:]
	}
	fd.Source = src
	root := &Entry{Kind: "file", Name: fd.File, File: fd.File}
	fd.Entries = root
	text := string(src)
	if fd.Lang == "markdown" {
		msg("Reading %s...\n", fd.File)
		d.parseMarkdownFile(fd, text)
		return
	}
	if fd.Lang == "python" || fd.Lang == "fortran" || fd.Lang == "vhdl" {
		msg("Parsing file %s...\n", fd.File)
		// unsupported languages: no entities extracted
		return
	}
	var defines []*Macro
	if cfg.Bool("ENABLE_PREPROCESSING") {
		msg("Preprocessing %s...\n", fd.File)
		pp := newPreprocessor(d)
		text, defines = pp.process(text, fd.File)
	} else {
		msg("Reading %s...\n", fd.File)
	}
	msg("Parsing file %s...\n", fd.File)
	toks := tokenizeSource([]byte(text), fd.Lang)
	p := &CParser{d: d, toks: toks, file: fd.File, root: root, lang: fd.Lang, defines: defines}
	p.parseTop()
}

func readFileBytes(path string) ([]byte, error) {
	return osReadFile(path)
}

func (p *CParser) peek() *Token {
	if p.pos < len(p.toks) {
		return &p.toks[p.pos]
	}
	return &p.toks[len(p.toks)-1]
}

func (p *CParser) peekN(n int) *Token {
	if p.pos+n < len(p.toks) {
		return &p.toks[p.pos+n]
	}
	return &p.toks[len(p.toks)-1]
}

func (p *CParser) next() *Token {
	t := p.peek()
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *CParser) atEOF() bool { return p.peek().Kind == TokEOF }

func (p *CParser) isPunct(s string) bool {
	t := p.peek()
	return t.Kind == TokPunct && t.Text == s
}

func (p *CParser) isIdent(s string) bool {
	t := p.peek()
	return t.Kind == TokIdent && t.Text == s
}

// skipBalanced skips from the current open token to its matching close token.
func (p *CParser) skipBalanced(open, close string) int {
	depth := 0
	endLine := p.peek().Line
	for !p.atEOF() {
		t := p.next()
		if t.Kind == TokPunct {
			if t.Text == open {
				depth++
			} else if t.Text == close {
				depth--
				if depth == 0 {
					return t.Line
				}
			}
		}
		endLine = t.EndLine
	}
	return endLine
}

func (p *CParser) parseTop() {
	p.parseScope(p.root, "file", Public)
}

// collectDocs attaches pending doc comments (those preceding) to an entry.
func (p *CParser) attachPendingDocs(e *Entry) {
	for _, dt := range p.pendingDocs {
		p.d.handleDocComment(e, dt, p.file, false)
	}
	p.pendingDocs = nil
}

// handleDocToken processes a doc comment token encountered at scope level.
func (p *CParser) handleDocToken(scope *Entry, t Token) {
	if t.After {
		if p.lastEntry != nil {
			p.d.handleDocComment(p.lastEntry, t, p.file, true)
		} else {
			// no previous entry: treat as normal doc
			p.pendingDocs = append(p.pendingDocs, t)
		}
		return
	}
	// a doc comment that is standalone (documents a named entity via \file, \class, ...)
	// is handled when attaching: if it contains such a command it is detached.
	if p.d.isStandaloneDoc(t.Text) {
		p.d.handleStandaloneDoc(scope, p.root, t, p.file)
		return
	}
	// if two doc comments appear consecutively, the earlier ones become standalone docs for the file?
	// Doxygen attaches all preceding doc blocks to the next declaration; keep them pending.
	p.pendingDocs = append(p.pendingDocs, t)
}

// parseScope parses declarations until the closing brace (or EOF) of the scope.
func (p *CParser) parseScope(scope *Entry, kind string, defaultProt Protection) {
	prot := defaultProt
	for !p.atEOF() {
		t := p.peek()
		switch t.Kind {
		case TokDocComment:
			p.next()
			p.handleDocToken(scope, *t)
			continue
		case TokPreproc:
			p.next()
			p.handlePreproc(scope, *t)
			continue
		case TokPunct:
			switch t.Text {
			case "}":
				if kind != "file" {
					return
				}
				p.next()
				continue
			case ";":
				p.next()
				continue
			case "{":
				// stray block (e.g. extern "C" handled elsewhere) -> parse inside same scope
				p.next()
				p.parseScope(scope, "block", prot)
				if p.isPunct("}") {
					p.next()
				}
				continue
			case "[":
				if p.peekN(1).Kind == TokPunct && p.peekN(1).Text == "[" {
					// attribute
					p.skipBalanced("[", "]")
					continue
				}
			}
		case TokIdent:
			switch t.Text {
			case "public", "private", "protected":
				if kind == "class" && p.peekN(1).Kind == TokPunct && p.peekN(1).Text == ":" {
					p.next()
					p.next()
					switch t.Text {
					case "public":
						prot = Public
					case "private":
						prot = Private
					case "protected":
						prot = Protected
					}
					p.pendingDocs = nil
					continue
				}
			case "signals", "Q_SIGNALS":
				if kind == "class" && p.peekN(1).Kind == TokPunct && p.peekN(1).Text == ":" {
					p.next()
					p.next()
					prot = Public
					continue
				}
			case "slots", "Q_SLOTS":
				if kind == "class" && p.peekN(1).Kind == TokPunct && p.peekN(1).Text == ":" {
					p.next()
					p.next()
					continue
				}
			case "namespace":
				if p.parseNamespace(scope) {
					continue
				}
			case "extern":
				if p.peekN(1).Kind == TokString {
					// extern "C" { ... } or extern "C" decl
					p.next()
					p.next()
					if p.isPunct("{") {
						p.next()
						p.parseScope(scope, "block", prot)
						if p.isPunct("}") {
							p.next()
						}
						continue
					}
					// single declaration follows
					p.parseDeclaration(scope, kind, prot, nil)
					continue
				}
			case "template":
				tArgs := p.parseTemplateHeader()
				if tArgs != nil {
					p.parseAfterTemplate(scope, kind, prot, tArgs)
					continue
				}
			case "using":
				p.parseUsing(scope, prot)
				continue
			case "typedef":
				p.parseTypedef(scope, prot)
				continue
			case "friend":
				p.parseFriend(scope, prot)
				continue
			case "static_assert", "_Static_assert":
				p.skipToSemicolon()
				continue
			case "Q_OBJECT", "Q_GADGET":
				p.next()
				continue
			case "class", "struct", "union", "enum", "interface":
				if t.Text == "interface" && p.lang != "idl" && !(p.peekN(1).Kind == TokIdent && p.peekN(2).Kind == TokPunct && (p.peekN(2).Text == "{" || p.peekN(2).Text == ":")) {
					break
				}
				if p.parseCompound(scope, kind, prot, nil) {
					continue
				}
				continue
			}
		}
		p.parseDeclaration(scope, kind, prot, nil)
	}
}

func (p *CParser) skipToSemicolon() {
	for !p.atEOF() {
		t := p.next()
		if t.Kind == TokPunct {
			switch t.Text {
			case ";":
				return
			case "{":
				p.pos--
				p.skipBalanced("{", "}")
			case "(":
				p.pos--
				p.skipBalanced("(", ")")
			}
		}
	}
}

func (p *CParser) handlePreproc(scope *Entry, t Token) {
	text := strings.TrimSpace(t.Text)
	text = strings.TrimPrefix(text, "#")
	text = strings.TrimSpace(text)
	if strings.HasPrefix(text, "include") || strings.HasPrefix(text, "import") {
		rest := strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(text, "include"), "import"))
		rest = stripComments(rest)
		rest = strings.TrimSpace(rest)
		if len(rest) >= 2 {
			local := rest[0] == '"'
			end := strings.IndexAny(rest[1:], "\">")
			if end >= 0 {
				name := rest[1 : 1+end]
				e := &Entry{Kind: "include", Name: name, Line: t.Line, File: p.file, Local: local}
				p.root.addChild(e)
			}
		}
		return
	}
	if strings.HasPrefix(text, "define") {
		rest := strings.TrimSpace(text[6:])
		rest = stripComments(rest)
		name := firstIdent(rest)
		if name == "" {
			return
		}
		e := &Entry{Kind: "define", Name: name, Line: t.Line, File: p.file, Prot: Public}
		r := rest[len(name):]
		if strings.HasPrefix(r, "(") {
			end := strings.IndexByte(r, ')')
			if end > 0 {
				e.Args = "(" + strings.TrimSpace(r[1:end]) + ")"
				// normalize spacing: doxygen writes args as given
				e.Args = normalizeDefineArgs(r[1:end])
				r = r[end+1:]
			}
		}
		e.Initializer = strings.TrimSpace(r)
		p.attachPendingDocs(e)
		p.root.addChild(e)
		p.lastEntry = e
		return
	}
}

func normalizeDefineArgs(a string) string {
	parts := strings.Split(a, ",")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return "(" + strings.Join(parts, ", ") + ")"
}

// parseNamespace parses `namespace name { ... }` or `namespace A::B {`, or `namespace x = y;`
func (p *CParser) parseNamespace(scope *Entry) bool {
	save := p.pos
	startTok := p.next() // namespace
	inline := false
	if p.isIdent("inline") {
		inline = true
		p.next()
	}
	_ = inline
	name := ""
	for p.peek().Kind == TokIdent || p.isPunct("::") {
		name += p.next().Text
	}
	if p.isPunct("=") {
		// namespace alias
		p.skipToSemicolon()
		p.pendingDocs = nil
		return true
	}
	if p.isPunct("[") {
		p.skipBalanced("[", "]")
	}
	if !p.isPunct("{") {
		p.pos = save
		return false
	}
	// nested namespaces A::B::C
	parts := strings.Split(name, "::")
	cur := scope
	var created []*Entry
	for i, part := range parts {
		e := &Entry{Kind: "namespace", Name: part, Line: startTok.Line, File: p.file, Prot: Public}
		if part == "" {
			e.Name = "anonymous_namespace{" + filepath.Base(p.file) + "}"
			e.Local_ = true
		}
		if i == len(parts)-1 {
			p.attachPendingDocs(e)
		}
		cur.addChild(e)
		cur = e
		created = append(created, e)
	}
	p.pendingDocs = nil
	bodyStart := p.next().Line // {
	p.lastEntry = nil
	p.parseScope(cur, "namespace", Public)
	endLine := p.peek().Line
	if p.isPunct("}") {
		p.next()
	}
	for _, e := range created {
		e.BodyStart = bodyStart
		e.BodyEnd = endLine
	}
	p.lastEntry = nil
	return true
}

// parseTemplateHeader parses `template < ... >` and returns the argument list.
func (p *CParser) parseTemplateHeader() *ArgumentList {
	save := p.pos
	p.next() // template
	if !p.isPunct("<") {
		p.pos = save
		// `template` used in another context (e.g. explicit instantiation `template class X<int>;`)
		p.next()
		return &ArgumentList{Valid: true}
	}
	text := p.collectAngle()
	al := parseTemplateArgs(text)
	return al
}

// collectAngle collects the text of a balanced <...> group (current token is '<').
func (p *CParser) collectAngle() string {
	depth := 0
	var parts []string
	for !p.atEOF() {
		t := p.next()
		if t.Kind == TokPunct {
			if t.Text == "<" {
				depth++
				if depth == 1 {
					continue
				}
			} else if t.Text == ">" {
				depth--
				if depth == 0 {
					break
				}
			} else if t.Text == ">>" {
				depth -= 2
				if depth <= 0 {
					break
				}
			}
		}
		parts = append(parts, t.Text)
	}
	return joinTokens(parts)
}

func (p *CParser) parseAfterTemplate(scope *Entry, kind string, prot Protection, tArgs *ArgumentList) {
	// template followed by class/struct/union or declaration; multiple template headers possible
	tlist := []*ArgumentList{tArgs}
	for p.isIdent("template") {
		tl := p.parseTemplateHeader()
		tlist = append(tlist, tl)
	}
	t := p.peek()
	if t.Kind == TokIdent {
		switch t.Text {
		case "class", "struct", "union", "interface":
			// explicit instantiation / specialization handled by parseCompound
			p.parseCompound(scope, kind, prot, tlist)
			return
		case "using":
			p.parseUsing(scope, prot)
			if e := p.lastEntry; e != nil && e.Kind == "typedef" {
				e.TArgLists = tlist
			}
			return
		case "friend":
			p.parseFriend(scope, prot)
			return
		case "concept":
			p.parseConcept(scope, prot, tlist)
			return
		}
	}
	p.parseDeclaration(scope, kind, prot, tlist)
}

func (p *CParser) parseConcept(scope *Entry, prot Protection, tlist []*ArgumentList) {
	start := p.next() // concept
	name := ""
	if p.peek().Kind == TokIdent {
		name = p.next().Text
	}
	var init []string
	if p.isPunct("=") {
		p.next()
		for !p.atEOF() && !p.isPunct(";") {
			init = append(init, p.next().Text)
		}
	}
	if p.isPunct(";") {
		p.next()
	}
	e := &Entry{Kind: "concept", Name: name, Line: start.Line, File: p.file, Prot: prot, TArgLists: tlist, Initializer: joinTokens(init)}
	p.attachPendingDocs(e)
	scope.addChild(e)
	p.lastEntry = e
}

func (p *CParser) parseUsing(scope *Entry, prot Protection) {
	start := p.next() // using
	if p.isIdent("namespace") {
		p.next()
		name := ""
		for p.peek().Kind == TokIdent || p.isPunct("::") {
			name += p.next().Text
		}
		p.skipToSemicolon()
		e := &Entry{Kind: "usingdir", Name: name, Line: start.Line, File: p.file}
		scope.addChild(e)
		p.pendingDocs = nil
		return
	}
	// using alias or using declaration
	var toks []string
	isAlias := false
	for !p.atEOF() && !p.isPunct(";") {
		t := p.next()
		if t.Kind == TokPunct && t.Text == "=" && !isAlias {
			isAlias = true
			toks = append(toks, "=")
			continue
		}
		if t.Kind == TokPunct && t.Text == "{" {
			p.pos--
			p.skipBalanced("{", "}")
			continue
		}
		toks = append(toks, t.Text)
	}
	if p.isPunct(";") {
		p.next()
	}
	if isAlias {
		eq := indexOf(toks, "=")
		name := joinTokens(toks[:eq])
		// strip attributes
		typ := joinTokens(toks[eq+1:])
		e := &Entry{Kind: "typedef", Name: name, Type: typ, Line: start.Line, File: p.file, Prot: prot, Alias: true}
		p.attachPendingDocs(e)
		scope.addChild(e)
		p.lastEntry = e
		return
	}
	name := joinTokens(toks)
	e := &Entry{Kind: "using", Name: name, Line: start.Line, File: p.file, Prot: prot}
	p.attachPendingDocs(e)
	scope.addChild(e)
	p.lastEntry = e
}

func indexOf(s []string, v string) int {
	for i, x := range s {
		if x == v {
			return i
		}
	}
	return -1
}

func (p *CParser) parseTypedef(scope *Entry, prot Protection) {
	start := p.next() // typedef
	// typedef struct {...} name;  or typedef type name;  or typedef ret (*name)(args);
	if p.peek().Kind == TokIdent && (p.peek().Text == "struct" || p.peek().Text == "union" || p.peek().Text == "enum" || p.peek().Text == "class") {
		// look ahead for '{' before ';'
		save := p.pos
		depth := 0
		hasBody := false
		for i := p.pos; i < len(p.toks); i++ {
			t := p.toks[i]
			if t.Kind == TokPunct {
				if t.Text == "{" {
					if depth == 0 {
						hasBody = true
					}
					depth++
				} else if t.Text == "}" {
					depth--
				} else if t.Text == ";" && depth == 0 {
					break
				}
			}
			if t.Kind == TokEOF {
				break
			}
		}
		p.pos = save
		if hasBody {
			p.parseCompound(scope, "typedef", prot, nil)
			return
		}
	}
	var toks []Token
	for !p.atEOF() && !p.isPunct(";") {
		t := p.next()
		if t.Kind == TokDocComment {
			continue
		}
		toks = append(toks, *t)
	}
	if p.isPunct(";") {
		p.next()
	}
	decls := splitDeclarators(toks)
	for _, dcl := range decls {
		typ, name, args := analyzeDeclarator(dcl, false)
		if name == "" {
			continue
		}
		e := &Entry{Kind: "typedef", Name: name, Type: typ, Args: args, Line: start.Line, File: p.file, Prot: prot}
		p.attachPendingDocs(e)
		scope.addChild(e)
		p.lastEntry = e
	}
	p.pendingDocs = nil
}

func (p *CParser) parseFriend(scope *Entry, prot Protection) {
	start := p.next() // friend
	// friend class X; or friend ret func(args);
	var toks []Token
	for !p.atEOF() && !p.isPunct(";") {
		t := p.peek()
		if t.Kind == TokPunct && t.Text == "{" {
			// friend function definition
			p.skipBalanced("{", "}")
			break
		}
		toks = append(toks, *p.next())
	}
	if p.isPunct(";") {
		p.next()
	}
	if len(toks) == 0 {
		return
	}
	if toks[0].Kind == TokIdent && (toks[0].Text == "class" || toks[0].Text == "struct" || toks[0].Text == "union") {
		name := joinTokenTexts(toks[1:])
		e := &Entry{Kind: "friend", Name: name, Type: "friend " + toks[0].Text, Line: start.Line, File: p.file, Prot: Public, Friend: true}
		p.attachPendingDocs(e)
		scope.addChild(e)
		p.lastEntry = e
		return
	}
	typ, name, args := analyzeDeclarator(toks, true)
	e := &Entry{Kind: "function", Name: name, Type: "friend " + typ, Args: args, Line: start.Line, File: p.file, Prot: Public, Friend: true}
	e.ArgList = parseArgList(args)
	p.attachPendingDocs(e)
	scope.addChild(e)
	p.lastEntry = e
}

func joinTokenTexts(toks []Token) string {
	parts := make([]string, len(toks))
	for i, t := range toks {
		parts[i] = t.Text
	}
	return joinTokens(parts)
}

// joinTokens joins token texts with spacing rules similar to doxygen's.
func joinTokens(parts []string) string {
	var sb strings.Builder
	for i, t := range parts {
		if i > 0 {
			prev := parts[i-1]
			if needSpace(prev, t) {
				sb.WriteByte(' ')
			}
		}
		sb.WriteString(t)
	}
	return sb.String()
}

func isWordTok(s string) bool {
	return len(s) > 0 && (isIdentChar(s[0]) || s[0] == '"' || s[0] == '\'')
}

func needSpace(prev, cur string) bool {
	if prev == "" || cur == "" {
		return false
	}
	if isWordTok(prev) && isWordTok(cur) {
		return true
	}
	switch cur {
	case ",", ")", "]", ";", "::", ">", "(", "[":
		if cur == "(" || cur == "[" {
			return false
		}
		return false
	}
	switch prev {
	case "::", "(", "[", "<", "~", "!":
		return false
	case ",":
		return true
	case "*", "&", "&&":
		return isWordTok(cur)
	}
	if cur == "*" || cur == "&" || cur == "&&" {
		return true
	}
	if cur == "<" {
		return false
	}
	if cur == "=" || prev == "=" {
		return true
	}
	if prev == ">" && isWordTok(cur) {
		return true
	}
	if prev == ")" && (isWordTok(cur) || cur == "-" || cur == "->") {
		return true
	}
	if cur == "->" || prev == "->" {
		return true
	}
	if prev == "..." {
		return true
	}
	if isWordTok(prev) && (cur == "{" || cur == "}") {
		return true
	}
	if cur == "..." {
		return false
	}
	// generic operators: space around binary operators
	if !isWordTok(prev) && !isWordTok(cur) {
		return false
	}
	return false
}

// parseCompound parses class/struct/union/enum definitions and declarations.
func (p *CParser) parseCompound(scope *Entry, scopeKind string, prot Protection, tlist []*ArgumentList) bool {
	startTok := p.next()
	kw := startTok.Text // class, struct, union, enum, interface
	kind := kw
	isTypedef := scopeKind == "typedef"
	// enum class / enum struct
	strong := false
	if kw == "enum" && p.peek().Kind == TokIdent && (p.peek().Text == "class" || p.peek().Text == "struct") {
		p.next()
		strong = true
	}
	// attributes / alignas / declspec
	for p.isPunct("[") || p.isIdent("alignas") || p.isIdent("__declspec") || p.isIdent("__attribute__") {
		if p.isPunct("[") {
			p.skipBalanced("[", "]")
		} else {
			p.next()
			if p.isPunct("(") {
				p.skipBalanced("(", ")")
			}
		}
	}
	// name (possibly qualified, possibly with template specialization)
	name := ""
	for p.peek().Kind == TokIdent || p.isPunct("::") {
		t := p.peek()
		if t.Kind == TokIdent && (t.Text == "final" || t.Text == "sealed" || t.Text == "abstract") && p.peekN(1).Kind == TokPunct && (p.peekN(1).Text == "{" || p.peekN(1).Text == ":") {
			break
		}
		if t.Kind == TokIdent && (t.Text == "__declspec" || t.Text == "alignas") {
			p.next()
			if p.isPunct("(") {
				p.skipBalanced("(", ")")
			}
			continue
		}
		name += p.next().Text
		if p.isPunct("<") {
			name += "< " + p.collectAngle() + " >"
		}
	}
	// macro-like export attribute: `class DLL_EXPORT Name` -> two identifiers in a row
	// handled: name accumulates both; split on uppercase macro heuristically
	final := false
	for p.peek().Kind == TokIdent && (p.peek().Text == "final" || p.peek().Text == "sealed" || p.peek().Text == "abstract") {
		final = true
		p.next()
	}
	// enum base type
	enumBase := ""
	var bases []BaseInfo
	if p.isPunct(":") {
		p.next()
		if kw == "enum" {
			var parts []string
			for !p.atEOF() && !p.isPunct("{") && !p.isPunct(";") {
				parts = append(parts, p.next().Text)
			}
			enumBase = joinTokens(parts)
		} else {
			bases = p.parseBaseList()
		}
	}
	if !p.isPunct("{") {
		// forward declaration, elaborated type usage, or variable declaration `struct X x;`
		if p.isPunct(";") {
			p.next()
			// forward declaration: ignore
			p.pendingDocs = nil
			return true
		}
		// `class X var;` or function returning struct etc: parse as declaration with type prefix
		typPrefix := kw
		if name != "" {
			typPrefix += " " + name
		}
		p.parseDeclarationWithPrefix(scope, scopeKind, prot, tlist, typPrefix, startTok.Line)
		return true
	}
	bodyStartTok := p.next() // {
	e := &Entry{Kind: kind, Name: name, Line: startTok.Line, File: p.file, Prot: prot, TArgLists: tlist, Final: final, Strong: strong}
	if name == "" {
		e.Name = ""
	}
	e.Bases = bases
	e.BodyStart = bodyStartTok.Line
	if kw == "enum" {
		e.Type = enumBase
		if strong {
			e.Strong = true
		}
	}
	p.attachPendingDocs(e)
	savedLast := p.lastEntry
	p.lastEntry = nil
	if kw == "enum" {
		p.parseEnumBody(e)
	} else {
		defProt := Private
		if kw == "struct" || kw == "union" || kw == "interface" {
			defProt = Public
		}
		if p.lang == "java" || p.lang == "csharp" {
			defProt = Package
		}
		p.parseScope(e, "class", defProt)
	}
	endLine := p.peek().Line
	if p.isPunct("}") {
		p.next()
	}
	e.BodyEnd = endLine
	_ = savedLast
	// declarators after the body: `} x, *y;` or typedef name
	var declToks []Token
	for !p.atEOF() && !p.isPunct(";") {
		t := p.next()
		if t.Kind == TokDocComment {
			if t.After {
				// doc after the closing brace documents the compound (or the variable)
				p.d.handleDocComment(e, *t, p.file, true)
			}
			continue
		}
		if t.Kind == TokPunct && t.Text == "{" {
			p.pos--
			p.skipBalanced("{", "}")
			continue
		}
		declToks = append(declToks, *t)
	}
	if p.isPunct(";") {
		p.next()
	}
	// check for a trailing doc comment on the same line as ';'
	if p.peek().Kind == TokDocComment && p.peek().After {
		t := p.next()
		if len(declToks) == 0 {
			p.d.handleDocComment(e, *t, p.file, true)
		} else {
			// attach to the variable declared below
			p.pendingDocs = append(p.pendingDocs, *t)
		}
	}
	anonymous := name == ""
	if isTypedef && len(declToks) > 0 {
		decls := splitDeclarators(declToks)
		if anonymous && len(decls) > 0 {
			// typedef struct { } Name; -> the struct gets the name
			_, tname, _ := analyzeDeclarator(decls[0], false)
			if tname != "" {
				e.Name = tname
				anonymous = false
				decls = decls[1:]
			}
		}
		scope.addChild(e)
		for _, dcl := range decls {
			_, tname, targs := analyzeDeclarator(dcl, false)
			if tname == "" {
				continue
			}
			td := &Entry{Kind: "typedef", Name: tname, Type: kw + " " + e.Name, Args: targs, Line: startTok.Line, File: p.file, Prot: prot}
			scope.addChild(td)
		}
		p.lastEntry = e
		p.pendingDocs = nil
		return true
	}
	if anonymous {
		// anonymous struct/union/enum
		if kw == "enum" {
			e.Name = "@" + itoa(len(scope.Children))
			e.Anonymous()
		} else {
			e.Name = "@" + itoa(len(scope.Children))
		}
	}
	scope.addChild(e)
	p.lastEntry = e
	// variables declared with the compound
	if len(declToks) > 0 {
		decls := splitDeclarators(declToks)
		typName := e.Name
		if anonymous {
			typName = kw
		} else {
			typName = kw + " " + e.Name
		}
		for _, dcl := range decls {
			_, vname, vargs := analyzeDeclarator(dcl, false)
			if vname == "" {
				continue
			}
			v := &Entry{Kind: "variable", Name: vname, Type: typName, Args: vargs, Line: startTok.Line, File: p.file, Prot: prot}
			if anonymous {
				v.Type = e.Name
			}
			if idx := indexOfTok(dcl, "="); idx >= 0 {
				v.Initializer = "= " + joinTokenTexts(dcl[idx+1:])
			}
			p.attachPendingDocs(v)
			scope.addChild(v)
			p.lastEntry = v
		}
	}
	p.pendingDocs = nil
	return true
}

func (e *Entry) Anonymous() {}

func itoa(i int) string {
	return strings.TrimSpace(strings.Repeat("", 0) + intToStr(i))
}

func intToStr(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

func indexOfTok(toks []Token, s string) int {
	depth := 0
	for i, t := range toks {
		if t.Kind == TokPunct {
			switch t.Text {
			case "(", "[", "{", "<":
				depth++
			case ")", "]", "}", ">":
				depth--
			}
			if t.Text == s && depth == 0 {
				return i
			}
		}
	}
	return -1
}

// parseBaseList parses the inheritance list after ':'.
func (p *CParser) parseBaseList() []BaseInfo {
	var bases []BaseInfo
	for !p.atEOF() && !p.isPunct("{") && !p.isPunct(";") {
		b := BaseInfo{Prot: Private}
		if p.lang == "java" || p.lang == "csharp" || p.lang == "idl" {
			b.Prot = Public
		}
		var nameParts []string
		for !p.atEOF() && !p.isPunct(",") && !p.isPunct("{") && !p.isPunct(";") {
			t := p.peek()
			if t.Kind == TokIdent {
				switch t.Text {
				case "public":
					b.Prot = Public
					p.next()
					continue
				case "protected":
					b.Prot = Protected
					p.next()
					continue
				case "private":
					b.Prot = Private
					p.next()
					continue
				case "virtual":
					b.Virtual = true
					p.next()
					continue
				}
			}
			if t.Kind == TokPunct && t.Text == "<" {
				nameParts = append(nameParts, "< "+p.collectAngle()+" >")
				continue
			}
			nameParts = append(nameParts, p.next().Text)
		}
		b.Name = strings.Join(nameParts, "")
		b.Name = strings.ReplaceAll(b.Name, "...", "")
		if b.Name != "" {
			bases = append(bases, b)
		}
		if p.isPunct(",") {
			p.next()
		}
	}
	return bases
}

// parseEnumBody parses enumerators until '}'.
func (p *CParser) parseEnumBody(e *Entry) {
	for !p.atEOF() && !p.isPunct("}") {
		t := p.peek()
		if t.Kind == TokDocComment {
			p.next()
			p.handleDocToken(e, *t)
			continue
		}
		if t.Kind == TokPreproc {
			p.next()
			continue
		}
		if t.Kind != TokIdent {
			p.next()
			continue
		}
		nameTok := p.next()
		// attributes
		for p.isPunct("[") {
			p.skipBalanced("[", "]")
		}
		ev := &Entry{Kind: "enumvalue", Name: nameTok.Text, Line: nameTok.Line, File: p.file, Prot: Public}
		if p.isPunct("=") {
			p.next()
			var parts []string
			depth := 0
			for !p.atEOF() {
				tt := p.peek()
				if tt.Kind == TokDocComment {
					break
				}
				if tt.Kind == TokPunct {
					if tt.Text == "(" || tt.Text == "{" || tt.Text == "[" {
						depth++
					} else if tt.Text == ")" || tt.Text == "}" || tt.Text == "]" {
						if depth == 0 {
							break
						}
						depth--
					} else if tt.Text == "," && depth == 0 {
						break
					}
				}
				parts = append(parts, p.next().Text)
			}
			ev.Initializer = "= " + joinTokens(parts)
		}
		p.attachPendingDocs(ev)
		e.addChild(ev)
		p.lastEntry = ev
		if p.isPunct(",") {
			p.next()
		}
	}
}

// parseDeclaration parses a general declaration (function, variable, ...).
func (p *CParser) parseDeclaration(scope *Entry, scopeKind string, prot Protection, tlist []*ArgumentList) {
	p.parseDeclarationWithPrefix(scope, scopeKind, prot, tlist, "", p.peek().Line)
}

func (p *CParser) parseDeclarationWithPrefix(scope *Entry, scopeKind string, prot Protection, tlist []*ArgumentList, prefix string, startLine int) {
	var toks []Token
	if prefix != "" {
		for _, part := range strings.Fields(prefix) {
			toks = append(toks, Token{Kind: TokIdent, Text: part, Line: startLine})
		}
	}
	line := startLine
	bodyStart, bodyEnd := -1, -1
	hasBody := false
	var trailingDoc *Token
	depth := 0
	for !p.atEOF() {
		t := p.peek()
		if t.Kind == TokDocComment {
			if t.After && len(toks) > 0 {
				// trailing doc inside the declaration (e.g. after '(' or ',') - attach to decl
				tt := p.next()
				trailingDoc = tt
				continue
			}
			if !t.After {
				// a doc comment in the middle of a declaration: treat as end of this (broken) declaration
				if len(toks) == 0 {
					return
				}
				break
			}
			p.next()
			continue
		}
		if t.Kind == TokPreproc {
			p.next()
			p.handlePreproc(scope, *t)
			continue
		}
		if t.Kind == TokPunct {
			switch t.Text {
			case ";":
				if depth == 0 {
					p.next()
					goto done
				}
			case "{":
				if depth == 0 {
					// function body or initializer list
					if isInitializerBrace(toks) {
						// brace initializer: collect as part of tokens
						start := p.pos
						p.skipBalanced("{", "}")
						for i := start; i < p.pos; i++ {
							toks = append(toks, p.toks[i])
						}
						continue
					}
					bodyStart = t.Line
					bodyEnd = p.skipBalanced("{", "}")
					hasBody = true
					// K&R style or function try block ignored
					if p.isPunct(";") {
						p.next()
					}
					goto done
				}
			case "(", "[", "<":
				if t.Text == "<" && !isTemplateContext(toks) {
					break
				}
				depth++
			case ")", "]", ">":
				if t.Text == ">" && depth == 0 {
					break
				}
				depth--
			case "}":
				if depth == 0 {
					// end of enclosing scope: stop
					goto done
				}
			}
		}
		toks = append(toks, *p.next())
		if len(toks) == 1 {
			line = toks[0].Line
		}
	}
done:
	// trailing doc on the same line after ';'
	if p.peek().Kind == TokDocComment && p.peek().After {
		td := p.next()
		trailingDoc = td
	}
	if len(toks) == 0 {
		return
	}
	entries := p.analyzeDeclaration(toks, scope, scopeKind, prot, tlist, line)
	for i, e := range entries {
		if hasBody {
			e.BodyStart = bodyStart
			e.BodyEnd = bodyEnd
		}
		if i == 0 {
			p.attachPendingDocs(e)
		}
		if trailingDoc != nil && i == len(entries)-1 {
			p.d.handleDocComment(e, *trailingDoc, p.file, true)
		}
		scope.addChild(e)
		p.lastEntry = e
	}
	if len(entries) == 0 {
		p.pendingDocs = nil
		p.lastEntry = nil
	}
	p.pendingDocs = nil
}

func isTemplateContext(toks []Token) bool {
	// '<' follows an identifier that is likely a template name
	if len(toks) == 0 {
		return false
	}
	last := toks[len(toks)-1]
	if last.Kind == TokIdent {
		switch last.Text {
		case "operator", "return", "sizeof":
			return false
		}
		return true
	}
	return last.Kind == TokPunct && (last.Text == "::" || last.Text == ">")
}

// isInitializerBrace decides whether a '{' at depth 0 starts an initializer rather than a body.
func isInitializerBrace(toks []Token) bool {
	if len(toks) == 0 {
		return false
	}
	// look for '=' at top level (variable initializer) or a declarator name directly followed by '{'
	depth := 0
	parenSeen := false
	for _, t := range toks {
		if t.Kind == TokPunct {
			switch t.Text {
			case "(", "[":
				depth++
				if t.Text == "(" && depth == 1 {
					parenSeen = true
				}
			case ")", "]":
				depth--
			case "=":
				if depth == 0 {
					return true
				}
			}
		}
	}
	last := toks[len(toks)-1]
	if last.Kind == TokIdent && !parenSeen {
		// `Type name{...}` direct-list-initialization (not a function)
		switch last.Text {
		case "const", "override", "final", "noexcept", "try", "volatile", "constexpr":
			return false
		}
		return true
	}
	return false
}

// analyzeDeclaration splits a declaration token list into one or more entries.
func (p *CParser) analyzeDeclaration(toks []Token, scope *Entry, scopeKind string, prot Protection, tlist []*ArgumentList, line int) []*Entry {
	// strip attributes [[...]] and __attribute__((...))
	toks = stripAttributes(toks)
	if len(toks) == 0 {
		return nil
	}
	// determine if this is a function: find top-level '(' that is followed by a parameter list
	if isFunctionDecl(toks) {
		e := p.analyzeFunction(toks, scope, scopeKind, prot, tlist, line)
		if e != nil {
			return []*Entry{e}
		}
		return nil
	}
	// variable(s)
	var entries []*Entry
	decls := splitDeclarators(toks)
	for _, dcl := range decls {
		e := p.analyzeVariable(dcl, scope, scopeKind, prot, line)
		if e != nil {
			e.TArgLists = tlist
			entries = append(entries, e)
		}
	}
	return entries
}

func stripAttributes(toks []Token) []Token {
	var out []Token
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		if t.Kind == TokPunct && t.Text == "[" && i+1 < len(toks) && toks[i+1].Kind == TokPunct && toks[i+1].Text == "[" {
			depth := 0
			for ; i < len(toks); i++ {
				if toks[i].Kind == TokPunct && toks[i].Text == "[" {
					depth++
				} else if toks[i].Kind == TokPunct && toks[i].Text == "]" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			continue
		}
		if t.Kind == TokIdent && (t.Text == "__attribute__" || t.Text == "__declspec" || t.Text == "alignas" || t.Text == "__asm__" || t.Text == "asm") && i+1 < len(toks) && toks[i+1].Kind == TokPunct && toks[i+1].Text == "(" {
			depth := 0
			i++
			for ; i < len(toks); i++ {
				if toks[i].Kind == TokPunct && toks[i].Text == "(" {
					depth++
				} else if toks[i].Kind == TokPunct && toks[i].Text == ")" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			continue
		}
		out = append(out, t)
	}
	return out
}

// isFunctionDecl checks whether the declaration contains a parameter list.
func isFunctionDecl(toks []Token) bool {
	depth := 0
	angle := 0
	for i, t := range toks {
		if t.Kind != TokPunct {
			continue
		}
		switch t.Text {
		case "<":
			if i > 0 && isTemplateContext(toks[:i]) {
				angle++
			}
		case ">":
			if angle > 0 {
				angle--
			}
		case "=":
			if depth == 0 && angle == 0 {
				// `= 0`, `= default`, `= delete` after ')' is fine; '=' before '(' means variable init
				if i > 0 && toks[i-1].Kind == TokPunct && toks[i-1].Text == ")" {
					return true
				}
				// check whether a '(' occurred before at depth 0 with an identifier before it
				return false
			}
		case "(":
			if depth == 0 && angle == 0 {
				// identifier (or operator) before '(' => function; `(*name)` pointer-to-function => function pointer variable
				if i > 0 {
					prev := toks[i-1]
					if prev.Kind == TokIdent && prev.Text != "decltype" && prev.Text != "sizeof" && prev.Text != "alignof" && prev.Text != "typeof" && prev.Text != "__typeof__" {
						// make sure the '(' is not a function-style cast in an initializer; fine for declarations
						return !isPointerToFunction(toks, i)
					}
					if prev.Kind == TokPunct && prev.Text == ">" {
						return !isPointerToFunction(toks, i)
					}
					if prev.Kind == TokPunct && prev.Text == "operator" {
						return true
					}
				}
			}
			depth++
		case ")":
			depth--
		}
	}
	return false
}

// isPointerToFunction checks patterns like `int (*fp)(int)`.
func isPointerToFunction(toks []Token, parenIdx int) bool {
	if parenIdx+1 < len(toks) && toks[parenIdx+1].Kind == TokPunct && (toks[parenIdx+1].Text == "*" || toks[parenIdx+1].Text == "&" || toks[parenIdx+1].Text == "^") {
		// `(*name)` form: followed later by another '('
		return true
	}
	return false
}

// splitDeclarators splits `int a, *b = 3, c[4]` into separate declarator token lists,
// each including the common type prefix.
func splitDeclarators(toks []Token) [][]Token {
	// find the top-level commas
	var groups [][]Token
	depth := 0
	angle := 0
	start := 0
	for i, t := range toks {
		if t.Kind == TokPunct {
			switch t.Text {
			case "(", "[", "{":
				depth++
			case ")", "]", "}":
				depth--
			case "<":
				if i > 0 && isTemplateContext(toks[:i]) {
					angle++
				}
			case ">":
				if angle > 0 {
					angle--
				}
			case ",":
				if depth == 0 && angle == 0 {
					groups = append(groups, toks[start:i])
					start = i + 1
				}
			}
		}
	}
	groups = append(groups, toks[start:])
	if len(groups) == 1 {
		return groups
	}
	// the type prefix is the part of the first group before the declarator
	first := groups[0]
	typeLen := typePrefixLength(first)
	prefix := first[:typeLen]
	result := [][]Token{first}
	for _, g := range groups[1:] {
		ng := append(append([]Token{}, prefix...), g...)
		result = append(result, ng)
	}
	return result
}

// typePrefixLength determines how many leading tokens form the type (before pointer/ref/name).
func typePrefixLength(toks []Token) int {
	// find the declared name: last identifier at depth 0 that is not followed by '::' and before '=', '[', ':' or end
	nameIdx := findDeclaratorName(toks)
	if nameIdx < 0 {
		return len(toks)
	}
	// back up over '*', '&', '&&', 'const' pointer qualifiers
	i := nameIdx
	for i > 0 {
		pt := toks[i-1]
		if pt.Kind == TokPunct && (pt.Text == "*" || pt.Text == "&" || pt.Text == "&&" || pt.Text == "^") {
			i--
			continue
		}
		if pt.Kind == TokIdent && (pt.Text == "const" || pt.Text == "volatile" || pt.Text == "restrict" || pt.Text == "__restrict") && i-1 > 0 && toks[i-2].Kind == TokPunct && (toks[i-2].Text == "*" || toks[i-2].Text == "&") {
			i--
			continue
		}
		break
	}
	return i
}

// findDeclaratorName finds the index of the declared identifier in a variable/typedef declarator.
func findDeclaratorName(toks []Token) int {
	depth := 0
	angle := 0
	last := -1
	for i, t := range toks {
		if t.Kind == TokPunct {
			switch t.Text {
			case "(", "[", "{":
				if depth == 0 && angle == 0 && last >= 0 && (t.Text == "[" || t.Text == "(" || t.Text == "{") {
					// name found before array/initializer/bitfield
					if t.Text == "(" && i > 0 && toks[i-1].Kind == TokPunct && toks[i-1].Text == ")" {
						// `(*name)(args)` -> name already found inside
					}
					if last >= 0 && t.Text != "(" {
						return last
					}
				}
				depth++
				continue
			case ")", "]", "}":
				depth--
				continue
			case "<":
				if i > 0 && isTemplateContext(toks[:i]) {
					angle++
				}
				continue
			case ">":
				if angle > 0 {
					angle--
				}
				continue
			case "=", ":":
				if depth == 0 && angle == 0 && last >= 0 {
					return last
				}
			}
		}
		if t.Kind == TokIdent && angle == 0 {
			if depth == 0 {
				if isTypeKeyword(t.Text) {
					continue
				}
				// skip identifiers followed by '::'
				if i+1 < len(toks) && toks[i+1].Kind == TokPunct && toks[i+1].Text == "::" {
					continue
				}
				last = i
			} else if depth == 1 && i > 0 && toks[i-1].Kind == TokPunct && (toks[i-1].Text == "*" || toks[i-1].Text == "&" || toks[i-1].Text == "^") {
				// `(*name)` pointer-to-function
				if i+1 < len(toks) && toks[i+1].Kind == TokPunct && (toks[i+1].Text == ")" || toks[i+1].Text == "[") {
					return i
				}
			}
		}
	}
	return last
}

var typeKeywords = map[string]bool{
	"const": true, "volatile": true, "static": true, "extern": true, "inline": true, "mutable": true, "register": true,
	"unsigned": true, "signed": true, "short": true, "long": true, "int": true, "char": true, "float": true, "double": true,
	"void": true, "bool": true, "struct": true, "class": true, "union": true, "enum": true, "typename": true, "constexpr": true,
	"constinit": true, "consteval": true, "thread_local": true, "virtual": true, "explicit": true, "friend": true, "typedef": true,
	"auto": true, "wchar_t": true, "char8_t": true, "char16_t": true, "char32_t": true, "restrict": true, "__restrict": true,
	"_Bool": true, "_Complex": true, "__int64": true, "__int32": true, "export": true, "final": true, "override": true,
}

func isTypeKeyword(s string) bool {
	switch s {
	case "final", "override":
		return false
	}
	return typeKeywords[s]
}

// analyzeDeclarator splits declarator tokens into type, name and args (array/bitfield/function-pointer args).
func analyzeDeclarator(toks []Token, isFunc bool) (string, string, string) {
	toks = stripAttributes(toks)
	if len(toks) == 0 {
		return "", "", ""
	}
	// remove initializer
	if idx := indexOfTok(toks, "="); idx >= 0 {
		toks = toks[:idx]
	}
	nameIdx := findDeclaratorName(toks)
	if nameIdx < 0 {
		return joinTokenTexts(toks), "", ""
	}
	name := toks[nameIdx].Text
	// pointer-to-function: int (*name)(args)
	if nameIdx > 0 && toks[nameIdx-1].Kind == TokPunct && (toks[nameIdx-1].Text == "*" || toks[nameIdx-1].Text == "&" || toks[nameIdx-1].Text == "^") && nameIdx+1 < len(toks) && toks[nameIdx+1].Kind == TokPunct && toks[nameIdx+1].Text == ")" {
		// find the '(' before
		open := nameIdx - 1
		for open >= 0 && !(toks[open].Kind == TokPunct && toks[open].Text == "(") {
			open--
		}
		if open >= 0 {
			typ := joinTokenTexts(toks[:open]) + "(" + joinTokenTexts(toks[open+1:nameIdx]) + ")"
			typ = joinTokenTexts(toks[:open]) + "(" + joinTokenTexts(toks[open+1:nameIdx])
			args := joinTokenTexts(toks[nameIdx+1:])
			return typ, name, args
		}
	}
	typ := joinTokenTexts(toks[:nameIdx])
	args := ""
	if nameIdx+1 < len(toks) {
		rest := toks[nameIdx+1:]
		if rest[0].Kind == TokPunct && rest[0].Text == ":" {
			// bitfield handled by caller
			args = joinTokenTexts(rest)
		} else {
			args = joinTokenTexts(rest)
		}
	}
	return typ, name, args
}

func (p *CParser) analyzeVariable(toks []Token, scope *Entry, scopeKind string, prot Protection, line int) *Entry {
	e := &Entry{Kind: "variable", Line: line, File: p.file, Prot: prot}
	if len(toks) > 0 {
		e.Line = toks[0].Line
	}
	// initializer
	var init []Token
	if idx := indexOfTok(toks, "="); idx >= 0 {
		init = toks[idx+1:]
		toks = toks[:idx]
	} else if len(toks) > 0 && toks[len(toks)-1].Kind == TokPunct && toks[len(toks)-1].Text == "}" {
		// brace initializer: find the matching '{'
		depth := 0
		for i := len(toks) - 1; i >= 0; i-- {
			if toks[i].Kind == TokPunct && toks[i].Text == "}" {
				depth++
			} else if toks[i].Kind == TokPunct && toks[i].Text == "{" {
				depth--
				if depth == 0 {
					init = toks[i:]
					toks = toks[:i]
					break
				}
			}
		}
	}
	// bitfield
	if idx := indexOfTok(toks, ":"); idx >= 0 && !(idx+1 < len(toks) && toks[idx+1].Kind == TokPunct && toks[idx+1].Text == ":") {
		e.Bitfield = ": " + joinTokenTexts(toks[idx+1:])
		toks = toks[:idx]
	}
	// strip specifiers
	var rest []Token
	for _, t := range toks {
		if t.Kind == TokIdent {
			switch t.Text {
			case "static":
				e.Static = true
				continue
			case "extern":
				e.Extern = true
				continue
			case "mutable":
				e.Mutable = true
				continue
			case "constexpr":
				e.ConstExpr = true
				rest = append(rest, t)
				continue
			case "inline":
				e.Inline = true
				continue
			case "thread_local", "register":
				continue
			case "typename":
				continue
			}
		}
		rest = append(rest, t)
	}
	typ, name, args := analyzeDeclarator(rest, false)
	if name == "" {
		return nil
	}
	e.Name = name
	e.Type = typ
	e.Args = args
	if len(init) > 0 {
		if init[0].Kind == TokPunct && init[0].Text == "{" {
			e.Initializer = joinTokenTexts(init)
		} else {
			e.Initializer = "= " + joinTokenTexts(init)
		}
	}
	return e
}

// analyzeFunction builds a function entry from declaration tokens.
func (p *CParser) analyzeFunction(toks []Token, scope *Entry, scopeKind string, prot Protection, tlist []*ArgumentList, line int) *Entry {
	e := &Entry{Kind: "function", Line: line, File: p.file, Prot: prot, TArgLists: tlist}
	if len(toks) > 0 {
		e.Line = toks[0].Line
	}
	// find the parameter list '(' : first '(' at depth 0 preceded by identifier/operator/'>'
	parenIdx := -1
	depth := 0
	angle := 0
	for i, t := range toks {
		if t.Kind != TokPunct {
			continue
		}
		switch t.Text {
		case "<":
			if i > 0 && isTemplateContext(toks[:i]) {
				angle++
			}
		case ">":
			if angle > 0 {
				angle--
			}
		case "(":
			if depth == 0 && angle == 0 && i > 0 {
				prev := toks[i-1]
				if (prev.Kind == TokIdent && prev.Text != "decltype") || (prev.Kind == TokPunct && prev.Text == ">") || (prev.Kind == TokPunct && isOperatorEnd(toks, i)) {
					if !isPointerToFunction(toks, i) {
						parenIdx = i
					}
				}
			}
			if parenIdx >= 0 {
				break
			}
			depth++
		case ")":
			depth--
		}
		if parenIdx >= 0 {
			break
		}
	}
	if parenIdx < 0 {
		return nil
	}
	// find matching ')'
	closeIdx := -1
	depth = 0
	for i := parenIdx; i < len(toks); i++ {
		if toks[i].Kind == TokPunct {
			if toks[i].Text == "(" {
				depth++
			} else if toks[i].Text == ")" {
				depth--
				if depth == 0 {
					closeIdx = i
					break
				}
			}
		}
	}
	if closeIdx < 0 {
		return nil
	}
	// name: tokens before '(' back to the start of the qualified name
	nameEnd := parenIdx
	nameStart := nameEnd - 1
	// operator functions
	opIdx := -1
	for i := nameStart; i >= 0; i-- {
		if toks[i].Kind == TokIdent && toks[i].Text == "operator" {
			opIdx = i
			break
		}
		if toks[i].Kind == TokPunct && (toks[i].Text == "::" || toks[i].Text == "<" || toks[i].Text == ">" || toks[i].Text == "," || toks[i].Text == "~" || toks[i].Text == "*" || toks[i].Text == "&" || toks[i].Text == "[" || toks[i].Text == "]" || toks[i].Text == "(" || toks[i].Text == ")" || toks[i].Text == "+" || toks[i].Text == "-" || toks[i].Text == "==" || toks[i].Text == "!=" || toks[i].Text == "<=" || toks[i].Text == ">=" || toks[i].Text == "=" || toks[i].Text == "!" || toks[i].Text == "+=" || toks[i].Text == "-=" || toks[i].Text == "*=" || toks[i].Text == "/=" || toks[i].Text == "/" || toks[i].Text == "%" || toks[i].Text == "^" || toks[i].Text == "|" || toks[i].Text == "||" || toks[i].Text == "&&" || toks[i].Text == "<<" || toks[i].Text == ">>" || toks[i].Text == "->" || toks[i].Text == "->*" || toks[i].Text == "++" || toks[i].Text == "--" || toks[i].Text == "<=>" || toks[i].Text == "<<=" || toks[i].Text == ">>=" || toks[i].Text == "%=" || toks[i].Text == "^=" || toks[i].Text == "|=" || toks[i].Text == "&=") {
			continue
		}
		if toks[i].Kind == TokIdent {
			continue
		}
		break
	}
	if opIdx >= 0 {
		nameStart = opIdx
		// include preceding scope qualifiers
		for nameStart >= 2 && toks[nameStart-1].Kind == TokPunct && toks[nameStart-1].Text == "::" {
			nameStart -= 2
			// template args in scope e.g. A<int>::
			for nameStart > 0 && toks[nameStart].Kind == TokPunct && toks[nameStart].Text == ">" {
				d := 0
				j := nameStart
				for j >= 0 {
					if toks[j].Kind == TokPunct && toks[j].Text == ">" {
						d++
					} else if toks[j].Kind == TokPunct && toks[j].Text == "<" {
						d--
						if d == 0 {
							break
						}
					}
					j--
				}
				nameStart = j - 1
			}
		}
	} else {
		// walk back over Name, ::, template args, ~
		i := parenIdx - 1
		if i >= 0 && toks[i].Kind == TokPunct && toks[i].Text == ">" {
			// template id: skip back to matching '<'
			d := 0
			for i >= 0 {
				if toks[i].Kind == TokPunct && toks[i].Text == ">" {
					d++
				} else if toks[i].Kind == TokPunct && toks[i].Text == "<" {
					d--
					if d == 0 {
						break
					}
				}
				i--
			}
			i--
		}
		// now toks[i] should be an identifier
		nameStart = i
		for nameStart > 0 {
			if toks[nameStart-1].Kind == TokPunct && toks[nameStart-1].Text == "~" {
				nameStart--
				continue
			}
			if toks[nameStart-1].Kind == TokPunct && toks[nameStart-1].Text == "::" {
				nameStart--
				if nameStart > 0 && toks[nameStart-1].Kind == TokPunct && toks[nameStart-1].Text == ">" {
					d := 0
					j := nameStart - 1
					for j >= 0 {
						if toks[j].Kind == TokPunct && toks[j].Text == ">" {
							d++
						} else if toks[j].Kind == TokPunct && toks[j].Text == "<" {
							d--
							if d == 0 {
								break
							}
						}
						j--
					}
					nameStart = j
				}
				if nameStart > 0 && toks[nameStart-1].Kind == TokIdent {
					nameStart--
					continue
				}
				break
			}
			break
		}
		if nameStart < 0 {
			nameStart = 0
		}
	}
	nameToks := toks[nameStart:nameEnd]
	typeToks := toks[:nameStart]
	// specifiers in type
	var typeRest []Token
	for _, t := range typeToks {
		if t.Kind == TokIdent {
			switch t.Text {
			case "static":
				e.Static = true
				continue
			case "virtual":
				e.Virtual = true
				continue
			case "explicit":
				e.Explicit = true
				continue
			case "inline":
				e.Inline = true
				continue
			case "constexpr":
				e.ConstExpr = true
				typeRest = append(typeRest, t)
				continue
			case "consteval", "constinit":
				typeRest = append(typeRest, t)
				continue
			case "extern":
				e.Extern = true
				continue
			case "friend":
				e.Friend = true
				continue
			case "typename":
				continue
			}
		}
		typeRest = append(typeRest, t)
	}
	e.Name = joinTokenTexts(nameToks)
	e.Name = strings.ReplaceAll(e.Name, "operator ", "operator")
	if strings.HasPrefix(e.Name, "operator") && len(e.Name) > 8 && (isIdentStart(e.Name[8])) {
		// conversion operator: keep a space
		e.Name = "operator " + e.Name[8:]
	}
	e.Type = joinTokenTexts(typeRest)
	argToks := toks[parenIdx : closeIdx+1]
	e.Args = formatArgs(argToks)
	e.ArgList = parseArgList(e.Args)
	// trailing specifiers
	trailing := toks[closeIdx+1:]
	var trailParts []string
	for i := 0; i < len(trailing); i++ {
		t := trailing[i]
		if t.Kind == TokIdent {
			switch t.Text {
			case "const":
				e.Const = true
				trailParts = append(trailParts, "const")
				continue
			case "volatile":
				e.Volatile = true
				trailParts = append(trailParts, "volatile")
				continue
			case "override":
				e.Override = true
				continue
			case "final":
				e.Final = true
				continue
			case "noexcept":
				e.NoExcept = true
				trailParts = append(trailParts, "noexcept")
				if i+1 < len(trailing) && trailing[i+1].Kind == TokPunct && trailing[i+1].Text == "(" {
					// noexcept(expr)
					d := 0
					j := i + 1
					var parts []string
					for ; j < len(trailing); j++ {
						parts = append(parts, trailing[j].Text)
						if trailing[j].Kind == TokPunct && trailing[j].Text == "(" {
							d++
						} else if trailing[j].Kind == TokPunct && trailing[j].Text == ")" {
							d--
							if d == 0 {
								break
							}
						}
					}
					trailParts[len(trailParts)-1] = "noexcept" + joinTokens(parts)
					i = j
				}
				continue
			case "throw":
				if i+1 < len(trailing) && trailing[i+1].Kind == TokPunct && trailing[i+1].Text == "(" {
					d := 0
					j := i + 1
					var parts []string
					for ; j < len(trailing); j++ {
						parts = append(parts, trailing[j].Text)
						if trailing[j].Kind == TokPunct && trailing[j].Text == "(" {
							d++
						} else if trailing[j].Kind == TokPunct && trailing[j].Text == ")" {
							d--
							if d == 0 {
								break
							}
						}
					}
					e.Exception = "throw" + joinTokens(parts)
					trailParts = append(trailParts, e.Exception)
					i = j
				}
				continue
			case "requires":
				var parts []string
				for j := i + 1; j < len(trailing); j++ {
					parts = append(parts, trailing[j].Text)
				}
				e.Requires = joinTokens(parts)
				i = len(trailing)
				continue
			case "try":
				continue
			}
		}
		if t.Kind == TokPunct {
			switch t.Text {
			case "=":
				if i+1 < len(trailing) {
					v := trailing[i+1].Text
					switch v {
					case "0":
						e.PureVirtual = true
						e.Virtual = true
						trailParts = append(trailParts, "=0")
					case "default":
						e.Default = true
						trailParts = append(trailParts, "=default")
					case "delete":
						e.Delete = true
						trailParts = append(trailParts, "=delete")
					}
					i++
				}
				continue
			case "&":
				e.ArgList.RefQual = "&"
				trailParts = append(trailParts, "&")
				continue
			case "&&":
				e.ArgList.RefQual = "&&"
				trailParts = append(trailParts, "&&")
				continue
			case "->":
				// trailing return type
				var parts []string
				j := i + 1
				for ; j < len(trailing); j++ {
					tt := trailing[j]
					if tt.Kind == TokIdent && (tt.Text == "override" || tt.Text == "final" || tt.Text == "requires") {
						break
					}
					if tt.Kind == TokPunct && tt.Text == "=" {
						break
					}
					parts = append(parts, tt.Text)
				}
				e.ArgList.TrailingRet = joinTokens(parts)
				trailParts = append(trailParts, "-> "+e.ArgList.TrailingRet)
				i = j - 1
				continue
			case ":":
				// constructor initializer list without body (shouldn't happen) - stop
				i = len(trailing)
				continue
			}
		}
	}
	if len(trailParts) > 0 {
		e.Args += " " + strings.Join(trailParts, " ")
	}
	if e.ArgList != nil {
		e.ArgList.ConstSpec = e.Const
		e.ArgList.VolatileSpec = e.Volatile
		e.ArgList.PureSpec = e.PureVirtual
	}
	// constructors/destructors: name equals class name
	if scopeKind == "class" {
		baseName := scope.Name
		if i := strings.Index(baseName, "<"); i >= 0 {
			baseName = baseName[:i]
		}
		n := e.Name
		if strings.HasPrefix(n, "~") {
			n = n[1:]
		}
		if n == baseName && strings.TrimSpace(e.Type) == "" {
			// ctor/dtor
		}
	}
	return e
}

func isOperatorEnd(toks []Token, i int) bool {
	// check whether tokens before i form `operator <symbols>`
	for j := i - 1; j >= 0 && j >= i-3; j-- {
		if toks[j].Kind == TokIdent && toks[j].Text == "operator" {
			return true
		}
		if toks[j].Kind == TokIdent {
			return false
		}
	}
	return false
}

// formatArgs formats parameter list tokens the way doxygen does: "(int a, char *b)".
func formatArgs(toks []Token) string {
	if len(toks) < 2 {
		return "()"
	}
	inner := toks[1 : len(toks)-1]
	if len(inner) == 0 {
		return "()"
	}
	// split on top-level commas
	var params []string
	depth := 0
	start := 0
	for i, t := range inner {
		if t.Kind == TokPunct {
			switch t.Text {
			case "(", "[", "{", "<":
				depth++
			case ")", "]", "}", ">":
				depth--
			case ",":
				if depth == 0 {
					params = append(params, formatParam(inner[start:i]))
					start = i + 1
				}
			}
		}
	}
	params = append(params, formatParam(inner[start:]))
	return "(" + strings.Join(params, ", ") + ")"
}

func formatParam(toks []Token) string {
	parts := make([]string, len(toks))
	for i, t := range toks {
		parts[i] = t.Text
	}
	return joinTokens(parts)
}

// parseArgList converts an argument string "(int a, char *b=0)" into an ArgumentList.
func parseArgList(args string) *ArgumentList {
	al := &ArgumentList{Valid: true}
	s := strings.TrimSpace(args)
	if !strings.HasPrefix(s, "(") {
		return al
	}
	// find matching ')'
	depth := 0
	end := -1
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '(', '[', '{', '<':
			depth++
		case ')', ']', '}', '>':
			depth--
			if depth == 0 && s[i] == ')' {
				end = i
			}
		}
		if end >= 0 {
			break
		}
	}
	if end < 0 {
		end = len(s)
	}
	inner := strings.TrimSpace(s[1:end])
	if inner == "" || inner == "void" {
		al.NoParams = true
		return al
	}
	// split on top-level commas
	var params []string
	depth = 0
	start := 0
	for i := 0; i < len(inner); i++ {
		switch inner[i] {
		case '(', '[', '{', '<':
			depth++
		case ')', ']', '}', '>':
			depth--
		case ',':
			if depth == 0 {
				params = append(params, inner[start:i])
				start = i + 1
			}
		}
	}
	params = append(params, inner[start:])
	for _, ps := range params {
		ps = strings.TrimSpace(ps)
		a := &Argument{}
		if idx := indexTopLevel(ps, '='); idx >= 0 {
			a.DefVal = strings.TrimSpace(ps[idx+1:])
			ps = strings.TrimSpace(ps[:idx])
		}
		if ps == "..." {
			a.Type = "..."
			al.Args = append(al.Args, a)
			continue
		}
		// array suffix
		if idx := strings.IndexByte(ps, '['); idx >= 0 && !strings.Contains(ps[:idx], "(") {
			a.Array = strings.TrimSpace(ps[idx:])
			ps = strings.TrimSpace(ps[:idx])
		}
		// function pointer param: type (*name)(args)
		if idx := strings.Index(ps, "(*"); idx >= 0 {
			close := strings.IndexByte(ps[idx:], ')')
			if close >= 0 {
				a.Name = strings.TrimSpace(ps[idx+2 : idx+close])
				a.Type = strings.TrimSpace(ps[:idx]) + "(*"
				a.Array = ")" + ps[idx+close+1:]
				al.Args = append(al.Args, a)
				continue
			}
		}
		toks := tokenizeSource([]byte(ps), "cpp")
		// name is the last identifier if preceded by a type
		var texts []Token
		for _, t := range toks {
			if t.Kind != TokEOF {
				texts = append(texts, t)
			}
		}
		if len(texts) >= 2 && texts[len(texts)-1].Kind == TokIdent && !isTypeKeyword(texts[len(texts)-1].Text) {
			prev := texts[len(texts)-2]
			if !(prev.Kind == TokPunct && prev.Text == "::") {
				a.Name = texts[len(texts)-1].Text
				a.Type = joinTokenTexts(texts[:len(texts)-1])
			} else {
				a.Type = ps
			}
		} else {
			a.Type = ps
		}
		if a.Type == "" {
			a.Type = a.Name
			a.Name = ""
		}
		al.Args = append(al.Args, a)
	}
	return al
}

func indexTopLevel(s string, c byte) int {
	depth := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '(', '[', '{', '<':
			depth++
		case ')', ']', '}', '>':
			depth--
		default:
			if s[i] == c && depth == 0 {
				return i
			}
		}
	}
	return -1
}

// parseTemplateArgs parses "typename T, int N = 3" into an ArgumentList.
func parseTemplateArgs(text string) *ArgumentList {
	al := &ArgumentList{Valid: true}
	text = strings.TrimSpace(text)
	if text == "" {
		return al
	}
	var params []string
	depth := 0
	start := 0
	for i := 0; i < len(text); i++ {
		switch text[i] {
		case '(', '[', '{', '<':
			depth++
		case ')', ']', '}', '>':
			depth--
		case ',':
			if depth == 0 {
				params = append(params, text[start:i])
				start = i + 1
			}
		}
	}
	params = append(params, text[start:])
	for _, ps := range params {
		ps = strings.TrimSpace(ps)
		a := &Argument{}
		if idx := indexTopLevel(ps, '='); idx >= 0 {
			a.DefVal = strings.TrimSpace(ps[idx+1:])
			ps = strings.TrimSpace(ps[:idx])
		}
		fields := strings.Fields(ps)
		if len(fields) >= 2 {
			a.Name = fields[len(fields)-1]
			a.Type = strings.Join(fields[:len(fields)-1], " ")
			if strings.HasSuffix(a.Type, "...") {
				// variadic pack: keep as is
			}
		} else {
			a.Type = ps
		}
		al.Args = append(al.Args, a)
	}
	return al
}
