// cleanComment removes comment decorations (leading '*' on each line) from a doc comment body.
func cleanComment(body string, lineStyle bool) string {
	lines := strings.Split(body, "\n")
	if lineStyle {
		// each line is the text after /// or //!
		return strings.Join(lines, "\n")
	}
	for i, l := range lines {
		if i == 0 {
			continue
		}
		// strip leading whitespace followed by one or more '*'
		j := 0
		for j < len(l) && (l[j] == ' ' || l[j] == '\t') {
			j++
		}
		if j < len(l) && l[j] == '*' {
			k := j
			for k < len(l) && l[k] == '*' {
				k++
			}
			if k < len(l) && l[k] == '/' {
				// "*/" should not occur; keep
			}
			lines[i] = l[k:]
		}
	}
	return strings.Join(lines, "\n")
}

