	"subparagraph": true, "subsubparagraph": true, "li": true, "arg": true, "htmlonly": true, "latexonly": true, "xmlonly": true, "manonly": true,
	"rtfonly": true, "docbookonly": true, "copydetails": true, "copydoc": true, "xrefitem": true, "refitem": true, "dotfile": true,
	"mscfile": true, "diafile": true, "f[": true, "f{": true, "ifile": true, "iline": true, "tableofcontents": true, "parblock": true,
	"snippet": true, "include": true, "dontinclude": true, "verbinclude": true, "htmlinclude": true, "latexinclude": true,
	"skip": true, "skipline": true, "until": true, "line": true, "secreflist": true, "anchor": false, "inbody": true,
	"plantumlfile": true, "doxyconfig": false, "showdate": false, "cite": false,
}

// structural commands (handled by the comment scanner rather than the doc parser)
var structuralCmds = map[string]bool{
	"file": true, "class": true, "struct": true, "union": true, "enum": true, "fn": true, "var": true, "typedef": true,
	"def": true, "namespace": true, "interface": true, "protocol": true, "category": true, "package": true,
	"property": true, "overload": true, "page": true, "mainpage": true, "defgroup": true, "addtogroup": true, "weakgroup": true,
	"ingroup": true, "name": true, "dir": true, "example": true, "relates": true, "relatesalso": true, "related": true, "relatedalso": true, "memberof": true,
	"private": true, "protected": true, "public": true, "privatesection": true, "protectedsection": true, "publicsection": true,
	"static": true, "pure": true, "extends": true, "implements": true, "headerfile": true, "nosubgrouping": true,
	"showinitializer": true, "hideinitializer": true, "callgraph": true, "callergraph": true, "hidecallgraph": true, "hidecallergraph": true,
	"internal": true, "endinternal": true, "brief": true, "short": true, "details": true, "concept": true, "module": true,
	"idlexcept": true, "cond": true, "endcond": true, "showrefby": true, "hiderefby": true, "showrefs": true, "hiderefs": true,
	"showenumvalues": true, "hideenumvalues": true, "showinlinesource": true, "hideinlinesource": true, "qualifier": true,
	"language": true, "requirement": true, "satisfies": true, "verifies": true, "inheritancegraph": true, "groupgraph": true, "hidegroupgraph": true, "directorygraph": true, "hidedirectorygraph": true, "includegraph": true, "hideincludegraph": true, "includedbygraph": true, "hideincludedbygraph": true, "collaborationgraph": true, "hidecollaborationgraph": true, "enumvalues": true,
}

// isStandaloneDoc checks whether a doc comment documents a named entity (and thus should not
// be attached to the following declaration).
func (d *Doxygen) isStandaloneDoc(text string) bool {
	cleaned := cleanComment(text, false)
	for _, l := range strings.Split(cleaned, "\n") {
		s := strings.TrimSpace(l)
		if s == "" {
			continue
		}
		for s != "" {
			m := cmdRe.FindStringSubmatch(s)
			if m == nil {
				break
			}
			switch m[1] {
			case "file", "class", "struct", "union", "enum", "fn", "var", "typedef", "def", "namespace", "interface", "protocol", "category", "package", "property", "page", "mainpage", "defgroup", "addtogroup", "weakgroup", "dir", "example", "overload", "concept", "module", "idlexcept":
				return true
			}
			break
		}
	}
	return false
}

// commentScanner processes a cleaned comment into brief/detailed documentation.
type commentScanner struct {
	d        *Doxygen
	file     string
	line     int
	brief    strings.Builder
	doc      strings.Builder
	inBrief  bool
	briefSet bool
	entry    *Entry
	// structural results
	kind      string
	name      string
	title     string
	groups    []string
	relates   string
	prot      *Protection
	static    bool
	isStatic  bool
	memberGroupStart bool
	memberGroupEnd   bool
	memberGroupName  string
	sectionName string
	inCode   bool
	inVerbatim string
	hideInit bool
	showInit bool
	stdChanged bool
	overload bool
	internal bool
	condSkip bool
	callgraph bool
	noSubgrouping bool
	briefEndsAtDot bool
	briefIsLine bool
	inbody   bool
	xrefs    []string
	anchor   string
	explicitDetails bool
	privateSec *Protection
	pure bool
	hadBriefCmd bool
	condStack []bool
}

func (cs *commentScanner) out() *strings.Builder {
	if cs.inBrief {
		return &cs.brief
	}
	return &cs.doc
}

func (cs *commentScanner) endBrief() {
	if cs.inBrief {
		cs.inBrief = false
		cs.briefSet = true
	}
}

// processComment scans the text and fills brief/doc.
func (cs *commentScanner) processComment(text string) {
	cfg := cs.d.cfg
	javadocAutoBrief := cfg.Bool("JAVADOC_AUTOBRIEF")
	qtAutoBrief := cfg.Bool("QT_AUTOBRIEF")
	_ = qtAutoBrief
	lines := strings.Split(text, "\n")
	// autobrief: first sentence becomes brief
	autoBrief := javadocAutoBrief
	if autoBrief && !cs.briefSet {
		cs.inBrief = true
		cs.briefEndsAtDot = true
	}
	for li, line := range lines {
		cs.processLine(line, li == len(lines)-1)
		cs.line++
	}
}

func (cs *commentScanner) processLine(line string, last bool) {
	// verbatim / code blocks: copy until end command
	if cs.inVerbatim != "" {
		cs.out().WriteString(line)
		cs.out().WriteString("\n")
		if strings.Contains(line, "\\"+cs.inVerbatim) || strings.Contains(line, "@"+cs.inVerbatim) {
			cs.inVerbatim = ""
		}
		return
	}
	trimmed := strings.TrimSpace(line)
	// blank line ends the brief description
	if trimmed == "" {
		if cs.inBrief && cs.brief.Len() > 0 {
			cs.endBrief()
			return
		}
		if cs.condSkip {
			return
		}
		cs.out().WriteString("\n")
		return
	}
	i := 0
	// keep leading whitespace (relevant for markdown)
	for i < len(line) {
		c := line[i]
		if (c == '\\' || c == '@') && i+1 < len(line) {
			m := cmdRe.FindStringSubmatch(line[i:])
			if m != nil {
				cmd := m[1]
				rest := line[i+len(m[0]):]
				if cs.condSkip && cmd != "endcond" && cmd != "cond" {
					i += len(m[0])
					continue
				}
				consumed, handled := cs.handleCommand(cmd, rest, line, i)
				if handled {
					i += len(m[0]) + consumed
					if consumed < 0 {
						return
					}
					continue
				}
				// unhandled command: ends brief if it is a block command
				if briefEndingCmds[cmd] && cs.inBrief {
					cs.endBrief()
				}
				if cmd == "code" || cmd == "verbatim" || cmd == "dot" || cmd == "msc" || cmd == "startuml" || cmd == "htmlonly" || cmd == "latexonly" || cmd == "xmlonly" || cmd == "manonly" || cmd == "rtfonly" || cmd == "docbookonly" || cmd == "f[" || cmd == "f{" {
					end := "end" + cmd
					switch cmd {
					case "f[":
						end = "f]"
					case "f{":
						end = "f}"
					case "startuml":
						end = "enduml"
					}
					if !strings.Contains(rest, "\\"+end) && !strings.Contains(rest, "@"+end) {
						cs.inVerbatim = end
					}
				}
				cs.out().WriteString(m[0])
				i += len(m[0])
				continue
			}
		}
		if cs.condSkip {
			i++
			continue
		}
		// autobrief: brief ends at the first '.' followed by whitespace/end
		if cs.inBrief && cs.briefEndsAtDot && c == '.' && (i+1 >= len(line) || line[i+1] == ' ' || line[i+1] == '\t') {
			cs.brief.WriteByte('.')
			cs.endBrief()
			i++
			// the rest of the line goes to the detailed description
			cs.doc.WriteString(strings.TrimLeft(line[i:], " \t"))
			cs.doc.WriteString("\n")
			return
		}
		cs.out().WriteByte(c)
		i++
	}
	if cs.condSkip {
		return
	}
	if cs.inBrief && cs.briefIsLine {
		cs.endBrief()
		return
	}
	cs.out().WriteString("\n")
}

// handleCommand processes structural commands. Returns the number of extra chars consumed
// from rest (or -1 to consume the rest of the line) and whether the command was handled here.
func (cs *commentScanner) handleCommand(cmd, rest, line string, pos int) (int, bool) {
	switch cmd {
	case "brief", "short":
		cs.inBrief = true
		cs.briefIsLine = false
		cs.briefEndsAtDot = false
		cs.hadBriefCmd = true
		if cs.brief.Len() > 0 {
			cs.brief.Reset()
		}
		// consume whitespace after the command
		j := 0
		for j < len(rest) && (rest[j] == ' ' || rest[j] == '\t') {
			j++
		}
		return j, true
	case "details":
		cs.endBrief()
		cs.explicitDetails = true
		j := 0
		for j < len(rest) && (rest[j] == ' ' || rest[j] == '\t') {
			j++
		}
		return j, true
	case "file", "class", "struct", "union", "enum", "namespace", "interface", "protocol", "category", "package", "def", "dir", "concept", "module", "idlexcept":
		cs.endBrief()
		cs.kind = cmd
		cs.name = strings.TrimSpace(rest)
		if cmd == "class" || cmd == "struct" || cmd == "union" || cmd == "interface" || cmd == "protocol" || cmd == "category" {
			// \class name [header] [header-name]
			f := strings.Fields(rest)
			if len(f) > 0 {
				cs.name = f[0]
			}
		}
		if cmd == "enum" || cmd == "namespace" || cmd == "def" || cmd == "concept" {
			f := strings.Fields(rest)
			if len(f) > 0 {
				cs.name = f[0]
			}
		}
		return -1, true
	case "fn", "var", "typedef", "property":
		cs.endBrief()
		cs.kind = cmd
		cs.name = strings.TrimSpace(rest)
		return -1, true
	case "overload":
		cs.endBrief()
		cs.overload = true
		if strings.TrimSpace(rest) != "" {
			cs.kind = "fn"
			cs.name = strings.TrimSpace(rest)
		}
		return -1, true
	case "page":
		cs.endBrief()
		cs.kind = "page"
		f := strings.Fields(rest)
		if len(f) > 0 {
			cs.name = f[0]
			cs.title = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), f[0]))
		}
		return -1, true
	case "mainpage":
		cs.endBrief()
		cs.kind = "mainpage"
		cs.name = "index"
		cs.title = strings.TrimSpace(rest)
		return -1, true
	case "defgroup":
		cs.endBrief()
		cs.kind = "defgroup"
		f := strings.Fields(rest)
		if len(f) > 0 {
			cs.name = f[0]
			cs.title = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), f[0]))
		}
		return -1, true
	case "addtogroup", "weakgroup":
		cs.endBrief()
		cs.kind = "addtogroup"
		f := strings.Fields(rest)
		if len(f) > 0 {
			cs.name = f[0]
			cs.title = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), f[0]))
		}
		return -1, true
	case "ingroup":
		cs.endBrief()
		cs.groups = append(cs.groups, strings.Fields(rest)...)
		return -1, true
	case "name":
		cs.endBrief()
		cs.memberGroupName = strings.TrimSpace(rest)
		cs.kind = "membergroup"
		return -1, true
	case "{":
		cs.memberGroupStart = true
		return 0, true
	case "}":
		cs.memberGroupEnd = true
		return 0, true
	case "relates", "relatesalso", "related", "relatedalso", "memberof":
		cs.endBrief()
		f := strings.Fields(rest)
		if len(f) > 0 {
			cs.relates = f[0]
		}
		return -1, true
	case "private", "privatesection":
		p := Private
		cs.prot = &p
		return 0, true
	case "protected", "protectedsection":
		p := Protected
		cs.prot = &p
		return 0, true
	case "public", "publicsection":
		p := Public
		cs.prot = &p
		return 0, true
	case "static":
		cs.isStatic = true
		return 0, true
	case "pure":
		cs.pure = true
		return 0, true
	case "hideinitializer":
		cs.hideInit = true
		return 0, true
	case "showinitializer":
		cs.showInit = true
		return 0, true
	case "nosubgrouping", "callgraph", "callergraph", "hidecallgraph", "hidecallergraph", "showrefby", "hiderefby", "showrefs", "hiderefs", "showenumvalues", "hideenumvalues", "showinlinesource", "hideinlinesource", "inheritancegraph", "groupgraph", "hidegroupgraph", "directorygraph", "hidedirectorygraph", "includegraph", "hideincludegraph", "includedbygraph", "hideincludedbygraph", "collaborationgraph", "hidecollaborationgraph", "enumvalues":
		if cmd == "inheritancegraph" {
			return -1, true
		}
		return 0, true
	case "extends", "implements", "headerfile", "language", "qualifier", "requirement", "satisfies", "verifies":
		cs.endBrief()
		return -1, true
	case "example":
		cs.endBrief()
		cs.kind = "example"
		cs.name = strings.TrimSpace(rest)
		return -1, true
	case "internal":
		if !cs.d.cfg.Bool("INTERNAL_DOCS") {
			cs.endBrief()
			cs.condSkip = true
			cs.internal = true
		}
		return 0, true
	case "endinternal":
		if cs.internal {
			cs.condSkip = false
			cs.internal = false
		}
		return 0, true
	case "cond":
		sec := strings.TrimSpace(rest)
		enabled := cs.d.sectionEnabled(sec)
		cs.condStack = append(cs.condStack, cs.condSkip)
		if !enabled {
			cs.condSkip = true
		}
		return -1, true
	case "endcond":
		if len(cs.condStack) > 0 {
			cs.condSkip = cs.condStack[len(cs.condStack)-1]
			cs.condStack = cs.condStack[:len(cs.condStack)-1]
		} else {
			cs.condSkip = false
		}
		return 0, true
	case "inbody":
		cs.endBrief()
		cs.inbody = true
		return 0, true
	}
	return 0, false
}

// sectionEnabled evaluates a \cond expression against ENABLED_SECTIONS.
func (d *Doxygen) sectionEnabled(expr string) bool {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return false
	}
	enabled := map[string]bool{}
	for _, s := range d.cfg.List("ENABLED_SECTIONS") {
		enabled[s] = true
	}
	// simple expression support: identifiers, !, &&, ||, parentheses
	toks := tokenizeExpr(expr)
	var out []string
	for _, t := range toks {
		if isIdentStart(t[0]) {
			if enabled[t] {
				out = append(out, "1")
			} else {
				out = append(out, "0")
			}
		} else {
			out = append(out, t)
		}
	}
	ep := &exprParser{toks: out}
	return ep.parseTernary() != 0
}

// handleDocComment attaches the documentation in a comment token to an entry.
func (d *Doxygen) handleDocComment(e *Entry, t Token, file string, after bool) {
	text := cleanComment(t.Text, t.LineStyle)
	cs := &commentScanner{d: d, file: file, line: t.Line, entry: e}
	// for Qt style (//! or /*!) with QT_AUTOBRIEF the first sentence is the brief
	if t.Qt && d.cfg.Bool("QT_AUTOBRIEF") {
		cs.inBrief = true
		cs.briefEndsAtDot = true
	}
	cs.processComment(text)
	cs.apply(e, t.Line, file)
}

// apply stores the scanned results into the entry.
func (cs *commentScanner) apply(e *Entry, line int, file string) {
	brief := cs.brief.String()
	doc := cs.doc.String()
	brief = strings.TrimSpace(brief)
	if brief != "" {
		if e.Doc.Brief == "" {
			e.Doc.Brief = brief
			e.Doc.BriefLine = line
			e.Doc.BriefFile = file
		} else {
			// multiple briefs: append to the detailed documentation
			if e.Doc.Doc != "" {
				e.Doc.Doc += "\n\n"
			}
			e.Doc.Doc += brief
		}
	}
	doc = trimEmptyLines(doc)
	if doc != "" {
		if cs.inbody {
			e.Doc.InBody = joinDocs(e.Doc.InBody, doc)
			e.Doc.InBodyLine = line
		} else {
			if e.Doc.Doc == "" {
				e.Doc.DocLine = line
				e.Doc.DocFile = file
			}
			e.Doc.Doc = joinDocs(e.Doc.Doc, doc)
		}
	}
	if len(cs.groups) > 0 {
		e.Groups = append(e.Groups, cs.groups...)
	}
	if cs.relates != "" {
		e.Relates = cs.relates
	}
	if cs.prot != nil {
		e.Prot = *cs.prot
	}
	if cs.isStatic {
		e.Static = true
	}
	if cs.pure {
		e.PureVirtual = true
		e.Virtual = true
	}
	if cs.hideInit {
		e.MemberSpec = append(e.MemberSpec, "hideinitializer")
	}
	if cs.showInit {
		e.MemberSpec = append(e.MemberSpec, "showinitializer")
	}
	if cs.memberGroupName != "" {
		e.Section = cs.memberGroupName
	}
}

func joinDocs(a, b string) string {
	if a == "" {
		return b
	}
	if b == "" {
		return a
	}
	return a + "\n\n" + b
}

func trimEmptyLines(s string) string {
	lines := strings.Split(s, "\n")
	start := 0
	for start < len(lines) && strings.TrimSpace(lines[start]) == "" {
		start++
	}
	end := len(lines)
	for end > start && strings.TrimSpace(lines[end-1]) == "" {
		end--
	}
	if start >= end {
		return ""
	}
	return strings.Join(lines[start:end], "\n")
}

// handleStandaloneDoc creates a documentation entry for a comment that documents a named entity.
func (d *Doxygen) handleStandaloneDoc(scope *Entry, root *Entry, t Token, file string) {
	text := cleanComment(t.Text, t.LineStyle)
	cs := &commentScanner{d: d, file: file, line: t.Line}
	if t.Qt && d.cfg.Bool("QT_AUTOBRIEF") {
		cs.inBrief = true
		cs.briefEndsAtDot = true
	}
	cs.processComment(text)
	e := &Entry{Kind: "doc:" + cs.kind, Name: cs.name, Title: cs.title, Line: t.Line, File: file, Prot: Public}
	cs.apply(e, t.Line, file)
	e.Kind = "doc:" + cs.kind
	if cs.kind == "file" && cs.name == "" {
		e.Name = file
	}
	if cs.kind == "fn" || cs.kind == "var" || cs.kind == "typedef" || cs.kind == "property" {
		// parse the signature
		sig := cs.name
		e.Name, e.Type, e.Args = parseDocSignature(sig)
		e.ArgList = parseArgList(e.Args)
	}
	root.addChild(e)
}

// parseDocSignature splits "int Foo::bar(int x) const" into name/type/args.
func parseDocSignature(sig string) (name, typ, args string) {
	sig = strings.TrimSpace(sig)
	toks := tokenizeSource([]byte(sig), "cpp")
	var ts []Token
	for _, t := range toks {
		if t.Kind != TokEOF {
			ts = append(ts, t)
		}
	}
	if isFunctionDecl(ts) {
		p := &CParser{toks: append(ts, Token{Kind: TokEOF})}
		e := p.analyzeFunction(ts, &Entry{}, "file", Public, nil, 0)
		if e != nil {
			return e.Name, e.Type, e.Args
		}
	}
	typ, name, args = analyzeDeclarator(ts, false)
	return name, typ, args
}

// parseMarkdownFile handles a markdown input file as a page.
func (d *Doxygen) parseMarkdownFile(fd *FileDef, text string) {
	root := fd.Entries
	title := ""
	body := text
	// a first-level header on the first line(s) becomes the page title
	lines := strings.Split(text, "\n")
	idx := 0
	for idx < len(lines) && strings.TrimSpace(lines[idx]) == "" {
		idx++
	}
	id := ""
	if idx < len(lines) {
		l := strings.TrimSpace(lines[idx])
		if strings.HasPrefix(l, "# ") || strings.HasPrefix(l, "#") && !strings.HasPrefix(l, "##") {
			title = strings.TrimSpace(strings.TrimLeft(l, "#"))
			title = strings.TrimRight(title, "# ")
			// optional {#id}
			if m := regexp.MustCompile(`\{#([^}]+)\}\s*$`).FindStringSubmatch(title); m != nil {
				id = m[1]
				title = strings.TrimSpace(title[:len(title)-len(m[0])])
			}
			body = strings.Join(lines[idx+1:], "\n")
		} else if idx+1 < len(lines) && strings.TrimSpace(lines[idx+1]) != "" && strings.Trim(strings.TrimSpace(lines[idx+1]), "=") == "" {
			title = l
			if m := regexp.MustCompile(`\{#([^}]+)\}\s*$`).FindStringSubmatch(title); m != nil {
				id = m[1]
				title = strings.TrimSpace(title[:len(title)-len(m[0])])
			}
			body = strings.Join(lines[idx+2:], "\n")
		}
	}
	e := &Entry{Kind: "doc:page", Line: 1, File: fd.File}
	mainPage := d.cfg.Str("USE_MDFILE_AS_MAINPAGE")
	isMain := false
	if mainPage != "" {
		mp := absPath(mainPage)
		if mp == fd.File || mainPage == fd.Name || strings.HasSuffix(fd.File, "/"+mainPage) {
			isMain = true
		}
	}
	if isMain {
		e.Kind = "doc:mainpage"
		e.Name = "index"
	} else {
		if id == "" {
			id = markdownFileNameToId(fd.File, d)
		}
		e.Name = id
	}
	e.Title = title
	e.Doc.Doc = trimEmptyLines(body)
	e.Doc.DocLine = 1
	e.Doc.DocFile = fd.File
	e.Lang = "markdown"
	root.addChild(e)
}

// markdownFileNameToId creates the page id for a markdown file, e.g. "md_README".
func markdownFileNameToId(path string, d *Doxygen) string {
	base := d.stripFromPath(path)
	// remove extension
	if i := strings.LastIndex(base, "."); i >= 0 {
		base = base[:i]
	}
	var sb strings.Builder
	sb.WriteString("md_")
	for i := 0; i < len(base); i++ {
		c := base[i]
		if isIdentChar(c) {
			sb.WriteByte(c)
		} else {
			sb.WriteString("_" + strings.ToLower(hexByte(c)))
		}
	}
	return sb.String()
}

func hexByte(c byte) string {
	return string(hexDigits[c>>4]) + string(hexDigits[c&0xf])
}
