// markdownFileNameToId creates the page id for a markdown file, e.g. "md_README".
func markdownFileNameToId(path string, d *Doxygen) string {
	base := d.stripFromPath(path)
	// remove extension
	if i := strings.LastIndex(base, "."); i >= 0 {
		base = base[:i]
	}
	var sb strings.Builder
	sb.WriteString("md_")
	for i := 0; i < len(base); i++ {
		c := base[i]
		if isIdentChar(c) {
			sb.WriteByte(c)
		} else {
			sb.WriteString("_" + strings.ToLower(hexByte(c)))
		}
	}
	return sb.String()
}

func hexByte(c byte) string {
	return string(hexDigits[c>>4]) + string(hexDigits[c&0xf])
