// ---------------------------------------------------------------------------
// Building definitions from entries

func (d *Doxygen) protectionVisible(p Protection) bool {
	switch p {
	case Private:
		return d.cfg.Bool("EXTRACT_PRIVATE")
	case Package:
		return d.cfg.Bool("EXTRACT_PACKAGE")
	}
	return true
}

func (d *Doxygen) buildDefines() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			if e.Kind == "define" {
				md := d.newMemberFromEntry(e, fd, MemberDefine)
				md.Args = e.Args
				md.Initializer = e.Initializer
				fd.Members = append(fd.Members, md)
			}
		}
		// documentation blocks for defines (\def)
		for _, e := range fd.Entries.Children {
			if e.Kind == "doc:def" {
				for _, md := range fd.Members {
					if md.Kind == MemberDefine && md.Name == e.Name {
						mergeDocs(&md.Doc, &e.Doc)
					}
				}
			}
		}
	}
}

func mergeDocs(dst *DocBlock, src *DocBlock) {
	if src.Brief != "" {
		if dst.Brief == "" {
			dst.Brief = src.Brief
			dst.BriefLine = src.BriefLine
			dst.BriefFile = src.BriefFile
		} else if dst.Brief != src.Brief {
			dst.Doc = joinDocs(dst.Doc, src.Brief)
		}
	}
	if src.Doc != "" {
		if dst.Doc == "" {
			dst.DocLine = src.DocLine
			dst.DocFile = src.DocFile
		}
		dst.Doc = joinDocs(dst.Doc, src.Doc)
	}
	if src.InBody != "" {
		dst.InBody = joinDocs(dst.InBody, src.InBody)
	}
}

func (d *Doxygen) newMemberFromEntry(e *Entry, fd *FileDef, kind MemberKind) *MemberDef {
	md := &MemberDef{}
	md.Kind = kind
	md.Name = e.Name
	md.QualName = e.Name
	md.Type = e.Type
	md.Args = e.Args
	md.ArgList = e.ArgList
	if len(e.TArgLists) > 0 {
		md.TArgList = e.TArgLists[len(e.TArgLists)-1]
	}
	md.Prot = e.Prot
	md.Static = e.Static
	md.Virtual = e.Virtual
	md.PureVirtual = e.PureVirtual
	md.Const = e.Const
	md.Explicit = e.Explicit
	md.Inline = e.Inline
	md.Mutable = e.Mutable
	md.Volatile = e.Volatile
	md.ConstExpr = e.ConstExpr
	md.Final = e.Final
	md.Override = e.Override
	md.Default = e.Default
	md.Delete = e.Delete
	md.NoExcept = e.NoExcept
	md.Extern = e.Extern
	md.Strong = e.Strong
	md.Friend = e.Friend
	md.Initializer = e.Initializer
	md.Bitfield = e.Bitfield
	md.Exception = e.Exception
	md.Doc = e.Doc
	md.File = e.File
	md.Line = e.Line
	md.BodyStart = e.BodyStart
	md.BodyEnd = e.BodyEnd
	md.FileDef = fd
	md.Entry = e
	md.Requires = e.Requires
	md.Lang = fd.Lang
	if e.BodyStart > 0 {
		md.DefFile = e.File
		md.DefLine = e.BodyStart
	}
	d.allMembers = append(d.allMembers, md)
	return md
}

func (d *Doxygen) buildGroups() {
	// topics (\defgroup) : minimal support
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			if e.Kind == "doc:defgroup" {
				g := d.findOrCreateGroup(e.Name)
				if g.Title == "" {
					g.Title = e.Title
				}
				mergeDocs(&g.Doc, &e.Doc)
				g.File = e.File
				g.Line = e.Line
				g.Entry = e
			}
		}
	}
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			if e.Kind == "doc:addtogroup" {
				g := d.findOrCreateGroup(e.Name)
				if g.Title == "" {
					g.Title = e.Title
				}
				mergeDocs(&g.Doc, &e.Doc)
				if g.File == "" {
					g.File = e.File
					g.Line = e.Line
				}
			}
		}
	}
}

func (d *Doxygen) findOrCreateGroup(name string) *GroupDef {
	for _, g := range d.groups {
		if g.Name == name {
			return g
		}
	}
	g := &GroupDef{}
	g.Name = name
	g.QualName = name
	d.groups = append(d.groups, g)
	return g
}

func (d *Doxygen) buildDirectories() {
	// directories are only documented when used (e.g. \dir); keep the structure for file lists
	dirMap := map[string]*DirDef{}
	for _, fd := range d.files {
		dir := strings.TrimSuffix(fd.Path, "/")
		dd := dirMap[dir]
		if dd == nil {
			dd = &DirDef{Path: dir + "/"}
			dd.Name = dir
			dd.QualName = dir
			dd.ShortName = filepath.Base(dir)
			dirMap[dir] = dd
			d.dirs = append(d.dirs, dd)
		}
		dd.Files = append(dd.Files, fd)
		fd.DirDef = dd
	}
	sort.Slice(d.dirs, func(i, j int) bool { return d.dirs[i].Path < d.dirs[j].Path })
}

func (d *Doxygen) findOrCreateNamespace(qualName string, fd *FileDef, e *Entry) *NamespaceDef {
	if ns, ok := d.nsMap[qualName]; ok {
		return ns
	}
	ns := &NamespaceDef{}
	ns.Name = stripScope(qualName)
	ns.QualName = qualName
	ns.FileDef = fd
	if e != nil {
		ns.File = e.File
		ns.Line = e.Line
		ns.BodyStart = e.BodyStart
		ns.BodyEnd = e.BodyEnd
		ns.Entry = e
	}
	ns.IsAnonymous = strings.Contains(qualName, "anonymous_namespace{")
	d.nsMap[qualName] = ns
	d.namespaces = append(d.namespaces, ns)
	if sp := scopePart(qualName); sp != "" {
		parent := d.findOrCreateNamespace(sp, fd, nil)
		ns.Parent = parent
		parent.Namespaces = appendUniqueNs(parent.Namespaces, ns)
	}
	return ns
}

func appendUniqueNs(list []*NamespaceDef, ns *NamespaceDef) []*NamespaceDef {
	for _, x := range list {
		if x == ns {
			return list
		}
	}
	return append(list, ns)
}

func (d *Doxygen) buildNamespaces() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkNamespaces(fd.Entries, "", fd)
	}
	// documentation blocks
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			if e.Kind == "doc:namespace" {
				ns := d.nsMap[e.Name]
				if ns == nil {
					ns = d.findOrCreateNamespace(e.Name, fd, nil)
					ns.File = e.File
					ns.Line = e.Line
				}
				mergeDocs(&ns.Doc, &e.Doc)
			}
		}
	}
}

func (d *Doxygen) walkNamespaces(e *Entry, scope string, fd *FileDef) {
	for _, c := range e.Children {
		if c.Kind == "namespace" {
			qual := c.Name
			if scope != "" {
				qual = scope + "::" + c.Name
			}
			ns := d.findOrCreateNamespace(qual, fd, c)
			if ns.Entry == nil {
				ns.Entry = c
			}
			if ns.File == "" || (c.Doc.hasDocs() && !ns.Doc.hasDocs()) {
				ns.File = c.File
				ns.Line = c.Line
				ns.BodyStart = c.BodyStart
				ns.BodyEnd = c.BodyEnd
			}
			mergeDocs(&ns.Doc, &c.Doc)
			if !containsFile(ns.Files, fd) {
				ns.Files = append(ns.Files, fd)
			}
			if scope == "" {
				if !containsNs(fd.Namespaces, ns) {
					fd.Namespaces = append(fd.Namespaces, ns)
				}
			}
			d.walkNamespaces(c, qual, fd)
		}
	}
}

func containsFile(list []*FileDef, fd *FileDef) bool {
	for _, x := range list {
		if x == fd {
			return true
		}
	}
	return false
}
func containsNs(list []*NamespaceDef, ns *NamespaceDef) bool {
	for _, x := range list {
		if x == ns {
			return true
		}
	}
	return false
}

func (d *Doxygen) buildClasses() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkClasses(fd.Entries, "", fd, nil, nil)
	}
	// documentation blocks (\class etc.)
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			switch e.Kind {
			case "doc:class", "doc:struct", "doc:union", "doc:interface", "doc:protocol", "doc:category":
				cd := d.classMap[e.Name]
				if cd == nil {
					// create a class without a definition
					cd = &ClassDef{}
					cd.Name = stripScope(e.Name)
					cd.QualName = e.Name
					cd.CompoundType = strings.TrimPrefix(e.Kind, "doc:")
					cd.File = e.File
					cd.Line = e.Line
					cd.FileDef = fd
					cd.Prot = Public
					cd.Artificial = false
					cd.Lang = fd.Lang
					d.classMap[e.Name] = cd
					d.classes = append(d.classes, cd)
					if sp := scopePart(e.Name); sp != "" {
						if ns := d.nsMap[sp]; ns != nil {
							cd.Namespace = ns
							ns.Classes = append(ns.Classes, cd)
						}
					} else {
						fd.Classes = append(fd.Classes, cd)
					}
				}
				mergeDocs(&cd.Doc, &e.Doc)
				if cd.Doc.BriefFile == "" && cd.Doc.Brief != "" {
					cd.Doc.BriefFile = e.File
				}
			}
		}
	}
}

func (d *Doxygen) walkClasses(e *Entry, scope string, fd *FileDef, ns *NamespaceDef, outer *ClassDef) {
	for _, c := range e.Children {
		switch c.Kind {
		case "namespace":
			qual := c.Name
			if scope != "" {
				qual = scope + "::" + c.Name
			}
			d.walkClasses(c, qual, fd, d.nsMap[qual], nil)
		case "class", "struct", "union", "interface":
			qual := c.Name
			if scope != "" {
				qual = scope + "::" + c.Name
			}
			cd := d.classMap[qual]
			if cd == nil {
				cd = &ClassDef{}
				cd.Name = c.Name
				cd.QualName = qual
				cd.CompoundType = c.Kind
				cd.File = c.File
				cd.Line = c.Line
				cd.BodyStart = c.BodyStart
				cd.BodyEnd = c.BodyEnd
				cd.FileDef = fd
				cd.Prot = c.Prot
				cd.Entry = c
				cd.Namespace = ns
				cd.TemplateArgs = c.TArgLists
				cd.isTemplate = len(c.TArgLists) > 0
				cd.IsAnonymous = strings.HasPrefix(c.Name, "@")
				cd.Lang = fd.Lang
				cd.Final = c.Final
				cd.memberLists = map[string][]*MemberDef{}
				d.classMap[qual] = cd
				d.classes = append(d.classes, cd)
				if outer != nil {
					cd.OuterScope = outer
					outer.Inner = append(outer.Inner, cd)
				} else if ns != nil {
					ns.Classes = append(ns.Classes, cd)
				} else {
					fd.Classes = append(fd.Classes, cd)
				}
				if ns != nil {
					cd.OuterScope = ns
				}
				for _, b := range c.Bases {
					cd.Bases = append(cd.Bases, &BaseClass{Name: b.Name, Prot: b.Prot, Virtual: b.Virtual})
				}
			} else {
				// second definition (e.g. in another file): merge
			}
			mergeDocs(&cd.Doc, &c.Doc)
			if !containsFile(cd.UsedFiles, fd) {
				cd.UsedFiles = append(cd.UsedFiles, fd)
			}
			d.walkClasses(c, qual, fd, ns, cd)
		}
	}
}

func (d *Doxygen) buildEnums() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkMembers(fd.Entries, "", fd, nil, nil, "enum")
	}
}

func (d *Doxygen) buildTypedefs() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkMembers(fd.Entries, "", fd, nil, nil, "typedef")
	}
}

func (d *Doxygen) buildVariables() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkMembers(fd.Entries, "", fd, nil, nil, "variable")
	}
}

func (d *Doxygen) buildFunctions() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		d.walkMembers(fd.Entries, "", fd, nil, nil, "function")
	}
}

// walkMembers creates MemberDefs of the given kind in the entry tree.
func (d *Doxygen) walkMembers(e *Entry, scope string, fd *FileDef, ns *NamespaceDef, cd *ClassDef, kind string) {
	for _, c := range e.Children {
		switch c.Kind {
		case "namespace":
			qual := c.Name
			if scope != "" {
				qual = scope + "::" + c.Name
			}
			d.walkMembers(c, qual, fd, d.nsMap[qual], nil, kind)
			continue
		case "class", "struct", "union", "interface":
			qual := c.Name
			if scope != "" {
				qual = scope + "::" + c.Name
			}
			d.walkMembers(c, qual, fd, ns, d.classMap[qual], kind)
			continue
		}
		if c.Kind != kind {
			if !(kind == "function" && c.Kind == "friend") {
				continue
			}
		}
		var mk MemberKind
		switch c.Kind {
		case "enum":
			mk = MemberEnum
		case "typedef":
			mk = MemberTypedef
		case "variable":
			mk = MemberVariable
		case "function":
			mk = MemberFunction
		case "friend":
			mk = MemberFriend
		}
		if c.Kind == "function" && c.Friend && cd != nil {
			mk = MemberFriend
		}
		// a function definition with a scope qualifier (Class::method) defined at file scope
		if c.Kind == "function" && cd == nil && strings.Contains(c.Name, "::") {
			d.addMemberDefinition(c, fd, scope)
			continue
		}
		if c.Kind == "variable" && cd == nil && strings.Contains(c.Name, "::") {
			d.addMemberDefinition(c, fd, scope)
			continue
		}
		md := d.newMemberFromEntry(c, fd, mk)
		if c.Kind == "enum" {
			if strings.HasPrefix(c.Name, "@") {
				md.Anonymous = true
			}
			for _, ev := range c.Children {
				if ev.Kind != "enumvalue" {
					continue
				}
				evd := d.newMemberFromEntry(ev, fd, MemberEnumValue)
				evd.Prot = c.Prot
				evd.EnumScope = md
				evd.Class = cd
				evd.Namespace = ns
				evd.Initializer = ev.Initializer
				if cd != nil {
					evd.QualName = cd.QualName + "::" + ev.Name
					evd.ScopeName = cd.QualName
				} else if ns != nil {
					evd.QualName = ns.QualName + "::" + ev.Name
					evd.ScopeName = ns.QualName
				}
				if md.Strong {
					evd.QualName = md.QualName + "::" + ev.Name
				}
				md.EnumValues = append(md.EnumValues, evd)
			}
		}
		if cd != nil {
			md.Class = cd
			md.QualName = cd.QualName + "::" + c.Name
			md.ScopeName = cd.QualName
			// ctor/dtor detection
			base := cd.Name
			if i := strings.Index(base, "<"); i >= 0 {
				base = base[:i]
			}
			if mk == MemberFunction {
				if c.Name == base {
					md.IsCtor = true
				} else if c.Name == "~"+base {
					md.IsDtor = true
				}
			}
			cd.Members = append(cd.Members, md)
		} else if ns != nil {
			md.Namespace = ns
			md.QualName = ns.QualName + "::" + c.Name
			md.ScopeName = ns.QualName
			ns.Members = append(ns.Members, md)
			fd.Members = append(fd.Members, md)
		} else {
			fd.Members = append(fd.Members, md)
		}
		// strong enum values are scoped by the enum name
		if c.Kind == "enum" && md.Strong {
			for _, ev := range md.EnumValues {
				ev.QualName = md.QualName + "::" + ev.Name
				ev.ScopeName = md.QualName
			}
		}
	}
}

// addMemberDefinition handles `int Class::method() {...}` definitions outside the class body.
func (d *Doxygen) addMemberDefinition(c *Entry, fd *FileDef, scope string) {
	scopeName := scopePart(c.Name)
	name := stripScope(c.Name)
	if scope != "" {
		scopeName = scope + "::" + scopeName
	}
	cd := d.classMap[scopeName]
	if cd == nil {
		// maybe a namespace-scoped function definition
		ns := d.nsMap[scopeName]
		if ns != nil {
			// try to find a matching declaration
			for _, md := range ns.Members {
				if md.Name == name && md.Kind == MemberFunction && argsMatch(md, c) {
					d.mergeDefinition(md, c, fd)
					return
				}
			}
			// no declaration: create member in the namespace
			md := d.newMemberFromEntry(c, fd, MemberFunction)
			md.Name = name
			md.QualName = ns.QualName + "::" + name
			md.ScopeName = ns.QualName
			md.Namespace = ns
			ns.Members = append(ns.Members, md)
			fd.Members = append(fd.Members, md)
			return
		}
		// unknown scope: ignore (doxygen warns)
		if d.cfg.Bool("WARN_IF_UNDOCUMENTED") || true {
			d.pendingDefs = append(d.pendingDefs, pendingDef{c, fd, scopeName, name})
		}
		return
	}
	for _, md := range cd.Members {
		if md.Name == name && md.Kind == kindOf(c) && (c.Kind != "function" || argsMatch(md, c)) {
			d.mergeDefinition(md, c, fd)
			return
		}
	}
	// no matching declaration found
	d.pendingDefs = append(d.pendingDefs, pendingDef{c, fd, scopeName, name})
}

type pendingDef struct {
	e     *Entry
	fd    *FileDef
	scope string
	name  string
}

func kindOf(c *Entry) MemberKind {
	switch c.Kind {
	case "function":
		return MemberFunction
	case "variable":
		return MemberVariable
	}
	return MemberFunction
}

// argsMatch compares the argument types of a declaration and a definition.
func argsMatch(md *MemberDef, c *Entry) bool {
	if md.ArgList == nil || c.ArgList == nil {
		return true
	}
	a, b := md.ArgList, c.ArgList
	if len(a.Args) != len(b.Args) {
		return false
	}
	if a.ConstSpec != b.ConstSpec {
		return false
	}
	for i := range a.Args {
		if normalizeType(a.Args[i].Type) != normalizeType(b.Args[i].Type) {
			// allow name/type confusion for unnamed params
			if normalizeType(a.Args[i].Type+" "+a.Args[i].Name) != normalizeType(b.Args[i].Type+" "+b.Args[i].Name) {
				return false
			}
		}
	}
	return true
}

func normalizeType(t string) string {
	t = strings.ReplaceAll(t, " ", "")
	t = strings.TrimPrefix(t, "const")
	return t
}

// mergeDefinition merges a member definition (with body) into the declaration member.
func (d *Doxygen) mergeDefinition(md *MemberDef, c *Entry, fd *FileDef) {
	md.DefFile = c.File
	md.DefLine = c.Line
	md.BodyStart = c.BodyStart
	md.BodyEnd = c.BodyEnd
	if c.Doc.hasDocs() {
		// documentation at the definition
		if md.Doc.Brief == "" && md.Doc.Doc == "" {
			md.Doc.BriefFile = c.Doc.BriefFile
			md.Doc.DocFile = c.Doc.DocFile
			md.DocsForDefinition = true
		}
		mergeDocs(&md.Doc, &c.Doc)
	}
	if c.ArgList != nil && md.ArgList != nil {
		// take argument names from the definition when the declaration lacks them
		for i := range md.ArgList.Args {
			if i < len(c.ArgList.Args) && md.ArgList.Args[i].Name == "" && c.ArgList.Args[i].Name != "" {
				md.ArgList.Args[i].Name = c.ArgList.Args[i].Name
			}
		}
	}
	md.DeclArgList = c.ArgList
}

func (d *Doxygen) computeInheritance() {
	for _, cd := range d.classes {
		for _, b := range cd.Bases {
			name := b.Name
			bc := d.resolveClass(name, cd)
			if bc != nil {
				b.Class = bc
				bc.Derived = append(bc.Derived, cd)
			}
		}
	}
}

// resolveClass finds a class by name, searching from the scope of the given class.
func (d *Doxygen) resolveClass(name string, from *ClassDef) *ClassDef {
	d.typeLookupMisses++
	stripped := stripTemplateSpecifiers(name)
	stripped = strings.TrimSpace(stripped)
	if cd := d.classMap[stripped]; cd != nil {
		return cd
	}
	if cd := d.classMap[name]; cd != nil {
		return cd
	}
	// try enclosing scopes
	if from != nil {
		scope := from.QualName
		for scope != "" {
			sp := scopePart(scope)
			if sp == "" {
				break
			}
			if cd := d.classMap[sp+"::"+stripped]; cd != nil {
				return cd
			}
			scope = sp
		}
		if from.Namespace != nil {
			ns := from.Namespace
			for ns != nil {
				if cd := d.classMap[ns.QualName+"::"+stripped]; cd != nil {
					return cd
				}
				ns = ns.Parent
			}
		}
	}
	// match by unqualified name
	for _, cd := range d.classes {
		if cd.Name == stripped {
			return cd
		}
	}
	return nil
}

func (d *Doxygen) warnUndocumentedNamespaces() {
	// handled in the generation phase to match doxygen warnings ordering
}

func (d *Doxygen) findMemberDocumentation() {
	// \fn, \var, \typedef, \enum documentation blocks
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			switch e.Kind {
			case "doc:fn", "doc:var", "doc:typedef", "doc:enum", "doc:property":
				d.attachMemberDoc(e, fd)
			case "doc:file":
				target := d.fileMap[e.Name]
				if target == nil {
					// match by name
					for _, f := range d.files {
						if f.Name == e.Name || f.File == e.Name || strings.HasSuffix(f.File, "/"+e.Name) {
							target = f
							break
						}
					}
				}
				if target == nil && (e.Name == "" || e.Name == fd.File) {
					target = fd
				}
				if target != nil {
					mergeDocs(&target.Doc, &e.Doc)
					target.Documented = true
				} else {
					warn(e.File, e.Line, "the name '%s' supplied as the argument in the \\file statement is not an input file", e.Name)
				}
			}
		}
	}
	// pending definitions without declarations
	for _, pd := range d.pendingDefs {
		if cd := d.classMap[pd.scope]; cd != nil {
			if pd.e.Doc.hasDocs() || true {
				warn(pd.e.File, pd.e.Line, "no matching class member found for \n  %s", memberSignatureText(pd.e, pd.scope))
			}
		} else if d.cfg.Bool("WARN_IF_UNDOCUMENTED") || true {
			// unknown scope: doxygen reports no uniquely matching class member
		}
	}
}

func memberSignatureText(e *Entry, scope string) string {
	s := ""
	if e.Type != "" {
		s = e.Type + " "
	}
	s += scope + "::" + stripScope(e.Name) + e.Args
	return s
}

func (d *Doxygen) attachMemberDoc(e *Entry, fd *FileDef) {
	name := e.Name
	scope := scopePart(name)
	local := stripScope(name)
	var candidates []*MemberDef
	for _, md := range d.allMembers {
		if md.Name != local {
			continue
		}
		if scope != "" && md.ScopeName != scope && !strings.HasSuffix(md.ScopeName, "::"+scope) {
			continue
		}
		candidates = append(candidates, md)
	}
	if len(candidates) == 0 {
		warn(e.File, e.Line, "documented symbol '%s' was not declared or defined.", strings.TrimSpace(e.Type+" "+e.Name+e.Args))
		return
	}
	if len(candidates) > 1 && e.Kind == "doc:fn" && e.ArgList != nil {
		var filtered []*MemberDef
		for _, md := range candidates {
			if md.Kind == MemberFunction && argsMatch(md, e) {
				filtered = append(filtered, md)
			}
		}
		if len(filtered) > 0 {
			candidates = filtered
		}
	}
	mergeDocs(&candidates[0].Doc, &e.Doc)
}

func (d *Doxygen) buildPages() {
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			switch e.Kind {
			case "doc:mainpage":
				if d.mainPage == nil {
					pg := &PageDef{}
					pg.Name = "index"
					pg.QualName = "index"
					pg.Title = e.Title
					pg.Doc = e.Doc
					pg.File = e.File
					pg.Line = e.Line
					pg.FileDef = fd
					pg.IsMain = true
					pg.Entry = e
					pg.Lang = e.Lang
					d.mainPage = pg
				} else {
					warn(e.File, e.Line, "found more than one \\mainpage comment block! (first occurrence: %s, line %d), skipping current block!", d.mainPage.File, d.mainPage.Line)
				}
			case "doc:page":
				var pg *PageDef
				for _, p := range d.pages {
					if p.Name == e.Name {
						pg = p
						break
					}
				}
				if pg == nil {
					pg = &PageDef{}
					pg.Name = e.Name
					pg.QualName = e.Name
					pg.Title = e.Title
					pg.File = e.File
					pg.Line = e.Line
					pg.FileDef = fd
					pg.Entry = e
					pg.Lang = e.Lang
					pg.Doc = e.Doc
					d.pages = append(d.pages, pg)
				} else {
					mergeDocs(&pg.Doc, &e.Doc)
					if pg.Title == "" {
						pg.Title = e.Title
					}
				}
			}
		}
	}
}

func (d *Doxygen) sortLists() {
	sort.SliceStable(d.classes, func(i, j int) bool { return qstricmpSort(d.classes[i].QualName, d.classes[j].QualName) < 0 })
	sort.SliceStable(d.namespaces, func(i, j int) bool { return qstricmpSort(d.namespaces[i].QualName, d.namespaces[j].QualName) < 0 })
	sort.SliceStable(d.pages, func(i, j int) bool { return qstricmpSort(d.pages[i].Name, d.pages[j].Name) < 0 })
	sort.SliceStable(d.groups, func(i, j int) bool { return qstricmpSort(d.groups[i].Name, d.groups[j].Name) < 0 })
}

func (d *Doxygen) inheritDocumentation() {
	if !d.cfg.Bool("INHERIT_DOCS") {
		return
	}
	for _, cd := range d.classes {
		for _, md := range cd.Members {
			if md.Kind != MemberFunction || md.Doc.hasDocs() {
				continue
			}
			// look for the same function in base classes
			if bm := d.findBaseMember(cd, md, 0); bm != nil {
				md.Reimplements = bm
				bm.ReimplementedBy = append(bm.ReimplementedBy, md)
				if bm.Doc.hasDocs() {
					md.Doc.Brief = bm.Doc.Brief
					md.Doc.BriefFile = bm.Doc.BriefFile
					md.Doc.BriefLine = bm.Doc.BriefLine
					md.Doc.Doc = bm.Doc.Doc
					md.Doc.DocFile = bm.Doc.DocFile
					md.Doc.DocLine = bm.Doc.DocLine
					md.Doc.InBody = bm.Doc.InBody
				}
			}
		}
	}
}

func (d *Doxygen) findBaseMember(cd *ClassDef, md *MemberDef, depth int) *MemberDef {
	if depth > 20 {
		return nil
	}
	for _, b := range cd.Bases {
		if b.Class == nil {
			continue
		}
		for _, bm := range b.Class.Members {
			if bm.Kind == MemberFunction && bm.Name == md.Name && (bm.Virtual || md.Virtual || md.Override) && argsMatch(bm, md.Entry) && bm.Const == md.Const {
				return bm
			}
		}
		if r := d.findBaseMember(b.Class, md, depth+1); r != nil {
			return r
		}
	}
	return nil
}

func (d *Doxygen) generateDiskNames() {
	// classes
	for _, cd := range d.classes {
		prefix := "class"
		switch cd.CompoundType {
		case "struct":
			prefix = "struct"
		case "union":
			prefix = "union"
		case "interface":
			prefix = "interface"
		case "protocol":
			prefix = "protocol"
		case "category":
			prefix = "category"
		case "exception":
			prefix = "exception"
		}
		cd.OutputBase = prefix + escapeCharsInString(d, cd.QualName, false, false)
		if d.cfg.Bool("SHORT_NAMES") {
			cd.OutputBase = d.shortName()
		}
	}
	for _, ns := range d.namespaces {
		ns.OutputBase = "namespace" + escapeCharsInString(d, ns.QualName, false, false)
	}
	// files: use the stripped path when names are ambiguous, otherwise the file name
	fullPathNames := d.cfg.Bool("FULL_PATH_NAMES")
	for _, fd := range d.files {
		name := fd.Name
		if fullPathNames {
			name = d.stripFromPath(fd.File)
		}
		fd.OutputBase = escapeCharsInString(d, name, false, false)
	}
	// resolve duplicate file disk names
	seen := map[string]int{}
	for _, fd := range d.files {
		seen[fd.OutputBase]++
	}
	for _, fd := range d.files {
		if seen[fd.OutputBase] > 1 {
			fd.OutputBase = escapeCharsInString(d, d.stripFromPath(fd.File), false, false)
		}
	}
	for _, pg := range d.pages {
		pg.OutputBase = escapeCharsInString(d, pg.Name, false, true)
	}
	if d.mainPage != nil {
		d.mainPage.OutputBase = "index"
	}
	for _, g := range d.groups {
		g.OutputBase = "group__" + escapeCharsInString(d, g.Name, false, false)
	}
	for _, dd := range d.dirs {
		dd.OutputBase = "dir_" + md5Hex(dd.Path)[:32]
	}
	// member anchors
	for _, md := range d.allMembers {
		md.Anchor = d.memberAnchor(md)
	}
	// enum values share the anchor scheme
}

var shortNameCounter = 0

func (d *Doxygen) shortName() string {
	shortNameCounter++
	return "a" + intToStr(shortNameCounter)
}

// memberAnchor computes the anchor of a member as doxygen does: 'a' + md5(definition+name+args).
func (d *Doxygen) memberAnchor(md *MemberDef) string {
	memAnchor := md.Name
	if md.Args != "" {
		memAnchor += md.Args
	}
	memAnchor = md.definitionString() + memAnchor
	if md.TArgList != nil && len(md.TArgList.Args) > 0 {
		memAnchor += tempArgListToString(md.TArgList)
	}
	return "a" + md5Hex(memAnchor)
}

func tempArgListToString(al *ArgumentList) string {
	var parts []string
	for _, a := range al.Args {
		s := a.Type
		if a.Name != "" {
			s += " " + a.Name
		}
		parts = append(parts, s)
	}
	return "<" + strings.Join(parts, ", ") + ">"
}

// definitionString returns the "definition" of a member: type + qualified name.
func (md *MemberDef) definitionString() string {
	if md.Definition_ != "" {
		return md.Definition_
	}
	def := ""
	typ := md.Type
	if md.Kind == MemberEnum && md.Anonymous {
		def = md.QualName
	}
	if md.Kind == MemberDefine {
		def = "#define " + md.Name
	} else if md.Kind == MemberTypedef {
		def = "typedef " + typ + " " + md.QualName
		if md.Entry != nil && md.Entry.Alias {
			def = "using " + md.QualName + " = " + typ
		}
	} else if md.Kind == MemberEnum {
		if md.Strong {
			def = "enum class " + md.QualName
		} else {
			def = "enum " + md.QualName
		}
	} else {
		if typ != "" {
			def = typ + " " + md.QualName
		} else {
			def = md.QualName
		}
		if md.Static && (md.Class != nil || md.Namespace == nil) {
			def = "static " + def
		}
	}
	md.Definition_ = def
	return def
}

