const (
	tkWord = iota
	tkWhitespace
	tkNewline
	tkCommand
	tkHtmlTag
	tkEntity
	tkListItem
	tkParaBreak
	tkEnd
	tkEndList
	tkRawText
)

// docParser parses documentation text.
type docParser struct {
