	text   string
	pos    int
	toks   []docToken
	tpos   int
	root   *DocNode
	sectionLevelOffset int
	autoTocCount int
	warnFile string
	warnLine int
	inPre  int
}

// parseDocText parses a documentation string into a tree.
func (d *Doxygen) parseDocText(ctx *DocContext, text string) *DocNode {
	if ctx.d == nil {
		ctx.d = d
	}
	p := &docParser{ctx: ctx}
	if d.cfg.Bool("MARKDOWN_SUPPORT") {
		text = processMarkdown(text, ctx)
	}
	if text == "" || text[len(text)-1] != '\n' {
		text += "\n"
	}
	p.text = text
	p.tokenize()
	p.root = newDocNode(DocRoot)
	p.root.Flag = ctx.singleLine
	p.parseBlocks(p.root, nil)
	return p.root
}

// ---------------------------------------------------------------------------
// Tokenizer

var htmlTagRe = regexp.MustCompile(`^<(/?)([a-zA-Z][a-zA-Z0-9]*)((?:\s+[a-zA-Z_:][-a-zA-Z0-9_:.]*(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(/?)>`)
var htmlAttrRe = regexp.MustCompile(`([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s>]+))?`)
var entityRe = regexp.MustCompile(`^&(#[0-9]+|#[xX][0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);`)
var listMarkerRe = regexp.MustCompile(`^([ \t]*)(-#|-|\*|\+|[0-9]+\.)[ \t]+`)

func (p *docParser) tokenize() {
	text := p.text
	i := 0
	n := len(text)
	atLineStart := true
	var toks []docToken
	for i < n {
		c := text[i]
		if atLineStart {
			// detect list markers at the start of a line
			if m := listMarkerRe.FindStringSubmatch(text[i:]); m != nil {
				indent := len(m[1])
				marker := m[2]
				ordered := marker == "-#" || (marker[len(marker)-1] == '.')
				// "- " markers must not be followed by '-' (horizontal rule handled by markdown)
				toks = append(toks, docToken{kind: tkListItem, indent: indent, ordered: ordered, text: m[0]})
				i += len(m[0])
				atLineStart = false
				continue
			}
			// blank line -> paragraph break
			j := i
			for j < n && (text[j] == ' ' || text[j] == '\t') {
				j++
			}
			if j < n && text[j] == '\n' {
				// one or more blank lines
				for j < n {
					k := j
					for k < n && (text[k] == ' ' || text[k] == '\t') {
						k++
					}
					if k < n && text[k] == '\n' {
						j = k + 1
					} else {
						break
					}
				}
				toks = append(toks, docToken{kind: tkParaBreak})
				i = j
				continue
			}
			atLineStart = false
			// leading whitespace of a line is insignificant unless inside preformatted
			if j > i {
				toks = append(toks, docToken{kind: tkWhitespace, text: text[i:j], indent: j - i})
				i = j
				continue
			}
		}
		switch {
		case c == '\n':
			toks = append(toks, docToken{kind: tkNewline, text: "\n"})
			i++
			atLineStart = true
		case c == ' ' || c == '\t' || c == '\r':
			j := i
			for j < n && (text[j] == ' ' || text[j] == '\t' || text[j] == '\r') {
				j++
			}
			toks = append(toks, docToken{kind: tkWhitespace, text: text[i:j]})
			i = j
		case (c == '\\' || c == '@') && i+1 < n:
			m := cmdRe.FindStringSubmatch(text[i:])
			if m != nil {
				cmd := m[1]
				// special: \f[ \f] \f{ \f} \f$
				if cmd == "f" && i+2 < n && (text[i+2] == '$' || text[i+2] == '[' || text[i+2] == ']' || text[i+2] == '{' || text[i+2] == '}') {
					cmd = "f" + string(text[i+2])
					toks = append(toks, docToken{kind: tkCommand, cmd: cmd, text: text[i : i+3]})
					i += 3
					continue
				}
				toks = append(toks, docToken{kind: tkCommand, cmd: cmd, text: m[0]})
				i += len(m[0])
				continue
			}
			toks = append(toks, docToken{kind: tkWord, text: string(c)})
			i++
		case c == '<':
			m := htmlTagRe.FindStringSubmatch(text[i:])
			if m != nil {
				tag := strings.ToLower(m[2])
				tk := docToken{kind: tkHtmlTag, tag: tag, close: m[1] == "/", selfClose: m[4] == "/", text: m[0], attrs: map[string]string{}}
				for _, am := range htmlAttrRe.FindAllStringSubmatch(m[3], -1) {
					v := am[2]
					if len(v) >= 2 && (v[0] == '"' || v[0] == '\'') {
						v = v[1 : len(v)-1]
					}
					tk.attrs[strings.ToLower(am[1])] = v
				}
				toks = append(toks, tk)
				i += len(m[0])
				continue
			}
			if strings.HasPrefix(text[i:], "<!--") {
				e := strings.Index(text[i:], "-->")
				if e >= 0 {
					i += e + 3
					continue
				}
			}
			toks = append(toks, docToken{kind: tkWord, text: "<"})
			i++
		case c == '&':
			m := entityRe.FindStringSubmatch(text[i:])
			if m != nil {
				toks = append(toks, docToken{kind: tkEntity, text: m[0]})
				i += len(m[0])
				continue
			}
			toks = append(toks, docToken{kind: tkWord, text: "&"})
			i++
		default:
			// word: sequence of non-space, non-special characters
			j := i
			for j < n {
				cj := text[j]
				if cj == ' ' || cj == '\t' || cj == '\n' || cj == '\r' || cj == '<' || cj == '&' {
					break
				}
				if (cj == '\\' || cj == '@') && j+1 < n && j > i {
					// command inside word (e.g. word\n) : split
					if cmdRe.MatchString(text[j:]) {
						break
					}
				}
				j++
			}
			if j == i {
				j = i + 1
			}
			toks = append(toks, docToken{kind: tkWord, text: text[i:j]})
			i = j
		}
	}
	toks = append(toks, docToken{kind: tkEnd})
	p.toks = toks
}

func (p *docParser) peek() *docToken {
	if p.tpos < len(p.toks) {
		return &p.toks[p.tpos]
	}
	return &p.toks[len(p.toks)-1]
}

func (p *docParser) next() *docToken {
	t := p.peek()
	if p.tpos < len(p.toks)-1 {
		p.tpos++
	}
	return t
}

func (p *docParser) atEnd() bool { return p.peek().kind == tkEnd }

// ---------------------------------------------------------------------------
// Block parsing

var simpleSectTitles = map[string]string{
	"see": "See also", "sa": "See also", "return": "Returns", "returns": "Returns", "result": "Returns",
	"author": "Author", "authors": "Authors", "version": "Version", "since": "Since", "date": "Date",
	"note": "Note", "warning": "Warning", "pre": "Precondition", "post": "Postcondition", "copyright": "Copyright",
	"invariant": "Invariant", "remark": "Remarks", "remarks": "Remarks", "attention": "Attention", "important": "Important",
	"par": "", "rcs": "", "deprecated": "Deprecated", "todo": "Todo", "bug": "Bug", "test": "Test",
}

var simpleSectClass = map[string]string{
	"see": "see", "sa": "see", "return": "return", "returns": "return", "result": "return",
	"author": "author", "authors": "authors", "version": "version", "since": "since", "date": "date",
	"note": "note", "warning": "warning", "pre": "pre", "post": "post", "copyright": "copyright",
	"invariant": "invariant", "remark": "remark", "remarks": "remark", "attention": "attention", "important": "important",
	"par": "user", "rcs": "rcs",
}

var xrefSections = map[string]struct{ list, title string }{
	"todo":       {"todo", "Todo"},
	"bug":        {"bug", "Bug"},
	"test":       {"test", "Test"},
	"deprecated": {"deprecated", "Deprecated"},
}

func isBlockCommand(cmd string) bool {
	switch cmd {
	case "param", "tparam", "retval", "exception", "throw", "throws", "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph",
		"code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "li", "arg",
		"image", "dotfile", "mscfile", "diafile", "plantumlfile", "include", "dontinclude", "verbinclude", "htmlinclude", "latexinclude", "snippet", "snippetlineno", "includelineno", "includedoc", "snippetdoc",
		"skip", "skipline", "until", "line", "parblock", "endparblock", "internal", "endinternal", "secreflist", "endsecreflist", "tableofcontents", "xrefitem", "refitem", "copydetails", "copydoc":
		return true
	}
	if _, ok := simpleSectTitles[cmd]; ok {
		return true
	}
	return false
}

// parseBlocks parses a sequence of paragraphs and block-level constructs into parent.
// stopAt lists html tags which terminate the block sequence (e.g. "/li").
func (p *docParser) parseBlocks(parent *DocNode, stop func(*docToken) bool) {
	for !p.atEnd() {
		t := p.peek()
		if stop != nil && stop(t) {
			return
		}
		switch t.kind {
		case tkParaBreak:
			p.next()
			continue
		case tkNewline, tkWhitespace:
			p.next()
			continue
		case tkListItem:
			p.parseAutoList(parent)
			continue
		case tkHtmlTag:
			if !t.close {
				switch t.tag {
				case "ul", "ol":
					p.parseHtmlList(parent)
					continue
				case "dl":
					p.parseHtmlDescList(parent)
					continue
				case "table":
					p.parseHtmlTable(parent)
					continue
				case "pre":
					p.parseHtmlPre(parent)
					continue
				case "h1", "h2", "h3", "h4", "h5", "h6":
					p.parseHtmlHeader(parent)
					continue
				case "hr":
					p.next()
					parent.add(newDocNode(DocHorRuler))
					continue
				case "blockquote":
					p.parseBlockQuote(parent)
					continue
				case "details":
					p.parseDetails(parent)
					continue
				}
			} else {
				// stray closing tag at block level: skip
				switch t.tag {
				case "p", "div", "ul", "ol", "li", "dl", "dd", "dt", "table", "tr", "td", "th", "blockquote", "details", "summary", "center", "pre", "h1", "h2", "h3", "h4", "h5", "h6":
					p.next()
					continue
				}
			}
		case tkCommand:
			switch t.cmd {
			case "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph":
				p.parseSection(parent)
				continue
			case "code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "iliteral":
				p.parseVerbatim(parent)
				continue
			case "li", "arg":
				p.parseSimpleList(parent)
				continue
			case "internal":
				p.next()
				if !p.ctx.d.cfg.Bool("INTERNAL_DOCS") {
					p.skipUntilCommand("endinternal")
				}
				continue
			case "endinternal", "endparblock", "endsecreflist":
				p.next()
				continue
			case "parblock":
				p.next()
				pb := parent.add(newDocNode(DocParBlock))
				p.parseBlocks(pb, func(t *docToken) bool { return t.kind == tkCommand && t.cmd == "endparblock" })
				if p.peek().kind == tkCommand && p.peek().cmd == "endparblock" {
					p.next()
				}
				continue
			case "tableofcontents":
				p.next()
				p.skipLineArgs()
				parent.add(newDocNode(DocTocList))
				continue
			case "secreflist":
				p.next()
				sl := parent.add(newDocNode(DocSecRefList))
				for !p.atEnd() {
					tt := p.peek()
					if tt.kind == tkCommand && tt.cmd == "endsecreflist" {
						p.next()
						break
					}
					if tt.kind == tkCommand && tt.cmd == "refitem" {
						p.next()
						p.skipWhitespace()
						target := p.readWord()
						item := sl.add(newDocNode(DocSecRefItem))
						item.Text = target
						item.Target = p.ctx.d.resolveLink(target, p.ctx)
						item.Children = nil
						// title is the rest of the line
						title := p.readRestOfLine()
						item.Attrs["title"] = strings.TrimSpace(title)
						continue
					}
					p.next()
				}
				continue
			}
		}
		// default: a paragraph
		p.parsePara(parent, stop)
	}
}

func (p *docParser) skipUntilCommand(cmd string) {
	for !p.atEnd() {
		t := p.next()
		if t.kind == tkCommand && t.cmd == cmd {
			return
		}
	}
}

func (p *docParser) skipWhitespace() {
	for p.peek().kind == tkWhitespace {
		p.next()
	}
}

func (p *docParser) skipLineArgs() {
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkNewline || t.kind == tkParaBreak {
			break
		}
		p.next()
	}
}

// readWord reads the next word token (or returns "").
func (p *docParser) readWord() string {
	p.skipWhitespace()
	t := p.peek()
	if t.kind == tkWord {
		p.next()
		return t.text
	}
	if t.kind == tkCommand {
		p.next()
		return t.text
	}
	return ""
}

// readRestOfLine returns the raw text until the end of the current line.
func (p *docParser) readRestOfLine() string {
	var sb strings.Builder
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkNewline || t.kind == tkParaBreak || t.kind == tkEnd {
			break
		}
		p.next()
		sb.WriteString(t.text)
	}
	return sb.String()
}

// readQuotedOrWord reads either a "quoted string" or a single word.
func (p *docParser) readQuotedOrWord() string {
	p.skipWhitespace()
	t := p.peek()
	if t.kind == tkWord && strings.HasPrefix(t.text, "\"") {
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			sb.WriteString(tt.text)
			if strings.HasSuffix(tt.text, "\"") && (sb.Len() > 1) {
				break
			}
			if tt.kind == tkNewline {
				break
			}
		}
		s := sb.String()
		s = strings.TrimSuffix(strings.TrimPrefix(s, "\""), "\"")
		return s
	}
	return p.readWord()
}

// parsePara parses a paragraph (inline content) until a paragraph break or block construct.
func (p *docParser) parsePara(parent *DocNode, stop func(*docToken) bool) {
	para := newDocNode(DocPara)
	parent.add(para)
	p.parseInline(para, func(t *docToken) bool {
		if stop != nil && stop(t) {
			return true
		}
		switch t.kind {
		case tkParaBreak, tkListItem:
			return true
		case tkHtmlTag:
			if !t.close {
				switch t.tag {
				case "ul", "ol", "dl", "table", "pre", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "blockquote", "p", "details":
					return true
				}
			} else {
				switch t.tag {
				case "p", "li", "dd", "dt", "td", "th", "tr", "ul", "ol", "dl", "table", "blockquote", "details", "summary", "div":
					return true
				}
			}
		case tkCommand:
			switch t.cmd {
			case "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph", "code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "li", "arg", "internal", "endinternal", "parblock", "endparblock", "tableofcontents", "secreflist", "endsecreflist", "endcode", "endverbatim", "iliteral":
				return true
			}
		}
		return false
	})
	// remove empty paragraphs
	if len(para.Children) == 0 {
		parent.Children = parent.Children[:len(parent.Children)-1]
		return
	}
	// drop trailing whitespace-only nodes? doxygen keeps the trailing whitespace as a single space
	trimTrailingWhitespace(para)
	// a <p> tag directly after this paragraph starts a new paragraph
	if p.peek().kind == tkHtmlTag && p.peek().tag == "p" && !p.peek().close {
		p.next()
	}
}

// trimTrailingWhitespace collapses trailing whitespace of a paragraph into one space node
// (doxygen emits a single space for whitespace tokens).
func trimTrailingWhitespace(para *DocNode) {
	for len(para.Children) > 1 {
		last := para.Children[len(para.Children)-1]
		prev := para.Children[len(para.Children)-2]
		if last.Kind == DocWhitespace && prev.Kind == DocWhitespace {
			para.Children = para.Children[:len(para.Children)-1]
			continue
		}
		break
	}
	// a paragraph consisting only of whitespace is empty
	if len(para.Children) == 1 && para.Children[0].Kind == DocWhitespace {
		para.Children = nil
	}
}

// addWhitespace appends a whitespace node, merging consecutive ones.
func addWhitespace(para *DocNode) {
	if len(para.Children) > 0 && para.Children[len(para.Children)-1].Kind == DocWhitespace {
		return
	}
	if len(para.Children) == 0 {
		return // leading whitespace is dropped
	}
	para.add(newDocNode(DocWhitespace))
}

var inlineStyleTags = map[string]string{
	"b": "bold", "strong": "bold", "i": "italic", "em": "italic", "code": "code", "tt": "code", "u": "underline",
	"strike": "strike", "s": "s", "del": "del", "ins": "ins", "sub": "subscript", "sup": "superscript", "small": "small",
	"cite": "cite", "center": "center", "span": "span", "div": "div", "var": "italic", "kbd": "code", "dfn": "italic", "samp": "code",
}

// parseInline parses inline content into node until stop returns true.
func (p *docParser) parseInline(node *DocNode, stop func(*docToken) bool) {
	for !p.atEnd() {
		t := p.peek()
		if stop(t) {
			return
		}
		switch t.kind {
		case tkWord:
			p.next()
			p.addWord(node, t.text)
		case tkWhitespace, tkNewline:
			p.next()
			addWhitespace(node)
		case tkEntity:
			p.next()
			sym := node.add(newDocNode(DocSymbol))
			sym.Text = t.text
		case tkRawText:
			p.next()
			r := node.add(newDocNode(DocHtmlRaw))
			r.Text = t.text
		case tkHtmlTag:
			p.next()
			p.handleInlineHtmlTag(node, t, stop)
		case tkCommand:
			p.next()
			p.handleInlineCommand(node, t, stop)
		default:
			p.next()
		}
	}
}

func (p *docParser) addWord(node *DocNode, text string) {
	// autolinking
	if p.ctx.d.cfg.Bool("AUTOLINK_SUPPORT") && p.inPre == 0 {
		if ln := p.ctx.d.autoLinkWord(text, p.ctx); ln != nil {
			node.add(ln)
			return
		}
	}
	w := node.add(newDocNode(DocWord))
	w.Text = text
}

func (p *docParser) handleInlineHtmlTag(node *DocNode, t *docToken, stop func(*docToken) bool) {
	if t.close {
		return // unmatched closing tag: ignore
	}
	switch t.tag {
	case "br":
		node.add(newDocNode(DocLineBreak))
	case "a":
		a := newDocNode(DocURL)
		if href, ok := t.attrs["href"]; ok {
			a.Kind = DocURL
			a.Text = href
			a.Attrs["href"] = href
			node.add(a)
			p.parseInline(a, func(tt *docToken) bool { return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == "a" && tt.close) })
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if name, ok := t.attrs["name"]; ok {
			a.Kind = DocAnchor
			a.Text = name
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if id, ok := t.attrs["id"]; ok {
			a.Kind = DocAnchor
			a.Text = id
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		}
	case "img":
		img := node.add(newDocNode(DocImage))
		img.Attrs = t.attrs
		img.Text = t.attrs["src"]
		img.Attrs["html"] = "1"
	case "p":
		// handled as paragraph break by caller
	default:
		if style, ok := inlineStyleTags[t.tag]; ok {
			s := newDocNode(DocStyle)
			s.Attrs["style"] = style
			s.Attrs["tag"] = t.tag
			for k, v := range t.attrs {
				s.Attrs["attr:"+k] = v
			}
			node.add(s)
			if t.selfClose {
				return
			}
			p.parseInline(s, func(tt *docToken) bool {
				return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == t.tag && tt.close)
			})
			if p.peek().kind == tkHtmlTag && p.peek().tag == t.tag && p.peek().close {
				p.next()
			}
			return
		}
		// unknown tag: emit as text? doxygen warns and ignores. Keep raw for things like <div>.
		r := node.add(newDocNode(DocHtmlRaw))
		r.Text = t.text
	}
}

func (p *docParser) handleInlineCommand(node *DocNode, t *docToken, stop func(*docToken) bool) {
	cmd := t.cmd
	switch cmd {
	case "n":
		node.add(newDocNode(DocLineBreak))
	case "a", "e", "em":
		p.styledWord(node, "italic")
	case "b":
		p.styledWord(node, "bold")
	case "c", "p":
		p.styledWord(node, "code")
	case "ref", "refitem":
		p.parseRef(node, false)
	case "link":
		p.parseLink(node)
	case "endlink":
	case "anchor":
		name := p.readWord()
		a := node.add(newDocNode(DocAnchor))
		a.Text = name
	case "cite":
		name := p.readWord()
		c := node.add(newDocNode(DocCite))
		c.Text = name
	case "emoji":
		name := p.readWord()
		e := node.add(newDocNode(DocEmoji))
		e.Text = strings.Trim(name, ":")
	case "copybrief", "copydetails", "copydoc":
		name := p.readWord()
		c := node.add(newDocNode(DocCopy))
		c.Text = name
		c.Attrs["kind"] = cmd
	case "f$":
		// inline formula
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			if tt.kind == tkCommand && tt.cmd == "f$" {
				break
			}
			sb.WriteString(tt.text)
		}
		f := node.add(newDocNode(DocFormula))
		f.Text = "$" + sb.String() + "$"
		f.Flag = true
	case "image":
		p.parseImage(node)
	case "dotfile", "mscfile", "diafile", "plantumlfile":
		p.skipWhitespace()
		name := p.readQuotedOrWord()
		caption := strings.TrimSpace(p.readRestOfLine())
		n := node.add(newDocNode(DocDotFile))
		n.Text = name
		n.Attrs["kind"] = cmd
		n.Attrs["caption"] = caption
	case "include", "dontinclude", "verbinclude", "htmlinclude", "latexinclude", "snippet", "snippetlineno", "includelineno", "includedoc", "snippetdoc", "rtfinclude", "maninclude", "docbookinclude", "xmlinclude":
		p.parseInclude(node, cmd)
	case "skip", "skipline", "until", "line":
		p.readRestOfLine()
	case "xrefitem":
		p.skipWhitespace()
		key := p.readWord()
		heading := p.readQuotedOrWord()
		title := p.readQuotedOrWord()
		x := node.add(newDocNode(DocXRefItem))
		x.Attrs["key"] = key
		x.Attrs["heading"] = heading
		x.Attrs["title"] = title
		x.Text = title
		para := x.add(newDocNode(DocPara))
		p.parseInline(para, p.sectStop(stop))
	case "param", "tparam", "retval", "exception", "throw", "throws":
		p.parseParamSect(node, cmd, stop)
	case "~", "&", "$", "#", "<", ">", "%", "\"", ".", "::", "|", "--", "---", "\\", "@", "=":
		if cmd == "~" {
			// language switch: ignore until next \~ ... simply ignore the command
			lang := p.readWord()
			_ = lang
			return
		}
		w := node.add(newDocNode(DocWord))
		w.Text = cmd
		if cmd == "::" {
			w.Text = "::"
		}
		if cmd == "--" {
			w.Text = "--"
		}
	case "showdate":
		p.readRestOfLine()
	case "ifile", "iline", "ianchor", "iprefix", "ilinebr", "ilinebr_i", "isection":
		p.readRestOfLine()
	case "showinitializer", "hideinitializer", "callgraph", "callergraph", "hidecallgraph", "hidecallergraph", "showrefby", "hiderefby", "showrefs", "hiderefs", "nosubgrouping", "static", "pure", "private", "protected", "public":
	case "brief", "short", "details":
		// already handled by comment scanner; ignore here (a leftover means text follows)
	case "endcode", "endverbatim", "endhtmlonly", "endlatexonly", "endxmlonly", "endmanonly", "endrtfonly", "enddocbookonly", "enddot", "endmsc", "enduml", "f]", "f}", "endiliteral":
	case "if", "ifnot", "elseif", "else", "endif":
		p.handleIf(node, cmd, stop)
	case "cond", "endcond":
		p.readRestOfLine()
	case "startuml":
		p.parseVerbatim(node)
	default:
		if _, ok := simpleSectTitles[cmd]; ok {
			p.parseSimpleSect(node, cmd, stop)
			return
		}
		// unknown command: doxygen warns "Found unknown command '\cmd'"
		warnDocErr(p.ctx.file, p.ctx.line, "Found unknown command '\\%s'", cmd)
	}
}

func (p *docParser) sectStop(stop func(*docToken) bool) func(*docToken) bool {
	return func(t *docToken) bool {
		if stop(t) {
			return true
		}
		if t.kind == tkParaBreak || t.kind == tkListItem {
			return true
		}
		if t.kind == tkCommand && isBlockCommand(t.cmd) {
			return true
		}
		if t.kind == tkHtmlTag && !t.close {
			switch t.tag {
			case "ul", "ol", "dl", "table", "pre", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "blockquote", "p":
				return true
			}
		}
		return false
	}
}

func (p *docParser) handleIf(node *DocNode, cmd string, stop func(*docToken) bool) {
	// conditional sections: evaluate the section name against ENABLED_SECTIONS
	switch cmd {
	case "if", "ifnot":
		expr := p.readWord()
		enabled := p.ctx.d.sectionEnabled(expr)
		if cmd == "ifnot" {
			enabled = !enabled
		}
		if enabled {
			return
		}
		// skip until matching else/elseif/endif
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				case "else":
					if depth == 0 {
						return
					}
				case "elseif":
					if depth == 0 {
						e := p.readWord()
						if p.ctx.d.sectionEnabled(e) {
							return
						}
					}
				}
			}
		}
	case "else", "elseif":
		// we reached an else branch while the if branch was active: skip to endif
		if cmd == "elseif" {
			p.readWord()
		}
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				}
			}
		}
	case "endif":
	}
}

// styledWord handles \a word, \b word, \c word.
func (p *docParser) styledWord(node *DocNode, style string) {
	p.skipWhitespace()
	t := p.peek()
	if t.kind != tkWord {
		return
	}
	p.next()
	word := t.text
	// trailing punctuation stays outside the style
	trail := ""
	for len(word) > 0 {
		c := word[len(word)-1]
		if c == '.' || c == ',' || c == ';' || c == ':' || c == ')' || c == '?' || c == '!' {
			trail = string(c) + trail
			word = word[:len(word)-1]
			continue
		}
		break
	}
	if word == "" {
		word = t.text
		trail = ""
	}
	s := node.add(newDocNode(DocStyle))
	s.Attrs["style"] = style
	s.Attrs["cmd"] = "1"
	w := s.add(newDocNode(DocWord))
	w.Text = word
	if trail != "" {
		w2 := node.add(newDocNode(DocWord))
		w2.Text = trail
	}
}

func (p *docParser) parseRef(node *DocNode, isLink bool) {
	p.skipWhitespace()
	target := p.readWord()
	if target == "" {
		return
	}
	// strip trailing punctuation from the target
	trail := ""
	for len(target) > 1 {
		c := target[len(target)-1]
		if c == '.' || c == ',' || c == ';' || c == ':' || c == '?' || c == '!' {
			trail = string(c) + trail
			target = target[:len(target)-1]
			continue
		}
		break
	}
	ref := newDocNode(DocRef)
	ref.Text = target
	// optional "text"
	save := p.tpos
	p.skipWhitespace()
	if t := p.peek(); t.kind == tkWord && strings.HasPrefix(t.text, "\"") {
		txt := p.readQuotedOrWord()
		ref.Attrs["text"] = txt
	} else {
		p.tpos = save
	}
	ref.Target = p.ctx.d.resolveLink(target, p.ctx)
	node.add(ref)
	if ref.Target == nil {
		warnDocErr(p.ctx.file, p.ctx.line, "unable to resolve reference to '%s' for \\ref command", target)
	}
	if trail != "" {
		w := node.add(newDocNode(DocWord))
		w.Text = trail
	}
}

func (p *docParser) parseLink(node *DocNode) {
	p.skipWhitespace()
	target := p.readWord()
	ref := newDocNode(DocRef)
	ref.Text = target
	ref.Target = p.ctx.d.resolveLink(target, p.ctx)
	node.add(ref)
	p.parseInline(ref, func(t *docToken) bool { return t.kind == tkCommand && t.cmd == "endlink" || t.kind == tkParaBreak })
	if p.peek().kind == tkCommand && p.peek().cmd == "endlink" {
		p.next()
	}
	if len(ref.Children) > 0 {
		var sb strings.Builder
		for _, c := range ref.Children {
			if c.Kind == DocWord {
				sb.WriteString(c.Text)
			} else if c.Kind == DocWhitespace {
				sb.WriteString(" ")
			}
		}
		ref.Attrs["text"] = strings.TrimSpace(sb.String())
		ref.Children = nil
	}
}

func (p *docParser) parseImage(node *DocNode) {
	p.skipWhitespace()
	// optional {options}
	t := p.peek()
	if t.kind == tkWord && strings.HasPrefix(t.text, "{") {
		for !p.atEnd() {
			tt := p.next()
			if strings.Contains(tt.text, "}") {
				break
			}
		}
		p.skipWhitespace()
	}
	format := p.readWord()
	name := p.readQuotedOrWord()
	img := newDocNode(DocImage)
	img.Attrs["format"] = format
	img.Text = name
	// optional caption (quoted) and size
	rest := strings.TrimSpace(p.readRestOfLine())
	if strings.HasPrefix(rest, "\"") {
		e := strings.Index(rest[1:], "\"")
		if e >= 0 {
			img.Attrs["caption"] = rest[1 : 1+e]
			rest = strings.TrimSpace(rest[e+2:])
		}
	}
	for _, f := range strings.Fields(rest) {
		if strings.HasPrefix(f, "width=") {
			img.Attrs["width"] = f[6:]
		} else if strings.HasPrefix(f, "height=") {
			img.Attrs["height"] = f[7:]
		}
	}
	if format == "html" || format == "" {
		node.add(img)
		p.ctx.d.copyImage(name)
	} else if format == "latex" || format == "rtf" || format == "docbook" || format == "xml" {
		img.Attrs["skip"] = "1"
		node.add(img)
	}
}

func (p *docParser) parseInclude(node *DocNode, cmd string) {
	p.skipWhitespace()
	// optional {options}
	t := p.peek()
	opts := ""
	if t.kind == tkWord && strings.HasPrefix(t.text, "{") {
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			sb.WriteString(tt.text)
			if strings.Contains(tt.text, "}") {
				break
			}
		}
		opts = sb.String()
		p.skipWhitespace()
	}
	name := p.readQuotedOrWord()
	inc := node.add(newDocNode(DocInclude))
	inc.Attrs["cmd"] = cmd
	inc.Attrs["opts"] = opts
	inc.Text = name
	if cmd == "snippet" || cmd == "snippetlineno" || cmd == "snippetdoc" {
		inc.Attrs["block"] = strings.TrimSpace(p.readRestOfLine())
	}
	// resolve example file
	inc.File = p.ctx.d.findExampleFile(name)
}

// parseSimpleSect parses \note, \return etc. The node is appended to the current paragraph.
func (p *docParser) parseSimpleSect(para *DocNode, cmd string, stop func(*docToken) bool) {
	if xs, ok := xrefSections[cmd]; ok {
		x := para.add(newDocNode(DocXRefItem))
		x.Attrs["key"] = xs.list
		x.Attrs["heading"] = xs.title
		x.Attrs["title"] = xs.title
		x.Text = xs.title
		inner := x.add(newDocNode(DocPara))
		p.parseInline(inner, p.sectStop(stop))
		trimTrailingWhitespace(inner)
		return
	}
	ss := newDocNode(DocSimpleSect)
	ss.Attrs["type"] = cmd
	ss.Attrs["class"] = simpleSectClass[cmd]
	ss.Attrs["title"] = simpleSectTitles[cmd]
	if cmd == "par" {
		// user defined title on the rest of the line
		title := strings.TrimSpace(p.readRestOfLine())
		ss.Attrs["title"] = title
		if p.peek().kind == tkNewline {
			p.next()
		}
	}
	// merge consecutive sections of the same type (e.g. multiple \see) handled by the visitor
	para.add(ss)
	inner := ss.add(newDocNode(DocPara))
	p.parseInline(inner, p.sectStop(stop))
	trimTrailingWhitespace(inner)
	if len(inner.Children) == 0 {
		ss.Children = nil
	}
}

// parseParamSect parses \param [in|out] name description.
func (p *docParser) parseParamSect(para *DocNode, cmd string, stop func(*docToken) bool) {
	ps := newDocNode(DocParamSect)
	ps.Attrs["type"] = cmd
	// merge into a previous param section of the same type in this paragraph
	if len(para.Children) > 0 {
		last := para.Children[len(para.Children)-1]
		if last.Kind == DocParamSect && last.Attrs["type"] == paramSectType(cmd) {
			ps = last
		} else {
			ps.Attrs["type"] = paramSectType(cmd)
			para.add(ps)
		}
	} else {
		ps.Attrs["type"] = paramSectType(cmd)
		para.add(ps)
	}
	item := ps.add(newDocNode(DocParamList))
	p.skipWhitespace()
	// direction
	if cmd == "param" {
		t := p.peek()
		if t.kind == tkWord && strings.HasPrefix(t.text, "[") {
			// may be "[in]" or "[in," "out]"
			var sb strings.Builder
			for !p.atEnd() {
				tt := p.next()
				sb.WriteString(tt.text)
				if strings.Contains(tt.text, "]") {
					break
				}
			}
			dir := strings.ReplaceAll(sb.String(), " ", "")
			item.Attrs["dir"] = dir
			p.skipWhitespace()
		}
	}
	// names separated by commas
	for {
		t := p.peek()
		if t.kind != tkWord {
			break
		}
		p.next()
		name := t.text
		more := strings.HasSuffix(name, ",")
		name = strings.TrimSuffix(name, ",")
		for _, nm := range strings.Split(name, ",") {
			if nm != "" {
				item.Names = append(item.Names, nm)
			}
		}
		if !more {
			// check for ", name" continuation
			save := p.tpos
			p.skipWhitespace()
			if nt := p.peek(); nt.kind == tkWord && strings.HasPrefix(nt.text, ",") {
				p.next()
				rest := strings.TrimPrefix(nt.text, ",")
				if rest != "" {
					item.Names = append(item.Names, rest)
				}
				p.skipWhitespace()
				continue
			}
			p.tpos = save
			break
		}
		p.skipWhitespace()
	}
	desc := item.add(newDocNode(DocPara))
	p.parseInline(desc, p.sectStop(stop))
	trimTrailingWhitespace(desc)
	// check parameter names against the member's argument list
	if cmd == "param" && p.ctx.member != nil {
		p.ctx.d.checkParamName(p.ctx, item.Names)
	}
}

func paramSectType(cmd string) string {
	switch cmd {
	case "tparam":
		return "tparam"
	case "retval":
		return "retval"
	case "exception", "throw", "throws":
		return "exception"
	}
	return "param"
}

func (p *docParser) parseSection(parent *DocNode) {
	t := p.next()
	level := 1
	switch t.cmd {
	case "subsection":
		level = 2
	case "subsubsection":
		level = 3
	case "paragraph":
		level = 4
	case "subparagraph":
		level = 5
	case "subsubparagraph":
		level = 6
	}
	p.skipWhitespace()
	id := p.readWord()
	title := strings.TrimSpace(p.readRestOfLine())
	sec := parent.add(newDocNode(DocSection))
	sec.Level = level
	sec.Anchor = id
	sec.Text = title
	if si := p.ctx.d.findSection(id); si != nil {
		sec.File = si.Ref
		if title == "" {
			sec.Text = si.Title
		}
	}
	// the section contains the following blocks until the next section of same or higher level
	p.parseBlocks(sec, func(tt *docToken) bool {
		if tt.kind == tkCommand {
			switch tt.cmd {
			case "section":
				return true
			case "subsection":
				return level >= 2
			case "subsubsection":
				return level >= 3
			case "paragraph":
				return level >= 4
			case "subparagraph":
				return level >= 5
			case "subsubparagraph":
				return level >= 6
			}
		}
		return false
	})
}

func (p *docParser) parseVerbatim(parent *DocNode) {
	t := p.next()
	cmd := t.cmd
	end := "end" + cmd
	switch cmd {
	case "f[":
		end = "f]"
	case "f{":
		end = "f}"
	case "startuml":
		end = "enduml"
	}
	// optional {options} for code
	opts := ""
	if cmd == "code" || cmd == "iliteral" {
		save := p.tpos
		p.skipWhitespace()
		tt := p.peek()
		if tt.kind == tkWord && strings.HasPrefix(tt.text, "{") {
			var sb strings.Builder
			for !p.atEnd() {
				x := p.next()
				sb.WriteString(x.text)
				if strings.Contains(x.text, "}") {
					break
				}
			}
			opts = strings.Trim(sb.String(), "{}")
		} else {
			p.tpos = save
		}
	}
	// collect raw text until the end command
	var sb strings.Builder
	first := true
	for !p.atEnd() {
		tt := p.next()
		if tt.kind == tkCommand && tt.cmd == end {
			break
		}
		if tt.kind == tkEnd {
			break
		}
		if first && (tt.kind == tkNewline) {
			first = false
			continue
		}
		first = false
		switch tt.kind {
		case tkParaBreak:
			sb.WriteString("\n\n")
		case tkListItem:
			sb.WriteString(tt.text)
		default:
			sb.WriteString(tt.text)
		}
	}
	v := newDocNode(DocVerbatim)
	v.Attrs["kind"] = cmd
	v.Attrs["opts"] = opts
	text := sb.String()
	// remove trailing newline (added back by the visitor)
	v.Text = text
	// the verbatim block belongs to the current paragraph in doxygen's model; we add it to the parent
	parent.add(v)
}

// parseAutoList parses markdown-style '-' lists.
func (p *docParser) parseAutoList(parent *DocNode) {
	first := p.peek()
	indent := first.indent
	list := parent.add(newDocNode(DocAutoList))
	list.Ordered = first.ordered
	num := 1
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkListItem || t.indent != indent {
			// nested list?
			if t.kind == tkListItem && t.indent > indent && len(list.Children) > 0 {
				item := list.Children[len(list.Children)-1]
				p.parseAutoList(item)
				continue
			}
			break
		}
		if t.ordered != list.Ordered {
			break
		}
		p.next()
		item := list.add(newDocNode(DocAutoListItem))
		item.Num = num
		num++
		para := item.add(newDocNode(DocPara))
		p.parseInline(para, func(tt *docToken) bool {
			switch tt.kind {
			case tkParaBreak, tkListItem:
				return true
			case tkCommand:
				return isBlockCommand(tt.cmd) && tt.cmd != "li" || tt.cmd == "endcode"
			case tkHtmlTag:
				if !tt.close {
					switch tt.tag {
					case "ul", "ol", "dl", "table", "pre", "p":
						return true
					}
				} else {
					switch tt.tag {
					case "li", "ul", "ol", "dd", "td", "p":
						return true
					}
				}
			}
			return false
		})
		trimTrailingWhitespace(para)
		// paragraph break followed by an indented continuation or nested list
		if p.peek().kind == tkParaBreak {
			save := p.tpos
			p.next()
			nt := p.peek()
			if nt.kind == tkListItem && nt.indent > indent {
				p.parseAutoList(item)
				continue
			}
			if nt.kind == tkListItem && nt.indent == indent && nt.ordered == list.Ordered {
				// same list continues after blank line
				continue
			}
			p.tpos = save
			break
		}
	}
	if len(list.Children) == 0 {
		parent.Children = parent.Children[:len(parent.Children)-1]
	}
}

// parseSimpleList parses \li / \arg items.
func (p *docParser) parseSimpleList(parent *DocNode) {
	list := parent.add(newDocNode(DocSimpleList))
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkCommand || (t.cmd != "li" && t.cmd != "arg") {
			break
		}
		p.next()
		item := list.add(newDocNode(DocSimpleListItem))
		para := item.add(newDocNode(DocPara))
		p.parseInline(para, func(tt *docToken) bool {
			if tt.kind == tkParaBreak || tt.kind == tkListItem {
				return true
			}
			if tt.kind == tkCommand && isBlockCommand(tt.cmd) {
				return true
			}
			return false
		})
		trimTrailingWhitespace(para)
	}
}

func (p *docParser) parseHtmlList(parent *DocNode) {
	open := p.next()
	list := parent.add(newDocNode(DocHtmlList))
	list.Ordered = open.tag == "ol"
	for k, v := range open.attrs {
		list.Attrs["attr:"+k] = v
	}
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && (t.tag == open.tag) {
			p.next()
			break
		}
		if t.kind == tkHtmlTag && !t.close && t.tag == "li" {
			p.next()
			item := list.add(newDocNode(DocHtmlListItem))
			for k, v := range t.attrs {
				item.Attrs["attr:"+k] = v
			}
			p.parseBlocks(item, func(tt *docToken) bool {
				return tt.kind == tkHtmlTag && ((tt.close && (tt.tag == "li" || tt.tag == open.tag)) || (!tt.close && tt.tag == "li"))
			})
			if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "li" {
				p.next()
			}
			continue
		}
		if t.kind == tkEnd {
			break
		}
		p.next()
	}
}

func (p *docParser) parseHtmlDescList(parent *DocNode) {
	p.next()
	dl := parent.add(newDocNode(DocHtmlDescList))
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && t.tag == "dl" {
			p.next()
			break
		}
		if t.kind == tkHtmlTag && !t.close && (t.tag == "dt" || t.tag == "dd") {
			p.next()
			var item *DocNode
			if t.tag == "dt" {
				item = dl.add(newDocNode(DocHtmlDescTitle))
				p.parseInline(item, func(tt *docToken) bool {
					return tt.kind == tkHtmlTag && (tt.tag == "dt" || tt.tag == "dd" || tt.tag == "dl")
				})
			} else {
				item = dl.add(newDocNode(DocHtmlDescData))
				p.parseBlocks(item, func(tt *docToken) bool {
					return tt.kind == tkHtmlTag && ((tt.tag == "dt" || tt.tag == "dd") || (tt.close && tt.tag == "dl"))
				})
			}
			if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == t.tag {
				p.next()
			}
			continue
		}
		p.next()
	}
}

func (p *docParser) parseHtmlTable(parent *DocNode) {
	open := p.next()
	table := parent.add(newDocNode(DocHtmlTable))
	for k, v := range open.attrs {
		table.Attrs["attr:"+k] = v
	}
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && t.tag == "table" {
			p.next()
			break
		}
		if t.kind == tkHtmlTag && !t.close && t.tag == "caption" {
			p.next()
			cap := table.add(newDocNode(DocHtmlCaption))
			p.parseInline(cap, func(tt *docToken) bool { return tt.kind == tkHtmlTag && tt.close && tt.tag == "caption" })
			if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "caption" {
				p.next()
			}
			continue
		}
		if t.kind == tkHtmlTag && !t.close && t.tag == "tr" {
			p.next()
			row := table.add(newDocNode(DocHtmlRow))
			for k, v := range t.attrs {
				row.Attrs["attr:"+k] = v
			}
			for !p.atEnd() {
				tt := p.peek()
				if tt.kind == tkHtmlTag && tt.close && (tt.tag == "tr" || tt.tag == "table") {
					if tt.tag == "tr" {
						p.next()
					}
					break
				}
				if tt.kind == tkHtmlTag && !tt.close && tt.tag == "tr" {
					break
				}
				if tt.kind == tkHtmlTag && !tt.close && (tt.tag == "td" || tt.tag == "th") {
					p.next()
					cell := row.add(newDocNode(DocHtmlCell))
					cell.Flag = tt.tag == "th"
					for k, v := range tt.attrs {
						cell.Attrs["attr:"+k] = v
					}
					p.parseBlocks(cell, func(x *docToken) bool {
						return x.kind == tkHtmlTag && ((x.close && (x.tag == "td" || x.tag == "th" || x.tag == "tr" || x.tag == "table")) || (!x.close && (x.tag == "td" || x.tag == "th" || x.tag == "tr")))
					})
					if p.peek().kind == tkHtmlTag && p.peek().close && (p.peek().tag == "td" || p.peek().tag == "th") {
						p.next()
					}
					continue
				}
				p.next()
			}
			continue
		}
		if t.kind == tkEnd {
			break
		}
		p.next()
	}
}

func (p *docParser) parseHtmlPre(parent *DocNode) {
	p.next()
	pre := parent.add(newDocNode(DocStyle))
	pre.Attrs["style"] = "preformatted"
	p.inPre++
	// collect raw text preserving whitespace
	var sb strings.Builder
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && t.tag == "pre" {
			p.next()
			break
		}
		p.next()
		switch t.kind {
		case tkParaBreak:
			sb.WriteString("\n\n")
		default:
			sb.WriteString(t.text)
		}
	}
	p.inPre--
	w := pre.add(newDocNode(DocText))
	w.Text = sb.String()
}

func (p *docParser) parseHtmlHeader(parent *DocNode) {
	t := p.next()
	h := parent.add(newDocNode(DocHtmlHeader))
	h.Level = int(t.tag[1] - '0')
	for k, v := range t.attrs {
		h.Attrs["attr:"+k] = v
	}
	p.parseInline(h, func(tt *docToken) bool {
		return (tt.kind == tkHtmlTag && tt.close && tt.tag == t.tag) || tt.kind == tkParaBreak
	})
	if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == t.tag {
		p.next()
	}
}

func (p *docParser) parseBlockQuote(parent *DocNode) {
	p.next()
	bq := parent.add(newDocNode(DocHtmlBlockQuote))
	p.parseBlocks(bq, func(tt *docToken) bool { return tt.kind == tkHtmlTag && tt.close && tt.tag == "blockquote" })
	if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "blockquote" {
		p.next()
	}
}

func (p *docParser) parseDetails(parent *DocNode) {
	p.next()
	det := parent.add(newDocNode(DocHtmlDetails))
	if p.peek().kind == tkHtmlTag && !p.peek().close && p.peek().tag == "summary" {
		p.next()
		sum := det.add(newDocNode(DocHtmlSummary))
		p.parseInline(sum, func(tt *docToken) bool { return tt.kind == tkHtmlTag && tt.close && tt.tag == "summary" })
		if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "summary" {
			p.next()
		}
	}
	p.parseBlocks(det, func(tt *docToken) bool { return tt.kind == tkHtmlTag && tt.close && tt.tag == "details" })
	if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "details" {
		p.next()
	}
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > docparser.go <<'EOF'
package main

import (
	"regexp"
	"strings"
)

// DocContext carries information needed while parsing documentation.
type DocContext struct {
	d          *Doxygen
	scope      interface{} // *ClassDef, *NamespaceDef, *FileDef, *PageDef, *GroupDef or nil
	member     *MemberDef
	file       string
	line       int
	singleLine bool
	isExample  bool
	relPath    string
	fileDef    *FileDef
}

// ParsedDoc is the result of parsing a documentation block.
type ParsedDoc struct {
	Root *DocNode
}

type docToken struct {
	kind  int // 0 word, 1 whitespace, 2 newline, 3 command, 4 html tag, 5 entity, 6 listitem marker, 7 paragraph break, 8 end
	text  string
	cmd   string
	tag   string
	close bool
	attrs map[string]string
	indent int
	ordered bool
	selfClose bool
}

const (
	tkWord = iota
	tkWhitespace
	tkNewline
	tkCommand
	tkHtmlTag
	tkEntity
	tkListItem
	tkParaBreak
	tkEnd
	tkEndList
	tkRawText
)

// docParser parses documentation text.
type docParser struct {
	ctx    *DocContext
	text   string
	pos    int
	toks   []docToken
	tpos   int
	root   *DocNode
	sectionLevelOffset int
	autoTocCount int
	warnFile string
	warnLine int
	inPre  int
}

// parseDocText parses a documentation string into a tree.
func (d *Doxygen) parseDocText(ctx *DocContext, text string) *DocNode {
	if ctx.d == nil {
		ctx.d = d
	}
	p := &docParser{ctx: ctx}
	if d.cfg.Bool("MARKDOWN_SUPPORT") {
		text = processMarkdown(text, ctx)
	}
	if text == "" || text[len(text)-1] != '\n' {
		text += "\n"
	}
	p.text = text
	p.tokenize()
	p.root = newDocNode(DocRoot)
	p.root.Flag = ctx.singleLine
	p.parseBlocks(p.root, nil)
	return p.root
}

// ---------------------------------------------------------------------------
// Tokenizer

var htmlTagRe = regexp.MustCompile(`^<(/?)([a-zA-Z][a-zA-Z0-9]*)((?:\s+[a-zA-Z_:][-a-zA-Z0-9_:.]*(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(/?)>`)
var htmlAttrRe = regexp.MustCompile(`([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s>]+))?`)
var entityRe = regexp.MustCompile(`^&(#[0-9]+|#[xX][0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);`)
var listMarkerRe = regexp.MustCompile(`^([ \t]*)(-#|-|\*|\+|[0-9]+\.)[ \t]+`)

func (p *docParser) tokenize() {
	text := p.text
	i := 0
	n := len(text)
	atLineStart := true
	var toks []docToken
	for i < n {
		c := text[i]
		if atLineStart {
			// detect list markers at the start of a line
			if m := listMarkerRe.FindStringSubmatch(text[i:]); m != nil {
				indent := len(m[1])
				marker := m[2]
				ordered := marker == "-#" || (marker[len(marker)-1] == '.')
				// "- " markers must not be followed by '-' (horizontal rule handled by markdown)
				toks = append(toks, docToken{kind: tkListItem, indent: indent, ordered: ordered, text: m[0]})
				i += len(m[0])
				atLineStart = false
				continue
			}
			// blank line -> paragraph break
			j := i
			for j < n && (text[j] == ' ' || text[j] == '\t') {
				j++
			}
			if j < n && text[j] == '\n' {
				// one or more blank lines
				for j < n {
					k := j
					for k < n && (text[k] == ' ' || text[k] == '\t') {
						k++
					}
					if k < n && text[k] == '\n' {
						j = k + 1
					} else {
						break
					}
				}
				toks = append(toks, docToken{kind: tkParaBreak})
				i = j
				continue
			}
			atLineStart = false
			// leading whitespace of a line is insignificant unless inside preformatted
			if j > i {
				toks = append(toks, docToken{kind: tkWhitespace, text: text[i:j], indent: j - i})
				i = j
				continue
			}
		}
		switch {
		case c == '\n':
			toks = append(toks, docToken{kind: tkNewline, text: "\n"})
			i++
			atLineStart = true
		case c == ' ' || c == '\t' || c == '\r':
			j := i
			for j < n && (text[j] == ' ' || text[j] == '\t' || text[j] == '\r') {
				j++
			}
			toks = append(toks, docToken{kind: tkWhitespace, text: text[i:j]})
			i = j
		case (c == '\\' || c == '@') && i+1 < n:
			m := cmdRe.FindStringSubmatch(text[i:])
			if m != nil {
				cmd := m[1]
				// special: \f[ \f] \f{ \f} \f$
				if cmd == "f" && i+2 < n && (text[i+2] == '$' || text[i+2] == '[' || text[i+2] == ']' || text[i+2] == '{' || text[i+2] == '}') {
					cmd = "f" + string(text[i+2])
					toks = append(toks, docToken{kind: tkCommand, cmd: cmd, text: text[i : i+3]})
					i += 3
					continue
				}
				toks = append(toks, docToken{kind: tkCommand, cmd: cmd, text: m[0]})
				i += len(m[0])
				continue
			}
			toks = append(toks, docToken{kind: tkWord, text: string(c)})
			i++
		case c == '<':
			m := htmlTagRe.FindStringSubmatch(text[i:])
			if m != nil {
				tag := strings.ToLower(m[2])
				tk := docToken{kind: tkHtmlTag, tag: tag, close: m[1] == "/", selfClose: m[4] == "/", text: m[0], attrs: map[string]string{}}
				for _, am := range htmlAttrRe.FindAllStringSubmatch(m[3], -1) {
					v := am[2]
					if len(v) >= 2 && (v[0] == '"' || v[0] == '\'') {
						v = v[1 : len(v)-1]
					}
					tk.attrs[strings.ToLower(am[1])] = v
				}
				toks = append(toks, tk)
				i += len(m[0])
				continue
			}
			if strings.HasPrefix(text[i:], "<!--") {
				e := strings.Index(text[i:], "-->")
				if e >= 0 {
					i += e + 3
					continue
				}
			}
			toks = append(toks, docToken{kind: tkWord, text: "<"})
			i++
		case c == '&':
			m := entityRe.FindStringSubmatch(text[i:])
			if m != nil {
				toks = append(toks, docToken{kind: tkEntity, text: m[0]})
				i += len(m[0])
				continue
			}
			toks = append(toks, docToken{kind: tkWord, text: "&"})
			i++
		default:
			// word: sequence of non-space, non-special characters
			j := i
			for j < n {
				cj := text[j]
				if cj == ' ' || cj == '\t' || cj == '\n' || cj == '\r' || cj == '<' || cj == '&' {
					break
				}
				if (cj == '\\' || cj == '@') && j+1 < n && j > i {
					// command inside word (e.g. word\n) : split
					if cmdRe.MatchString(text[j:]) {
						break
					}
				}
				j++
			}
			if j == i {
				j = i + 1
			}
			toks = append(toks, docToken{kind: tkWord, text: text[i:j]})
			i = j
		}
	}
	toks = append(toks, docToken{kind: tkEnd})
	p.toks = toks
}

func (p *docParser) peek() *docToken {
	if p.tpos < len(p.toks) {
		return &p.toks[p.tpos]
	}
	return &p.toks[len(p.toks)-1]
}

func (p *docParser) next() *docToken {
	t := p.peek()
	if p.tpos < len(p.toks)-1 {
		p.tpos++
	}
	return t
}

func (p *docParser) atEnd() bool { return p.peek().kind == tkEnd }

// ---------------------------------------------------------------------------
// Block parsing

var simpleSectTitles = map[string]string{
	"see": "See also", "sa": "See also", "return": "Returns", "returns": "Returns", "result": "Returns",
	"author": "Author", "authors": "Authors", "version": "Version", "since": "Since", "date": "Date",
	"note": "Note", "warning": "Warning", "pre": "Precondition", "post": "Postcondition", "copyright": "Copyright",
	"invariant": "Invariant", "remark": "Remarks", "remarks": "Remarks", "attention": "Attention", "important": "Important",
	"par": "", "rcs": "", "deprecated": "Deprecated", "todo": "Todo", "bug": "Bug", "test": "Test",
}

var simpleSectClass = map[string]string{
	"see": "see", "sa": "see", "return": "return", "returns": "return", "result": "return",
	"author": "author", "authors": "authors", "version": "version", "since": "since", "date": "date",
	"note": "note", "warning": "warning", "pre": "pre", "post": "post", "copyright": "copyright",
	"invariant": "invariant", "remark": "remark", "remarks": "remark", "attention": "attention", "important": "important",
	"par": "user", "rcs": "rcs",
}

var xrefSections = map[string]struct{ list, title string }{
	"todo":       {"todo", "Todo"},
	"bug":        {"bug", "Bug"},
	"test":       {"test", "Test"},
	"deprecated": {"deprecated", "Deprecated"},
}

func isBlockCommand(cmd string) bool {
	switch cmd {
	case "param", "tparam", "retval", "exception", "throw", "throws", "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph",
		"code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "li", "arg",
		"image", "dotfile", "mscfile", "diafile", "plantumlfile", "include", "dontinclude", "verbinclude", "htmlinclude", "latexinclude", "snippet", "snippetlineno", "includelineno", "includedoc", "snippetdoc",
		"skip", "skipline", "until", "line", "parblock", "endparblock", "internal", "endinternal", "secreflist", "endsecreflist", "tableofcontents", "xrefitem", "refitem", "copydetails", "copydoc":
		return true
	}
	if _, ok := simpleSectTitles[cmd]; ok {
		return true
	}
	return false
}

// parseBlocks parses a sequence of paragraphs and block-level constructs into parent.
// stopAt lists html tags which terminate the block sequence (e.g. "/li").
func (p *docParser) parseBlocks(parent *DocNode, stop func(*docToken) bool) {
	for !p.atEnd() {
		t := p.peek()
		if stop != nil && stop(t) {
			return
		}
		switch t.kind {
		case tkParaBreak:
			p.next()
			continue
		case tkNewline, tkWhitespace:
			p.next()
			continue
		case tkListItem:
			p.parseAutoList(parent)
			continue
		case tkHtmlTag:
			if !t.close {
				switch t.tag {
				case "ul", "ol":
					p.parseHtmlList(parent)
					continue
				case "dl":
					p.parseHtmlDescList(parent)
					continue
				case "table":
					p.parseHtmlTable(parent)
					continue
				case "pre":
					p.parseHtmlPre(parent)
					continue
				case "h1", "h2", "h3", "h4", "h5", "h6":
					p.parseHtmlHeader(parent)
					continue
				case "hr":
					p.next()
					parent.add(newDocNode(DocHorRuler))
					continue
				case "blockquote":
					p.parseBlockQuote(parent)
					continue
				case "details":
					p.parseDetails(parent)
					continue
				}
			} else {
				// stray closing tag at block level: skip
				switch t.tag {
				case "p", "div", "ul", "ol", "li", "dl", "dd", "dt", "table", "tr", "td", "th", "blockquote", "details", "summary", "center", "pre", "h1", "h2", "h3", "h4", "h5", "h6":
					p.next()
					continue
				}
			}
		case tkCommand:
			switch t.cmd {
			case "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph":
				p.parseSection(parent)
				continue
			case "code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "iliteral":
				p.parseVerbatim(parent)
				continue
			case "li", "arg":
				p.parseSimpleList(parent)
				continue
			case "internal":
				p.next()
				if !p.ctx.d.cfg.Bool("INTERNAL_DOCS") {
					p.skipUntilCommand("endinternal")
				}
				continue
			case "endinternal", "endparblock", "endsecreflist":
				p.next()
				continue
			case "parblock":
				p.next()
				pb := parent.add(newDocNode(DocParBlock))
				p.parseBlocks(pb, func(t *docToken) bool { return t.kind == tkCommand && t.cmd == "endparblock" })
				if p.peek().kind == tkCommand && p.peek().cmd == "endparblock" {
					p.next()
				}
				continue
			case "tableofcontents":
				p.next()
				p.skipLineArgs()
				parent.add(newDocNode(DocTocList))
				continue
			case "secreflist":
				p.next()
				sl := parent.add(newDocNode(DocSecRefList))
				for !p.atEnd() {
					tt := p.peek()
					if tt.kind == tkCommand && tt.cmd == "endsecreflist" {
						p.next()
						break
					}
					if tt.kind == tkCommand && tt.cmd == "refitem" {
						p.next()
						p.skipWhitespace()
						target := p.readWord()
						item := sl.add(newDocNode(DocSecRefItem))
						item.Text = target
						item.Target = p.ctx.d.resolveLink(target, p.ctx)
						item.Children = nil
						// title is the rest of the line
						title := p.readRestOfLine()
						item.Attrs["title"] = strings.TrimSpace(title)
						continue
					}
					p.next()
				}
				continue
			}
		}
		// default: a paragraph
		p.parsePara(parent, stop)
	}
}

func (p *docParser) skipUntilCommand(cmd string) {
	for !p.atEnd() {
		t := p.next()
		if t.kind == tkCommand && t.cmd == cmd {
			return
		}
	}
}

func (p *docParser) skipWhitespace() {
	for p.peek().kind == tkWhitespace {
		p.next()
	}
}

func (p *docParser) skipLineArgs() {
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkNewline || t.kind == tkParaBreak {
			break
		}
		p.next()
	}
}

// readWord reads the next word token (or returns "").
func (p *docParser) readWord() string {
	p.skipWhitespace()
	t := p.peek()
	if t.kind == tkWord {
		p.next()
		return t.text
	}
	if t.kind == tkCommand {
		p.next()
		return t.text
	}
	return ""
}

// readRestOfLine returns the raw text until the end of the current line.
func (p *docParser) readRestOfLine() string {
	var sb strings.Builder
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkNewline || t.kind == tkParaBreak || t.kind == tkEnd {
			break
		}
		p.next()
		sb.WriteString(t.text)
	}
	return sb.String()
}

// readQuotedOrWord reads either a "quoted string" or a single word.
func (p *docParser) readQuotedOrWord() string {
	p.skipWhitespace()
	t := p.peek()
	if t.kind == tkWord && strings.HasPrefix(t.text, "\"") {
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			sb.WriteString(tt.text)
			if strings.HasSuffix(tt.text, "\"") && (sb.Len() > 1) {
				break
			}
			if tt.kind == tkNewline {
				break
			}
		}
		s := sb.String()
		s = strings.TrimSuffix(strings.TrimPrefix(s, "\""), "\"")
		return s
	}
	return p.readWord()
}

// parsePara parses a paragraph (inline content) until a paragraph break or block construct.
func (p *docParser) parsePara(parent *DocNode, stop func(*docToken) bool) {
	para := newDocNode(DocPara)
	parent.add(para)
	p.parseInline(para, func(t *docToken) bool {
		if stop != nil && stop(t) {
			return true
		}
		switch t.kind {
		case tkParaBreak, tkListItem:
			return true
		case tkHtmlTag:
			if !t.close {
				switch t.tag {
				case "ul", "ol", "dl", "table", "pre", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "blockquote", "p", "details":
					return true
				}
			} else {
				switch t.tag {
				case "p", "li", "dd", "dt", "td", "th", "tr", "ul", "ol", "dl", "table", "blockquote", "details", "summary", "div":
					return true
				}
			}
		case tkCommand:
			switch t.cmd {
			case "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph", "code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "li", "arg", "internal", "endinternal", "parblock", "endparblock", "tableofcontents", "secreflist", "endsecreflist", "endcode", "endverbatim", "iliteral":
				return true
			}
		}
		return false
	})
	// remove empty paragraphs
	if len(para.Children) == 0 {
		parent.Children = parent.Children[:len(parent.Children)-1]
		return
	}
	// drop trailing whitespace-only nodes? doxygen keeps the trailing whitespace as a single space
	trimTrailingWhitespace(para)
	// a <p> tag directly after this paragraph starts a new paragraph
	if p.peek().kind == tkHtmlTag && p.peek().tag == "p" && !p.peek().close {
		p.next()
	}
}

// trimTrailingWhitespace collapses trailing whitespace of a paragraph into one space node
// (doxygen emits a single space for whitespace tokens).
func trimTrailingWhitespace(para *DocNode) {
	for len(para.Children) > 1 {
		last := para.Children[len(para.Children)-1]
		prev := para.Children[len(para.Children)-2]
		if last.Kind == DocWhitespace && prev.Kind == DocWhitespace {
			para.Children = para.Children[:len(para.Children)-1]
			continue
		}
		break
	}
	// a paragraph consisting only of whitespace is empty
	if len(para.Children) == 1 && para.Children[0].Kind == DocWhitespace {
		para.Children = nil
	}
}

// addWhitespace appends a whitespace node, merging consecutive ones.
func addWhitespace(para *DocNode) {
	if len(para.Children) > 0 && para.Children[len(para.Children)-1].Kind == DocWhitespace {
		return
	}
	if len(para.Children) == 0 {
		return // leading whitespace is dropped
	}
	para.add(newDocNode(DocWhitespace))
}

var inlineStyleTags = map[string]string{
	"b": "bold", "strong": "bold", "i": "italic", "em": "italic", "code": "code", "tt": "code", "u": "underline",
	"strike": "strike", "s": "s", "del": "del", "ins": "ins", "sub": "subscript", "sup": "superscript", "small": "small",
	"cite": "cite", "center": "center", "span": "span", "div": "div", "var": "italic", "kbd": "code", "dfn": "italic", "samp": "code",
}

// parseInline parses inline content into node until stop returns true.
func (p *docParser) parseInline(node *DocNode, stop func(*docToken) bool) {
	for !p.atEnd() {
		t := p.peek()
		if stop(t) {
			return
		}
		switch t.kind {
		case tkWord:
			p.next()
			p.addWord(node, t.text)
		case tkWhitespace, tkNewline:
			p.next()
			addWhitespace(node)
		case tkEntity:
			p.next()
			sym := node.add(newDocNode(DocSymbol))
			sym.Text = t.text
		case tkRawText:
			p.next()
			r := node.add(newDocNode(DocHtmlRaw))
			r.Text = t.text
		case tkHtmlTag:
			p.next()
			p.handleInlineHtmlTag(node, t, stop)
		case tkCommand:
			p.next()
			p.handleInlineCommand(node, t, stop)
		default:
			p.next()
		}
	}
}

func (p *docParser) addWord(node *DocNode, text string) {
	// autolinking
	if p.ctx.d.cfg.Bool("AUTOLINK_SUPPORT") && p.inPre == 0 {
		if ln := p.ctx.d.autoLinkWord(text, p.ctx); ln != nil {
			node.add(ln)
			return
		}
	}
	w := node.add(newDocNode(DocWord))
	w.Text = text
}

func (p *docParser) handleInlineHtmlTag(node *DocNode, t *docToken, stop func(*docToken) bool) {
	if t.close {
		return // unmatched closing tag: ignore
	}
	switch t.tag {
	case "br":
		node.add(newDocNode(DocLineBreak))
	case "a":
		a := newDocNode(DocURL)
		if href, ok := t.attrs["href"]; ok {
			a.Kind = DocURL
			a.Text = href
			a.Attrs["href"] = href
			node.add(a)
			p.parseInline(a, func(tt *docToken) bool { return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == "a" && tt.close) })
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if name, ok := t.attrs["name"]; ok {
			a.Kind = DocAnchor
			a.Text = name
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if id, ok := t.attrs["id"]; ok {
			a.Kind = DocAnchor
			a.Text = id
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		}
	case "img":
		img := node.add(newDocNode(DocImage))
		img.Attrs = t.attrs
		img.Text = t.attrs["src"]
		img.Attrs["html"] = "1"
	case "p":
		// handled as paragraph break by caller
	default:
		if style, ok := inlineStyleTags[t.tag]; ok {
			s := newDocNode(DocStyle)
			s.Attrs["style"] = style
			s.Attrs["tag"] = t.tag
			for k, v := range t.attrs {
				s.Attrs["attr:"+k] = v
			}
			node.add(s)
			if t.selfClose {
				return
			}
			p.parseInline(s, func(tt *docToken) bool {
				return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == t.tag && tt.close)
			})
			if p.peek().kind == tkHtmlTag && p.peek().tag == t.tag && p.peek().close {
				p.next()
			}
			return
		}
		// unknown tag: emit as text? doxygen warns and ignores. Keep raw for things like <div>.
		r := node.add(newDocNode(DocHtmlRaw))
		r.Text = t.text
	}
}

func (p *docParser) handleInlineCommand(node *DocNode, t *docToken, stop func(*docToken) bool) {
	cmd := t.cmd
	switch cmd {
	case "n":
		node.add(newDocNode(DocLineBreak))
	case "a", "e", "em":
		p.styledWord(node, "italic")
	case "b":
		p.styledWord(node, "bold")
	case "c", "p":
		p.styledWord(node, "code")
	case "ref", "refitem":
		p.parseRef(node, false)
	case "link":
		p.parseLink(node)
	case "endlink":
	case "anchor":
		name := p.readWord()
		a := node.add(newDocNode(DocAnchor))
		a.Text = name
	case "cite":
		name := p.readWord()
		c := node.add(newDocNode(DocCite))
		c.Text = name
	case "emoji":
		name := p.readWord()
		e := node.add(newDocNode(DocEmoji))
		e.Text = strings.Trim(name, ":")
	case "copybrief", "copydetails", "copydoc":
		name := p.readWord()
		c := node.add(newDocNode(DocCopy))
		c.Text = name
		c.Attrs["kind"] = cmd
	case "f$":
		// inline formula
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			if tt.kind == tkCommand && tt.cmd == "f$" {
				break
			}
			sb.WriteString(tt.text)
		}
		f := node.add(newDocNode(DocFormula))
		f.Text = "$" + sb.String() + "$"
		f.Flag = true
	case "image":
		p.parseImage(node)
	case "dotfile", "mscfile", "diafile", "plantumlfile":
		p.skipWhitespace()
		name := p.readQuotedOrWord()
		caption := strings.TrimSpace(p.readRestOfLine())
		n := node.add(newDocNode(DocDotFile))
		n.Text = name
		n.Attrs["kind"] = cmd
		n.Attrs["caption"] = caption
	case "include", "dontinclude", "verbinclude", "htmlinclude", "latexinclude", "snippet", "snippetlineno", "includelineno", "includedoc", "snippetdoc", "rtfinclude", "maninclude", "docbookinclude", "xmlinclude":
		p.parseInclude(node, cmd)
	case "skip", "skipline", "until", "line":
		p.readRestOfLine()
	case "xrefitem":
		p.skipWhitespace()
		key := p.readWord()
		heading := p.readQuotedOrWord()
		title := p.readQuotedOrWord()
		x := node.add(newDocNode(DocXRefItem))
		x.Attrs["key"] = key
		x.Attrs["heading"] = heading
		x.Attrs["title"] = title
		x.Text = title
		para := x.add(newDocNode(DocPara))
		p.parseInline(para, p.sectStop(stop))
	case "param", "tparam", "retval", "exception", "throw", "throws":
		p.parseParamSect(node, cmd, stop)
	case "~", "&", "$", "#", "<", ">", "%", "\"", ".", "::", "|", "--", "---", "\\", "@", "=":
		if cmd == "~" {
			// language switch: ignore until next \~ ... simply ignore the command
			lang := p.readWord()
			_ = lang
			return
		}
		w := node.add(newDocNode(DocWord))
		w.Text = cmd
		if cmd == "::" {
			w.Text = "::"
		}
		if cmd == "--" {
			w.Text = "--"
		}
	case "showdate":
		p.readRestOfLine()
	case "ifile", "iline", "ianchor", "iprefix", "ilinebr", "ilinebr_i", "isection":
		p.readRestOfLine()
	case "showinitializer", "hideinitializer", "callgraph", "callergraph", "hidecallgraph", "hidecallergraph", "showrefby", "hiderefby", "showrefs", "hiderefs", "nosubgrouping", "static", "pure", "private", "protected", "public":
	case "brief", "short", "details":
		// already handled by comment scanner; ignore here (a leftover means text follows)
	case "endcode", "endverbatim", "endhtmlonly", "endlatexonly", "endxmlonly", "endmanonly", "endrtfonly", "enddocbookonly", "enddot", "endmsc", "enduml", "f]", "f}", "endiliteral":
	case "if", "ifnot", "elseif", "else", "endif":
		p.handleIf(node, cmd, stop)
	case "cond", "endcond":
		p.readRestOfLine()
	case "startuml":
		p.parseVerbatim(node)
	default:
		if _, ok := simpleSectTitles[cmd]; ok {
			p.parseSimpleSect(node, cmd, stop)
			return
		}
		// unknown command: doxygen warns "Found unknown command '\cmd'"
		warnDocErr(p.ctx.file, p.ctx.line, "Found unknown command '\\%s'", cmd)
	}
}

func (p *docParser) sectStop(stop func(*docToken) bool) func(*docToken) bool {
	return func(t *docToken) bool {
		if stop(t) {
			return true
		}
		if t.kind == tkParaBreak || t.kind == tkListItem {
			return true
		}
		if t.kind == tkCommand && isBlockCommand(t.cmd) {
			return true
		}
		if t.kind == tkHtmlTag && !t.close {
			switch t.tag {
			case "ul", "ol", "dl", "table", "pre", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "blockquote", "p":
				return true
			}
		}
		return false
	}
}

func (p *docParser) handleIf(node *DocNode, cmd string, stop func(*docToken) bool) {
	// conditional sections: evaluate the section name against ENABLED_SECTIONS
	switch cmd {
	case "if", "ifnot":
		expr := p.readWord()
		enabled := p.ctx.d.sectionEnabled(expr)
		if cmd == "ifnot" {
			enabled = !enabled
		}
		if enabled {
			return
		}
		// skip until matching else/elseif/endif
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				case "else":
					if depth == 0 {
						return
					}
				case "elseif":
					if depth == 0 {
						e := p.readWord()
						if p.ctx.d.sectionEnabled(e) {
							return
						}
					}
				}
			}
		}
	case "else", "elseif":
		// we reached an else branch while the if branch was active: skip to endif
		if cmd == "elseif" {
			p.readWord()
		}
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				}
			}
		}
	case "endif":
	}
}

// styledWord handles \a word, \b word, \c word.
func (p *docParser) styledWord(node *DocNode, style string) {
	p.skipWhitespace()
	t := p.peek()
	if t.kind != tkWord {
		return
	}
	p.next()
	word := t.text
	// trailing punctuation stays outside the style
	trail := ""
	for len(word) > 0 {
		c := word[len(word)-1]
		if c == '.' || c == ',' || c == ';' || c == ':' || c == ')' || c == '?' || c == '!' {
			trail = string(c) + trail
			word = word[:len(word)-1]
			continue
		}
		break
	}
	if word == "" {
		word = t.text
		trail = ""
	}
	s := node.add(newDocNode(DocStyle))
	s.Attrs["style"] = style
	s.Attrs["cmd"] = "1"
	w := s.add(newDocNode(DocWord))
	w.Text = word
	if trail != "" {
		w2 := node.add(newDocNode(DocWord))
		w2.Text = trail
	}
}

func (p *docParser) parseRef(node *DocNode, isLink bool) {
	p.skipWhitespace()
	target := p.readWord()
	if target == "" {
		return
	}
	// strip trailing punctuation from the target
	trail := ""
	for len(target) > 1 {
		c := target[len(target)-1]
		if c == '.' || c == ',' || c == ';' || c == ':' || c == '?' || c == '!' {
			trail = string(c) + trail
			target = target[:len(target)-1]
			continue
		}
		break
	}
	ref := newDocNode(DocRef)
	ref.Text = target
	// optional "text"
	save := p.tpos
	p.skipWhitespace()
	if t := p.peek(); t.kind == tkWord && strings.HasPrefix(t.text, "\"") {
		txt := p.readQuotedOrWord()
		ref.Attrs["text"] = txt
	} else {
		p.tpos = save
	}
	ref.Target = p.ctx.d.resolveLink(target, p.ctx)
	node.add(ref)
	if ref.Target == nil {
		warnDocErr(p.ctx.file, p.ctx.line, "unable to resolve reference to '%s' for \\ref command", target)
	}
	if trail != "" {
		w := node.add(newDocNode(DocWord))
		w.Text = trail
	}
}

func (p *docParser) parseLink(node *DocNode) {
	p.skipWhitespace()
	target := p.readWord()
	ref := newDocNode(DocRef)
	ref.Text = target
	ref.Target = p.ctx.d.resolveLink(target, p.ctx)
	node.add(ref)
	p.parseInline(ref, func(t *docToken) bool { return t.kind == tkCommand && t.cmd == "endlink" || t.kind == tkParaBreak })
	if p.peek().kind == tkCommand && p.peek().cmd == "endlink" {
		p.next()
	}
	if len(ref.Children) > 0 {
		var sb strings.Builder
		for _, c := range ref.Children {
			if c.Kind == DocWord {
				sb.WriteString(c.Text)
			} else if c.Kind == DocWhitespace {
				sb.WriteString(" ")
			}
		}
		ref.Attrs["text"] = strings.TrimSpace(sb.String())
		ref.Children = nil
	}
}

func (p *docParser) parseImage(node *DocNode) {
	p.skipWhitespace()
	// optional {options}
	t := p.peek()
	if t.kind == tkWord && strings.HasPrefix(t.text, "{") {
		for !p.atEnd() {
			tt := p.next()
			if strings.Contains(tt.text, "}") {
				break
			}
		}
		p.skipWhitespace()
	}
	format := p.readWord()
	name := p.readQuotedOrWord()
	img := newDocNode(DocImage)
	img.Attrs["format"] = format
	img.Text = name
	// optional caption (quoted) and size
	rest := strings.TrimSpace(p.readRestOfLine())
	if strings.HasPrefix(rest, "\"") {
		e := strings.Index(rest[1:], "\"")
		if e >= 0 {
			img.Attrs["caption"] = rest[1 : 1+e]
			rest = strings.TrimSpace(rest[e+2:])
		}
	}
	for _, f := range strings.Fields(rest) {
		if strings.HasPrefix(f, "width=") {
			img.Attrs["width"] = f[6:]
		} else if strings.HasPrefix(f, "height=") {
			img.Attrs["height"] = f[7:]
		}
	}
	if format == "html" || format == "" {
		node.add(img)
		p.ctx.d.copyImage(name)
	} else if format == "latex" || format == "rtf" || format == "docbook" || format == "xml" {
		img.Attrs["skip"] = "1"
		node.add(img)
	}
}

func (p *docParser) parseInclude(node *DocNode, cmd string) {
	p.skipWhitespace()
	// optional {options}
	t := p.peek()
	opts := ""
	if t.kind == tkWord && strings.HasPrefix(t.text, "{") {
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			sb.WriteString(tt.text)
			if strings.Contains(tt.text, "}") {
				break
			}
		}
		opts = sb.String()
		p.skipWhitespace()
	}
	name := p.readQuotedOrWord()
	inc := node.add(newDocNode(DocInclude))
	inc.Attrs["cmd"] = cmd
	inc.Attrs["opts"] = opts
	inc.Text = name
	if cmd == "snippet" || cmd == "snippetlineno" || cmd == "snippetdoc" {
		inc.Attrs["block"] = strings.TrimSpace(p.readRestOfLine())
	}
	// resolve example file
	inc.File = p.ctx.d.findExampleFile(name)
}

// parseSimpleSect parses \note, \return etc. The node is appended to the current paragraph.
func (p *docParser) parseSimpleSect(para *DocNode, cmd string, stop func(*docToken) bool) {
	if xs, ok := xrefSections[cmd]; ok {
		x := para.add(newDocNode(DocXRefItem))
		x.Attrs["key"] = xs.list
		x.Attrs["heading"] = xs.title
		x.Attrs["title"] = xs.title
		x.Text = xs.title
		inner := x.add(newDocNode(DocPara))
		p.parseInline(inner, p.sectStop(stop))
		trimTrailingWhitespace(inner)
		return
	}
	ss := newDocNode(DocSimpleSect)
	ss.Attrs["type"] = cmd
	ss.Attrs["class"] = simpleSectClass[cmd]
	ss.Attrs["title"] = simpleSectTitles[cmd]
	if cmd == "par" {
		// user defined title on the rest of the line
		title := strings.TrimSpace(p.readRestOfLine())
		ss.Attrs["title"] = title
		if p.peek().kind == tkNewline {
			p.next()
		}
	}
	// merge consecutive sections of the same type (e.g. multiple \see) handled by the visitor
	para.add(ss)
	inner := ss.add(newDocNode(DocPara))
	p.parseInline(inner, p.sectStop(stop))
	trimTrailingWhitespace(inner)
	if len(inner.Children) == 0 {
		ss.Children = nil
	}
}

// parseParamSect parses \param [in|out] name description.
func (p *docParser) parseParamSect(para *DocNode, cmd string, stop func(*docToken) bool) {
	ps := newDocNode(DocParamSect)
	ps.Attrs["type"] = cmd
	// merge into a previous param section of the same type in this paragraph
	if len(para.Children) > 0 {
		last := para.Children[len(para.Children)-1]
		if last.Kind == DocParamSect && last.Attrs["type"] == paramSectType(cmd) {
			ps = last
		} else {
			ps.Attrs["type"] = paramSectType(cmd)
			para.add(ps)
		}
	} else {
		ps.Attrs["type"] = paramSectType(cmd)
		para.add(ps)
	}
	item := ps.add(newDocNode(DocParamList))
	p.skipWhitespace()
	// direction
	if cmd == "param" {
		t := p.peek()
		if t.kind == tkWord && strings.HasPrefix(t.text, "[") {
			// may be "[in]" or "[in," "out]"
			var sb strings.Builder
			for !p.atEnd() {
				tt := p.next()
				sb.WriteString(tt.text)
				if strings.Contains(tt.text, "]") {
					break
				}
			}
			dir := strings.ReplaceAll(sb.String(), " ", "")
			item.Attrs["dir"] = dir
			p.skipWhitespace()
		}
	}
	// names separated by commas
	for {
		t := p.peek()
		if t.kind != tkWord {
			break
		}
		p.next()
		name := t.text
		more := strings.HasSuffix(name, ",")
		name = strings.TrimSuffix(name, ",")
		for _, nm := range strings.Split(name, ",") {
			if nm != "" {
				item.Names = append(item.Names, nm)
			}
		}
		if !more {
			// check for ", name" continuation
			save := p.tpos
			p.skipWhitespace()
			if nt := p.peek(); nt.kind == tkWord && strings.HasPrefix(nt.text, ",") {
				p.next()
				rest := strings.TrimPrefix(nt.text, ",")
				if rest != "" {
					item.Names = append(item.Names, rest)
				}
				p.skipWhitespace()
				continue
			}
			p.tpos = save
			break
		}
		p.skipWhitespace()
	}
	desc := item.add(newDocNode(DocPara))
	p.parseInline(desc, p.sectStop(stop))
	trimTrailingWhitespace(desc)
	// check parameter names against the member's argument list
	if cmd == "param" && p.ctx.member != nil {
		p.ctx.d.checkParamName(p.ctx, item.Names)
	}
}

func paramSectType(cmd string) string {
	switch cmd {
	case "tparam":
		return "tparam"
	case "retval":
		return "retval"
	case "exception", "throw", "throws":
		return "exception"
	}
	return "param"
}

func (p *docParser) parseSection(parent *DocNode) {
	t := p.next()
	level := 1
	switch t.cmd {
	case "subsection":
		level = 2
	case "subsubsection":
		level = 3
	case "paragraph":
		level = 4
	case "subparagraph":
		level = 5
	case "subsubparagraph":
		level = 6
	}
	p.skipWhitespace()
	id := p.readWord()
	title := strings.TrimSpace(p.readRestOfLine())
	sec := parent.add(newDocNode(DocSection))
	sec.Level = level
	sec.Anchor = id
	sec.Text = title
	if si := p.ctx.d.findSection(id); si != nil {
		sec.File = si.Ref
		if title == "" {
			sec.Text = si.Title
		}
	}
	// the section contains the following blocks until the next section of same or higher level
	p.parseBlocks(sec, func(tt *docToken) bool {
		if tt.kind == tkCommand {
			switch tt.cmd {
			case "section":
				return true
			case "subsection":
				return level >= 2
			case "subsubsection":
				return level >= 3
			case "paragraph":
				return level >= 4
			case "subparagraph":
				return level >= 5
			case "subsubparagraph":
				return level >= 6
			}
		}
		return false
	})
}

func (p *docParser) parseVerbatim(parent *DocNode) {
	t := p.next()
	cmd := t.cmd
	end := "end" + cmd
	switch cmd {
	case "f[":
		end = "f]"
	case "f{":
		end = "f}"
	case "startuml":
		end = "enduml"
	}
	// optional {options} for code
	opts := ""
	if cmd == "code" || cmd == "iliteral" {
		save := p.tpos
		p.skipWhitespace()
		tt := p.peek()
		if tt.kind == tkWord && strings.HasPrefix(tt.text, "{") {
			var sb strings.Builder
			for !p.atEnd() {
				x := p.next()
				sb.WriteString(x.text)
				if strings.Contains(x.text, "}") {
					break
				}
			}
			opts = strings.Trim(sb.String(), "{}")
		} else {
			p.tpos = save
		}
	}
	// collect raw text until the end command
	var sb strings.Builder
	first := true
	for !p.atEnd() {
		tt := p.next()
		if tt.kind == tkCommand && tt.cmd == end {
			break
		}
		if tt.kind == tkEnd {
			break
		}
		if first && (tt.kind == tkNewline) {
			first = false
			continue
		}
		first = false
		switch tt.kind {
		case tkParaBreak:
			sb.WriteString("\n\n")
		case tkListItem:
			sb.WriteString(tt.text)
		default:
			sb.WriteString(tt.text)
		}
	}
	v := newDocNode(DocVerbatim)
	v.Attrs["kind"] = cmd
	v.Attrs["opts"] = opts
	text := sb.String()
	// remove trailing newline (added back by the visitor)
	v.Text = text
	// the verbatim block belongs to the current paragraph in doxygen's model; we add it to the parent
	parent.add(v)
}

// parseAutoList parses markdown-style '-' lists.
func (p *docParser) parseAutoList(parent *DocNode) {
	first := p.peek()
	indent := first.indent
	list := parent.add(newDocNode(DocAutoList))
	list.Ordered = first.ordered
	num := 1
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkListItem || t.indent != indent {
			// nested list?
			if t.kind == tkListItem && t.indent > indent && len(list.Children) > 0 {
				item := list.Children[len(list.Children)-1]
				p.parseAutoList(item)
				continue
			}
			break
		}
		if t.ordered != list.Ordered {
			break
		}
		p.next()
		item := list.add(newDocNode(DocAutoListItem))
		item.Num = num
		num++
		para := item.add(newDocNode(DocPara))
		p.parseInline(para, func(tt *docToken) bool {
			switch tt.kind {
			case tkParaBreak, tkListItem:
				return true
			case tkCommand:
				return isBlockCommand(tt.cmd) && tt.cmd != "li" || tt.cmd == "endcode"
			case tkHtmlTag:
				if !tt.close {
					switch tt.tag {
					case "ul", "ol", "dl", "table", "pre", "p":
						return true
					}
				} else {
					switch tt.tag {
					case "li", "ul", "ol", "dd", "td", "p":
						return true
					}
				}
			}
			return false
		})
		trimTrailingWhitespace(para)
		// paragraph break followed by an indented continuation or nested list
		if p.peek().kind == tkParaBreak {
			save := p.tpos
			p.next()
			nt := p.peek()
			if nt.kind == tkListItem && nt.indent > indent {
				p.parseAutoList(item)
				continue
			}
			if nt.kind == tkListItem && nt.indent == indent && nt.ordered == list.Ordered {
				// same list continues after blank line
				continue
			}
			p.tpos = save
			break
		}
	}
	if len(list.Children) == 0 {
		parent.Children = parent.Children[:len(parent.Children)-1]
	}
}

// parseSimpleList parses \li / \arg items.
func (p *docParser) parseSimpleList(parent *DocNode) {
	list := parent.add(newDocNode(DocSimpleList))
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkCommand || (t.cmd != "li" && t.cmd != "arg") {
			break
		}
		p.next()
		item := list.add(newDocNode(DocSimpleListItem))
		para := item.add(newDocNode(DocPara))
		p.parseInline(para, func(tt *docToken) bool {
			if tt.kind == tkParaBreak || tt.kind == tkListItem {
				return true
			}
			if tt.kind == tkCommand && isBlockCommand(tt.cmd) {
				return true
			}
			return false
		})
		trimTrailingWhitespace(para)
	}
}

func (p *docParser) parseHtmlList(parent *DocNode) {
	open := p.next()
	list := parent.add(newDocNode(DocHtmlList))
	list.Ordered = open.tag == "ol"
	for k, v := range open.attrs {
		list.Attrs["attr:"+k] = v
	}
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && (t.tag == open.tag) {
			p.next()
			break
		}
		if t.kind == tkHtmlTag && !t.close && t.tag == "li" {
			p.next()
			item := list.add(newDocNode(DocHtmlListItem))
			for k, v := range t.attrs {
				item.Attrs["attr:"+k] = v
			}
			p.parseBlocks(item, func(tt *docToken) bool {
				return tt.kind == tkHtmlTag && ((tt.close && (tt.tag == "li" || tt.tag == open.tag)) || (!tt.close && tt.tag == "li"))
			})
			if p.peek().kind == tkHtmlTag && p.peek().close && p.peek().tag == "li" {
				p.next()
			}
			continue
		}
		if t.kind == tkEnd {
			break
		}
		p.next()
	}
}

func (p *docParser) parseHtmlDescList(parent *DocNode) {
	p.next()
	dl := parent.add(newDocNode(DocHtmlDescList))
	for !p.atEnd() {
		t := p.peek()
		if t.kind == tkHtmlTag && t.close && t.tag == "dl" {
			p.next()
			break
		}
		if t.kind == tkHtmlTag && !t.close && (t.tag == "dt" || t.tag == "dd") {
