	mdImageRe     = regexp.MustCompile(`!\[([^\]]*)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)`)
	mdRefLinkRe   = regexp.MustCompile(`\[([^\]]+)\]\[([^\]]*)\]`)
	mdAutoLinkRe  = regexp.MustCompile(`<((?:https?|ftp|file)://[^>\s]+|mailto:[^>\s]+)>`)
	mdLinkDefRe   = regexp.MustCompile(`^[ \t]{0,3}\[([^\]]+)\]:[ \t]*(\S+)(?:[ \t]+["'(]([^"')]*)["')])?[ \t]*$`)
	mdStrikeRe    = regexp.MustCompile(`~~([^~\s][^~]*?)~~`)
)

// processMarkdown converts markdown constructs into doxygen/HTML commands.
func processMarkdown(text string, ctx *DocContext) string {
	lines := strings.Split(text, "\n")
	var out []string
	inFence := false
	fenceMarker := ""
	fenceIndent := 0
	// collect link definitions
	linkDefs := map[string][2]string{}
	for _, l := range lines {
		if m := mdLinkDefRe.FindStringSubmatch(l); m != nil {
			linkDefs[strings.ToLower(m[1])] = [2]string{m[2], m[3]}
		}
	}
	inCodeCmd := false
	for i := 0; i < len(lines); i++ {
		l := lines[i]
		// doxygen verbatim/code blocks are passed through
		if inCodeCmd {
			out = append(out, l)
			if strings.Contains(l, "\\endcode") || strings.Contains(l, "@endcode") || strings.Contains(l, "\\endverbatim") || strings.Contains(l, "@endverbatim") || strings.Contains(l, "endhtmlonly") || strings.Contains(l, "endlatexonly") || strings.Contains(l, "enddot") || strings.Contains(l, "enduml") || strings.Contains(l, "endmsc") {
				inCodeCmd = false
			}
			continue
		}
		if inFence {
			if m := mdFenceRe.FindStringSubmatch(l); m != nil && strings.HasPrefix(m[2], fenceMarker[:1]) && len(m[2]) >= len(fenceMarker) && m[3] == "" {
				inFence = false
				out = append(out, "@endcode")
				continue
			}
			// remove the fence indentation
			if fenceIndent > 0 && len(l) >= fenceIndent && strings.TrimSpace(l[:fenceIndent]) == "" {
				l = l[fenceIndent:]
			}
			out = append(out, l)
			continue
		}
		if m := mdFenceRe.FindStringSubmatch(l); m != nil {
			inFence = true
			fenceMarker = m[2]
			fenceIndent = len(m[1])
			lang := m[3]
			if lang != "" {
				if !strings.HasPrefix(lang, ".") {
					lang = "." + lang
				}
				out = append(out, "@code{"+lang+"}")
			} else {
				out = append(out, "@code")
			}
			continue
		}
		if hasCodeCmdStart(l) {
			out = append(out, processInlineMarkdown(l, linkDefs, ctx))
			if !(strings.Contains(l, "\\endcode") || strings.Contains(l, "@endcode") || strings.Contains(l, "\\endverbatim") || strings.Contains(l, "@endverbatim")) {
				inCodeCmd = true
			}
			continue
		}
		// link definition lines are removed
		if mdLinkDefRe.MatchString(l) {
			out = append(out, "")
			continue
		}
		// headers
		if m := mdHeaderRe.FindStringSubmatch(l); m != nil {
			level := len(m[1])
			title := m[2]
			id := ""
			if im := mdHeaderIdRe.FindStringSubmatch(title); im != nil {
				id = im[1]
				title = strings.TrimSpace(title[:len(title)-len(im[0])])
			}
			out = append(out, makeHeader(level, title, id, ctx))
			continue
		}
		// setext headers
		if i+1 < len(lines) && strings.TrimSpace(l) != "" && mdSetextRe.MatchString(lines[i+1]) && !strings.HasPrefix(strings.TrimSpace(l), "-") && !isListLine(l) {
			level := 1
			if strings.HasPrefix(strings.TrimSpace(lines[i+1]), "-") {
				level = 2
			}
			title := strings.TrimSpace(l)
			id := ""
			if im := mdHeaderIdRe.FindStringSubmatch(title); im != nil {
				id = im[1]
				title = strings.TrimSpace(title[:len(title)-len(im[0])])
			}
			out = append(out, makeHeader(level, title, id, ctx))
			out = append(out, "")
			i++
			continue
		}
		// horizontal rules
		if mdHRuleRe.MatchString(l) && !isListLine(l) {
			out = append(out, "<hr>")
			continue
		}
		// tables
		if i+1 < len(lines) && strings.Contains(l, "|") && mdTableSepRe.MatchString(lines[i+1]) && mdTableRowRe.MatchString(l) {
			end := i + 2
			for end < len(lines) && strings.Contains(lines[end], "|") && strings.TrimSpace(lines[end]) != "" {
				end++
			}
			out = append(out, convertTable(lines[i:end], linkDefs, ctx)...)
			i = end - 1
			continue
		}
		// block quotes
		if m := mdBlockQuoteRe.FindStringSubmatch(l); m != nil && !strings.HasPrefix(strings.TrimSpace(l), ">>") {
			var q []string
			j := i
			for j < len(lines) {
				if bm := mdBlockQuoteRe.FindStringSubmatch(lines[j]); bm != nil {
					q = append(q, bm[1])
					j++
					continue
				}
				break
			}
			inner := processMarkdown(strings.Join(q, "\n"), ctx)
			out = append(out, "<blockquote class=\"doxtable\">")
			out = append(out, strings.Split(inner, "\n")...)
			out = append(out, "</blockquote>")
			i = j - 1
			continue
		}
		// indented code blocks (4 spaces / tab) after a blank line
		if (strings.HasPrefix(l, "    ") || strings.HasPrefix(l, "\t")) && strings.TrimSpace(l) != "" && (i == 0 || strings.TrimSpace(lines[i-1]) == "") && !isListLine(l) && !inListContext(lines, i) {
			j := i
			var code []string
			for j < len(lines) && (strings.HasPrefix(lines[j], "    ") || strings.HasPrefix(lines[j], "\t") || strings.TrimSpace(lines[j]) == "") {
				if strings.TrimSpace(lines[j]) == "" {
					code = append(code, "")
				} else if strings.HasPrefix(lines[j], "\t") {
					code = append(code, lines[j][1:])
				} else {
					code = append(code, lines[j][4:])
				}
				j++
			}
			// trim trailing blank lines
			for len(code) > 0 && code[len(code)-1] == "" {
				code = code[:len(code)-1]
				j--
			}
			out = append(out, "@verbatim")
			out = append(out, code...)
			out = append(out, "@endverbatim")
			i = j - 1
			continue
		}
		out = append(out, processInlineMarkdown(l, linkDefs, ctx))
	}
	if inFence {
		out = append(out, "@endcode")
	}
	return strings.Join(out, "\n")
}

func hasCodeCmdStart(l string) bool {
	for _, c := range []string{"\\code", "@code", "\\verbatim", "@verbatim", "\\htmlonly", "@htmlonly", "\\latexonly", "@latexonly", "\\dot", "@dot", "\\startuml", "@startuml", "\\msc", "@msc"} {
		if idx := strings.Index(l, c); idx >= 0 {
			// make sure it's not \endcode etc. and followed by non-letter
			after := l[idx+len(c):]
			if after == "" || !isIdentChar(after[0]) {
				if c == "\\dot" || c == "@dot" {
					if strings.Contains(l, c+"file") {
						continue
					}
				}
				return true
			}
		}
	}
	return false
}

func inListContext(lines []string, i int) bool {
	// indented text following a list item is part of the list, not a code block
	for j := i - 1; j >= 0; j-- {
		t := strings.TrimSpace(lines[j])
		if t == "" {
			continue
		}
		if isListLine(lines[j]) {
			return true
		}
		return false
	}
	return false
}

func isListLine(l string) bool {
	return listMarkerRe.MatchString(l)
}

func makeHeader(level int, title string, id string, ctx *DocContext) string {
	tocLevel := ctx.d.cfg.Int("TOC_INCLUDE_HEADINGS")
	_, isPage := ctx.scope.(*PageDef)
	if isPage || ctx.scope == nil {
		if level <= tocLevel || id != "" {
			if id == "" {
				id = ctx.d.nextAutoTocId(title)
			}
			cmd := []string{"", "section", "subsection", "subsubsection", "paragraph", "subparagraph", "subsubparagraph"}[level]
			ctx.d.registerSection(id, title, cmd, ctx)
			return "@" + cmd + " " + id + " " + title
		}
	}
	if id != "" {
		return "<h" + intToStr(level) + " id=\"" + id + "\">" + title + "</h" + intToStr(level) + ">"
	}
	return "<h" + intToStr(level) + ">" + title + "</h" + intToStr(level) + ">"
}

func (d *Doxygen) nextAutoTocId(title string) string {
	if d.cfg.Enum("MARKDOWN_ID_STYLE") == "GITHUB" {
		id := strings.ToLower(title)
		var sb strings.Builder
		for i := 0; i < len(id); i++ {
			c := id[i]
			if c == ' ' {
				sb.WriteByte('-')
			} else if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c >= 0x80 {
				sb.WriteByte(c)
			}
		}
		return sb.String()
	}
	id := "autotoc_md" + intToStr(d.autoTocCounter)
	d.autoTocCounter++
	return id
}

func convertTable(rows []string, linkDefs map[string][2]string, ctx *DocContext) []string {
	var out []string
	splitRow := func(r string) []string {
		r = strings.TrimSpace(r)
		r = strings.TrimPrefix(r, "|")
		r = strings.TrimSuffix(r, "|")
		var cells []string
		var cur strings.Builder
		for i := 0; i < len(r); i++ {
			if r[i] == '\\' && i+1 < len(r) && r[i+1] == '|' {
				cur.WriteByte('|')
				i++
				continue
			}
			if r[i] == '|' {
				cells = append(cells, strings.TrimSpace(cur.String()))
				cur.Reset()
				continue
			}
			cur.WriteByte(r[i])
		}
		cells = append(cells, strings.TrimSpace(cur.String()))
		return cells
	}
	header := splitRow(rows[0])
	seps := splitRow(rows[1])
	aligns := make([]string, len(seps))
	for i, s := range seps {
		s = strings.TrimSpace(s)
		switch {
		case strings.HasPrefix(s, ":") && strings.HasSuffix(s, ":"):
			aligns[i] = "center"
		case strings.HasSuffix(s, ":"):
			aligns[i] = "right"
		case strings.HasPrefix(s, ":"):
			aligns[i] = "left"
		}
	}
	out = append(out, "<table class=\"markdownTable\">")
	writeRow := func(cells []string, isHeader bool, rowIdx int) {
		cls := "markdownTableHead"
		if !isHeader {
			if rowIdx%2 == 1 {
				cls = "markdownTableRowOdd"
			} else {
				cls = "markdownTableRowEven"
			}
		}
		line := "<tr class=\"" + cls + "\">"
		for i, c := range cells {
			tag := "td"
			if isHeader {
				tag = "th"
			}
			align := ""
			if i < len(aligns) {
				align = aligns[i]
			}
			cellCls := "markdownTableHead"
			if !isHeader {
				cellCls = "markdownTableBody"
			}
			if align != "" {
				cellCls += capitalize(align)
			} else {
				cellCls += "None"
			}
			attrs := " class=\"" + cellCls + "\""
			if align != "" {
				attrs += " align=\"" + align + "\""
			}
			line += "<" + tag + attrs + ">" + processInlineMarkdown(c, linkDefs, ctx) + "</" + tag + ">"
		}
		line += "</tr>"
		out = append(out, line)
	}
	writeRow(header, true, 0)
	for i, r := range rows[2:] {
		cells := splitRow(r)
		for len(cells) < len(header) {
			cells = append(cells, "")
		}
		writeRow(cells, false, i+1)
	}
	out = append(out, "</table>")
	return out
}

// processInlineMarkdown handles emphasis, code spans, links and images within a line.
func processInlineMarkdown(l string, linkDefs map[string][2]string, ctx *DocContext) string {
	// code spans first (protect their content)
	var sb strings.Builder
	i := 0
	for i < len(l) {
		c := l[i]
		if c == '`' {
			// find closing backtick run
			j := i
			for j < len(l) && l[j] == '`' {
				j++
			}
			run := l[i:j]
			end := strings.Index(l[j:], run)
			if end >= 0 {
				code := l[j : j+end]
				code = strings.TrimSpace(code)
				sb.WriteString("<tt>" + escapeDoxyChars(code) + "</tt>")
				i = j + end + len(run)
				continue
			}
			sb.WriteString(run)
			i = j
			continue
		}
		if c == '\\' && i+1 < len(l) {
			// escaped markdown char or doxygen command: keep as-is (two chars)
			if i+2 <= len(l) && (l[i+1] == '*' || l[i+1] == '_' || l[i+1] == '`' || l[i+1] == '#' || l[i+1] == '[' || l[i+1] == ']' || l[i+1] == '(' || l[i+1] == ')' || l[i+1] == '|') {
				sb.WriteString(l[i : i+2])
				i += 2
				continue
			}
			// doxygen command: copy the command word
			j := i + 1
			for j < len(l) && isIdentChar(l[j]) {
				j++
			}
			if j == i+1 && j < len(l) {
				j++
			}
			sb.WriteString(l[i:j])
			i = j
			continue
		}
		if c == '!' && i+1 < len(l) && l[i+1] == '[' {
			if m := mdImageRe.FindStringSubmatchIndex(l[i:]); m != nil && m[0] == 0 {
				alt := l[i+m[2] : i+m[3]]
				src := l[i+m[4] : i+m[5]]
				title := ""
				if m[6] >= 0 {
					title = l[i+m[6] : i+m[7]]
				}
				if strings.Contains(src, "://") {
					sb.WriteString("<img src=\"" + src + "\" alt=\"" + alt + "\"" + optTitle(title) + "/>")
				} else {
					sb.WriteString("@image{inline} html " + src)
					if title != "" {
						sb.WriteString(" \"" + title + "\"")
					}
					sb.WriteString("\n")
				}
				i += m[1]
				continue
			}
		}
		if c == '[' {
			if m := mdLinkRe.FindStringSubmatchIndex(l[i:]); m != nil && m[0] == 0 {
				text := l[i+m[2] : i+m[3]]
				url := l[i+m[4] : i+m[5]]
				title := ""
				if m[6] >= 0 {
					title = l[i+m[6] : i+m[7]]
				}
				sb.WriteString(makeLink(text, url, title, ctx))
				i += m[1]
				continue
			}
			if m := mdRefLinkRe.FindStringSubmatchIndex(l[i:]); m != nil && m[0] == 0 {
				text := l[i+m[2] : i+m[3]]
				ref := l[i+m[4] : i+m[5]]
				if ref == "" {
					ref = text
				}
				if def, ok := linkDefs[strings.ToLower(ref)]; ok {
					sb.WriteString(makeLink(text, def[0], def[1], ctx))
					i += m[1]
					continue
				}
			}
		}
		if c == '<' {
			if m := mdAutoLinkRe.FindStringSubmatchIndex(l[i:]); m != nil && m[0] == 0 {
				url := l[i+m[2] : i+m[3]]
				sb.WriteString("<a href=\"" + url + "\">" + url + "</a>")
				i += m[1]
				continue
			}
		}
		if (c == '*' || c == '_') && isEmphStart(l, i) {
			// find the closing marker
			marker := string(c)
			if i+1 < len(l) && l[i+1] == c {
				marker = string(c) + string(c)
			}
			end := findEmphEnd(l, i+len(marker), marker)
			if end > 0 {
				inner := l[i+len(marker) : end]
				tag := "em"
				if len(marker) == 2 {
					tag = "b"
				}
				sb.WriteString("<" + tag + ">" + processInlineMarkdown(inner, linkDefs, ctx) + "</" + tag + ">")
				i = end + len(marker)
				continue
			}
		}
		if c == '~' && i+1 < len(l) && l[i+1] == '~' {
			if m := mdStrikeRe.FindStringSubmatchIndex(l[i:]); m != nil && m[0] == 0 {
				sb.WriteString("<strike>" + processInlineMarkdown(l[i+m[2]:i+m[3]], linkDefs, ctx) + "</strike>")
				i += m[1]
				continue
			}
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

func optTitle(t string) string {
	if t == "" {
		return ""
	}
	return " title=\"" + t + "\""
}

func makeLink(text, url, title string, ctx *DocContext) string {
	if strings.HasPrefix(url, "#") {
		return "@ref " + url[1:] + " \"" + text + "\""
	}
	if strings.Contains(url, "://") || strings.HasPrefix(url, "mailto:") || strings.HasPrefix(url, "www.") {
		return "<a href=\"" + url + "\"" + optTitle(title) + ">" + text + "</a>"
	}
	// local file or reference: if it is a known markdown file -> page ref; otherwise a link
	if strings.HasSuffix(strings.ToLower(url), ".md") || strings.HasSuffix(strings.ToLower(url), ".markdown") {
		return "@ref " + markdownFileNameToId(url, ctx.d) + " \"" + text + "\""
	}
	if !strings.ContainsAny(url, "./") {
		return "@ref " + url + " \"" + text + "\""
	}
	return "<a href=\"" + url + "\"" + optTitle(title) + ">" + text + "</a>"
}

func escapeDoxyChars(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\\':
			sb.WriteString("\\\\")
		case '@':
			sb.WriteString("\\@")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		case '*', '_', '`', '#', '[', ']', '|':
			sb.WriteByte('\\')
			sb.WriteByte(c)
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func isEmphStart(l string, i int) bool {
	c := l[i]
	// must be at word start: previous char is not alphanumeric (for '_' also not inside words)
	if i > 0 && isIdentChar(l[i-1]) && c == '_' {
		return false
	}
	if i > 0 && isIdentChar(l[i-1]) {
		return false
	}
	j := i
	for j < len(l) && l[j] == c {
		j++
	}
	if j-i > 2 {
		return false
	}
	if j >= len(l) {
		return false
	}
	// next char must be non-space
	return l[j] != ' ' && l[j] != '\t' && l[j] != c
}

func findEmphEnd(l string, start int, marker string) int {
	for j := start; j+len(marker) <= len(l); j++ {
		if l[j:j+len(marker)] == marker {
			// closing must be preceded by non-space and not followed by alnum (for _)
			if j > start && l[j-1] != ' ' && l[j-1] != '\t' {
				if j+len(marker) < len(l) && isIdentChar(l[j+len(marker)]) && marker[0] == '_' {
					continue
				}
				if j+len(marker) < len(l) && l[j+len(marker)] == marker[0] {
					continue
				}
				return j
			}
		}
		if l[j] == '`' {
			// skip code spans
			e := strings.IndexByte(l[j+1:], '`')
			if e >= 0 {
				j += e + 1
			}
		}
	}
	return -1
}
