		scopeName = scopePart(scopeName)
	}
	return nil
}

func (d *Doxygen) findMemberForLink(name string, ctx *DocContext) *MemberDef {
	n := strings.TrimSpace(name)
	args := ""
	if i := strings.Index(n, "("); i >= 0 {
		args = n[i:]
		n = n[:i]
	}
	_ = args
	scope := scopePart(n)
	local := stripScope(n)
	var scopeName string
	var scopeClass *ClassDef
	switch s := ctx.scope.(type) {
	case *ClassDef:
		scopeName = s.QualName
		scopeClass = s
	case *NamespaceDef:
		scopeName = s.QualName
	}
	if ctx.member != nil && ctx.member.Class != nil {
		scopeClass = ctx.member.Class
		scopeName = scopeClass.QualName
	}
	var best *MemberDef
	for _, md := range d.allMembers {
		if md.Name != local || !md.isLinkable(d) {
			continue
		}
		if scope != "" {
			if md.ScopeName == scope || strings.HasSuffix(md.ScopeName, "::"+scope) || (scopeName != "" && md.ScopeName == scopeName+"::"+scope) {
				return md
			}
			continue
		}
		// unqualified: prefer same scope, then global
		if md.ScopeName == scopeName {
			return md
		}
		if best == nil && (md.ScopeName == "" || scopeName == "") {
			best = md
		}
		if best == nil {
			best = md
		}
	}
	if scopeClass != nil && scope == "" {
		// inherited members
		for _, b := range scopeClass.Bases {
			if b.Class != nil {
				for _, md := range b.Class.Members {
					if md.Name == local && md.isLinkable(d) {
						return md
					}
				}
			}
		}
	}
	return best
}

// autoLinkWord creates a linked word node for words that match documented entities.
func (d *Doxygen) autoLinkWord(word string, ctx *DocContext) *DocNode {
	if len(word) < 2 {
		return nil
	}
	for _, w := range d.cfg.List("AUTOLINK_IGNORE_WORDS") {
		if w == word {
			return nil
		}
	}
	// strip trailing punctuation
	core := word
	trail := ""
	for len(core) > 0 {
		c := core[len(core)-1]
		if c == '.' || c == ',' || c == ';' || c == ':' || c == '?' || c == '!' || c == ')' {
			if c == ')' && strings.HasSuffix(core, "()") {
				break
			}
			trail = string(c) + trail
			core = core[:len(core)-1]
			continue
		}
		break
	}
	if core == "" {
		return nil
	}
	// function call form name() or Class::member()
	isFunc := strings.HasSuffix(core, "()")
	nameOnly := strings.TrimSuffix(core, "()")
	if !isValidLinkWord(nameOnly) {
		return nil
	}
	var target *LinkTarget
	hasScope := strings.Contains(nameOnly, "::")
	// a word needs an uppercase letter / scope / () to be autolinked (doxygen heuristics for classes)
	if cd := d.classMap[nameOnly]; cd != nil && cd.isLinkable(d) && !isFunc && (hasUpper(nameOnly) || hasScope || cd.Lang != "cpp" && cd.Lang != "c") {
		target = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
	} else if cd := d.findClassForLink(nameOnly, ctx); cd != nil && !isFunc && (hasUpper(nameOnly) || hasScope) {
		target = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
	} else if isFunc || hasScope {
		if md := d.findMemberForLink(nameOnly, ctx); md != nil {
			target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.Name, Def: md}
		}
	} else if ns := d.nsMap[nameOnly]; ns != nil && ns.isLinkable(d) && hasUpper(nameOnly) {
		target = &LinkTarget{File: ns.OutputBase, Name: ns.QualName, Def: ns}
	}
	if target == nil {
		// member of the current class without ()?  doxygen links words matching members only with ()
		return nil
	}
	d.symbolLookupHits++
	n := newDocNode(DocLinkedWord)
	n.Text = core
	n.Target = target
	if trail != "" {
		// the caller only adds a single node; wrap in a container paragraph fragment
		wrap := newDocNode(DocText)
		wrap.add(n)
		w := wrap.add(newDocNode(DocWord))
		w.Text = trail
		return wrap
	}
	return n
}

func hasUpper(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			return true
		}
	}
	return false
}

func isValidLinkWord(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(isIdentChar(c) || c == ':' || c == '~' || c == '<' || c == '>' || c == '.' || c == '#') {
			return false
		}
	}
	return isIdentStart(s[0]) || s[0] == '~'
}

func (d *Doxygen) copyImage(name string) {
	// copy an image from IMAGE_PATH to the html output directory
	for _, img := range d.imageFiles {
		if filepath.Base(img) == name {
			if d.htmlDir != "" {
				data, err := os.ReadFile(img)
				if err == nil {
					os.WriteFile(filepath.Join(d.htmlDir, name), data, 0644)
				}
			}
			if d.latexDir != "" {
				data, err := os.ReadFile(img)
				if err == nil {
					os.WriteFile(filepath.Join(d.latexDir, name), data, 0644)
				}
			}
			return
		}
	}
	// file may exist relative to the current directory
	if fileExists(name) && d.htmlDir != "" {
		data, _ := os.ReadFile(name)
		os.WriteFile(filepath.Join(d.htmlDir, filepath.Base(name)), data, 0644)
	}
}

func (d *Doxygen) findExampleFile(name string) string {
	for _, ex := range d.exampleFiles {
		if filepath.Base(ex) == name || strings.HasSuffix(ex, "/"+name) {
			return ex
		}
	}
	return ""
}

func (d *Doxygen) checkParamName(ctx *DocContext, names []string) {
	md := ctx.member
	if md == nil || md.ArgList == nil {
		return
	}
	for _, n := range names {
		found := false
		for _, a := range md.ArgList.Args {
			if a.Name == n || strings.TrimLeft(a.Name, "*&") == n {
				found = true
			}
			if a.Type == n && a.Name == "" {
				found = true
			}
		}
		if !found && warnIfDocErr {
			// find the member signature for the message
			args := strings.TrimSpace(md.Args)
			warn(ctx.file, ctx.line, "argument '%s' of command @param is not found in the argument list of %s%s", n, md.QualName, args)
		}
	}
}

// outputFile returns the output file base of a member (the file where its documentation lives).
func (md *MemberDef) outputFile(d *Doxygen) string {
	if md.EnumScope != nil && md.Kind == MemberEnumValue {
		return md.EnumScope.outputFile(d)
	}
	if md.Class != nil {
		return md.Class.OutputBase
	}
	if md.Namespace != nil && md.Namespace.isLinkable(d) {
		return md.Namespace.OutputBase
	}
	if md.FileDef != nil {
		return md.FileDef.OutputBase
	}
	return ""
}

// ---------------------------------------------------------------------------
// Linkability rules

func (cd *ClassDef) isLinkable(d *Doxygen) bool {
	if cd.Name == "" || cd.IsAnonymous || cd.Artificial || cd.Hidden {
		return false
	}
	if !d.protectionVisible(cd.Prot) {
		return false
	}
	if cd.IsLocal && !d.cfg.Bool("EXTRACT_LOCAL_CLASSES") {
		return false
	}
	if d.cfg.Bool("HIDE_UNDOC_CLASSES") && !cd.hasDocumentation(d) {
		return false
	}
	// nested classes of non-linkable classes are not linkable
	if outer, ok := cd.OuterScope.(*ClassDef); ok && !outer.isLinkable(d) {
		return false
	}
	return true
}

func (cd *ClassDef) hasDocumentation(d *Doxygen) bool {
	return d.cfg.Bool("EXTRACT_ALL") || cd.Doc.hasDocs()
}

func (ns *NamespaceDef) isLinkable(d *Doxygen) bool {
	if ns.IsAnonymous && !d.cfg.Bool("EXTRACT_ANON_NSPACES") {
		return false
	}
	return d.cfg.Bool("EXTRACT_ALL") || ns.Doc.hasDocs() || !d.cfg.Bool("HIDE_UNDOC_NAMESPACES")
}

func (ns *NamespaceDef) hasDocumentation(d *Doxygen) bool {
	return d.cfg.Bool("EXTRACT_ALL") || ns.Doc.hasDocs()
}

func (fd *FileDef) hasDocumentation(d *Doxygen) bool {
	return d.cfg.Bool("EXTRACT_ALL") || fd.Doc.hasDocs()
}

func (fd *FileDef) isLinkable(d *Doxygen) bool {
	if fd.IsDocFile {
		return false
	}
	return fd.hasDocumentation(d) && d.cfg.Bool("SHOW_FILES")
}

// hasDocumentation for members.
func (md *MemberDef) hasDocumentation(d *Doxygen) bool {
	if d.cfg.Bool("EXTRACT_ALL") {
		return true
	}
	if md.Doc.hasDocs() {
		return true
	}
	if md.ArgList != nil {
		for _, a := range md.ArgList.Args {
			if a.Docs != "" {
				return true
			}
		}
	}
	return false
}

// isBriefSectionVisible: whether the member is shown in the declaration list.
func (md *MemberDef) isBriefSectionVisible(d *Doxygen) bool {
	cfg := d.cfg
	extractStatic := cfg.Bool("EXTRACT_STATIC")
	hideUndocMembers := cfg.Bool("HIDE_UNDOC_MEMBERS")
	briefMemberDesc := cfg.Bool("BRIEF_MEMBER_DESC")
	repeatBrief := cfg.Bool("REPEAT_BRIEF")
	visibleIfStatic := !(md.Class == nil && md.Static && !extractStatic)
	visibleIfDocumented := !hideUndocMembers || md.hasDocumentation(d)
	visibleIfEnabled := !(hideUndocMembers && md.Doc.Doc == "" && !briefMemberDesc && !repeatBrief)
	visibleIfPrivate := d.protectionVisible(md.Prot) || md.Kind == MemberFriend ||
		(md.Prot == Private && (md.Virtual || md.Override || md.Final) && cfg.Bool("EXTRACT_PRIV_VIRTUAL") && md.hasDocumentation(d))
	cOrDTor := md.IsCtor || md.IsDtor
	noArgs := md.ArgList == nil || len(md.ArgList.Args) == 0 || (len(md.ArgList.Args) == 1 && md.ArgList.Args[0].Type == "void")
	visibleIfNotDefaultCDTor := !(cOrDTor && noArgs && !md.hasDocumentation(d))
	visibleIfFriendCompound := !(cfg.Bool("HIDE_FRIEND_COMPOUNDS") && md.Kind == MemberFriend && (md.Type == "friend class" || md.Type == "friend struct" || md.Type == "friend union"))
	return visibleIfStatic && visibleIfDocumented && visibleIfEnabled && visibleIfPrivate && visibleIfNotDefaultCDTor && visibleIfFriendCompound && !md.Anonymous
}

// isDetailedSectionLinkable: whether a detailed description section exists.
func (md *MemberDef) isDetailedSectionLinkable(d *Doxygen) bool {
	cfg := d.cfg
	extractAll := cfg.Bool("EXTRACT_ALL")
	alwaysDetailedSec := cfg.Bool("ALWAYS_DETAILED_SEC")
	repeatBrief := cfg.Bool("REPEAT_BRIEF")
	briefMemberDesc := cfg.Bool("BRIEF_MEMBER_DESC")
	extractStatic := cfg.Bool("EXTRACT_STATIC")
	docEnumValues := false
	if md.Kind == MemberEnum {
		for _, ev := range md.EnumValues {
			if ev.Doc.hasDocs() {
				docEnumValues = true
			}
		}
	}
	argDocs := false
	if md.ArgList != nil {
		for _, a := range md.ArgList.Args {
			if a.Docs != "" {
				argDocs = true
			}
		}
	}
	docFilter := extractAll || md.Doc.Doc != "" || md.Doc.InBody != "" ||
		(md.Kind == MemberEnum && docEnumValues) ||
		(md.Kind == MemberEnumValue && md.Doc.Brief != "") ||
		(md.Doc.Brief != "" && alwaysDetailedSec && (repeatBrief || !briefMemberDesc)) ||
		argDocs
	staticFilter := md.Class != nil || !md.Static || extractStatic
	privateFilter := d.protectionVisible(md.Prot) || md.Kind == MemberFriend ||
		(md.Prot == Private && (md.Virtual || md.Override || md.Final) && cfg.Bool("EXTRACT_PRIV_VIRTUAL") && md.hasDocumentation(d))
	friendCompoundFilter := !(cfg.Bool("HIDE_FRIEND_COMPOUNDS") && md.Kind == MemberFriend && (md.Type == "friend class" || md.Type == "friend struct" || md.Type == "friend union"))
	return docFilter && staticFilter && privateFilter && friendCompoundFilter
}

// isDetailedSectionVisible: shown in the detailed section of the compound
func (md *MemberDef) isDetailedSectionVisible(d *Doxygen, inGroup bool, inFile bool) bool {
	groupFilter := true
	fileFilter := true
	if inFile && md.Namespace != nil && md.Namespace.isLinkable(d) {
		// namespace members are documented in the namespace, not the file
		fileFilter = false
	}
	return md.isDetailedSectionLinkable(d) && groupFilter && fileFilter
}

// isLinkable: whether the member can be linked to.
func (md *MemberDef) isLinkable(d *Doxygen) bool {
	if md.Kind == MemberEnumValue && md.EnumScope != nil {
		return md.EnumScope.isLinkable(d) || md.isDetailedSectionLinkable(d)
	}
	if md.Class != nil && !md.Class.isLinkable(d) {
		return false
	}
	if md.Namespace != nil && !md.Namespace.isLinkable(d) {
		// members of non-linkable namespaces are documented in the file
		if md.FileDef == nil || !md.FileDef.isLinkable(d) {
			return false
		}
	}
	if md.Class == nil && md.Namespace == nil && (md.FileDef == nil || !md.FileDef.isLinkable(d)) {
		return false
	}
	return md.isDetailedSectionLinkable(d)
}
