package main

import (
	"strings"
)

// HtmlDocVisitor renders a documentation tree as HTML.
type HtmlDocVisitor struct {
	d       *Doxygen
	sb      *strings.Builder
	ctx     *DocContext
	relPath string
	insidePre int
	hide    int
}

func (d *Doxygen) docToHtml(root *DocNode, ctx *DocContext, relPath string) string {
	var sb strings.Builder
	v := &HtmlDocVisitor{d: d, sb: &sb, ctx: ctx, relPath: relPath}
	for _, c := range root.Children {
		v.visit(c)
	}
	return sb.String()
}

func (v *HtmlDocVisitor) w(s string) { v.sb.WriteString(s) }

func (v *HtmlDocVisitor) visitChildren(n *DocNode) {
	for _, c := range n.Children {
		v.visit(c)
	}
}

// paragraphContext determines whether a paragraph is the first/last in its parent.
func paragraphContext(p *DocNode) (isFirst, isLast bool) {
	parent := p.Parent
	if parent == nil {
		return true, true
	}
	var first, last *DocNode
	for _, c := range parent.Children {
		if c.Kind == DocPara || c.Kind == DocVerbatim || c.Kind == DocAutoList || c.Kind == DocSimpleList || c.Kind == DocHtmlList || c.Kind == DocHtmlTable || c.Kind == DocHtmlDescList || c.Kind == DocSection || c.Kind == DocHtmlHeader || c.Kind == DocHorRuler || c.Kind == DocHtmlBlockQuote || c.Kind == DocParBlock || c.Kind == DocTocList || c.Kind == DocSecRefList || c.Kind == DocHtmlDetails {
			if first == nil {
				first = c
			}
			last = c
		}
	}
	return first == p, last == p
}

func paraNeedsTag(p *DocNode) bool {
	parent := p.Parent
	if parent == nil {
		return false
	}
	needsTag := false
	switch parent.Kind {
	case DocSection, DocInternal, DocHtmlListItem, DocHtmlDescData, DocHtmlCell, DocSimpleListItem, DocAutoListItem, DocSimpleSect, DocXRefItem, DocCopy, DocHtmlBlockQuote, DocParBlock, DocHtmlDetails, DocHtmlSummary:
		needsTag = true
	case DocRoot:
		needsTag = !parent.Flag
	}
	if needsTag {
		isFirst, isLast := paragraphContext(p)
		if isFirst && isLast {
			needsTag = false
		}
	}
	return needsTag
}

// isBlockNode: nodes that break a paragraph (rendered outside <p>)
func isBlockNode(n *DocNode) bool {
	switch n.Kind {
	case DocSimpleSect, DocParamSect, DocXRefItem, DocVerbatim, DocAutoList, DocSimpleList, DocHtmlList, DocHtmlTable, DocHtmlDescList, DocHtmlHeader, DocHorRuler, DocHtmlBlockQuote, DocParBlock, DocImage, DocInclude, DocTocList, DocSecRefList, DocHtmlDetails, DocDotFile:
		if n.Kind == DocImage && n.Attrs["inline"] == "1" {
			return false
		}
		if n.Kind == DocVerbatim {
			k := n.Attrs["kind"]
			if k == "htmlonly" || k == "latexonly" || k == "xmlonly" || k == "manonly" || k == "rtfonly" || k == "docbookonly" {
				return false
			}
		}
		return true
	case DocStyle:
		return n.Attrs["style"] == "preformatted" || n.Attrs["style"] == "div" || n.Attrs["style"] == "center"
	case DocFormula:
		return !n.Flag
	}
	return false
}

func (v *HtmlDocVisitor) visitPara(p *DocNode) {
	needsTag := paraNeedsTag(p)
	// a paragraph starting with a block node does not need an opening tag
	children := p.Children
	// skip leading whitespace
	open := false
	i := 0
	for i < len(children) {
		c := children[i]
		if isBlockNode(c) {
			if open {
				v.w("</p>")
				open = false
			}
			v.visit(c)
			i++
			// skip whitespace directly after a block
			for i < len(children) && children[i].Kind == DocWhitespace {
				i++
			}
			continue
		}
		if !open {
			if needsTag {
				v.w("<p>")
			}
			open = true
		}
		v.visit(c)
		i++
	}
	if open && needsTag {
		v.w("</p>\n")
	} else if open && !needsTag {
		// nothing
	}
}

func (v *HtmlDocVisitor) visit(n *DocNode) {
	if v.hide > 0 && n.Kind != DocVerbatim {
		return
	}
	switch n.Kind {
	case DocPara:
		v.visitPara(n)
	case DocText:
		if len(n.Children) > 0 {
			v.visitChildren(n)
		} else {
			v.w(htmlEscape(n.Text))
		}
	case DocWord:
		v.w(filterWord(n.Text))
	case DocLinkedWord:
		t, _ := n.Target.(*LinkTarget)
		v.startLink(t)
		v.w(filterWord(n.Text))
		v.endLink(t)
	case DocWhitespace:
		if v.insidePre > 0 {
			v.w(n.Text)
		} else {
			v.w(" ")
		}
	case DocLineBreak:
		v.w("<br />\n")
	case DocHorRuler:
		v.w("<hr/>\n")
	case DocSymbol:
		v.w(htmlEntity(n.Text))
	case DocStyle:
		v.visitStyle(n)
	case DocURL:
		href := n.Attrs["href"]
		if len(n.Children) == 0 {
			v.w("<a href=\"" + htmlEscape(href) + "\">" + htmlEscape(n.Text) + "</a>")
		} else {
			v.w("<a href=\"" + htmlEscape(href) + "\">")
			v.visitChildren(n)
			v.w("</a>")
		}
	case DocRef:
		v.visitRef(n)
	case DocAnchor:
		v.w("<a class=\"anchor\" id=\"" + n.Text + "\"></a>")
	case DocSection:
		v.visitSection(n)
	case DocHtmlHeader:
		lvl := intToStr(n.Level)
		id := n.Attrs["attr:id"]
		if id != "" {
			v.w("<h" + lvl + " id=\"" + id + "\">")
		} else {
			v.w("<h" + lvl + ">")
		}
		v.visitChildren(n)
		v.w("</h" + lvl + ">\n")
	case DocSimpleSect:
		v.visitSimpleSect(n)
	case DocParamSect:
		v.visitParamSect(n)
	case DocXRefItem:
		v.visitXRefItem(n)
	case DocVerbatim:
		v.visitVerbatim(n)
	case DocAutoList:
		if n.Ordered {
			v.w("<ol type=\"1\">\n")
		} else {
			v.w("<ul>\n")
		}
		for _, item := range n.Children {
			v.w("<li>")
			v.visitChildren(item)
			v.w("</li>\n")
		}
		if n.Ordered {
			v.w("</ol>\n")
		} else {
			v.w("</ul>\n")
		}
	case DocSimpleList:
		v.w("<ul>\n")
		for _, item := range n.Children {
			v.w("<li>")
			v.visitChildren(item)
			v.w("</li>\n")
		}
		v.w("</ul>\n")
	case DocHtmlList:
		tag := "ul"
		if n.Ordered {
			tag = "ol"
		}
		v.w("<" + tag + htmlAttrs(n) + ">\n")
		for _, item := range n.Children {
			v.w("<li" + htmlAttrs(item) + ">")
			v.visitChildren(item)
			v.w("</li>\n")
		}
		v.w("</" + tag + ">\n")
	case DocHtmlDescList:
		v.w("<dl>\n")
		for _, c := range n.Children {
			switch c.Kind {
			case DocHtmlDescTitle:
				v.w("<dt>")
				v.visitChildren(c)
				v.w("</dt>\n")
			case DocHtmlDescData:
				v.w("<dd>")
				v.visitChildren(c)
				v.w("</dd>\n")
			}
		}
		v.w("</dl>\n")
	case DocHtmlTable:
		v.visitTable(n)
	case DocHtmlBlockQuote:
		v.w("<blockquote class=\"doxtable\">\n")
		v.visitChildren(n)
		v.w("</blockquote>\n")
	case DocParBlock:
		v.w("<div class=\"doxygen-parblock\">\n")
		v.visitChildren(n)
		v.w("</div>\n")
	case DocHtmlDetails:
		v.w("<details>\n")
		for _, c := range n.Children {
			if c.Kind == DocHtmlSummary {
				v.w("<summary>")
				v.visitChildren(c)
				v.w("</summary>\n")
			} else {
				v.visit(c)
			}
		}
		v.w("</details>\n")
	case DocImage:
		v.visitImage(n)
	case DocFormula:
		v.w(htmlEscape(n.Text))
	case DocInclude:
		v.visitInclude(n)
	case DocEmoji:
		v.w(emojiHtml(n.Text))
	case DocCite:
		v.w("<b>[" + htmlEscape(n.Text) + "]</b>")
	case DocHtmlRaw:
		v.w(n.Text)
	case DocCopy:
		// \copydoc: inline the target docs
		if t := v.d.resolveLink(n.Text, v.ctx); t != nil {
			if md, ok := t.Def.(*MemberDef); ok {
				doc := md.Doc.Doc
				if n.Attrs["kind"] == "copybrief" {
					doc = md.Doc.Brief
				} else if n.Attrs["kind"] == "copydoc" && md.Doc.Brief != "" {
					doc = md.Doc.Brief + "\n\n" + md.Doc.Doc
				}
				sub := v.d.parseDocText(&DocContext{d: v.d, scope: v.ctx.scope, member: md, file: md.Doc.DocFile, line: md.Doc.DocLine}, doc)
				for _, c := range sub.Children {
					v.visit(c)
				}
			}
		}
	case DocTocList:
		// table of contents for pages
		if pg, ok := v.ctx.scope.(*PageDef); ok {
			v.writeToc(pg)
		}
	case DocSecRefList:
		v.w("<div class=\"multicol\">\n<ul>\n")
		for _, item := range n.Children {
			v.w("<li>")
			t, _ := item.Target.(*LinkTarget)
			if t != nil {
				v.startLink(t)
			}
			v.w(htmlEscape(item.Attrs["title"]))
			if t != nil {
				v.endLink(t)
			}
			v.w("</li>\n")
		}
		v.w("</ul>\n</div>\n")
	case DocDotFile:
		// graphs require dot; nothing generated
	default:
		v.visitChildren(n)
	}
}

func htmlAttrs(n *DocNode) string {
	var sb strings.Builder
	keys := []string{}
	for k := range n.Attrs {
		if strings.HasPrefix(k, "attr:") {
			keys = append(keys, k)
		}
	}
	sortStringsCI(keys)
	for _, k := range keys {
		sb.WriteString(" " + k[5:] + "=\"" + htmlEscape(n.Attrs[k]) + "\"")
	}
	return sb.String()
}

func filterWord(s string) string {
	return convertToHtml(s, false)
}

func (v *HtmlDocVisitor) startLink(t *LinkTarget) {
	if t == nil {
		return
	}
	href := ""
	if t.File != "" {
		href = v.relPath + t.File + v.d.htmlExt()
	}
	if t.Anchor != "" {
		href += "#" + t.Anchor
	}
	v.w("<a class=\"el\" href=\"" + href + "\">")
}

func (v *HtmlDocVisitor) endLink(t *LinkTarget) {
	if t == nil {
		return
	}
	v.w("</a>")
}

func (v *HtmlDocVisitor) visitRef(n *DocNode) {
	t, _ := n.Target.(*LinkTarget)
	text := n.Attrs["text"]
	if text == "" {
		if t != nil && t.Name != "" {
			text = t.Name
		} else {
			text = n.Text
		}
		if t != nil {
			if md, ok := t.Def.(*MemberDef); ok && md.Kind == MemberFunction {
				text = md.Name + "()"
			}
		}
	}
	if t == nil {
		v.w(htmlEscape(text))
		return
	}
	v.startLink(t)
	v.w(htmlEscape(text))
	v.endLink(t)
}

func (v *HtmlDocVisitor) visitStyle(n *DocNode) {
	style := n.Attrs["style"]
	switch style {
	case "bold":
		v.w("<b>")
		v.visitChildren(n)
		v.w("</b>")
	case "italic":
		v.w("<em>")
		v.visitChildren(n)
		v.w("</em>")
	case "code":
		v.w("<code>")
		v.visitChildren(n)
		v.w("</code>")
	case "underline":
		v.w("<u>")
		v.visitChildren(n)
		v.w("</u>")
	case "strike":
		v.w("<strike>")
		v.visitChildren(n)
		v.w("</strike>")
	case "s":
		v.w("<s>")
		v.visitChildren(n)
		v.w("</s>")
	case "del":
		v.w("<del>")
		v.visitChildren(n)
		v.w("</del>")
	case "ins":
		v.w("<ins>")
		v.visitChildren(n)
		v.w("</ins>")
	case "subscript":
		v.w("<sub>")
		v.visitChildren(n)
		v.w("</sub>")
	case "superscript":
		v.w("<sup>")
		v.visitChildren(n)
		v.w("</sup>")
	case "small":
		v.w("<small>")
		v.visitChildren(n)
		v.w("</small>")
	case "cite":
		v.w("<cite>")
		v.visitChildren(n)
		v.w("</cite>")
	case "center":
		v.w("<center>")
		v.visitChildren(n)
		v.w("</center>")
	case "span":
		v.w("<span" + htmlAttrs(n) + ">")
		v.visitChildren(n)
		v.w("</span>")
	case "div":
		v.w("<div" + htmlAttrs(n) + ">")
		v.visitChildren(n)
		v.w("</div>")
	case "preformatted":
		v.w("<pre>")
		v.insidePre++
		for _, c := range n.Children {
			if c.Kind == DocText {
				v.w(htmlEscape(c.Text))
			} else {
				v.visit(c)
			}
		}
		v.insidePre--
		v.w("</pre>")
	default:
		v.visitChildren(n)
	}
}

func (v *HtmlDocVisitor) visitSection(n *DocNode) {
	lvl := n.Level
	if lvl > 6 {
		lvl = 6
	}
	tag := "h" + intToStr(lvl)
	v.w("<" + tag + " class=\"doxsection\"><a class=\"anchor\" id=\"" + n.Anchor + "\"></a>\n")
	v.w(htmlEscape(n.Text))
	v.w("</" + tag + ">\n")
	v.visitChildren(n)
}

func (v *HtmlDocVisitor) visitSimpleSect(n *DocNode) {
	class := n.Attrs["class"]
	title := n.Attrs["title"]
	v.w("<dl class=\"section " + class + "\"><dt>" + htmlEscape(title) + "</dt><dd>")
	v.visitChildren(n)
	v.w("</dd></dl>\n")
}

func (v *HtmlDocVisitor) visitXRefItem(n *DocNode) {
	key := n.Attrs["key"]
	id := v.d.addXRefItem(key, n, v.ctx)
	v.w("<dl class=\"section " + key + "\"><dt>")
	v.w("<a class=\"el\" href=\"" + v.relPath + key + v.d.htmlExt() + "#" + id + "\">" + htmlEscape(n.Attrs["title"]) + "</a>")
	v.w("</dt><dd>")
	v.visitChildren(n)
	v.w("</dd></dl>\n")
}

func (v *HtmlDocVisitor) visitParamSect(n *DocNode) {
	typ := n.Attrs["type"]
	class := "params"
	title := "Parameters"
	switch typ {
	case "tparam":
		class = "tparams"
		title = "Template Parameters"
	case "retval":
		class = "retval"
		title = "Return values"
	case "exception":
		class = "exception"
		title = "Exceptions"
	}
	v.w("<dl class=\"" + class + "\"><dt>" + title + "</dt><dd>\n")
	v.w("  <table class=\"" + class + "\">\n")
	for _, item := range n.Children {
		v.w("    <tr>")
		if typ == "param" {
			dir := item.Attrs["dir"]
			hasDir := false
			for _, it := range n.Children {
				if it.Attrs["dir"] != "" {
					hasDir = true
				}
			}
			if hasDir {
				v.w("<td class=\"paramdir\">" + dir + "</td>")
			}
		}
		v.w("<td class=\"paramname\">")
		for i, name := range item.Names {
			if i > 0 {
				v.w(",")
			}
			if typ == "exception" || typ == "retval" {
				// may be a linkable type
				if t := v.d.resolveLink(name, v.ctx); t != nil && typ == "exception" {
					v.startLink(t)
					v.w(htmlEscape(name))
					v.endLink(t)
					continue
				}
			}
			v.w(htmlEscape(name))
		}
		v.w("</td><td>")
		v.visitChildren(item)
		v.w("</td></tr>\n")
	}
	v.w("  </table>\n")
	v.w("  </dd>\n")
	v.w("</dl>\n")
}

func (v *HtmlDocVisitor) visitVerbatim(n *DocNode) {
	kind := n.Attrs["kind"]
	text := n.Text
	switch kind {
	case "code", "iliteral":
		lang := n.Attrs["opts"]
		v.w("<div class=\"fragment\">")
		v.w(v.d.highlightCodeHtml(text, lang, v.ctx, v.relPath))
		v.w("</div><!-- fragment -->")
	case "verbatim":
		v.w("<pre class=\"fragment\">")
		v.w(htmlEscape(text))
		v.w("</pre>")
	case "htmlonly":
		v.w(text)
	case "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly":
	case "dot", "msc", "startuml":
		// requires external tools; nothing
	case "f[", "f{":
		v.w(htmlEscape("\\[" + text + "\\]"))
	}
}

func (v *HtmlDocVisitor) visitTable(n *DocNode) {
	cls := n.Attrs["attr:class"]
	if cls == "" {
		cls = "doxtable"
	}
	var caption *DocNode
	for _, c := range n.Children {
		if c.Kind == DocHtmlCaption {
			caption = c
		}
	}
	v.w("<table class=\"" + cls + "\"" + htmlAttrsExcept(n, "class") + ">\n")
	if caption != nil {
		v.w("<caption>")
		v.visitChildren(caption)
		v.w("</caption>\n")
	}
	for _, row := range n.Children {
		if row.Kind != DocHtmlRow {
			continue
		}
		v.w("<tr" + htmlAttrs(row) + ">\n")
		for _, cell := range row.Children {
			tag := "td"
			if cell.Flag {
				tag = "th"
			}
			v.w("<" + tag + htmlAttrs(cell) + ">")
			v.visitChildren(cell)
			v.w("</" + tag + ">")
		}
		v.w("</tr>\n")
	}
	v.w("</table>\n")
}

func htmlAttrsExcept(n *DocNode, except string) string {
	var sb strings.Builder
	keys := []string{}
	for k := range n.Attrs {
		if strings.HasPrefix(k, "attr:") && k[5:] != except {
			keys = append(keys, k)
		}
	}
	sortStringsCI(keys)
	for _, k := range keys {
		sb.WriteString(" " + k[5:] + "=\"" + htmlEscape(n.Attrs[k]) + "\"")
	}
	return sb.String()
}

func (v *HtmlDocVisitor) visitImage(n *DocNode) {
	if n.Attrs["skip"] == "1" {
		return
	}
	name := n.Text
	caption := n.Attrs["caption"]
	inline := n.Attrs["inline"] == "1" || n.Attrs["html"] == "1"
	src := name
	if !strings.Contains(src, "://") && !strings.HasPrefix(src, "/") {
		src = v.relPath + name
	}
	sizeAttr := ""
	if w := n.Attrs["width"]; w != "" {
		sizeAttr += " width=\"" + w + "\""
	}
	if h := n.Attrs["height"]; h != "" {
		sizeAttr += " height=\"" + h + "\""
	}
	if n.Attrs["html"] == "1" {
		// raw <img> tag
		v.w("<img src=\"" + htmlEscape(src) + "\"")
		if alt, ok := n.Attrs["alt"]; ok {
			v.w(" alt=\"" + htmlEscape(alt) + "\"")
		}
		v.w(sizeAttr + "/>")
		return
	}
	if inline {
		v.w("<img src=\"" + src + "\" alt=\"" + name + "\" class=\"inline\"" + sizeAttr + "/>")
		return
	}
	v.w("<div class=\"image\">\n")
	v.w("<img src=\"" + src + "\" alt=\"" + name + "\"" + sizeAttr + "/>\n")
	if caption != "" {
		v.w("<div class=\"caption\">\n" + htmlEscape(caption) + "</div>")
	}
	v.w("</div>\n")
}

func (v *HtmlDocVisitor) visitInclude(n *DocNode) {
	cmd := n.Attrs["cmd"]
	file := n.File
	if file == "" {
		warnDocErr(v.ctx.file, v.ctx.line, "included file '%s' is not found. Check your EXAMPLE_PATH", n.Text)
		return
	}
	data, err := osReadFile(file)
	if err != nil {
		return
	}
	text := string(data)
	switch cmd {
	case "include", "includelineno", "includedoc":
		v.w("<div class=\"fragment\">")
		v.w(v.d.highlightCodeHtml(text, "", v.ctx, v.relPath))
		v.w("</div><!-- fragment -->")
	case "verbinclude":
		v.w("<pre class=\"fragment\">")
		v.w(htmlEscape(text))
		v.w("</pre>")
	case "htmlinclude":
		v.w(text)
	case "snippet", "snippetlineno", "snippetdoc":
		block := n.Attrs["block"]
		marker := "[" + block + "]"
		start := strings.Index(text, marker)
		if start >= 0 {
			rest := text[start+len(marker):]
			// skip to end of line
			if nl := strings.IndexByte(rest, '\n'); nl >= 0 {
				rest = rest[nl+1:]
			}
			end := strings.Index(rest, marker)
			if end >= 0 {
				snippet := rest[:end]
				// strip the last line (containing the marker)
				if nl := strings.LastIndexByte(snippet, '\n'); nl >= 0 {
					snippet = snippet[:nl+1]
				}
				v.w("<div class=\"fragment\">")
				v.w(v.d.highlightCodeHtml(snippet, "", v.ctx, v.relPath))
				v.w("</div><!-- fragment -->")
			}
		}
	}
}

func (v *HtmlDocVisitor) writeToc(pg *PageDef) {
	// collect sections of this page
	var secs []*SectionInfo
	for _, s := range v.d.sectionList {
		if s.Ref == pg.OutputBase && s.Type != "anchor" {
			secs = append(secs, s)
		}
	}
	if len(secs) == 0 {
		return
	}
	v.w("<div class=\"toc\">")
	v.w("<h3>Table of Contents</h3>\n")
	level := 0
	for _, s := range secs {
		l := sectionLevel(s.Type)
		for level < l {
			v.w("<ul>")
			level++
		}
		for level > l {
			v.w("</ul>")
			level--
		}
		v.w("<li class=\"level" + intToStr(l) + "\"><a href=\"#" + s.Label + "\">" + htmlEscape(s.Title) + "</a></li>")
	}
	for level > 0 {
		v.w("</ul>")
		level--
	}
	v.w("</div>\n")
}

func sectionLevel(t string) int {
	switch t {
	case "section":
		return 1
	case "subsection":
		return 2
	case "subsubsection":
		return 3
	case "paragraph":
		return 4
	case "subparagraph":
		return 5
	}
	return 6
}

// htmlEntity converts an entity token (&amp; etc.) into HTML output.
func htmlEntity(e string) string {
	switch e {
	case "&nbsp;":
		return "&#160;"
	case "&copy;":
		return "&#169;"
	case "&reg;":
		return "&#174;"
	case "&trade;":
		return "&#8482;"
	case "&ndash;":
		return "&#8211;"
	case "&mdash;":
		return "&#8212;"
	case "&hellip;":
		return "&#8230;"
	case "&lsquo;":
		return "&#8216;"
	case "&rsquo;":
		return "&#8217;"
	case "&ldquo;":
		return "&#8220;"
	case "&rdquo;":
		return "&#8221;"
	}
	return e
}

func emojiHtml(name string) string {
	return "<span class=\"emoji\">&#x" + emojiCode(name) + ";</span>"
}

func (d *Doxygen) addXRefItem(key string, n *DocNode, ctx *DocContext) string {
	if d.xrefLists == nil {
		d.xrefLists = map[string][]*XRefEntry{}
	}
	id := "_" + key + intToStr(len(d.xrefLists[key])+1)
	var scopeName, scopeFile, anchor string
	switch s := ctx.scope.(type) {
	case *ClassDef:
		scopeName = s.QualName
		scopeFile = s.OutputBase
	case *NamespaceDef:
		scopeName = s.QualName
		scopeFile = s.OutputBase
	case *FileDef:
		scopeName = s.displayName(d)
		scopeFile = s.OutputBase
	case *PageDef:
		scopeName = s.Title
		scopeFile = s.OutputBase
	}
	if ctx.member != nil {
		scopeName = ctx.member.QualName
		scopeFile = ctx.member.outputFile(d)
		anchor = ctx.member.Anchor
	}
	e := &XRefEntry{ID: id, Node: n, ScopeName: scopeName, ScopeFile: scopeFile, Anchor: anchor, Title: n.Attrs["heading"]}
	d.xrefLists[key] = append(d.xrefLists[key], e)
	return id
}

type XRefEntry struct {
	ID        string
	Node      *DocNode
	ScopeName string
	ScopeFile string
	Anchor    string
	Title     string
}
EOF
echo ok"}

