func (cw *codeWriter) startCodeLine() {
	if cw.lineOpen {
		return
	}
	cw.lineOpen = true
	if !cw.showLines {
		cw.sb.WriteString("<div class=\"line\">")
		return
	}
	ln := fmt.Sprintf("%05d", cw.lineNr)
	cw.sb.WriteString("<div class=\"line\"><a id=\"l" + ln + "\" name=\"l" + ln + "\"></a>")
	num := fmt.Sprintf("%5d", cw.lineNr)
	if t := cw.lineAnchors[cw.lineNr]; t != nil {
		href := cw.relPath + t.File + cw.d.htmlExt()
		if t.Anchor != "" {
			href += "#" + t.Anchor
		}
		cw.sb.WriteString("<span class=\"lineno\"><a class=\"line\" href=\"" + href + "\">" + num + "</a></span>")
	} else {
		cw.sb.WriteString("<span class=\"lineno\">" + num + "</span>")
	}
}

func (cw *codeWriter) endCodeLine() {
	if !cw.lineOpen {
		return
	}
	cw.lineOpen = false
	cw.sb.WriteString("</div>\n")
}

func (cw *codeWriter) codify(text string) {
	// text may contain newlines
	for {
		i := strings.IndexByte(text, '\n')
		if i < 0 {
			if text != "" {
				cw.startCodeLine()
				cw.sb.WriteString(htmlEscape(text))
			}
			return
		}
		if text[:i] != "" {
			cw.startCodeLine()
			cw.sb.WriteString(htmlEscape(text[:i]))
		}
		cw.newline()
		text = text[i+1:]
	}
}

func (cw *codeWriter) newline() {
	cw.startCodeLine()
	cw.endCodeLine()
	cw.lineNr++
}

func (cw *codeWriter) span(class string, text string) {
	cw.startCodeLine()
	cw.sb.WriteString("<span class=\"" + class + "\">" + htmlEscape(text) + "</span>")
}

func (cw *codeWriter) link(t *LinkTarget, class string, text string) {
	cw.startCodeLine()
	href := cw.relPath + t.File + cw.d.htmlExt()
	if t.Anchor != "" {
		href += "#" + t.Anchor
	}
	cw.sb.WriteString("<a class=\"code " + class + "\" href=\"" + href + "\">" + htmlEscape(text) + "</a>")
	// tooltip
	id := "a" + strings.ReplaceAll(strings.ReplaceAll(t.File+cw.d.htmlExt(), ".", "_"), "/", "_")
	if t.Anchor != "" {
		id += "_" + t.Anchor
	}
	if cw.tooltipSeen == nil {
		cw.tooltipSeen = map[string]bool{}
	}
	if !cw.tooltipSeen[id] {
		cw.tooltipSeen[id] = true
		cw.tooltips = append(cw.tooltips, &codeTooltip{id: id, target: t})
	}
}

func (cw *codeWriter) writeTooltips() {
	for _, tt := range cw.tooltips {
		t := tt.target
		href := cw.relPath + t.File + cw.d.htmlExt()
		if t.Anchor != "" {
			href += "#" + t.Anchor
		}
		cw.sb.WriteString("<div class=\"ttc\" id=\"" + tt.id + "\">")
		name := t.Name
		var brief string
		var decl string
		var defFile string
		var defLine int
		switch def := t.Def.(type) {
		case *ClassDef:
			name = def.QualName
			brief = def.Doc.Brief
			if def.BodyStart > 0 && def.FileDef != nil {
				defFile = def.FileDef.displayName(cw.d)
				defLine = def.Line
			}
		case *MemberDef:
			name = def.QualName
			brief = def.Doc.Brief
			decl = def.declString()
			if def.BodyStart > 0 {
				if fdd := cw.d.fileMap[def.DefFile]; fdd != nil {
					defFile = fdd.displayName(cw.d)
				} else {
					defFile = def.DefFile
				}
				defLine = def.BodyStart
			}
		case *NamespaceDef:
			name = def.QualName
			brief = def.Doc.Brief
		}
		cw.sb.WriteString("<div class=\"ttname\"><a href=\"" + href + "\">" + htmlEscape(name) + "</a></div>")
		if brief != "" {
			cw.sb.WriteString("<div class=\"ttdoc\">" + cw.d.briefToText(brief) + "</div>")
		}
		if decl != "" {
			cw.sb.WriteString("<div class=\"ttdeci\">" + htmlEscape(decl) + "</div>")
		}
		if defFile != "" {
			cw.sb.WriteString("<div class=\"ttdef\"><b>Definition</b> " + htmlEscape(defFile) + ":" + intToStr(defLine) + "</div>")
		}
		cw.sb.WriteString("</div>\n")
	}
}

// declString returns the declaration as shown in tooltips: "int hi(int n)".
func (md *MemberDef) declString() string {
	s := ""
	if md.Kind == MemberDefine {
		s = "#define " + md.Name + md.Args
		if md.Initializer != "" {
			s += " " + md.Initializer
		}
		return s
	}
	if md.Kind == MemberTypedef {
		return "typedef " + md.Type + " " + md.Name + md.Args
	}
	if md.Kind == MemberEnum {
		return "enum " + md.Name
	}
	if md.Static {
		s += "static "
	}
	if md.Type != "" {
		s += md.Type + " "
	}
	s += md.Name
	if md.Kind == MemberFunction {
		s += md.Args
	} else if md.Args != "" {
		s += md.Args
	}
	if md.Kind == MemberVariable && md.Initializer != "" && len(md.Initializer) < 30 {
		s += " " + md.Initializer
	}
	return strings.TrimSpace(s)
}

// briefToText renders a brief description as plain HTML text (for tooltips).
func (d *Doxygen) briefToText(brief string) string {
	root := d.parseDocText(&DocContext{d: d, singleLine: true}, brief)
	var sb strings.Builder
	var walk func(n *DocNode)
	walk = func(n *DocNode) {
		switch n.Kind {
		case DocWord, DocLinkedWord:
			sb.WriteString(htmlEscape(n.Text))
		case DocWhitespace:
			sb.WriteString(" ")
		case DocSymbol:
			sb.WriteString(htmlEntity(n.Text))
		default:
			for _, c := range n.Children {
				walk(c)
			}
		}
	}
	walk(root)
	return strings.TrimRight(sb.String(), " ")
}

// highlightCodeHtml renders a code fragment (from \code blocks) with syntax highlighting.
func (d *Doxygen) highlightCodeHtml(text string, lang string, ctx *DocContext, relPath string) string {
	cw := &codeWriter{d: d, relPath: relPath, lineNr: 1, showLines: false, stripComments: false}
	// strip common leading indentation
	text = stripIndentation(text)
	if strings.HasSuffix(text, "\n") {
		text = text[:len(text)-1]
	}
	var scope *ClassDef
	if ctx != nil {
		scope, _ = ctx.scope.(*ClassDef)
	}
	if strings.Contains(strings.ToLower(lang), "unparsed") || lang == ".txt" {
		for _, l := range strings.Split(text, "\n") {
			cw.codify(l)
			cw.endCodeLine()
			cw.lineNr++
		}
	} else {
		d.highlightCpp(cw, text, scope, nil)
	}
	cw.endCodeLine()
	cw.writeTooltips()
	return cw.sb.String()
}

func stripIndentation(text string) string {
	lines := strings.Split(text, "\n")
	minIndent := -1
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			continue
		}
		ind := 0
		for ind < len(l) && (l[ind] == ' ' || l[ind] == '\t') {
			ind++
		}
		if minIndent < 0 || ind < minIndent {
			minIndent = ind
		}
	}
	if minIndent <= 0 {
		return text
	}
	for i, l := range lines {
		if len(l) >= minIndent {
			lines[i] = l[minIndent:]
		} else {
			lines[i] = strings.TrimLeft(l, " \t")
		}
	}
	return strings.Join(lines, "\n")
}

// highlightCpp tokenizes C/C++ code and writes highlighted output.
func (d *Doxygen) highlightCpp(cw *codeWriter, text string, scope *ClassDef, fd *FileDef) {
	src := []byte(text)
	n := len(src)
	i := 0
	// scope tracking for member linking: stack of (classDef, braceDepth)
	type scopeEntry struct {
		cd    *ClassDef
		depth int
		fold  bool
		kind  string
	}
	var scopes []scopeEntry
	braceDepth := 0
	var pendingClass *ClassDef
	pendingKind := ""
	var pendingFn *MemberDef
	curScope := scope
	lastIdent := ""
	for i < n {
		c := src[i]
		switch {
		case c == '\n':
			cw.newline()
			i++
		case c == ' ' || c == '\t' || c == '\r':
			j := i
			for j < n && (src[j] == ' ' || src[j] == '\t' || src[j] == '\r') {
				j++
			}
			cw.codify(string(src[i:j]))
			i = j
		case c == '/' && i+1 < n && src[i+1] == '/':
			j := i
			for j < n && src[j] != '\n' {
				j++
			}
			comment := string(src[i:j])
			isDoc := strings.HasPrefix(comment, "///") && !strings.HasPrefix(comment, "////") || strings.HasPrefix(comment, "//!")
			if isDoc && cw.stripComments {
				// removed; keep the newline handling
			} else {
				cw.span("comment", comment)
			}
			i = j
		case c == '/' && i+1 < n && src[i+1] == '*':
			end := strings.Index(string(src[i+2:]), "*/")
			var comment string
			if end < 0 {
				comment = string(src[i:])
				i = n
			} else {
				comment = string(src[i : i+2+end+2])
				i += 2 + end + 2
			}
			isDoc := (strings.HasPrefix(comment, "/**") && !strings.HasPrefix(comment, "/**/")) || strings.HasPrefix(comment, "/*!")
			if isDoc && cw.stripComments {
				// count lines in the comment
				nl := strings.Count(comment, "\n")
				// a comment at the start of a line followed by a newline: swallow the newline too
				atLineStart := true
				for k := i - len(comment) - 1; k >= 0; k-- {
					if src[k] == '\n' {
						break
					}
					if src[k] != ' ' && src[k] != '\t' {
						atLineStart = false
						break
					}
				}
				if atLineStart && i < n && (src[i] == '\n' || (src[i] == ' ' && strings.TrimSpace(string(src[i:min(i+40, n)])) == "")) {
					// skip trailing blanks and the newline
					for i < n && (src[i] == ' ' || src[i] == '\t') {
						i++
					}
					if i < n && src[i] == '\n' {
						i++
						nl++
					}
					cw.lineNr += nl
					cw.endCodeLine()
					cw.startCodeLine()
				} else {
					cw.lineNr += nl
				}
			} else {
				// write the comment line by line
				parts := strings.Split(comment, "\n")
				for k, p := range parts {
					if k > 0 {
						cw.newline()
					}
					if p != "" {
						cw.span("comment", p)
					}
				}
			}
		case c == '#' && atLineStartBytes(src, i):
			// preprocessor line
			j := i
			for j < n && src[j] != '\n' {
				if src[j] == '\\' && j+1 < n && src[j+1] == '\n' {
					j += 2
					continue
				}
				j++
			}
			line := string(src[i:j])
			d.writePreprocLine(cw, line, fd)
			i = j
		case c == '"':
			j := i + 1
			for j < n && src[j] != '"' && src[j] != '\n' {
				if src[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && src[j] == '"' {
				j++
			}
			cw.span("stringliteral", string(src[i:j]))
			i = j
		case c == '\'':
			j := i + 1
			for j < n && src[j] != '\'' && src[j] != '\n' {
				if src[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && src[j] == '\'' {
				j++
			}
			cw.span("charliteral", string(src[i:j]))
			i = j
		case isIdentStart(c):
			j := i
			for j < n && isIdentChar(src[j]) {
				j++
			}
			word := string(src[i:j])
			// qualified name?
			fullWord := word
			k := j
			for k+1 < n && src[k] == ':' && src[k+1] == ':' {
				m := k + 2
				for m < n && isIdentChar(src[m]) {
					m++
				}
				if m == k+2 {
					break
				}
				fullWord += "::" + string(src[k+2:m])
				k = m
			}
			switch {
			case word == "class" || word == "struct" || word == "union" || word == "enum" || word == "namespace" || word == "interface" && false:
				// include following whitespace in the span (as doxygen does)
				m := j
				for m < n && (src[m] == ' ' || src[m] == '\t') {
					m++
				}
				if m > j && m < n && isIdentStart(src[m]) {
					cw.span("keyword", string(src[i:m]))
					j = m
				} else {
					cw.span("keyword", word)
				}
				pendingKind = word
				i = j
				lastIdent = word
				continue
			case cppFlowKeywords[word]:
				cw.span("keywordflow", word)
			case cppTypeKeywords[word]:
				cw.span("keywordtype", word)
			case cppKeywords[word]:
				cw.span("keyword", word)
			default:
				// symbol lookup
				var target *LinkTarget
				var class string
				// after class/struct keyword: the class being defined
				if pendingKind == "class" || pendingKind == "struct" || pendingKind == "union" || pendingKind == "interface" {
					cdName := fullWord
					var cd *ClassDef
					if curScope != nil {
						cd = d.classMap[curScope.QualName+"::"+cdName]
					}
					if cd == nil {
						cd = d.resolveClassInNs(cdName, fd, curScope)
					}
					if cd != nil {
						pendingClass = cd
						if cd.isLinkable(d) {
							target = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
							class = "hl_class"
						}
					}
				} else if pendingKind == "enum" {
					// enum name
					if md := d.findMemberInScope(fullWord, curScope, fd, MemberEnum); md != nil && md.isLinkable(d) {
						target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
						class = "hl_enumeration"
					}
					pendingKind = "enumname"
				} else if pendingKind == "namespace" {
					if ns := d.nsMap[fullWord]; ns != nil && ns.isLinkable(d) {
						target = &LinkTarget{File: ns.OutputBase, Name: ns.QualName, Def: ns}
						class = "hl_namespace"
					}
				} else {
					// is it followed by '(' => function
					m := k
					for m < n && (src[m] == ' ' || src[m] == '\t') {
						m++
					}
					isCall := m < n && src[m] == '('
					if cd := d.resolveClassInNs(fullWord, fd, curScope); cd != nil && cd.isLinkable(d) && !isCall {
						target = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
						class = "hl_class"
					} else if cd != nil && isCall && cd.isLinkable(d) {
						// constructor call / declaration: link the class
						target = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
						class = "hl_class"
						// constructor member?
						if ctor := d.findMemberInScope(cd.Name, cd, fd, MemberFunction); ctor != nil && ctor.isLinkable(d) && strings.Contains(fullWord, "::") {
							target = &LinkTarget{File: ctor.outputFile(d), Anchor: ctor.Anchor, Name: ctor.QualName, Def: ctor}
							class = "hl_function"
						}
					} else if isCall {
						if md := d.findMemberInScope(fullWord, curScope, fd, MemberFunction); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_function"
							pendingFn = md
						} else if md := d.findMemberInScope(fullWord, curScope, fd, MemberDefine); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_define"
						}
					} else {
						if md := d.findMemberInScope(fullWord, curScope, fd, MemberVariable); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_variable"
						} else if md := d.findMemberInScope(fullWord, curScope, fd, MemberTypedef); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_typedef"
						} else if md := d.findMemberInScope(fullWord, curScope, fd, MemberEnumValue); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_enumvalue"
						} else if md := d.findMemberInScope(fullWord, curScope, fd, MemberEnum); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_enumeration"
						} else if md := d.findMemberInScope(fullWord, curScope, fd, MemberDefine); md != nil && md.isLinkable(d) {
							target = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
							class = "hl_define"
						} else if ns := d.nsMap[fullWord]; ns != nil && ns.isLinkable(d) {
							target = &LinkTarget{File: ns.OutputBase, Name: ns.QualName, Def: ns}
							class = "hl_namespace"
						}
					}
				}
				if target != nil {
					cw.link(target, class, fullWord)
				} else {
					cw.codify(fullWord)
				}
				j = k
			}
			if pendingKind != "" && word != "class" && word != "struct" && word != "union" && word != "enum" && word != "namespace" {
				if pendingKind != "enumname" || true {
					// keep pendingKind until '{' or ';'
				}
			}
			lastIdent = word
			i = j
		case c == '{':
			braceDepth++
			if pendingKind != "" {
				kind := pendingKind
				if kind == "enumname" {
					kind = "enum"
				}
				if cw.folding && cw.showLines {
					// start fold region: emitted before the current line
					cw.startFold(kind)
				}
				scopes = append(scopes, scopeEntry{cd: pendingClass, depth: braceDepth, fold: cw.folding && cw.showLines, kind: kind})
				if pendingClass != nil {
					curScope = pendingClass
				}
				pendingClass = nil
				pendingKind = ""
			} else if pendingFn != nil || lastIdent == ")" || lastIdent == "const" || lastIdent == "override" || lastIdent == "noexcept" {
				// function body
				if cw.folding && cw.showLines {
					cw.startFold("function")
				}
				scopes = append(scopes, scopeEntry{cd: nil, depth: braceDepth, fold: cw.folding && cw.showLines, kind: "function"})
				pendingFn = nil
			}
			cw.codify("{")
			i++
			lastIdent = "{"
		case c == '}':
			cw.codify("}")
			i++
			if len(scopes) > 0 && scopes[len(scopes)-1].depth == braceDepth {
				se := scopes[len(scopes)-1]
				scopes = scopes[:len(scopes)-1]
				// restore scope
				curScope = scope
				for _, s := range scopes {
					if s.cd != nil {
						curScope = s.cd
					}
				}
				if se.fold {
					// fold ends after this line (including trailing ';')
					cw.pendingFoldEnd = true
				}
			}
			braceDepth--
			lastIdent = "}"
		case c == ';':
			cw.codify(";")
			i++
			pendingKind = ""
			pendingClass = nil
			pendingFn = nil
			lastIdent = ";"
		default:
			// punctuation
			if c == ')' {
				lastIdent = ")"
			} else if c != ' ' {
				lastIdent = string(c)
			}
			cw.codify(string(c))
			i++
		}
	}
}

func atLineStartBytes(src []byte, i int) bool {
	for k := i - 1; k >= 0; k-- {
		if src[k] == '\n' {
			return true
		}
		if src[k] != ' ' && src[k] != '\t' {
			return false
		}
	}
	return true
}

func (d *Doxygen) writePreprocLine(cw *codeWriter, line string, fd *FileDef) {
	// #include links to the included file when known
	trimmed := strings.TrimSpace(line[1:])
	if strings.HasPrefix(trimmed, "include") && fd != nil {
		rest := strings.TrimSpace(trimmed[7:])
		if len(rest) >= 2 {
			name := rest[1 : len(rest)-1]
			for _, inc := range fd.Includes {
				if inc.Name == name && inc.FileDef != nil && inc.FileDef.isLinkable(d) {
					idx := strings.Index(line, rest)
					prefix := line[:idx+1]
					suffix := line[idx+len(rest)-1:]
					cw.startCodeLine()
					cw.sb.WriteString("<span class=\"preprocessor\">" + htmlEscape(prefix))
					target := inc.FileDef.OutputBase
					if inc.FileDef.HasSource {
						target = inc.FileDef.OutputBase + "_source"
					}
					cw.sb.WriteString("<a class=\"code\" href=\"" + cw.relPath + target + d.htmlExt() + "\">" + htmlEscape(name) + "</a>")
					cw.sb.WriteString(htmlEscape(suffix) + "</span>")
					return
				}
			}
		}
	}
	parts := strings.Split(line, "\n")
	for k, p := range parts {
		if k > 0 {
			cw.newline()
		}
		cw.span("preprocessor", p)
	}
}

func (cw *codeWriter) startFold(kind string) {
	// written before the current line starts
	if cw.lineOpen {
		// the '{' is on the same line as the declaration: the fold div must precede the line.
		// Insert it before the last "<div class=\"line\">" occurrence.
		s := cw.sb.String()
		idx := strings.LastIndex(s, "<div class=\"line\">")
		if idx >= 0 {
			end := "}"
			if kind == "class" || kind == "struct" || kind == "union" || kind == "enum" || kind == "interface" {
				end = "};"
			}
			fold := "<div class=\"foldopen\" id=\"foldopen" + fmt.Sprintf("%05d", cw.lineNr) + "\" data-start=\"{\" data-end=\"" + end + "\">\n"
			cw.sb.Reset()
			cw.sb.WriteString(s[:idx] + fold + s[idx:])
		}
		return
	}
	end := "}"
	if kind == "class" || kind == "struct" || kind == "union" || kind == "enum" || kind == "interface" {
		end = "};"
	}
	cw.sb.WriteString("<div class=\"foldopen\" id=\"foldopen" + fmt.Sprintf("%05d", cw.lineNr) + "\" data-start=\"{\" data-end=\"" + end + "\">\n")
}

func (d *Doxygen) resolveClassInNs(name string, fd *FileDef, scope *ClassDef) *ClassDef {
	if cd := d.classMap[name]; cd != nil {
		return cd
	}
	if scope != nil {
		if cd := d.classMap[scope.QualName+"::"+name]; cd != nil {
			return cd
		}
		if scope.Namespace != nil {
			if cd := d.classMap[scope.Namespace.QualName+"::"+name]; cd != nil {
				return cd
			}
		}
	}
	if fd != nil {
		for _, ns := range fd.Namespaces {
			if cd := d.classMap[ns.QualName+"::"+name]; cd != nil {
				return cd
			}
		}
	}
	return nil
}

func (d *Doxygen) findMemberInScope(name string, scope *ClassDef, fd *FileDef, kind MemberKind) *MemberDef {
	sp := scopePart(name)
	local := stripScope(name)
	if sp != "" {
		if cd := d.classMap[sp]; cd != nil {
			for _, md := range cd.Members {
				if md.Name == local && md.Kind == kind {
					return md
				}
			}
		}
		if ns := d.nsMap[sp]; ns != nil {
			for _, md := range ns.Members {
				if md.Name == local && md.Kind == kind {
					return md
				}
			}
		}
		return nil
	}
	if scope != nil {
		for _, md := range scope.Members {
			if md.Name == local && md.Kind == kind {
				return md
			}
		}
		if kind == MemberEnumValue {
			for _, md := range scope.Members {
				if md.Kind == MemberEnum {
					for _, ev := range md.EnumValues {
						if ev.Name == local {
							return ev
						}
					}
				}
			}
		}
	}
	if fd != nil {
		for _, md := range fd.Members {
			if md.Name == local && md.Kind == kind {
				return md
			}
			if kind == MemberEnumValue && md.Kind == MemberEnum {
				for _, ev := range md.EnumValues {
					if ev.Name == local {
						return ev
					}
				}
			}
		}
		for _, ns := range fd.Namespaces {
			for _, md := range ns.Members {
				if md.Name == local && md.Kind == kind {
					return md
				}
			}
		}
	}
	// global search
	for _, md := range d.allMembers {
		if md.Name == local && md.Kind == kind && md.Class == nil {
			return md
		}
	}
	return nil
}
EOF
