	sb.WriteString("<script type=\"text/javascript\" src=\"" + relPath + "navtree.js\"></script>\n")
	sb.WriteString("<script type=\"text/javascript\" src=\"" + relPath + "cookie.js\"></script>")
	return sb.String()
}

func (h *HtmlGenerator) searchHeader(relPath string) string {
	if !h.searchEngine {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("<link href=\"" + relPath + "search/search.css\" rel=\"stylesheet\" type=\"text/css\"/>\n")
	if !h.d.cfg.Bool("SERVER_BASED_SEARCH") {
		sb.WriteString("<script type=\"text/javascript\" src=\"" + relPath + "search/searchdata.js\"></script>\n")
	}
	sb.WriteString("<script type=\"text/javascript\" src=\"" + relPath + "search/search.js\"></script>")
	return sb.String()
}

func (h *HtmlGenerator) searchBox(relPath string) string {
	if !h.searchEngine {
		return ""
	}
	return h.searchBoxContent(relPath, "")
}

func (h *HtmlGenerator) searchBoxContent(relPath string, indent string) string {
	var sb strings.Builder
	serverBased := h.d.cfg.Bool("SERVER_BASED_SEARCH")
	if serverBased {
		sb.WriteString(indent + "<div id=\"MSearchBox\" class=\"MSearchBoxInactive\">\n")
		sb.WriteString(indent + "<div class=\"left\">\n")
		sb.WriteString(indent + "  <form id=\"FSearchBox\" action=\"" + relPath + "search.php\" method=\"get\">\n")
		sb.WriteString(indent + "  <span id=\"MSearchSelectExt\">&#160;</span>\n")
		sb.WriteString(indent + "  <input type=\"text\" id=\"MSearchField\" name=\"query\" value=\"\" placeholder=\"Search\" size=\"20\" accesskey=\"S\" \n")
		sb.WriteString(indent + "         onfocus=\"searchBox.OnSearchFieldFocus(true)\" \n")
		sb.WriteString(indent + "         onblur=\"searchBox.OnSearchFieldFocus(false)\"/>\n")
		sb.WriteString(indent + "  </form>\n")
		sb.WriteString(indent + "</div><div class=\"right\"></div>\n")
		sb.WriteString(indent + "</div>\n")
		return sb.String()
	}
	sb.WriteString(indent + "<div id=\"MSearchBox\" class=\"MSearchBoxInactive\">\n")
	sb.WriteString(indent + "<span class=\"left\">\n")
	sb.WriteString(indent + "  <span id=\"MSearchSelect\" class=\"search-icon\" onmouseover=\"return searchBox.OnSearchSelectShow()\" onmouseout=\"return searchBox.OnSearchSelectHide()\"><span class=\"search-icon-dropdown\"></span></span>\n")
	sb.WriteString(indent + "  <input type=\"text\" id=\"MSearchField\" value=\"\" placeholder=\"Search\" accesskey=\"S\"\n")
	sb.WriteString(indent + "       onfocus=\"searchBox.OnSearchFieldFocus(true)\" \n")
	sb.WriteString(indent + "       onblur=\"searchBox.OnSearchFieldFocus(false)\" \n")
	sb.WriteString(indent + "       onkeyup=\"searchBox.OnSearchFieldChange(event)\"/>\n")
	sb.WriteString(indent + "  </span><span class=\"right\">\n")
	sb.WriteString(indent + "    <a id=\"MSearchClose\" href=\"javascript:searchBox.CloseResultsWindow()\"><div id=\"MSearchCloseImg\" class=\"close-icon\"></div></a>\n")
	sb.WriteString(indent + "  </span>\n")
	sb.WriteString(indent + "</div>\n")
	return sb.String()
}

func (h *HtmlGenerator) writeStaticMenu(p *HtmlPage) {
	// static tabs (HTML_DYNAMIC_MENUS=NO): a simplified version
	p.w("<div id=\"navrow1\" class=\"tabs\">\n  <ul class=\"tablist\">\n")
	for _, e := range h.d.menuEntries() {
		p.w("    <li><a href=\"" + p.relPath + e.url + "\"><span>" + e.text + "</span></a></li>\n")
	}
	if h.searchEngine {
		p.w("    <li>\n" + h.searchBoxContent(p.relPath, "      ") + "    </li>\n")
	}
	p.w("  </ul>\n</div>\n")
}

// substituteHtmlBlocks handles <!--BEGIN X-->...<!--END X--> conditional blocks.
func substituteHtmlBlocks(s string, conds map[string]bool) string {
	for {
		i := strings.Index(s, "<!--BEGIN ")
		if i < 0 {
			return s
		}
		e := strings.Index(s[i:], "-->")
		if e < 0 {
			return s
		}
		name := s[i+10 : i+e]
		endMarker := "<!--END " + name + "-->"
		j := strings.Index(s[i:], endMarker)
		if j < 0 {
			return s
		}
		inner := s[i+e+3 : i+j]
		neg := strings.HasPrefix(name, "!")
		key := strings.TrimPrefix(name, "!")
		val := conds[key]
		if neg {
			val = !val
		}
		if val {
			s = s[:i] + inner + s[i+j+len(endMarker):]
		} else {
			s = s[:i] + s[i+j+len(endMarker):]
		}
	}
}

// writeFooter writes the footer part.
func (p *HtmlPage) writeFooter(navPath string) {
	h := p.h
	cfg := h.d.cfg
	tmpl := resHtmlFooter
	if ff := cfg.Str("HTML_FOOTER"); ff != "" {
		if data, err := os.ReadFile(ff); err == nil {
			tmpl = string(data)
		}
	}
	if strings.HasPrefix(tmpl, "<!-- HTML footer for doxygen") {
		if i := strings.Index(tmpl, "\n"); i >= 0 {
			tmpl = tmpl[i+1:]
		}
	}
	if h.treeview {
		p.w("</div><!-- doc-content -->\n")
		if h.pageOutline && p.outlineName != "" {
			p.w("<div id=\"page-nav\" class=\"page-nav-panel\">\n")
			p.w("<div id=\"page-nav-resize-handle\"></div>\n")
			p.w("<div id=\"page-nav-tree\">\n")
			p.w("<div id=\"page-nav-contents\">\n")
			p.w("</div><!-- page-nav-contents -->\n")
			p.w("</div><!-- page-nav-tree -->\n")
			p.w("</div><!-- page-nav -->\n")
		}
		p.w("</div><!-- container -->\n")
	}
	conds := map[string]bool{
		"GENERATE_TREEVIEW": h.treeview,
	}
	s := substituteHtmlBlocks(tmpl, conds)
	s = strings.ReplaceAll(s, "$navpath", navPath)
	s = strings.ReplaceAll(s, "$generatedby", "Generated by")
	s = strings.ReplaceAll(s, "$doxygenversion", doxyVersion)
	s = strings.ReplaceAll(s, "$relpath^", p.relPath)
	s = strings.ReplaceAll(s, "$relpath$", p.relPath)
	s = strings.ReplaceAll(s, "$projectname", convertToHtml(cfg.Str("PROJECT_NAME"), false))
	s = strings.ReplaceAll(s, "$projectnumber", convertToHtml(cfg.Str("PROJECT_NUMBER"), false))
	s = strings.ReplaceAll(s, "$projectbrief", convertToHtml(cfg.Str("PROJECT_BRIEF"), false))
	p.w(s)
}

// navPathHtml builds the nav path list items for the footer.
func (h *HtmlGenerator) navPathItems(items []navItem) string {
	var sb strings.Builder
	for _, it := range items {
		sb.WriteString("    <li class=\"navelem\"><a href=\"" + it.url + "\">" + htmlEscape(it.text) + "</a></li>\n")
	}
	return strings.TrimSuffix(sb.String(), "\n")
}

type navItem struct {
	text string
	url  string
}

// startTitle writes the page title header.
func (p *HtmlPage) startContents(title string) {
	p.w("<div class=\"header\">\n")
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + title + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
}

func (p *HtmlPage) startContentsWithSummary(title string, summary string, projectName bool) {
	p.w("<div class=\"header\">\n")
	if summary != "" {
		p.w(summary)
	}
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + title + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
}

func (p *HtmlPage) endContents() {
	p.w("</div><!-- contents -->\n")
}

// finish writes the page to disk.
func (p *HtmlPage) finish() {
	p.h.writeFile(p.name+p.h.ext, p.sb.String())
	p.h.addCrawl(p.name + p.h.ext)
}

func (h *HtmlGenerator) finalize() {
	// crawl file
	var sb strings.Builder
	sb.WriteString("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n")
	sb.WriteString("<html xmlns=\"http://www.w3.org/1999/xhtml\" lang=\"en-US\">\n")
	sb.WriteString("<head>\n")
	sb.WriteString("<title>Validator / crawler helper</title>\n")
	sb.WriteString("<meta http-equiv=\"Content-Type\" content=\"text/xhtml;charset=UTF-8\"/>\n")
	sb.WriteString("<meta http-equiv=\"X-UA-Compatible\" content=\"IE=11\"/>\n")
	sb.WriteString("<meta name=\"generator\" content=\"Doxygen " + doxyVersion + "\"/>\n")
	sb.WriteString("<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n")
	sb.WriteString("</head>\n")
	sb.WriteString("<body>\n")
	for _, c := range h.crawl {
		sb.WriteString("<a href=\"" + c + "\"/>\n")
	}
	sb.WriteString("</body>\n")
	sb.WriteString("</html>\n")
	h.writeFile("doxygen_crawl"+h.ext, sb.String())
	if h.search != nil {
		h.search.write(h)
	}
	if !h.disableIndex && h.d.cfg.Bool("HTML_DYNAMIC_MENUS") {
		h.writeMenuData()
	}
	if h.treeview {
		h.writeNavTree()
	}
}
EOF
echo ok"}

