cd /workspace/src && cat > htmlgen.go <<'EOF'
package main

import (
	"os"
	"path/filepath"
	"strings"
)

// HtmlGenerator produces the HTML output.
type HtmlGenerator struct {
	d       *Doxygen
	dir     string
	ext     string
	search  *SearchIndex
	crawl   []string
	crawlSeen map[string]bool
	treeview bool
	searchEngine bool
	disableIndex bool
	fullSidebar bool
	pageOutline bool
}

func (d *Doxygen) htmlExt() string {
	e := d.cfg.Str("HTML_FILE_EXTENSION")
	if e == "" {
		return ".html"
	}
	return e
}

func newHtmlGenerator(d *Doxygen) *HtmlGenerator {
	return &HtmlGenerator{d: d, dir: d.htmlDir, ext: d.htmlExt(), crawlSeen: map[string]bool{}}
}

func (h *HtmlGenerator) init() {
	cfg := h.d.cfg
	h.treeview = cfg.Bool("GENERATE_TREEVIEW")
	h.searchEngine = cfg.Bool("SEARCHENGINE")
	h.disableIndex = cfg.Bool("DISABLE_INDEX")
	h.fullSidebar = cfg.Bool("FULL_SIDEBAR") && h.treeview && !h.disableIndex
	h.pageOutline = cfg.Bool("PAGE_OUTLINE_PANEL") && h.treeview
	// static files
	h.writeFile("tabs.css", resTabsCss)
	h.writeFile("menu.js", resMenuJs)
	if h.treeview {
		h.writeFile("navtree.css", resNavtreeCss)
	}
	if cfg.Bool("HTML_COPY_CLIPBOARD") {
		h.writeFile("clipboard.js", resClipboardJs)
	}
	if h.treeview || cfg.Enum("HTML_COLORSTYLE") == "TOGGLE" || cfg.Enum("HTML_COLORSTYLE") == "AUTO_LIGHT" || cfg.Enum("HTML_COLORSTYLE") == "AUTO_DARK" {
		h.writeFile("cookie.js", resCookieJs)
	}
	if !cfg.Bool("GENERATE_HTMLHELP") {
		h.writeFile("dynsections.js", resDynsectionsJs)
	}
	if cfg.Enum("HTML_COLORSTYLE") == "TOGGLE" || cfg.Enum("HTML_COLORSTYLE") == "AUTO_LIGHT" || cfg.Enum("HTML_COLORSTYLE") == "AUTO_DARK" {
		// darkmode toggle script is part of doxygen.css handling (not needed for AUTO modes)
	}
	// crawl file
	h.addCrawl("doxygen_crawl" + h.ext)
	h.addCrawl("index" + h.ext)
}

func (h *HtmlGenerator) writeFile(name string, content string) {
	path := filepath.Join(h.dir, name)
	os.MkdirAll(filepath.Dir(path), 0755)
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		termMsg("Could not open file %s for writing\n", path)
	}
}

func (h *HtmlGenerator) addCrawl(url string) {
	if !h.crawlSeen[url] {
		h.crawlSeen[url] = true
		h.crawl = append(h.crawl, url)
	}
}

func (h *HtmlGenerator) writeStyleSheets() {
	cfg := h.d.cfg
	css := replaceColorMarkers(resDoxygenCssTmpl, cfg)
	h.writeFile("doxygen.css", css)
	svg := replaceColorMarkers(resDoxygenSvgTmpl, cfg)
	h.writeFile("doxygen.svg", svg)
	// extra style sheets / files
	for _, f := range cfg.List("HTML_EXTRA_STYLESHEET") {
		if data, err := os.ReadFile(f); err == nil {
			h.writeFile(filepath.Base(f), string(data))
		}
	}
	for _, f := range cfg.List("HTML_EXTRA_FILES") {
		if data, err := os.ReadFile(f); err == nil {
			h.writeFile(filepath.Base(f), string(data))
		}
	}
	if logo := cfg.Str("PROJECT_LOGO"); logo != "" {
		if data, err := os.ReadFile(logo); err == nil {
			h.writeFile(filepath.Base(logo), string(data))
		}
	}
	if icon := cfg.Str("PROJECT_ICON"); icon != "" {
		if data, err := os.ReadFile(icon); err == nil {
			h.writeFile(filepath.Base(icon), string(data))
		}
	}
}

func (h *HtmlGenerator) initSearchIndex() {
	h.search = newSearchIndex(h.d)
	h.writeFile("search/search.css", replaceColorMarkers(resSearchCss, h.d.cfg))
	h.writeFile("search/search.js", resSearchJs)
}

// ---------------------------------------------------------------------------
// Page framework

// HtmlPage accumulates the content of one HTML page.
type HtmlPage struct {
	h        *HtmlGenerator
	sb       strings.Builder
	name     string // file base name
	relPath  string
	title    string
}

func (h *HtmlGenerator) newPage(name string, title string, relPath string) *HtmlPage {
	p := &HtmlPage{h: h, name: name, relPath: relPath, title: title}
	return p
}

func (p *HtmlPage) w(s string) { p.sb.WriteString(s) }

func (h *HtmlGenerator) projectName() string {
	return h.d.cfg.Str("PROJECT_NAME")
}

// writeHeader writes the header part of a page (substituted template).
func (p *HtmlPage) writeHeader(title string, navPath string, allowSearch bool) {
	h := p.h
	cfg := h.d.cfg
	tmpl := resHtmlHeader
	if hf := cfg.Str("HTML_HEADER"); hf != "" {
		if data, err := os.ReadFile(hf); err == nil {
			tmpl = string(data)
		}
	}
	// remove the "<!-- HTML header for doxygen" comment line
	if strings.HasPrefix(tmpl, "<!-- HTML header for doxygen") {
		if i := strings.Index(tmpl, "\n"); i >= 0 {
			tmpl = tmpl[i+1:]
		}
	}
	projectName := cfg.Str("PROJECT_NAME")
	projectNumber := cfg.Str("PROJECT_NUMBER")
	projectBrief := cfg.Str("PROJECT_BRIEF")
	projectLogo := cfg.Str("PROJECT_LOGO")
	projectIcon := cfg.Str("PROJECT_ICON")
	conds := map[string]bool{
		"PROJECT_NAME":      projectName != "",
		"PROJECT_NUMBER":    projectNumber != "",
		"PROJECT_BRIEF":     projectBrief != "",
		"PROJECT_LOGO":      projectLogo != "",
		"PROJECT_ICON":      projectIcon != "",
		"TITLEAREA":         projectName != "" || projectBrief != "" || projectLogo != "" || (h.disableIndex && h.searchEngine),
		"DISABLE_INDEX":     h.disableIndex,
		"GENERATE_TREEVIEW": h.treeview,
		"SEARCHENGINE":      h.searchEngine,
		"FULL_SIDEBAR":      h.fullSidebar,
		"GENERATE_HTMLHELP": cfg.Bool("GENERATE_HTMLHELP"),
		"COPY_CLIPBOARD":    cfg.Bool("HTML_COPY_CLIPBOARD"),
		"PAGE_OUTLINE_PANEL": h.pageOutline,
	}
	s := substituteHtmlBlocks(tmpl, conds)
	s = strings.ReplaceAll(s, "$projectname", convertToHtml(projectName, false))
	s = strings.ReplaceAll(s, "$projectnumber", convertToHtml(projectNumber, false))
	s = strings.ReplaceAll(s, "$projectbrief", convertToHtml(projectBrief, false))
	s = strings.ReplaceAll(s, "$projectlogo", filepath.Base(projectLogo))
	s = strings.ReplaceAll(s, "$projecticon", filepath.Base(projectIcon))
	s = strings.ReplaceAll(s, "$logosize", "")
	s = strings.ReplaceAll(s, "$title", convertToHtml(title, false))
	s = strings.ReplaceAll(s, "$doxygenversion", doxyVersion)
	s = strings.ReplaceAll(s, "$langISO", "en-US")
	s = strings.ReplaceAll(s, "$treeview", h.treeviewHeader(p.relPath))
	s = strings.ReplaceAll(s, "$search", h.searchHeader(p.relPath))
	s = strings.ReplaceAll(s, "$mathjax", "")
	s = strings.ReplaceAll(s, "$darkmode", "")
	s = strings.ReplaceAll(s, "$stylesheet", h.styleSheetName())
	s = strings.ReplaceAll(s, "$extrastylesheet", h.extraStyleSheets(p.relPath))
	s = strings.ReplaceAll(s, "$searchbox", h.searchBox(p.relPath))
	s = strings.ReplaceAll(s, "$generatedby", "Generated by")
	s = strings.ReplaceAll(s, "$relpath^", p.relPath)
	s = strings.ReplaceAll(s, "$relpath$", p.relPath)
	s = strings.ReplaceAll(s, "$navpath", navPath)
	p.w(s)
	// the part after the header template: menu, nav tree, search window
	p.w("<!-- " + "Generated by Doxygen " + doxyVersion + " -->\n")
	if h.searchEngine {
		p.w("<script type=\"text/javascript\">\n")
		p.w("let searchBox = new SearchBox(\"searchBox\", \"" + p.relPath + "search/\",'" + h.ext + "');\n")
		p.w("</script>\n")
	}
	if cfg.Bool("HTML_CODE_FOLDING") {
		p.w("<script type=\"text/javascript\">\ndocument.addEventListener('DOMContentLoaded', codefold.init);\n</script>\n")
	}
	if !h.disableIndex {
		if cfg.Bool("HTML_DYNAMIC_MENUS") {
			p.w("<script type=\"text/javascript\" src=\"" + p.relPath + "menudata.js\"></script>\n")
			p.w("<script type=\"text/javascript\" src=\"" + p.relPath + "menu.js\"></script>\n")
			p.w("<script type=\"text/javascript\">\n")
			p.w("document.addEventListener('DOMContentLoaded', () => {\n")
			p.w("  initMenu('" + p.relPath + "'," + boolJs(h.searchEngine) + ");\n")
			if h.searchEngine {
				if !cfg.Bool("SERVER_BASED_SEARCH") {
					p.w("  init_search();\n")
				} else {
					p.w("  searchBox.OnSelectItem(0);\n")
				}
			}
			p.w("});\n")
			p.w("</script>\n")
			p.w("<div id=\"main-nav-mobile\">\n")
			p.w("<div class=\"sm sm-dox\"><input id=\"main-menu-state\" type=\"checkbox\"/>\n")
			p.w("<label class=\"main-menu-btn\" for=\"main-menu-state\">\n")
			p.w("<span class=\"main-menu-btn-icon\"></span> Toggle main menu visibility</label>\n")
			p.w("<span id=\"searchBoxPos1\" style=\"position:absolute;right:8px;top:8px;height:36px;\"></span>\n")
			p.w("</div>\n")
			p.w("</div><!-- main-nav-mobile -->\n")
			p.w("<div id=\"main-nav\">\n")
			p.w("  <ul class=\"sm sm-dox\" id=\"main-menu\">\n")
			if h.searchEngine {
				p.w("    <li id=\"searchBoxPos2\" style=\"float:right\">\n")
				p.w(h.searchBoxContent(p.relPath, "        "))
				p.w("    </li>\n")
			}
			p.w("  </ul>\n")
			p.w("</div><!-- main-nav -->\n")
		} else {
			// static menu
			h.writeStaticMenu(p)
		}
	}
	if !h.fullSidebar {
		p.w("</div><!-- top -->\n")
	}
	if h.treeview {
		if !h.fullSidebar {
			p.w("<div id=\"side-nav\" class=\"ui-resizable side-nav-resizable\">\n")
		}
		p.w("  <div id=\"nav-tree\">\n")
		p.w("    <div id=\"nav-tree-contents\">\n")
		p.w("      <div id=\"nav-sync\" class=\"sync\"></div>\n")
		p.w("    </div>\n")
		p.w("  </div>\n")
		p.w("  <div id=\"splitbar\" style=\"-moz-user-select:none;\" \n")
		p.w("       class=\"ui-resizable-handle\">\n")
		p.w("  </div>\n")
		p.w("</div>\n")
		p.w("<script type=\"text/javascript\">\n")
		p.w("document.addEventListener('DOMContentLoaded',() => { initNavTree('" + p.name + h.ext + "','" + p.relPath + "','" + p.outlineName + "'); });\n")
		p.w("</script>\n")
		p.w("<div id=\"container\">\n")
		p.w("<div id=\"doc-content\">\n")
	}
	if h.searchEngine && !cfg.Bool("SERVER_BASED_SEARCH") {
		p.w("<!-- window showing the filter options -->\n")
		p.w("<div id=\"MSearchSelectWindow\"\n")
		p.w("     onmouseover=\"return searchBox.OnSearchSelectShow()\"\n")
		p.w("     onmouseout=\"return searchBox.OnSearchSelectHide()\"\n")
		p.w("     onkeydown=\"return searchBox.OnSearchSelectKey(event)\">\n")
		p.w("</div>\n")
		p.w("\n")
		p.w("<!-- iframe showing the search results (closed by default) -->\n")
		p.w("<div id=\"MSearchResultsWindow\">\n")
		p.w("<div id=\"MSearchResults\">\n")
		p.w("<div class=\"SRPage\">\n")
		p.w("<div id=\"SRIndex\">\n")
		p.w("<div id=\"SRResults\"></div>\n")
		p.w("<div class=\"SRStatus\" id=\"Loading\">Loading...</div>\n")
		p.w("<div class=\"SRStatus\" id=\"Searching\">Searching...</div>\n")
		p.w("<div class=\"SRStatus\" id=\"NoMatches\">No Matches</div>\n")
		p.w("</div>\n")
		p.w("</div>\n")
		p.w("</div>\n")
		p.w("</div>\n")
		p.w("\n")
	} else if h.searchEngine {
		p.w("<!-- window showing the filter options -->\n")
		p.w("<div id=\"MSearchSelectWindow\"\n")
		p.w("     onmouseover=\"return searchBox.OnSearchSelectShow()\"\n")
		p.w("     onmouseout=\"return searchBox.OnSearchSelectHide()\"\n")
		p.w("     onkeydown=\"return searchBox.OnSearchSelectKey(event)\">\n")
		p.w("</div>\n")
		p.w("\n")
	}
}

func boolJs(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func (h *HtmlGenerator) styleSheetName() string {
	if ss := h.d.cfg.Str("HTML_STYLESHEET"); ss != "" {
		return filepath.Base(ss)
	}
	return "doxygen.css"
}

func (h *HtmlGenerator) extraStyleSheets(relPath string) string {
	var sb strings.Builder
	for _, f := range h.d.cfg.List("HTML_EXTRA_STYLESHEET") {
		if f == "" {
			continue
		}
		sb.WriteString("<link href=\"" + relPath + filepath.Base(f) + "\" rel=\"stylesheet\" type=\"text/css\"/>\n")
	}
	return sb.String()
}

func (h *HtmlGenerator) treeviewHeader(relPath string) string {
	if !h.treeview {
		return ""
	}
	var sb strings.Builder
