// substituteHtmlBlocks handles <!--BEGIN X-->...<!--END X--> conditional blocks.
func substituteHtmlBlocks(s string, conds map[string]bool) string {
	for {
		i := strings.Index(s, "<!--BEGIN ")
		if i < 0 {
			return s
		}
		e := strings.Index(s[i:], "-->")
		if e < 0 {
			return s
		}
		name := s[i+10 : i+e]
		endMarker := "<!--END " + name + "-->"
		j := strings.Index(s[i:], endMarker)
		if j < 0 {
			return s
		}
		inner := s[i+e+3 : i+j]
		neg := strings.HasPrefix(name, "!")
		key := strings.TrimPrefix(name, "!")
		val := conds[key]
		if neg {
			val = !val
		}
		if val {
			s = s[:i] + inner + s[i+j+len(endMarker):]
		} else {
			s = s[:i] + s[i+j+len(endMarker):]
		}
	}
}

// writeFooter writes the footer part.
func (p *HtmlPage) writeFooter(navPath string) {
	h := p.h
	cfg := h.d.cfg
	tmpl := resHtmlFooter
	if ff := cfg.Str("HTML_FOOTER"); ff != "" {
		if data, err := os.ReadFile(ff); err == nil {
			tmpl = string(data)
		}
	}
	if strings.HasPrefix(tmpl, "<!-- HTML footer for doxygen") {
		if i := strings.Index(tmpl, "\n"); i >= 0 {
			tmpl = tmpl[i+1:]
		}
	}
	if h.treeview {
		p.w("</div><!-- doc-content -->\n")
		if h.pageOutline && p.outlineName != "" {
			p.w("<div id=\"page-nav\" class=\"page-nav-panel\">\n")
			p.w("<div id=\"page-nav-resize-handle\"></div>\n")
			p.w("<div id=\"page-nav-tree\">\n")
			p.w("<div id=\"page-nav-contents\">\n")
			p.w("</div><!-- page-nav-contents -->\n")
			p.w("</div><!-- page-nav-tree -->\n")
			p.w("</div><!-- page-nav -->\n")
		}
		p.w("</div><!-- container -->\n")
	}
	conds := map[string]bool{
		"GENERATE_TREEVIEW": h.treeview,
	}
	s := substituteHtmlBlocks(tmpl, conds)
	s = strings.ReplaceAll(s, "$navpath", navPath)
	s = strings.ReplaceAll(s, "$generatedby", "Generated by")
	s = strings.ReplaceAll(s, "$doxygenversion", doxyVersion)
	s = strings.ReplaceAll(s, "$relpath^", p.relPath)
	s = strings.ReplaceAll(s, "$relpath$", p.relPath)
	s = strings.ReplaceAll(s, "$projectname", convertToHtml(cfg.Str("PROJECT_NAME"), false))
	s = strings.ReplaceAll(s, "$projectnumber", convertToHtml(cfg.Str("PROJECT_NUMBER"), false))
	s = strings.ReplaceAll(s, "$projectbrief", convertToHtml(cfg.Str("PROJECT_BRIEF"), false))
