		h.writeFileIndex(files)
	}
	if l != nil {
		l.writeFileIndex(files)
	}
}

func (h *HtmlGenerator) writeFileIndex(files []*FileDef) {
	d := h.d
	p := h.newPage("files", "File List", "")
	p.writeHeader("File List", "", true)
	p.startContents("File List")
	p.w("<div class=\"textblock\">Here is a list of all documented files with brief descriptions:</div>")
	p.w("<div class=\"directory\">\n")
	p.w("<table class=\"directory\">\n")
	// group files by directory relative to the strip path
	type dirNode struct {
		name  string
		files []*FileDef
		subs  []*dirNode
		path  string
	}
	root := &dirNode{}
	fullPath := d.cfg.Bool("FULL_PATH_NAMES")
	for _, fd := range files {
		rel := fd.Name
		if fullPath {
			rel = d.stripFromPath(fd.File)
		}
		parts := strings.Split(rel, "/")
		cur := root
		for _, part := range parts[:len(parts)-1] {
			var found *dirNode
			for _, s := range cur.subs {
				if s.name == part {
					found = s
				}
			}
			if found == nil {
				found = &dirNode{name: part, path: strings.TrimPrefix(cur.path+"/"+part, "/")}
				cur.subs = append(cur.subs, found)
			}
			cur = found
		}
		cur.files = append(cur.files, fd)
	}
	idx := 0
	var writeDir func(n *dirNode, level int, label string)
	writeDir = func(n *dirNode, level int, label string) {
		for i, s := range n.subs {
			cls := ""
			if idx%2 == 0 {
				cls = " class=\"even\""
			}
			lab := label + intToStr(i) + "_"
			p.w("<tr id=\"row_" + lab + "\"" + cls + "><td class=\"entry\">")
			p.w("<span style=\"width:" + intToStr(level*16) + "px;display:inline-block;\">&#160;</span>")
			p.w("<span id=\"arr_" + lab + "\" class=\"arrow\" onclick=\"dynsection.toggleFolder('" + lab + "')\">&#9660;</span>")
			p.w("<span id=\"img_" + lab + "\" class=\"iconfopen\" onclick=\"dynsection.toggleFolder('" + lab + "')\">&#160;</span>")
			p.w("<a class=\"el\" href=\"dir_" + md5Hex(s.path)[:32] + h.ext + "\" target=\"_self\">" + htmlEscape(s.name) + "</a>")
			p.w("</td><td class=\"desc\"></td></tr>\n")
			idx++
			writeDir(s, level+1, lab)
		}
		for i, fd := range n.files {
			cls := ""
			if idx%2 == 0 {
				cls = " class=\"even\""
			}
			lab := label + intToStr(len(n.subs)+i) + "_"
			p.w("<tr id=\"row_" + lab + "\"" + cls + "><td class=\"entry\">")
			p.w("<span style=\"width:" + intToStr(level*16+16) + "px;display:inline-block;\">&#160;</span>")
			if fd.HasSource {
				p.w("<a href=\"" + fd.OutputBase + "_source" + h.ext + "\"><span class=\"icondoc\"><div class=\"doc-icon\"></div></span></a>")
			} else {
				p.w("<span class=\"icondoc\"><div class=\"doc-icon\"></div></span>")
			}
			p.w("<a class=\"el\" href=\"" + fd.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(fd.Name) + "</a>")
			p.w("</td><td class=\"desc\">" + d.briefHtml(fd.Doc.Brief, fd, fd.Name, "") + "</td></tr>\n")
			idx++
		}
	}
	writeDir(root, 0, "")
	p.w("</table>\n")
	p.w("</div><!-- directory -->\n")
	p.endContents()
	p.writeFooter("")
	p.finish()
}

