func (pg *PageDef) displayTitle() string {
	if pg.Title != "" {
		return pg.Title
	}
	return pg.Name
}

func (d *Doxygen) generatePageDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, pg := range d.pages {
		msg("Generating docs for page %s...\n", pg.Name)
		if h != nil {
			h.writePage(pg)
		}
		if l != nil {
			l.writePage(pg)
		}
	}
}

func (h *HtmlGenerator) writePage(pg *PageDef) {
	d := h.d
	title := pg.displayTitle()
	p := h.newPage(pg.OutputBase, title, "")
	p.writeHeader(title, "", true)
	p.startContents(convertToHtml(title, false))
	ctx := &DocContext{d: d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine}
	root := d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc))
	p.w("<div class=\"textblock\">")
	p.w(d.docToHtml(root, ctx, ""))
	p.w("</div>")
	p.endContents()
	nav := h.navPathItems([]navItem{{text: title, url: pg.OutputBase + h.ext}})
	p.writeFooter(nav)
	p.finish()
}
