func (cd *ClassDef) hasNonReferenceSuperClass(d *Doxygen) bool {
	if len(cd.Derived) > 0 && cd.isLinkable(d) {
		return true
	}
	for _, dc := range cd.Derived {
		if dc.hasNonReferenceSuperClass(d) {
			return true
		}
	}
	return false
}

func (cd *ClassDef) isVisibleInHierarchy(d *Doxygen) bool {
	return cd.hasNonReferenceSuperClass(d) && !cd.IsAnonymous && d.protectionVisible(cd.Prot) &&
		(cd.hasDocumentation(d) || !d.cfg.Bool("HIDE_UNDOC_CLASSES"))
}

// classMemberIndexEntries returns documented class members grouped by category.
type memberIndexEntry struct {
	name    string
	members []*MemberDef
}

func (d *Doxygen) classMembersForIndex() map[string][]*memberIndexEntry {
	cats := map[string]map[string]*memberIndexEntry{}
	add := func(cat string, md *MemberDef) {
		if cats[cat] == nil {
			cats[cat] = map[string]*memberIndexEntry{}
		}
		e := cats[cat][md.Name]
		if e == nil {
			e = &memberIndexEntry{name: md.Name}
			cats[cat][md.Name] = e
		}
		e.members = append(e.members, md)
	}
	for _, cd := range d.classes {
		if !cd.isLinkable(d) {
			continue
		}
		for _, md := range cd.Members {
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) {
				continue
			}
			if !md.isBriefSectionVisible(d) && !d.cfg.Bool("EXTRACT_ALL") {
				continue
			}
			add("all", md)
			switch md.Kind {
			case MemberFunction, MemberSignal, MemberSlot:
				add("func", md)
			case MemberVariable:
				add("vars", md)
			case MemberTypedef:
				add("type", md)
			case MemberEnum:
				add("enum", md)
				for _, ev := range md.EnumValues {
					add("all", ev)
					add("eval", ev)
				}
			case MemberProperty:
				add("prop", md)
			case MemberEvent:
				add("evnt", md)
			case MemberFriend:
				add("rela", md)
			}
		}
	}
	out := map[string][]*memberIndexEntry{}
	for cat, m := range cats {
		var list []*memberIndexEntry
		for _, e := range m {
			list = append(list, e)
		}
		sort.Slice(list, func(i, j int) bool { return qstricmpSort(list[i].name, list[j].name) < 0 })
		out[cat] = list
	}
	return out
}

func (d *Doxygen) fileMembersForIndex() map[string][]*memberIndexEntry {
	cats := map[string]map[string]*memberIndexEntry{}
	add := func(cat string, md *MemberDef) {
		if cats[cat] == nil {
