			continue
		}
		for _, md := range ns.Members {
			if !md.isLinkable(d) {
				continue
			}
			add("all", md)
			switch md.Kind {
			case MemberFunction:
				add("func", md)
			case MemberVariable:
				add("vars", md)
			case MemberTypedef:
				add("type", md)
			case MemberEnum:
				add("enum", md)
				for _, ev := range md.EnumValues {
					add("all", ev)
					add("eval", ev)
				}
			}
		}
	}
	out := map[string][]*memberIndexEntry{}
	for cat, m := range cats {
		var list []*memberIndexEntry
		for _, e := range m {
			list = append(list, e)
		}
		sort.Slice(list, func(i, j int) bool { return qstricmpSort(list[i].name, list[j].name) < 0 })
		out[cat] = list
