// ---------------------------------------------------------------------------
// Index page

func (d *Doxygen) generateIndexPage(h *HtmlGenerator, l *LatexGenerator) {
	if h != nil {
		h.writeIndexPage()
	}
	if l != nil {
		l.writeRefman()
	}
}

func (h *HtmlGenerator) writeIndexPage() {
	d := h.d
	projectName := d.cfg.Str("PROJECT_NAME")
	title := "Main Page"
	headerTitle := ""
	mp := d.mainPage
	if mp != nil && mp.Title != "" {
		title = mp.Title
	}
	if mp != nil && mp.Title != "" {
		headerTitle = convertToHtml(mp.Title, false)
	} else if projectName != "" {
		headerTitle = convertToHtml(projectName, false) + " Documentation"
	} else {
		headerTitle = "Main Page"
	}
	p := h.newPage("index", title, "")
	if mp != nil && mp.Title != "" {
		p.writeHeader(mp.Title, "", true)
	} else {
		p.writeHeader(title, "", true)
	}
	if mp != nil {
		if mp.Title != "" || true {
			p.startContents(headerTitle)
		}
		ctx := &DocContext{d: d, scope: mp, file: mp.Doc.DocFile, line: mp.Doc.DocLine}
		root := d.parseDocText(ctx, joinDocs(mp.Doc.Brief, mp.Doc.Doc))
