// ---------------------------------------------------------------------------
// Annotated class list

func (d *Doxygen) generateAnnotatedIndex(h *HtmlGenerator, l *LatexGenerator) {
	classes := d.annotatedClasses()
	if len(classes) == 0 {
		return
	}
	if h != nil {
		h.writeAnnotatedIndex(classes)
	}
	if l != nil {
		l.writeAnnotatedIndex(classes)
	}
}

func classIconLetter(cd *ClassDef) string {
	switch cd.CompoundType {
	case "struct":
		return "S"
	case "union":
		return "U"
	case "interface":
		return "I"
	case "protocol":
		return "P"
	case "category":
		return "C"
	case "exception":
		return "E"
	}
	return "C"
}

func (h *HtmlGenerator) writeAnnotatedIndex(classes []*ClassDef) {
	d := h.d
	p := h.newPage("annotated", "Class List", "")
	p.writeHeader("Class List", "", true)
	p.startContents("Class List")
	p.w("<div class=\"textblock\">Here are the classes, structs, unions and interfaces with brief descriptions:</div>")
	p.w("<div class=\"directory\">\n")
	p.w("<table class=\"directory\">\n")
	// build a tree: namespaces -> classes -> nested classes
	idx := 0
	var writeClass func(cd *ClassDef, level int, prefix string, i int, last bool)
	type treeNode struct {
		cd    *ClassDef
		ns    *NamespaceDef
		kids  []*treeNode
		label string
	}
	var buildKids func(parentNs *NamespaceDef, parentCd *ClassDef) []*treeNode
	buildKids = func(parentNs *NamespaceDef, parentCd *ClassDef) []*treeNode {
		var kids []*treeNode
		if parentCd != nil {
			for _, inner := range parentCd.Inner {
				if inner.isLinkable(d) {
					kids = append(kids, &treeNode{cd: inner})
				}
			}
			return kids
		}
		if parentNs == nil {
			for _, ns := range d.namespaces {
				if ns.Parent == nil && d.nsHasVisibleClasses(ns) && ns.isLinkable(d) {
					kids = append(kids, &treeNode{ns: ns})
				}
			}
			for _, cd := range classes {
				if cd.OuterScope == nil || (cd.Namespace == nil && cd.OuterScope == nil) {
					if _, isCls := cd.OuterScope.(*ClassDef); !isCls && cd.Namespace == nil {
						kids = append(kids, &treeNode{cd: cd})
					}
				} else if cd.Namespace != nil && !cd.Namespace.isLinkable(d) {
					if _, isCls := cd.OuterScope.(*ClassDef); !isCls {
						kids = append(kids, &treeNode{cd: cd})
					}
				}
			}
			return kids
		}
		for _, ns := range parentNs.Namespaces {
			if d.nsHasVisibleClasses(ns) && ns.isLinkable(d) {
				kids = append(kids, &treeNode{ns: ns})
			}
		}
		for _, cd := range parentNs.Classes {
			if cd.isLinkable(d) {
				if _, isCls := cd.OuterScope.(*ClassDef); !isCls {
					kids = append(kids, &treeNode{cd: cd})
				}
			}
		}
		return kids
	}
	var fill func(n *treeNode)
	fill = func(n *treeNode) {
		n.kids = buildKids(n.ns, n.cd)
		for _, k := range n.kids {
			fill(k)
		}
	}
	root := &treeNode{}
	fill(root)
	_ = writeClass
	var writeNode func(n *treeNode, level int, label string)
	writeNode = func(n *treeNode, level int, label string) {
		hasKids := len(n.kids) > 0
		cls := ""
		if idx%2 == 0 {
			cls = " class=\"even\""
		}
		p.w("<tr id=\"row_" + label + "\"" + cls + "><td class=\"entry\">")
		indentPx := level * 16
		if hasKids {
			p.w("<span style=\"width:" + intToStr(indentPx) + "px;display:inline-block;\">&#160;</span>")
			p.w("<span id=\"arr_" + label + "\" class=\"arrow\" onclick=\"dynsection.toggleFolder('" + label + "')\">&#9660;</span>")
		} else {
			p.w("<span style=\"width:" + intToStr(indentPx+16) + "px;display:inline-block;\">&#160;</span>")
		}
		var desc string
		if n.ns != nil {
			p.w("<span class=\"icona\"><span class=\"icon\">N</span></span>")
			p.w("<a class=\"el\" href=\"" + n.ns.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(n.ns.Name) + "</a>")
			desc = d.briefHtml(n.ns.Doc.Brief, n.ns, n.ns.Name, "")
		} else {
			p.w("<span class=\"icona\"><span class=\"icon\">" + classIconLetter(n.cd) + "</span></span>")
			p.w("<a class=\"el\" href=\"" + n.cd.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(n.cd.Name) + "</a>")
			desc = d.briefHtml(n.cd.Doc.Brief, n.cd, n.cd.Name, "")
		}
		p.w("</td><td class=\"desc\">" + desc + "</td></tr>\n")
		idx++
		for i, k := range n.kids {
			writeNode(k, level+1, label+intToStr(i)+"_")
		}
	}
	for i, k := range root.kids {
		writeNode(k, 0, intToStr(i)+"_")
	}
	p.w("</table>\n")
	p.w("</div><!-- directory -->\n")
	p.endContents()
	p.writeFooter("")
	p.finish()
}

func (d *Doxygen) nsHasVisibleClasses(ns *NamespaceDef) bool {
	for _, cd := range ns.Classes {
		if cd.isLinkable(d) {
			return true
		}
	}
	for _, sub := range ns.Namespaces {
		if d.nsHasVisibleClasses(sub) {
			return true
		}
	}
	return false
}

// briefHtml renders a brief description (abbreviated form) for index lists.
func (d *Doxygen) briefHtml(brief string, scope interface{}, name string, relPath string) string {
	if strings.TrimSpace(brief) == "" {
		return ""
	}
	ab := d.abbreviate(brief, name)
	ctx := &DocContext{d: d, scope: scope, singleLine: true}
	root := d.parseDocText(ctx, ab)
	return d.docToHtml(root, ctx, relPath)
}

// abbreviate strips the trailing dot and configured prefixes from a brief description.
func (d *Doxygen) abbreviate(s string, name string) string {
	scopeless := stripScope(name)
	result := strings.TrimSpace(s)
	if result != "" && result[len(result)-1] == '.' {
		result = result[:len(result)-1]
	}
	for _, p := range d.cfg.List("ABBREVIATE_BRIEF") {
		str := strings.ReplaceAll(p, "$name", scopeless)
		str += " "
		if strings.HasPrefix(result, str) {
			result = result[len(str):]
		}
	}
	if result != "" {
		c := result[0]
		if c >= 'a' && c <= 'z' {
			result = string(c-'a'+'A') + result[1:]
		}
	}
	return result
}

// ---------------------------------------------------------------------------
// Alphabetical class index

func (d *Doxygen) generateAlphabeticalIndex(h *HtmlGenerator, l *LatexGenerator) {
	if !d.cfg.Bool("ALPHABETICAL_INDEX") {
		return
	}
	classes := d.annotatedClasses()
	if len(classes) == 0 {
		return
	}
	if h != nil {
		h.writeAlphabeticalIndex(classes)
	}
}

func firstLetter(name string) string {
	n := stripScope(name)
	if n == "" {
		return ""
	}
	// handle UTF-8 start
	if n[0] >= 0x80 {
		i := 1
		for i < len(n) && n[i]&0xC0 == 0x80 {
			i++
		}
		return n[:i]
	}
	return strings.ToUpper(n[:1])
}

func letterId(letter string) string {
	if len(letter) == 1 && ((letter[0] >= 'A' && letter[0] <= 'Z') || (letter[0] >= 'a' && letter[0] <= 'z') || (letter[0] >= '0' && letter[0] <= '9')) {
		return letter
	}
	// hex encode
	var sb strings.Builder
	for i := 0; i < len(letter); i++ {
		sb.WriteString("0x" + strings.ToLower(hexByte(letter[i])))
	}
	return sb.String()
}

func (h *HtmlGenerator) writeAlphabeticalIndex(classes []*ClassDef) {
	d := h.d
	p := h.newPage("classes", "Class Index", "")
	p.writeHeader("Class Index", "", true)
	p.startContents("Class Index")
	// group by first letter
	type group struct {
		letter  string
		classes []*ClassDef
	}
	var groups []*group
	byLetter := map[string]*group{}
	sorted := append([]*ClassDef{}, classes...)
	sort.SliceStable(sorted, func(i, j int) bool { return qstricmpSort(stripScope(sorted[i].QualName), stripScope(sorted[j].QualName)) < 0 })
	for _, cd := range sorted {
		letter := firstLetter(cd.QualName)
		g := byLetter[letter]
		if g == nil {
			g = &group{letter: letter}
			byLetter[letter] = g
			groups = append(groups, g)
		}
		g.classes = append(g.classes, cd)
	}
	p.w("<div class=\"qindex\">")
	for i, g := range groups {
		if i > 0 {
			p.w("&#160;|&#160;")
		}
		p.w("<a class=\"qindex\" href=\"#letter_" + letterId(g.letter) + "\">" + htmlEscape(g.letter) + "</a>")
	}
	p.w("</div>\n")
	p.w("<div class=\"classindex\">\n")
	for i, g := range groups {
		cls := "even"
		if i%2 == 1 {
			cls = "odd"
		}
		p.w("<dl class=\"classindex " + cls + "\">\n")
		p.w("<dt class=\"alphachar\"><a id=\"letter_" + letterId(g.letter) + "\" name=\"letter_" + letterId(g.letter) + "\">" + htmlEscape(g.letter) + "</a></dt>\n")
		for j, cd := range g.classes {
			p.w("<dd><a class=\"el\" href=\"" + cd.OutputBase + h.ext + "\">" + htmlEscape(stripScope(cd.QualName)) + "</a>")
			if sp := scopePart(cd.QualName); sp != "" {
				p.w(" (" + htmlEscape(sp) + ")")
			}
			p.w("</dd>")
			if j < len(g.classes)-1 {
				p.w("\n")
			}
		}
		p.w("</dl>\n")
	}
	p.w("</div>\n")
	p.endContents()
	p.writeFooter("")
	p.finish()
}

// ---------------------------------------------------------------------------
// Class hierarchy

func (d *Doxygen) generateHierarchyIndex(h *HtmlGenerator, l *LatexGenerator) {
	if d.hierarchyClasses() == 0 {
		return
	}
	if h != nil {
		h.writeHierarchy()
	}
}

func (h *HtmlGenerator) writeHierarchy() {
	d := h.d
	p := h.newPage("hierarchy", "Class Hierarchy", "")
	p.writeHeader("Class Hierarchy", "", true)
	p.startContents("Class Hierarchy")
	p.w("<div class=\"textblock\">")
	p.w("This inheritance list is sorted roughly, but not completely, alphabetically:")
	p.w("</div><div class=\"directory\">\n")
	p.w("<table class=\"directory\">\n")
	idx := 0
	var writeNode func(cd *ClassDef, level int, label string, visited map[*ClassDef]bool)
	writeNode = func(cd *ClassDef, level int, label string, visited map[*ClassDef]bool) {
		var kids []*ClassDef
		for _, dc := range cd.Derived {
			if dc.isLinkable(d) || dc.hasNonReferenceSuperClass(d) {
				kids = append(kids, dc)
			}
		}
		sort.SliceStable(kids, func(i, j int) bool { return qstricmpSort(kids[i].QualName, kids[j].QualName) < 0 })
		cls := ""
		if idx%2 == 0 {
			cls = " class=\"even\""
		}
		p.w("<tr id=\"row_" + label + "\"" + cls + "><td class=\"entry\">")
		if len(kids) > 0 && !visited[cd] {
			p.w("<span style=\"width:" + intToStr(level*16) + "px;display:inline-block;\">&#160;</span>")
			p.w("<span id=\"arr_" + label + "\" class=\"arrow\" onclick=\"dynsection.toggleFolder('" + label + "')\">&#9660;</span>")
		} else {
			p.w("<span style=\"width:" + intToStr(level*16+16) + "px;display:inline-block;\">&#160;</span>")
		}
		p.w("<span class=\"icona\"><span class=\"icon\">" + classIconLetter(cd) + "</span></span>")
		if cd.isLinkable(d) {
			p.w("<a class=\"el\" href=\"" + cd.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(cd.QualName) + "</a>")
		} else {
			p.w("<b>" + htmlEscape(cd.QualName) + "</b>")
		}
		p.w("</td><td class=\"desc\">" + d.briefHtml(cd.Doc.Brief, cd, cd.Name, "") + "</td></tr>\n")
		idx++
		if visited[cd] {
			return
		}
		visited[cd] = true
		for i, k := range kids {
			writeNode(k, level+1, label+intToStr(i)+"_", visited)
		}
	}
	i := 0
	visited := map[*ClassDef]bool{}
	for _, cd := range d.classes {
		if cd.isVisibleInHierarchy(d) && !cd.hasVisibleBase(d) {
			writeNode(cd, 0, intToStr(i)+"_", visited)
			i++
		}
	}
	p.w("</table>\n")
