func (h *HtmlGenerator) writeMemberIndexPages(base string, title string, cats []memberIndexCat, members map[string][]*memberIndexEntry, intro func(string) string) {
	d := h.d
	for _, cat := range cats {
		list := members[cat.key]
		if len(list) == 0 {
			continue
		}
		name := base + cat.label
		pageTitle := title
		if cat.key != "all" {
			pageTitle = title + " - " + cat.title
		}
		p := h.newPage(name, pageTitle, "")
		p.writeHeader(pageTitle, "", true)
		p.w("<div class=\"contents\">\n")
		p.w("<div class=\"textblock\">" + intro(cat.key) + "</div>")
		// group by letter
		letters := []string{}
		byLetter := map[string][]*memberIndexEntry{}
		for _, e := range list {
			lt := strings.ToLower(firstLetter(e.name))
			if _, ok := byLetter[lt]; !ok {
				letters = append(letters, lt)
			}
			byLetter[lt] = append(byLetter[lt], e)
		}
		multi := len(letters) > 1
		for _, lt := range letters {
			if multi {
				p.w("\n<h3><a id=\"index_" + letterId(lt) + "\" name=\"index_" + letterId(lt) + "\"></a>- " + htmlEscape(lt) + " -</h3>")
			}
			p.w("<ul>\n")
			for _, e := range byLetter[lt] {
				p.w("<li>")
				nm := e.name
				if e.members[0].Kind == MemberFunction || e.members[0].Kind == MemberSignal || e.members[0].Kind == MemberSlot {
					nm += "()"
				}
				p.w(htmlEscape(nm) + "&#160;:&#160;")
				// list of scopes
				seen := map[string]bool{}
				first := true
				for _, md := range e.members {
					var scopeName, file string
					if md.Class != nil {
						scopeName = md.Class.QualName
						file = md.Class.OutputBase
					} else if md.Namespace != nil && md.Namespace.isLinkable(d) && base == "namespacemembers" {
						scopeName = md.Namespace.QualName
						file = md.Namespace.OutputBase
					} else if md.FileDef != nil {
						scopeName = md.FileDef.displayName(d)
						file = md.FileDef.OutputBase
					}
					key := file + "#" + md.Anchor
					if seen[key] {
						continue
					}
					seen[key] = true
					if !first {
						p.w(", ")
					}
					first = false
					anchor := md.Anchor
					if md.Kind == MemberEnumValue && md.EnumScope != nil {
						anchor = md.Anchor
					}
					p.w("<a class=\"el\" href=\"" + file + h.ext + "#" + anchor + "\">" + htmlEscape(scopeName) + "</a>")
				}
				p.w("</li>\n")
			}
			p.w("</ul>\n")
		}
		p.endContents()
		p.writeFooter("")
		p.finish()
	}
}

