func (d *Doxygen) generateNamespaceIndex(h *HtmlGenerator, l *LatexGenerator) {
	nss := d.documentedNamespaces()
	if len(nss) == 0 || !d.cfg.Bool("SHOW_NAMESPACES") {
		return
	}
	if h != nil {
		h.writeNamespaceIndex(nss)
	}
}

func (h *HtmlGenerator) writeNamespaceIndex(nss []*NamespaceDef) {
	d := h.d
	p := h.newPage("namespaces", "Namespace List", "")
	p.writeHeader("Namespace List", "", true)
	p.startContents("Namespace List")
	p.w("<div class=\"textblock\">Here is a list of all documented namespaces with brief descriptions:</div>")
	p.w("<div class=\"directory\">\n")
	p.w("<table class=\"directory\">\n")
	idx := 0
	var writeNs func(ns *NamespaceDef, level int, label string)
	writeNs = func(ns *NamespaceDef, level int, label string) {
		var kids []*NamespaceDef
		for _, sub := range ns.Namespaces {
			if sub.isLinkable(d) {
				kids = append(kids, sub)
			}
		}
		cls := ""
		if idx%2 == 0 {
			cls = " class=\"even\""
		}
		p.w("<tr id=\"row_" + label + "\"" + cls + "><td class=\"entry\">")
		if len(kids) > 0 {
			p.w("<span style=\"width:" + intToStr(level*16) + "px;display:inline-block;\">&#160;</span>")
			p.w("<span id=\"arr_" + label + "\" class=\"arrow\" onclick=\"dynsection.toggleFolder('" + label + "')\">&#9660;</span>")
		} else {
			p.w("<span style=\"width:" + intToStr(level*16+16) + "px;display:inline-block;\">&#160;</span>")
		}
		p.w("<span class=\"icona\"><span class=\"icon\">N</span></span>")
		p.w("<a class=\"el\" href=\"" + ns.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(ns.Name) + "</a>")
		p.w("</td><td class=\"desc\">" + d.briefHtml(ns.Doc.Brief, ns, ns.Name, "") + "</td></tr>\n")
		idx++
		for i, k := range kids {
			writeNs(k, level+1, label+intToStr(i)+"_")
		}
	}
	i := 0
	for _, ns := range nss {
		if ns.Parent == nil {
			writeNs(ns, 0, intToStr(i)+"_")
			i++
		}
	}
	p.w("</table>\n")
	p.w("</div><!-- directory -->\n")
	p.endContents()
	p.writeFooter("")
	p.finish()
}

