func (d *Doxygen) generatePageIndex(h *HtmlGenerator, l *LatexGenerator) {
	var pages []*PageDef
	for _, pg := range d.pages {
		if pg.Parent == nil {
			pages = append(pages, pg)
		}
	}
	if len(pages) == 0 {
		return
	}
	if h != nil {
		p := h.newPage("pages", "Related Pages", "")
		p.writeHeader("Related Pages", "", true)
		p.startContents("Related Pages")
		p.w("<div class=\"textblock\">Here is a list of all related documentation pages:</div>")
		p.w("<div class=\"directory\">\n")
		p.w("<table class=\"directory\">\n")
		for i, pg := range pages {
			cls := ""
			if i%2 == 0 {
				cls = " class=\"even\""
			}
			p.w("<tr id=\"row_" + intToStr(i) + "_\"" + cls + "><td class=\"entry\">")
			p.w("<span style=\"width:16px;display:inline-block;\">&#160;</span>")
			p.w("<a class=\"el\" href=\"" + pg.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(pg.displayTitle()) + "</a>")
			p.w("</td><td class=\"desc\"></td></tr>\n")
		}
		p.w("</table>\n")
		p.w("</div><!-- directory -->\n")
		p.endContents()
		p.writeFooter("")
		p.finish()
	}
}

func (pg *PageDef) displayTitle() string {
	if pg.Title != "" {
		return pg.Title
	}
	return pg.Name
}

func (d *Doxygen) generatePageDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, pg := range d.pages {
		msg("Generating docs for page %s...\n", pg.Name)
		if h != nil {
			h.writePage(pg)
		}
		if l != nil {
			l.writePage(pg)
		}
	}
}

func (h *HtmlGenerator) writePage(pg *PageDef) {
	d := h.d
	title := pg.displayTitle()
	p := h.newPage(pg.OutputBase, title, "")
	p.writeHeader(title, "", true)
	p.startContents(convertToHtml(title, false))
	ctx := &DocContext{d: d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine}
	root := d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc))
	p.w("<div class=\"textblock\">")
	p.w(d.docToHtml(root, ctx, ""))
	p.w("</div>")
	p.endContents()
	nav := h.navPathItems([]navItem{{text: title, url: pg.OutputBase + h.ext}})
	p.writeFooter(nav)
	p.finish()
}
