	add := func(key, title string, kind MemberKind) {
		var list []*MemberDef
		for _, md := range members {
			if md.Kind != kind || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			if inFile && md.Namespace != nil && md.Namespace.isLinkable(d) {
				continue
			}
			list = append(list, md)
		}
		if len(list) > 0 {
			if d.cfg.Bool("SORT_MEMBER_DOCS") {
				sortMembers(list, false)
			}
			out = append(out, &detailSection{key: key, title: title, members: list})
		}
	}
	add("doc-define-members", "Macro Definition Documentation", MemberDefine)
	add("doc-typedef-members", "Typedef Documentation", MemberTypedef)
	add("doc-enum-members", "Enumeration Type Documentation", MemberEnum)
	add("doc-func-members", "Function Documentation", MemberFunction)
	add("doc-var-members", "Variable Documentation", MemberVariable)
	return out
}

// ---------------------------------------------------------------------------
// Class documentation

func (d *Doxygen) generateClassDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, cd := range d.classes {
		if !cd.isLinkable(d) {
			continue
		}
		msg("Generating docs for compound %s...\n", cd.QualName)
		if h != nil {
			h.writeClassPage(cd)
			h.writeClassMemberList(cd)
		}
		if l != nil {
			l.writeClass(cd)
		}
	}
}

func compoundTypeName(cd *ClassDef) string {
	switch cd.CompoundType {
	case "struct":
		return "Struct"
	case "union":
		return "Union"
	case "interface":
		return "Interface"
	case "protocol":
		return "Protocol"
	case "category":
		return "Category"
	case "exception":
		return "Exception"
	}
	return "Class"
}

func (cd *ClassDef) hasDetailedDescription(d *Doxygen) bool {
	repeatBrief := d.cfg.Bool("REPEAT_BRIEF")
	sourceBrowser := d.cfg.Bool("SOURCE_BROWSER")
	return (cd.Doc.Brief != "" && repeatBrief) || cd.Doc.Doc != "" || (sourceBrowser && cd.BodyStart > 0)
}

func (h *HtmlGenerator) writeClassPage(cd *ClassDef) {
	d := h.d
	pageTitle := cd.QualName + " " + compoundTypeName(cd) + " Reference"
	if cd.isTemplate && len(cd.TemplateArgs) > 0 {
		pageTitle = cd.QualName + " " + compoundTypeName(cd) + " Template Reference"
	}
	p := h.newPage(cd.OutputBase, pageTitle, "")
	p.outlineName = cd.OutputBase + "-members"
	p.hasOutline = true
	p.writeHeader(pageTitle, "", true)
	// title with summary links
	var summary strings.Builder
	summary.WriteString("<div class=\"summary\">\n")
	sections := d.classMemberSections(cd)
	first := true
	hasNested := false
	for _, inner := range cd.Inner {
		if inner.isLinkable(d) {
			hasNested = true
		}
	}
	if hasNested {
		summary.WriteString("<a href=\"#nested-classes\">Classes</a>")
		first = false
	}
	for _, s := range sections {
		var label string
		switch {
		case strings.HasSuffix(s.key, "-types"):
			label = "Public Types"
			if strings.HasPrefix(s.key, "pro") {
				label = "Protected Types"
			} else if strings.HasPrefix(s.key, "pri") {
				label = "Private Types"
			}
		case strings.Contains(s.key, "methods"):
			label = "Public Member Functions"
			if strings.HasPrefix(s.key, "pro") {
				label = "Protected Member Functions"
			} else if strings.HasPrefix(s.key, "pri") {
				label = "Private Member Functions"
			}
			if strings.Contains(s.key, "static") {
				label = "Static " + label
			}
		case strings.Contains(s.key, "attribs"):
			label = "Public Attributes"
			if strings.HasPrefix(s.key, "pro") {
				label = "Protected Attributes"
			} else if strings.HasPrefix(s.key, "pri") {
				label = "Private Attributes"
			}
			if strings.Contains(s.key, "static") {
				label = "Static " + label
			}
		case s.key == "friends":
			label = "Friends"
		}
		if !first {
			summary.WriteString(" &#124;\n")
		}
		summary.WriteString("<a href=\"#" + s.key + "\">" + label + "</a>")
		first = false
	}
	if !first {
		summary.WriteString(" &#124;\n")
	}
	summary.WriteString("<a href=\"" + cd.OutputBase + "-members" + h.ext + "\">List of all members</a>")
	summary.WriteString("</div>\n")
	p.w("<div class=\"header\">\n")
	p.w(summary.String())
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + htmlEscape(pageTitle))
	if cd.isTemplate && len(cd.TemplateArgs) > 0 {
		// template parameters shown in title
	}
	p.w("</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
	ctx := &DocContext{d: d, scope: cd}
	// brief description
	if cd.Doc.Brief != "" {
		p.w("\n<p>")
		bctx := &DocContext{d: d, scope: cd, singleLine: true, file: cd.Doc.BriefFile, line: cd.Doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, cd.Doc.Brief), bctx, ""))
		p.w(" \n")
		if cd.hasDetailedDescription(d) {
			p.w("<a href=\"#details\">More...</a>")
		}
		p.w("</p>\n")
	}
	// include line
	if d.cfg.Bool("SHOW_HEADERFILE") && cd.FileDef != nil && cd.FileDef.isLinkable(d) {
		fd := cd.FileDef
		incName := fd.Name
		if d.cfg.Bool("FULL_PATH_NAMES") {
			incName = d.stripFromIncPath(fd.File)
			// only strip the inc path if it matches; otherwise show the stripped path
			if incName == fd.File {
				incName = fd.Name
			}
		}
		p.w("\n<p><code>#include &lt;")
		if fd.HasSource {
			p.w("<a class=\"el\" href=\"" + fd.OutputBase + "_source" + h.ext + "\">" + htmlEscape(incName) + "</a>")
		} else {
			p.w("<a class=\"el\" href=\"" + fd.OutputBase + h.ext + "\">" + htmlEscape(incName) + "</a>")
		}
		p.w("&gt;</code></p>\n")
	}
	// inheritance (text form, no dot)
	h.writeInheritanceText(p, cd)
	// nested classes
	if hasNested {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-nested-classes\" class=\"groupheader\"><a id=\"nested-classes\" name=\"nested-classes\"></a>\nClasses</h2></td></tr>\n")
		for _, inner := range cd.Inner {
			if !inner.isLinkable(d) {
				continue
			}
			h.writeClassDeclRow(p, inner, "")
		}
		p.w("</table>")
	}
	for i, s := range sections {
		if i > 0 || hasNested {
			// tables are directly concatenated
		}
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-" + s.key + "\" class=\"groupheader\"><a id=\"" + s.key + "\" name=\"" + s.key + "\"></a>\n" + s.title + "</h2></td></tr>\n")
		for _, md := range s.members {
			h.writeMemberDeclaration(p, md, cd, "")
		}
		p.w("</table>")
	}
	if hasNested || len(sections) > 0 {
		p.w("\n")
	}
	// inherited members from base classes (brief)
	// detailed description
	if cd.hasDetailedDescription(d) {
		p.w("<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
		p.w("<div class=\"textblock\">")
		h.writeDetailedDocBody(p, &cd.Doc, ctx, cd.QualName, nil)
		p.w("</div>")
	}
	// member documentation
	details := d.classDetailSections(cd)
	for _, ds := range details {
		p.w("<a name=\"" + ds.key + "\" id=\"" + ds.key + "\"></a><h2 id=\"header-" + ds.key + "\" class=\"groupheader\">" + ds.title + "</h2>\n")
		for _, md := range ds.members {
			h.writeMemberDocumentation(p, md, cd, "")
		}
	}
	// used files
	if d.cfg.Bool("SHOW_USED_FILES") && len(cd.UsedFiles) > 0 {
		p.w("<hr/>The documentation for this " + strings.ToLower(compoundTypeName(cd)) + " was generated from the following file")
		if len(cd.UsedFiles) > 1 {
			p.w("s")
		}
		p.w(":<ul>\n")
		for _, fd := range cd.UsedFiles {
			p.w("<li>")
			if fd.HasSource {
				p.w("<a class=\"el\" href=\"" + fd.OutputBase + "_source" + h.ext + "\">" + htmlEscape(fd.displayName(d)) + "</a>")
			} else if fd.isLinkable(d) {
				p.w("<a class=\"el\" href=\"" + fd.OutputBase + h.ext + "\">" + htmlEscape(fd.displayName(d)) + "</a>")
			} else {
				p.w(htmlEscape(fd.displayName(d)))
			}
			p.w("</li>\n")
		}
		p.w("</ul>\n")
	}
	p.endContents()
	nav := h.navPathItems(h.classNavPath(cd))
	p.writeFooter(nav)
	p.finish()
}

func (h *HtmlGenerator) classNavPath(cd *ClassDef) []navItem {
	var items []navItem
	var scopes []navItem
	var cur interface{} = cd
	for cur != nil {
		switch s := cur.(type) {
		case *ClassDef:
			scopes = append([]navItem{{text: s.Name, url: s.OutputBase + h.ext}}, scopes...)
			if s.OuterScope != nil {
				cur = s.OuterScope
			} else {
				cur = nil
			}
		case *NamespaceDef:
			if s.isLinkable(h.d) {
				scopes = append([]navItem{{text: s.Name, url: s.OutputBase + h.ext}}, scopes...)
			}
			if s.Parent != nil {
				cur = s.Parent
			} else {
				cur = nil
			}
		default:
			cur = nil
		}
	}
	items = append(items, scopes...)
	return items
}

func (h *HtmlGenerator) writeInheritanceText(p *HtmlPage, cd *ClassDef) {
	d := h.d
	classGraph := d.cfg.Enum("CLASS_GRAPH")
	if classGraph == "NO" {
		return
	}
	var bases, derived []*BaseClass
	for _, b := range cd.Bases {
		bases = append(bases, b)
	}
	for _, dc := range cd.Derived {
		derived = append(derived, &BaseClass{Class: dc, Name: dc.QualName})
	}
	if len(bases) == 0 && len(derived) == 0 {
		return
	}
	if len(bases) > 0 {
		p.w("<p>Inherits ")
		for i, b := range bases {
			if i > 0 {
				p.w(", ")
			}
			if b.Class != nil && b.Class.isLinkable(d) {
				p.w("<a class=\"el\" href=\"" + b.Class.OutputBase + h.ext + "\">" + htmlEscape(b.Class.QualName) + "</a>")
			} else {
				p.w(htmlEscape(b.Name))
			}
		}
		p.w(".</p>\n")
	}
	if len(derived) > 0 {
		p.w("<p>Inherited by ")
		for i, b := range derived {
			if i > 0 {
				p.w(", ")
			}
			if b.Class != nil && b.Class.isLinkable(d) {
				p.w("<a class=\"el\" href=\"" + b.Class.OutputBase + h.ext + "\">" + htmlEscape(b.Class.QualName) + "</a>")
			} else {
				p.w(htmlEscape(b.Name))
			}
		}
		p.w(".</p>\n")
	}
}

// writeClassDeclRow writes a nested class / file-level class declaration row.
func (h *HtmlGenerator) writeClassDeclRow(p *HtmlPage, cd *ClassDef, relPath string) {
	d := h.d
	name := cd.Name
	p.w("<tr class=\"memitem:" + cd.OutputBase + "\" id=\"r_" + cd.OutputBase + "\"><td class=\"memItemLeft\">" + cd.CompoundType + " &#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + relPath + cd.OutputBase + h.ext + "\">" + htmlEscape(name) + "</a></td></tr>\n")
	if cd.Doc.Brief != "" {
		p.w("<tr class=\"memdesc:" + cd.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">")
		p.w(d.briefHtml(cd.Doc.Brief, cd, cd.Name, relPath))
		p.w(" <a href=\"" + relPath + cd.OutputBase + h.ext + "#details\">More...</a><br /></td></tr>\n")
	}
}

// writeMemberDeclaration writes a row in the member declaration table.
func (h *HtmlGenerator) writeMemberDeclaration(p *HtmlPage, md *MemberDef, scope interface{}, relPath string) {
	d := h.d
	anchor := md.Anchor
	linkable := md.isLinkable(d) && md.isDetailedSectionLinkable(d)
	// template parameter row
	if md.TArgList != nil && len(md.TArgList.Args) > 0 {
		p.w("<tr class=\"memitem:" + anchor + "\" id=\"r_" + anchor + "\"><td class=\"memTemplParams\" colspan=\"2\">")
		p.w("template&lt;" + htmlEscape(templateArgsText(md.TArgList)) + "&gt;</td></tr>\n")
		p.w("<tr class=\"memitem:" + anchor + "\"><td class=\"memTemplItemLeft\">")
	} else {
		p.w("<tr class=\"memitem:" + anchor + "\" id=\"r_" + anchor + "\"><td class=\"memItemLeft\">")
	}
	// left column: type
	left := ""
	switch md.Kind {
	case MemberDefine:
		left = "#define"
	case MemberTypedef:
		if md.Entry != nil && md.Entry.Alias {
			left = "using"
		} else {
			left = "typedef " + md.Type
		}
	case MemberEnum:
		if md.Strong {
			left = "enum class"
		} else {
			left = "enum"
		}
	case MemberFriend:
		left = md.Type
	default:
		var parts []string
		if md.Static {
			parts = append(parts, "static")
		}
		if md.Virtual && md.Kind == MemberFunction {
			parts = append(parts, "virtual")
		}
		if md.Explicit {
			parts = append(parts, "explicit")
		}
		if md.Type != "" {
			parts = append(parts, md.Type)
		}
		left = strings.Join(parts, " ")
	}
	if left != "" {
		p.w(d.linkifyText(left, scope, relPath) + "&#160;")
	}
	if md.TArgList != nil && len(md.TArgList.Args) > 0 {
		p.w("</td><td class=\"memTemplItemRight\">")
	} else {
		p.w("</td><td class=\"memItemRight\">")
	}
	// name
	name := md.Name
	if md.Kind == MemberTypedef && md.Entry != nil && md.Entry.Alias {
		name = md.Name
	}
	if linkable {
		href := relPath + md.outputFile(d) + h.ext + "#" + anchor
		if scopeIsSame(scope, md) {
			href = "#" + anchor
		}
		p.w("<a class=\"el\" href=\"" + href + "\">" + htmlEscape(name) + "</a>")
	} else {
		p.w("<b>" + htmlEscape(name) + "</b>")
	}
	// right part
	switch md.Kind {
	case MemberFunction, MemberFriend:
		if md.Kind == MemberFriend && !strings.Contains(md.Type, "friend class") && md.Args != "" || md.Kind == MemberFunction {
			args := md.Args
			p.w(" " + d.linkifyText(args, scope, relPath))
		}
		if md.Kind == MemberFunction {
			if md.PureVirtual && !strings.Contains(md.Args, "=0") {
				p.w("=0")
			}
		}
	case MemberVariable:
		if md.Args != "" {
			p.w(d.linkifyText(md.Args, scope, relPath))
		}
		if md.Bitfield != "" {
			p.w(htmlEscape(md.Bitfield))
		}
		if md.Initializer != "" && d.showInitializer(md) {
			p.w(" " + htmlEscape(md.Initializer))
		}
	case MemberTypedef:
		if md.Entry != nil && md.Entry.Alias {
			p.w(" = " + d.linkifyText(md.Type, scope, relPath))
		} else if md.Args != "" {
			p.w(d.linkifyText(md.Args, scope, relPath))
		}
	case MemberDefine:
		if md.Args != "" {
			p.w(htmlEscape(md.Args))
		}
		if md.Initializer != "" && d.showInitializer(md) {
			p.w("&#160;&#160;&#160;" + htmlEscape(md.Initializer))
		}
	case MemberEnum:
		if len(md.EnumValues) > 0 {
			p.w(" { ")
			perLine := d.cfg.Int("ENUM_VALUES_PER_LINE")
			for i, ev := range md.EnumValues {
				if i > 0 {
					p.w("\n, ")
					if perLine > 0 && i%perLine == 0 {
						p.w("<br />\n&#160;&#160;")
					}
				}
				if ev.isLinkable(d) || linkable {
					href := relPath + md.outputFile(d) + h.ext + "#" + ev.Anchor
					if scopeIsSame(scope, md) {
						href = "#" + ev.Anchor
					}
					p.w("<a class=\"el\" href=\"" + href + "\">" + htmlEscape(ev.Name) + "</a>")
				} else {
					p.w("<b>" + htmlEscape(ev.Name) + "</b>")
				}
				if ev.Initializer != "" && d.showInitializer(ev) {
					p.w(" " + htmlEscape(ev.Initializer))
				}
			}
			p.w("\n }")
		}
	}
	// labels (override etc.) are shown in the detailed section only
	p.w("</td></tr>\n")
	// brief description row
	if md.Doc.Brief != "" && d.cfg.Bool("BRIEF_MEMBER_DESC") {
		p.w("<tr class=\"memdesc:" + anchor + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">")
		bctx := &DocContext{d: d, scope: scope, member: md, singleLine: true, file: md.Doc.BriefFile, line: md.Doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, md.Doc.Brief), bctx, relPath))
		if linkable {
			href := relPath + md.outputFile(d) + h.ext + "#" + anchor
			if scopeIsSame(scope, md) {
				href = "#" + anchor
			}
			p.w(" <a href=\"" + href + "\">More...</a>")
		}
		p.w("<br /></td></tr>\n")
	}
}

func scopeIsSame(scope interface{}, md *MemberDef) bool {
	switch s := scope.(type) {
	case *ClassDef:
		return md.Class == s
	case *NamespaceDef:
		return md.Namespace == s
	case *FileDef:
		return md.Class == nil && (md.Namespace == nil || true)
	}
	return false
}

func (d *Doxygen) showInitializer(md *MemberDef) bool {
	if md.Entry != nil {
		for _, s := range md.Entry.MemberSpec {
			if s == "hideinitializer" {
				return false
			}
			if s == "showinitializer" {
				return true
			}
		}
	}
	maxLines := d.cfg.Int("MAX_INITIALIZER_LINES")
	lines := strings.Count(md.Initializer, "\n") + 1
	return lines <= maxLines && maxLines > 0 && len(md.Initializer) < 200 || (maxLines > 0 && lines <= maxLines && !strings.Contains(md.Initializer, "\n") && len(md.Initializer) < 200)
}

func templateArgsText(al *ArgumentList) string {
	var parts []string
	for _, a := range al.Args {
		s := a.Type
		if a.Name != "" {
			s += " " + a.Name
		}
		if a.DefVal != "" {
			s += " = " + a.DefVal
		}
		parts = append(parts, s)
	}
	return strings.Join(parts, ", ")
}

// linkifyText converts a type string into HTML with links to known classes.
func (d *Doxygen) linkifyText(text string, scope interface{}, relPath string) string {
	var sb strings.Builder
	i := 0
	n := len(text)
	for i < n {
		c := text[i]
		if isIdentStart(c) {
			j := i
			for j < n && (isIdentChar(text[j]) || (text[j] == ':' && j+1 < n && text[j+1] == ':') || (text[j] == ':' && j > 0 && text[j-1] == ':')) {
				j++
			}
			word := text[i:j]
			// trailing "::" should not be part of the word
			for strings.HasSuffix(word, "::") {
				word = word[:len(word)-2]
				j -= 2
			}
			var cd *ClassDef
			switch s := scope.(type) {
			case *ClassDef:
				cd = d.resolveClassInNs(word, s.FileDef, s)
			case *FileDef:
				cd = d.resolveClassInNs(word, s, nil)
			case *NamespaceDef:
				if c := d.classMap[s.QualName+"::"+word]; c != nil {
					cd = c
				} else {
					cd = d.classMap[word]
				}
			default:
				cd = d.classMap[word]
			}
			if cd != nil && cd.isLinkable(d) && !isTypeKeyword(word) {
				sb.WriteString("<a class=\"el\" href=\"" + relPath + cd.OutputBase + d.htmlExt() + "\">" + htmlEscape(word) + "</a>")
			} else if md := d.findTypedefOrEnum(word, scope); md != nil {
				sb.WriteString("<a class=\"el\" href=\"" + relPath + md.outputFile(d) + d.htmlExt() + "#" + md.Anchor + "\">" + htmlEscape(word) + "</a>")
			} else {
				sb.WriteString(htmlEscape(word))
			}
			i = j
			continue
		}
		sb.WriteString(htmlEscape(string(c)))
		i++
	}
	return sb.String()
}

func (d *Doxygen) findTypedefOrEnum(word string, scope interface{}) *MemberDef {
	check := func(members []*MemberDef) *MemberDef {
		for _, md := range members {
			if (md.Kind == MemberTypedef || md.Kind == MemberEnum) && md.Name == word && md.isLinkable(d) {
				return md
			}
		}
		return nil
	}
	switch s := scope.(type) {
	case *ClassDef:
		if md := check(s.Members); md != nil {
			return md
		}
		if s.FileDef != nil {
			if md := check(s.FileDef.Members); md != nil {
				return md
			}
		}
	case *FileDef:
		if md := check(s.Members); md != nil {
			return md
		}
	case *NamespaceDef:
		if md := check(s.Members); md != nil {
			return md
		}
	}
	return nil
}

// writeDetailedDocBody writes brief (if repeated) + detailed + inbody docs.
func (h *HtmlGenerator) writeDetailedDocBody(p *HtmlPage, doc *DocBlock, ctx *DocContext, name string, md *MemberDef) {
	d := h.d
	repeatBrief := d.cfg.Bool("REPEAT_BRIEF")
	if repeatBrief && doc.Brief != "" {
		bctx := &DocContext{d: d, scope: ctx.scope, member: md, file: doc.BriefFile, line: doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, doc.Brief), bctx, p.relPath))
	}
	if doc.Doc != "" {
		dctx := &DocContext{d: d, scope: ctx.scope, member: md, file: doc.DocFile, line: doc.DocLine}
		p.w(d.docToHtml(d.parseDocText(dctx, doc.Doc), dctx, p.relPath))
	}
	if doc.InBody != "" {
		dctx := &DocContext{d: d, scope: ctx.scope, member: md, file: doc.DocFile, line: doc.InBodyLine}
		p.w(d.docToHtml(d.parseDocText(dctx, doc.InBody), dctx, p.relPath))
	}
}

// writeMemberDocumentation writes the detailed documentation block of a member.
func (h *HtmlGenerator) writeMemberDocumentation(p *HtmlPage, md *MemberDef, scope interface{}, relPath string) {
	d := h.d
	anchor := md.Anchor
	p.w("<a id=\"" + anchor + "\" name=\"" + anchor + "\"></a>\n")
	// title
	title := md.Name
	if md.Kind == MemberFunction || md.Kind == MemberFriend && md.Args != "" {
		title += "()"
	}
	overload := ""
	if md.Kind == MemberFunction {
		// count overloads in the same scope
		var siblings []*MemberDef
		switch s := scope.(type) {
		case *ClassDef:
			siblings = s.Members
		case *FileDef:
			siblings = s.Members
		case *NamespaceDef:
			siblings = s.Members
		}
		count := 0
		idx := 0
		for _, m := range siblings {
			if m.Kind == MemberFunction && m.Name == md.Name && m.isDetailedSectionLinkable(d) && m.isBriefSectionVisible(d) {
				count++
				if m == md {
					idx = count
				}
			}
		}
		if count > 1 {
			overload = " <span class=\"overload\">[" + intToStr(idx) + "/" + intToStr(count) + "]</span>"
		}
	}
	p.w("<h2 class=\"memtitle\"><span class=\"permalink\"><a href=\"#" + anchor + "\">&#9670;&#160;</a></span>" + htmlEscape(title) + overload + "</h2>\n")
	p.w("\n")
	p.w("<div class=\"memitem\">\n")
	p.w("<div class=\"memproto\">\n")
	// labels
	var labels []string
	if md.Kind == MemberFunction || md.Kind == MemberVariable {
		if md.Static {
			labels = append(labels, "static")
		}
		if md.Prot == Protected {
			labels = append(labels, "protected")
		} else if md.Prot == Private {
			labels = append(labels, "private")
		} else if md.Prot == Package {
			labels = append(labels, "package")
		}
		if md.Kind == MemberFunction {
			if md.PureVirtual {
				labels = append(labels, "pure virtual")
			} else if md.Virtual && md.Entry != nil && md.Entry.Virtual {
				labels = append(labels, "virtual")
			}
			if md.Inline || (md.BodyStart > 0 && md.Class != nil && md.DefFile == md.File && md.BodyStart >= md.Class.BodyStart && md.BodyEnd <= md.Class.BodyEnd) {
				if d.cfg.Bool("INLINE_INFO") {
					labels = append(labels, "inline")
				}
			}
			if md.Explicit {
				labels = append(labels, "explicit")
			}
			if md.ConstExpr {
				labels = append(labels, "constexpr")
			}
			if md.Override {
				labels = append(labels, "override")
			}
			if md.Final {
				labels = append(labels, "final")
			}
			if md.Default {
				labels = append(labels, "default")
			}
			if md.Delete {
				labels = append(labels, "delete")
			}
			if md.NoExcept && false {
				labels = append(labels, "noexcept")
			}
		} else {
			if md.Mutable {
				labels = append(labels, "mutable")
			}
			if md.ConstExpr {
				labels = append(labels, "constexpr")
			}
		}
	}
	if md.Kind == MemberTypedef || md.Kind == MemberEnum {
		if md.Prot == Protected {
			labels = append(labels, "protected")
		} else if md.Prot == Private {
			labels = append(labels, "private")
		}
		if md.Kind == MemberEnum && md.Strong {
			labels = append(labels, "strong")
		}
	}
	if len(labels) > 0 {
		p.w("<table class=\"mlabels\">\n")
		p.w("  <tr>\n")
		p.w("  <td class=\"mlabels-left\">\n")
	}
	p.w("      <table class=\"memname\">\n")
	h.writeMemberProto(p, md, scope, relPath)
	p.w("      </table>\n")
	if len(labels) > 0 {
		p.w("  </td>\n")
		p.w("  <td class=\"mlabels-right\">\n")
		p.w("<span class=\"mlabels\">")
		for _, l := range labels {
			p.w("<span class=\"mlabel " + strings.ReplaceAll(l, " ", "-") + "\">" + l + "</span>")
		}
		p.w("</span>  </td>\n")
		p.w("  </tr>\n")
		p.w("</table>\n")
	}
	p.w("</div><div class=\"memdoc\">\n")
	// documentation
	ctx := &DocContext{d: d, scope: scope, member: md}
	if md.Kind == MemberEnum && len(md.EnumValues) > 0 {
		// enum values table comes after the docs
	}
	if md.Kind == MemberVariable && md.Initializer != "" && d.showInitializer(md) && !d.cfg.Bool("HIDE_UNDOC_MEMBERS") && false {
	}
	h.writeDetailedDocBody(p, &md.Doc, ctx, md.QualName, md)
	// argument documentation (from inline comments)
	if md.ArgList != nil {
		hasArgDocs := false
		for _, a := range md.ArgList.Args {
			if a.Docs != "" {
				hasArgDocs = true
			}
		}
		if hasArgDocs {
			p.w("<dl class=\"params\"><dt>Parameters</dt><dd>\n  <table class=\"params\">\n")
			for _, a := range md.ArgList.Args {
				if a.Docs == "" {
					continue
				}
				p.w("    <tr><td class=\"paramname\">" + htmlEscape(a.Name) + "</td><td>")
				actx := &DocContext{d: d, scope: scope, member: md, singleLine: true}
				p.w(d.docToHtml(d.parseDocText(actx, a.Docs), actx, relPath))
				p.w("</td></tr>\n")
			}
			p.w("  </table>\n  </dd>\n</dl>\n")
		}
	}
	// enum values
	if md.Kind == MemberEnum && len(md.EnumValues) > 0 {
		hasDocValues := false
		for _, ev := range md.EnumValues {
			if ev.Doc.hasDocs() || d.cfg.Bool("EXTRACT_ALL") {
				hasDocValues = true
			}
		}
		if hasDocValues || d.cfg.Bool("SHOW_ENUM_VALUES") {
			p.w("<table class=\"fieldtable\">\n")
			p.w("<tr><th colspan=\"2\">Enumerator</th></tr>")
			for _, ev := range md.EnumValues {
				if !ev.Doc.hasDocs() && !d.cfg.Bool("EXTRACT_ALL") && !d.cfg.Bool("SHOW_ENUM_VALUES") {
					continue
				}
				p.w("<tr><td class=\"fieldname\"><a id=\"" + ev.Anchor + "\" name=\"" + ev.Anchor + "\"></a>" + htmlEscape(ev.Name) + "&#160;</td><td class=\"fielddoc\">")
				ectx := &DocContext{d: d, scope: scope, member: ev}
				if ev.Doc.Brief != "" {
					p.w(d.docToHtml(d.parseDocText(ectx, ev.Doc.Brief), ectx, relPath))
				}
				if ev.Doc.Doc != "" {
					p.w(d.docToHtml(d.parseDocText(ectx, ev.Doc.Doc), ectx, relPath))
				}
				p.w("</td></tr>\n")
			}
			p.w("</table>\n")
		}
	}
	// reimplements / reimplemented by
	if md.Reimplements != nil && md.Reimplements.isLinkable(d) {
		bm := md.Reimplements
		p.w("\n<p>Reimplemented from <a class=\"el\" href=\"" + relPath + bm.outputFile(d) + h.ext + "#" + bm.Anchor + "\">" + htmlEscape(bm.Class.QualName) + "</a>.</p>\n")
	}
	if len(md.ReimplementedBy) > 0 {
		var links []string
		for _, rm := range md.ReimplementedBy {
			if rm.isLinkable(d) && rm.Class != nil {
				links = append(links, "<a class=\"el\" href=\""+relPath+rm.outputFile(d)+h.ext+"#"+rm.Anchor+"\">"+htmlEscape(rm.Class.QualName)+"</a>")
			}
		}
		if len(links) > 0 {
			p.w("\n<p>Reimplemented in " + strings.Join(links, ", ") + ".</p>\n")
		}
	}
	// definition location / source link
	if d.cfg.Bool("SOURCE_BROWSER") && md.BodyStart > 0 {
		if fd := d.fileMap[md.DefFile]; fd != nil && fd.HasSource {
			p.w("\n<p class=\"definition\">Definition at line <a class=\"el\" href=\"" + relPath + fd.OutputBase + "_source" + h.ext + "#l" + padLine(md.BodyStart) + "\">" + intToStr(md.BodyStart) + "</a> of file <a class=\"el\" href=\"" + relPath + fd.OutputBase + "_source" + h.ext + "\">" + htmlEscape(fd.Name) + "</a>.</p>\n")
		}
	}
	p.w("\n</div>\n")
	p.w("</div>\n")
}

func padLine(n int) string {
	s := intToStr(n)
	for len(s) < 5 {
		s = "0" + s
	}
	return s
}

// writeMemberProto writes the memname table rows.
func (h *HtmlGenerator) writeMemberProto(p *HtmlPage, md *MemberDef, scope interface{}, relPath string) {
	d := h.d
	def := ""
	switch md.Kind {
	case MemberDefine:
		def = "#define " + htmlEscape(md.Name)
		if md.Args != "" {
			// macro with args: parameters in a table
			p.w("        <tr>\n")
			p.w("          <td class=\"memname\">" + def + "</td>\n")
			p.w("          <td>(</td>\n")
			params := strings.Split(strings.Trim(md.Args, "()"), ",")
			for i, a := range params {
				a = strings.TrimSpace(a)
				if i > 0 {
					p.w("        <tr>\n")
					p.w("          <td class=\"paramkey\"></td>\n")
					p.w("          <td></td>\n")
				}
				p.w("          <td class=\"paramtype\">&#160;</td>\n")
				p.w("          <td class=\"paramname\"><span class=\"paramname\"><em>" + htmlEscape(a) + "</em></span>")
				if i < len(params)-1 {
					p.w(", </td>\n")
					p.w("        </tr>\n")
				} else {
					p.w("&#160;)</td>\n")
					p.w("          <td></td>\n")
					p.w("        </tr>\n")
				}
			}
			return
		}
		if md.Initializer != "" && d.showInitializer(md) {
			def += "&#160;&#160;&#160;" + htmlEscape(md.Initializer)
		}
		p.w("        <tr>\n")
		p.w("          <td class=\"memname\">" + def + "</td>\n")
		p.w("        </tr>\n")
		return
	case MemberTypedef:
		if md.Entry != nil && md.Entry.Alias {
			def = "using " + htmlEscape(md.QualName) + " = " + d.linkifyText(md.Type, scope, relPath)
		} else {
			def = "typedef " + d.linkifyText(md.Type, scope, relPath) + " " + htmlEscape(md.QualName)
			if md.Args != "" {
				def += d.linkifyText(md.Args, scope, relPath)
			}
		}
		p.w("        <tr>\n")
		p.w("          <td class=\"memname\">" + def + "</td>\n")
		p.w("        </tr>\n")
		return
	case MemberEnum:
		kw := "enum "
		if md.Strong {
			kw = "enum class "
		}
		name := md.QualName
		if md.Anonymous {
			name = "anonymous enum"
			def = kw + "<a class=\"el\" href=\"#" + md.Anchor + "\">" + htmlEscape(name) + "</a>"
			def = "anonymous enum"
		} else {
			def = kw + "<a class=\"el\" href=\"#" + md.Anchor + "\">" + htmlEscape(name) + "</a>"
		}
		if md.Type != "" {
			def += " : " + d.linkifyText(md.Type, scope, relPath)
		}
		p.w("        <tr>\n")
		p.w("          <td class=\"memname\">" + def + "</td>\n")
		p.w("        </tr>\n")
		return
	case MemberVariable:
		var parts []string
		if md.Type != "" {
			parts = append(parts, d.linkifyText(md.Type, scope, relPath))
		}
		def = strings.Join(parts, " ")
		if def != "" {
			def += " "
		}
		def += htmlEscape(md.QualName)
		if md.Args != "" {
			def += d.linkifyText(md.Args, scope, relPath)
		}
		if md.Bitfield != "" {
			def += htmlEscape(md.Bitfield)
		}
		if md.Initializer != "" && d.showInitializer(md) {
			def += " " + htmlEscape(md.Initializer)
		}
		p.w("        <tr>\n")
		p.w("          <td class=\"memname\">" + def + "</td>\n")
		p.w("        </tr>\n")
		return
	}
	// functions
	var parts []string
	if md.Kind == MemberFriend {
		parts = append(parts, md.Type)
	} else {
		if md.Type != "" {
			parts = append(parts, d.linkifyText(md.Type, scope, relPath))
		}
	}
	def = strings.Join(parts, " ")
	if def != "" {
		def += " "
	}
	def += htmlEscape(md.QualName)
	if md.Kind == MemberFriend && md.Args == "" {
		p.w("        <tr>\n")
		p.w("          <td class=\"memname\">" + def + "</td>\n")
		p.w("        </tr>\n")
		return
	}
	al := md.ArgList
	if al == nil {
		al = parseArgList(md.Args)
	}
	p.w("        <tr>\n")
	p.w("          <td class=\"memname\">" + def + " </td>\n")
	p.w("          <td>(</td>\n")
	trailing := memberTrailingText(md)
	if len(al.Args) == 0 || al.NoParams {
		if al.NoParams && strings.Contains(md.Args, "void") {
			p.w("          <td class=\"paramtype\">void</td>          <td class=\"paramname\"><span class=\"paramname\"><em></em></span></td><td>)</td>\n")
		} else {
			p.w("          <td class=\"paramname\"><span class=\"paramname\"><em></em></span></td><td>)</td>\n")
		}
		p.w("          <td>" + trailing + "</td>\n")
		p.w("        </tr>\n")
		return
	}
	for i, a := range al.Args {
		if i > 0 {
			p.w("        <tr>\n")
			p.w("          <td class=\"paramkey\"></td>\n")
			p.w("          <td></td>\n")
		}
		typ := a.Type
		p.w("          <td class=\"paramtype\">" + d.linkifyText(typ, scope, relPath) + "</td>          <td class=\"paramname\"><span class=\"paramname\"><em>" + htmlEscape(a.Name) + "</em></span>")
		if a.Array != "" {
			p.w(htmlEscape(a.Array))
		}
		if a.DefVal != "" {
			p.w("<span class=\"paramdefsep\"> = </span><span class=\"paramdefval\">" + d.linkifyText(a.DefVal, scope, relPath) + "</span>")
		}
		if i < len(al.Args)-1 {
			p.w(", </td>\n")
			p.w("        </tr>\n")
		} else {
			if len(al.Args) > 1 {
				p.w("&#160;)</td>\n")
			} else {
				p.w("</td><td>)</td>\n")
			}
			p.w("          <td>" + trailing + "</td>\n")
			p.w("        </tr>\n")
		}
	}
}

// memberTrailingText returns const/volatile/= 0 etc. shown after the parameter list.
func memberTrailingText(md *MemberDef) string {
	var parts []string
	if md.Const {
		parts = append(parts, "const")
	}
	if md.Volatile {
		parts = append(parts, "volatile")
	}
	if md.ArgList != nil && md.ArgList.RefQual != "" {
		parts = append(parts, htmlEscape(md.ArgList.RefQual))
	}
	if md.NoExcept {
		parts = append(parts, "noexcept")
	}
	if md.Exception != "" {
		parts = append(parts, htmlEscape(md.Exception))
	}
	if md.PureVirtual {
		parts = append(parts, "= 0")
	}
	if md.Default {
		parts = append(parts, "= default")
	}
	if md.Delete {
		parts = append(parts, "= delete")
	}
	if md.ArgList != nil && md.ArgList.TrailingRet != "" {
		parts = append(parts, "-&gt; "+htmlEscape(md.ArgList.TrailingRet))
	}
	return strings.Join(parts, " ")
}

// ---------------------------------------------------------------------------
// Class member list page

func (h *HtmlGenerator) writeClassMemberList(cd *ClassDef) {
	d := h.d
	title := cd.QualName + " Member List"
	p := h.newPage(cd.OutputBase+"-members", "Member List", "")
	p.writeHeader("Member List", "", true)
	p.startContents(htmlEscape(title))
	p.w("\n<p>This is the complete list of members for <a class=\"el\" href=\"" + cd.OutputBase + h.ext + "\">" + htmlEscape(cd.QualName) + "</a>, including all inherited members.</p>\n")
	// collect members (including inherited)
	type entry struct {
		md *MemberDef
		cd *ClassDef
	}
	var entries []entry
	var collect func(c *ClassDef, depth int)
	seen := map[*ClassDef]bool{}
	collect = func(c *ClassDef, depth int) {
		if seen[c] || depth > 20 {
			return
		}
		seen[c] = true
		for _, md := range c.Members {
			if !md.isBriefSectionVisible(d) {
				continue
			}
			if depth > 0 && md.Prot == Private && !d.protectionVisible(Private) {
				continue
			}
			if depth > 0 && (md.IsCtor || md.IsDtor) {
				continue
			}
			entries = append(entries, entry{md, c})
			if md.Kind == MemberEnum {
				for _, ev := range md.EnumValues {
					entries = append(entries, entry{ev, c})
				}
			}
		}
		for _, b := range c.Bases {
			if b.Class != nil {
				collect(b.Class, depth+1)
			}
		}
	}
	collect(cd, 0)
	sort.SliceStable(entries, func(i, j int) bool {
		return qstricmpSort(entries[i].md.Name, entries[j].md.Name) < 0
	})
	p.w("<table class=\"directory\">\n")
	for i, e := range entries {
		md := e.md
		cls := ""
		if i%2 == 0 {
			cls = " class=\"even\""
		}
		p.w("  <tr" + cls + "><td class=\"entry\">")
		linkable := md.isLinkable(d) && md.isDetailedSectionLinkable(d)
		name := md.Name
		if linkable {
			p.w("<a class=\"el\" href=\"" + md.outputFile(d) + h.ext + "#" + md.Anchor + "\">" + htmlEscape(name) + "</a>")
		} else {
			p.w(htmlEscape(name))
		}
		if md.Kind == MemberFunction {
			p.w(htmlEscape(md.Args))
		} else if md.Kind == MemberEnumValue && md.EnumScope != nil {
			p.w(" enum value")
		} else if md.Kind == MemberEnum {
			p.w(" enum name")
		}
		p.w("</td><td class=\"entry\">")
		if e.cd.isLinkable(d) {
			p.w("<a class=\"el\" href=\"" + e.cd.OutputBase + h.ext + "\">" + htmlEscape(e.cd.QualName) + "</a>")
		} else {
			p.w(htmlEscape(e.cd.QualName))
		}
		p.w("</td><td class=\"entry\">")
		var labels []string
		if md.Kind == MemberFriend {
			labels = append(labels, "friend")
		}
		if md.Prot == Protected {
			labels = append(labels, "protected")
		} else if md.Prot == Private {
			labels = append(labels, "private")
		} else if md.Prot == Package {
			labels = append(labels, "package")
		}
		if md.Static {
			labels = append(labels, "static")
		}
		if md.Kind == MemberFunction {
			if md.PureVirtual {
				labels = append(labels, "pure virtual")
			} else if md.Virtual && md.Entry != nil && md.Entry.Virtual {
				labels = append(labels, "virtual")
			}
			if md.Inline && d.cfg.Bool("INLINE_INFO") {
				labels = append(labels, "inline")
			}
		}
		for i, l := range labels {
			if i > 0 {
				p.w("")
			}
			p.w("<span class=\"mlabel " + strings.ReplaceAll(l, " ", "-") + "\">" + l + "</span>")
		}
		p.w("</td></tr>\n")
	}
	p.w("</table></div><!-- contents -->\n")
	nav := h.navPathItems(h.classNavPath(cd))
	p.writeFooter(nav)
	p.finish()
}

// ---------------------------------------------------------------------------
// File documentation

func (d *Doxygen) generateFileDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, fd := range d.files {
		if !fd.isLinkable(d) {
			continue
		}
		msg("Generating docs for file %s...\n", fd.displayName(d))
		if h != nil {
			h.writeFilePage(fd)
		}
		if l != nil {
			l.writeFile(fd)
		}
	}
}

func (fd *FileDef) hasDetailedDescription(d *Doxygen) bool {
	repeatBrief := d.cfg.Bool("REPEAT_BRIEF")
	sourceBrowser := d.cfg.Bool("SOURCE_BROWSER")
	return (fd.Doc.Brief != "" && repeatBrief) || strings.TrimSpace(fd.Doc.Doc) != "" || (sourceBrowser && fd.HasSource)
}

func (h *HtmlGenerator) writeFilePage(fd *FileDef) {
	d := h.d
	title := fd.displayName(d) + " File Reference"
	p := h.newPage(fd.OutputBase, title, "")
	p.hasOutline = true
	p.writeHeader(title, "", true)
	// summary
	var summary strings.Builder
	sections := d.fileMemberSections(fd.Members, true)
	var visibleClasses []*ClassDef
	for _, cd := range fd.Classes {
		if cd.isLinkable(d) {
			visibleClasses = append(visibleClasses, cd)
		}
	}
	var visibleNs []*NamespaceDef
	for _, ns := range fd.Namespaces {
		if ns.isLinkable(d) {
			visibleNs = append(visibleNs, ns)
		}
	}
	var items []string
	if len(visibleClasses) > 0 {
		items = append(items, "<a href=\"#nested-classes\">Classes</a>")
	}
	if len(visibleNs) > 0 {
		items = append(items, "<a href=\"#namespaces\">Namespaces</a>")
	}
	for _, s := range sections {
		items = append(items, "<a href=\"#"+s.key+"\">"+s.title+"</a>")
	}
	if len(items) > 0 {
		summary.WriteString("<div class=\"summary\">\n")
		summary.WriteString(strings.Join(items, " &#124;\n"))
		summary.WriteString("</div>\n")
	}
	p.w("<div class=\"header\">\n")
	p.w(summary.String())
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + htmlEscape(title) + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
	ctx := &DocContext{d: d, scope: fd}
	// brief
	if fd.Doc.Brief != "" {
		p.w("\n<p>")
		bctx := &DocContext{d: d, scope: fd, singleLine: true, file: fd.Doc.BriefFile, line: fd.Doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, fd.Doc.Brief), bctx, ""))
		p.w(" \n")
		if d.cfg.Bool("REPEAT_BRIEF") || fd.Doc.Doc != "" {
			p.w("<a href=\"#details\">More...</a>")
		}
		p.w("</p>\n")
	}
	// includes
	if d.cfg.Bool("SHOW_INCLUDE_FILES") && len(fd.Includes) > 0 {
		p.w("<div class=\"textblock\">")
		for _, inc := range fd.Includes {
			p.w("<code>#include ")
			open, close := "&lt;", "&gt;"
			if inc.Local {
				open, close = "&quot;", "&quot;"
			}
			p.w(open)
			if inc.FileDef != nil && inc.FileDef.isLinkable(d) {
				p.w("<a class=\"el\" href=\"" + inc.FileDef.OutputBase + h.ext + "\">" + htmlEscape(inc.Name) + "</a>")
			} else {
				p.w(htmlEscape(inc.Name))
			}
			p.w(close + "</code><br />\n")
		}
		p.w("</div>")
	}
	// source link
	if fd.HasSource {
		p.w("\n<p><a href=\"" + fd.OutputBase + "_source" + h.ext + "\">Go to the source code of this file.</a></p>\n")
	}
	// classes
	if len(visibleClasses) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-nested-classes\" class=\"groupheader\"><a id=\"nested-classes\" name=\"nested-classes\"></a>\nClasses</h2></td></tr>\n")
		for _, cd := range visibleClasses {
			h.writeClassDeclRow(p, cd, "")
		}
		p.w("</table>")
	}
	if len(visibleNs) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-namespaces\" class=\"groupheader\"><a id=\"namespaces\" name=\"namespaces\"></a>\nNamespaces</h2></td></tr>\n")
		for _, ns := range visibleNs {
			p.w("<tr class=\"memitem:" + ns.OutputBase + "\" id=\"r_" + ns.OutputBase + "\"><td class=\"memItemLeft\">namespace &#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + ns.OutputBase + h.ext + "\">" + htmlEscape(ns.QualName) + "</a></td></tr>\n")
			if ns.Doc.Brief != "" {
				p.w("<tr class=\"memdesc:" + ns.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.briefHtml(ns.Doc.Brief, ns, ns.Name, "") + " <a href=\"" + ns.OutputBase + h.ext + "#details\">More...</a><br /></td></tr>\n")
			}
		}
		p.w("</table>")
	}
	for _, s := range sections {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-" + s.key + "\" class=\"groupheader\"><a id=\"" + s.key + "\" name=\"" + s.key + "\"></a>\n" + s.title + "</h2></td></tr>\n")
		for _, md := range s.members {
			h.writeMemberDeclaration(p, md, fd, "")
		}
		p.w("</table>")
	}
	if len(visibleClasses) > 0 || len(visibleNs) > 0 || len(sections) > 0 {
		p.w("\n")
	}
	// detailed description
	if fd.hasDetailedDescription(d) {
		p.w("<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
		p.w("<div class=\"textblock\">")
		h.writeDetailedDocBody(p, &fd.Doc, ctx, fd.Name, nil)
		if d.cfg.Bool("SOURCE_BROWSER") && fd.HasSource {
			p.w("\n<p class=\"definition\">Definition in file <a class=\"el\" href=\"" + fd.OutputBase + "_source" + h.ext + "\">" + htmlEscape(fd.Name) + "</a>.</p>\n")
		}
		p.w("</div>")
	}
	details := d.fileDetailSections(fd.Members, true)
	for _, ds := range details {
		p.w("<a name=\"" + ds.key + "\" id=\"" + ds.key + "\"></a><h2 id=\"header-" + ds.key + "\" class=\"groupheader\">" + ds.title + "</h2>\n")
		for _, md := range ds.members {
			h.writeMemberDocumentation(p, md, fd, "")
		}
	}
	p.endContents()
	nav := h.navPathItems([]navItem{{text: fd.Name, url: fd.OutputBase + h.ext}})
	p.writeFooter(nav)
	p.finish()
}

// ---------------------------------------------------------------------------
// Namespace documentation

func (d *Doxygen) generateNamespaceDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, ns := range d.namespaces {
		if !ns.isLinkable(d) {
			continue
		}
		if !ns.hasDocumentation(d) && d.cfg.Bool("HIDE_UNDOC_NAMESPACES") {
			continue
		}
		msg("Generating docs for namespace %s\n", ns.QualName)
		if h != nil {
			h.writeNamespacePage(ns)
		}
		if l != nil {
			l.writeNamespace(ns)
		}
	}
}

func (h *HtmlGenerator) writeNamespacePage(ns *NamespaceDef) {
	d := h.d
	title := ns.QualName + " Namespace Reference"
	p := h.newPage(ns.OutputBase, title, "")
	p.hasOutline = true
	p.writeHeader(title, "", true)
	sections := d.fileMemberSections(ns.Members, false)
	var visibleClasses []*ClassDef
	for _, cd := range ns.Classes {
		if cd.isLinkable(d) {
			if _, nested := cd.OuterScope.(*ClassDef); !nested {
				visibleClasses = append(visibleClasses, cd)
			}
		}
	}
	var visibleNs []*NamespaceDef
	for _, sub := range ns.Namespaces {
		if sub.isLinkable(d) {
			visibleNs = append(visibleNs, sub)
		}
	}
	var items []string
	if len(visibleNs) > 0 {
		items = append(items, "<a href=\"#namespaces\">Namespaces</a>")
	}
	if len(visibleClasses) > 0 {
		items = append(items, "<a href=\"#nested-classes\">Classes</a>")
	}
	for _, s := range sections {
		items = append(items, "<a href=\"#"+s.key+"\">"+s.title+"</a>")
	}
	p.w("<div class=\"header\">\n")
	if len(items) > 0 {
		p.w("<div class=\"summary\">\n")
		p.w(strings.Join(items, " &#124;\n"))
		p.w("</div>\n")
	}
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + htmlEscape(title) + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
	ctx := &DocContext{d: d, scope: ns}
	if ns.Doc.Brief != "" {
		p.w("\n<p>")
		bctx := &DocContext{d: d, scope: ns, singleLine: true, file: ns.Doc.BriefFile, line: ns.Doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, ns.Doc.Brief), bctx, ""))
		p.w(" \n")
		if d.cfg.Bool("REPEAT_BRIEF") || ns.Doc.Doc != "" {
			p.w("<a href=\"#details\">More...</a>")
		}
		p.w("</p>\n")
	}
	if len(visibleNs) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-namespaces\" class=\"groupheader\"><a id=\"namespaces\" name=\"namespaces\"></a>\nNamespaces</h2></td></tr>\n")
		for _, sub := range visibleNs {
			p.w("<tr class=\"memitem:" + sub.OutputBase + "\" id=\"r_" + sub.OutputBase + "\"><td class=\"memItemLeft\">namespace &#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + sub.OutputBase + h.ext + "\">" + htmlEscape(sub.Name) + "</a></td></tr>\n")
			if sub.Doc.Brief != "" {
				p.w("<tr class=\"memdesc:" + sub.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.briefHtml(sub.Doc.Brief, sub, sub.Name, "") + " <a href=\"" + sub.OutputBase + h.ext + "#details\">More...</a><br /></td></tr>\n")
			}
		}
		p.w("</table>")
	}
	if len(visibleClasses) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-nested-classes\" class=\"groupheader\"><a id=\"nested-classes\" name=\"nested-classes\"></a>\nClasses</h2></td></tr>\n")
		for _, cd := range visibleClasses {
			h.writeClassDeclRow(p, cd, "")
		}
		p.w("</table>")
	}
	for _, s := range sections {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-" + s.key + "\" class=\"groupheader\"><a id=\"" + s.key + "\" name=\"" + s.key + "\"></a>\n" + s.title + "</h2></td></tr>\n")
		for _, md := range s.members {
			h.writeMemberDeclaration(p, md, ns, "")
		}
		p.w("</table>")
	}
	if len(visibleClasses) > 0 || len(visibleNs) > 0 || len(sections) > 0 {
		p.w("\n")
	}
	hasDetails := (ns.Doc.Brief != "" && d.cfg.Bool("REPEAT_BRIEF")) || ns.Doc.Doc != ""
	if hasDetails {
		p.w("<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
		p.w("<div class=\"textblock\">")
		h.writeDetailedDocBody(p, &ns.Doc, ctx, ns.QualName, nil)
		p.w("</div>")
	}
	details := d.fileDetailSections(ns.Members, false)
	for _, ds := range details {
		p.w("<a name=\"" + ds.key + "\" id=\"" + ds.key + "\"></a><h2 id=\"header-" + ds.key + "\" class=\"groupheader\">" + ds.title + "</h2>\n")
		for _, md := range ds.members {
			h.writeMemberDocumentation(p, md, ns, "")
		}
	}
	p.endContents()
	var navs []navItem
	cur := ns
	for cur != nil {
		if cur.isLinkable(d) {
			navs = append([]navItem{{text: cur.Name, url: cur.OutputBase + h.ext}}, navs...)
		}
		cur = cur.Parent
	}
	p.writeFooter(h.navPathItems(navs))
	p.finish()
}

// ---------------------------------------------------------------------------
// Source browser

func (d *Doxygen) generateFileSources(h *HtmlGenerator, l *LatexGenerator) {
	sourceBrowser := d.cfg.Bool("SOURCE_BROWSER")
	verbatimHeaders := d.cfg.Bool("VERBATIM_HEADERS")
	for _, fd := range d.files {
		fd.HasSource = (sourceBrowser || (verbatimHeaders && fd.IsHeader)) && !fd.IsDocFile && fd.isLinkable(d)
		if !fd.HasSource && verbatimHeaders && fd.IsHeader && !fd.IsDocFile {
			// headers used by documented classes get a source page even when the file itself is undocumented
			for _, cd := range fd.Classes {
				if cd.isLinkable(d) {
					fd.HasSource = true
				}
			}
		}
	}
	for _, fd := range d.files {
		if !fd.HasSource {
			continue
		}
		msg("Generating code for file %s...\n", fd.displayName(d))
		if h != nil {
			h.writeSourcePage(fd)
		}
		if l != nil && d.cfg.Bool("LATEX_SOURCE_CODE_DUMMY") {
			// LaTeX source code is not generated by default
		}
	}
}

func (h *HtmlGenerator) writeSourcePage(fd *FileDef) {
	d := h.d
	title := fd.displayName(d) + " Source File"
	p := h.newPage(fd.OutputBase+"_source", title, "")
	p.writeHeader(title, "", true)
	p.startContents(htmlEscape(fd.displayName(d)))
	if fd.isLinkable(d) {
		p.w("<a href=\"" + fd.OutputBase + h.ext + "\">Go to the documentation of this file.</a>")
	}
	p.w("<div class=\"fragment\">")
	cw := &codeWriter{d: d, relPath: "", lineNr: 1, showLines: true, fd: fd, folding: d.cfg.Bool("HTML_CODE_FOLDING"), stripComments: d.cfg.Bool("STRIP_CODE_COMMENTS")}
	cw.lineAnchors = d.lineAnchorsForFile(fd)
	cw.startCodeLine()
	src := string(fd.Source)
	src = strings.ReplaceAll(src, "\r\n", "\n")
	// expand tabs
	src = expandTabs(src, d.cfg.Int("TAB_SIZE"))
	d.highlightCpp(cw, src, nil, fd)
	cw.endCodeLine()
	cw.writeTooltips()
	p.w(cw.sb.String())
	p.w("</div><!-- fragment -->")
	p.endContents()
	nav := h.navPathItems([]navItem{{text: fd.Name, url: fd.OutputBase + h.ext}})
	p.writeFooter(nav)
	p.finish()
}

func expandTabs(s string, tabSize int) string {
	if tabSize <= 0 || !strings.Contains(s, "\t") {
		return s
	}
	var sb strings.Builder
	col := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\t':
			spaces := tabSize - (col % tabSize)
			sb.WriteString(strings.Repeat(" ", spaces))
			col += spaces
		case '\n':
			sb.WriteByte(c)
			col = 0
		default:
			sb.WriteByte(c)
			if c&0xC0 != 0x80 {
				col++
			}
		}
	}
	return sb.String()
}

// lineAnchorsForFile maps source lines to the documentation of the entity defined there.
func (d *Doxygen) lineAnchorsForFile(fd *FileDef) map[int]*LinkTarget {
	m := map[int]*LinkTarget{}
	for _, cd := range d.classes {
		if cd.File == fd.File && cd.isLinkable(d) && cd.Line > 0 {
			m[cd.Line] = &LinkTarget{File: cd.OutputBase, Name: cd.QualName, Def: cd}
		}
	}
	for _, md := range d.allMembers {
		if md.Kind == MemberEnumValue {
			continue
		}
		if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) {
			continue
		}
		if md.File == fd.File && md.Line > 0 {
			if _, exists := m[md.Line]; !exists {
				m[md.Line] = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
			}
		}
		if md.DefFile == fd.File && md.BodyStart > 0 && md.DefLine > 0 {
			if _, exists := m[md.DefLine]; !exists {
				m[md.DefLine] = &LinkTarget{File: md.outputFile(d), Anchor: md.Anchor, Name: md.QualName, Def: md}
			}
		}
	}
	return m
}
