func (h *HtmlGenerator) writeMenuData() {
	d := h.d
	tree := d.buildNavTree(false)
	var sb strings.Builder
	sb.WriteString(jsLicense)
	sb.WriteString("var menudata={children:[\n")
	var writeEntries func(entries []*navEntry)
	writeEntries = func(entries []*navEntry) {
		for i, e := range entries {
			sb.WriteString("{text:\"" + convertToJSString(e.text) + "\",url:\"" + e.url + "\"")
			if len(e.children) > 0 {
				sb.WriteString(",children:[\n")
				writeEntries(e.children)
				sb.WriteString("]}")
			} else {
				sb.WriteString("}")
			}
			if i < len(entries)-1 {
				sb.WriteString(",\n")
			}
		}
	}
	writeEntries(tree)
	sb.WriteString("]}\n")
	h.writeFile("menudata.js", sb.String())
}

// ---------------------------------------------------------------------------
// navtree

func (h *HtmlGenerator) writeNavTree() {
	d := h.d
	tree := d.buildNavTree(true)
	projectName := d.cfg.Str("PROJECT_NAME")
	var sb strings.Builder
	sb.WriteString(jsLicense)
	sb.WriteString("var NAVTREE =\n[\n")
	sb.WriteString("  [ \"" + convertToJSString(projectName) + "\", \"index" + h.ext + "\", ")
	// index of urls -> path
	index := map[string][]int{}
	index["index"+h.ext] = []int{}
	index["pages"+h.ext] = []int{}
	var subFiles []struct {
		name    string
		entries []*navEntry
	}
	var writeEntries func(entries []*navEntry, indent string, path []int, lazy bool) string
	writeEntries = func(entries []*navEntry, indent string, path []int, lazy bool) string {
		var b strings.Builder
		for i, e := range entries {
			p := append(append([]int{}, path...), i)
			if _, exists := index[e.url]; !exists {
				index[e.url] = p
			}
			// the plain url of an anchor entry also maps to the parent
			b.WriteString(indent + "[ \"" + convertToJSString(e.text) + "\", \"" + e.url + "\", ")
			if len(e.children) > 0 {
				if e.jsFile != "" && lazy {
					b.WriteString("\"" + e.jsFile + "\" ]")
					subFiles = append(subFiles, struct {
						name    string
						entries []*navEntry
					}{e.jsFile, e.children})
					// register children paths
					h.registerIndexPaths(e.children, p, index)
				} else {
					b.WriteString("[\n")
					b.WriteString(writeEntries(e.children, indent+"  ", p, lazy))
					b.WriteString(indent + "] ]")
				}
			} else {
				b.WriteString("null ]")
			}
			if i < len(entries)-1 {
				b.WriteString(",\n")
			} else {
				b.WriteString("\n")
			}
		}
		return b.String()
	}
	if len(tree) > 1 {
		sb.WriteString("[\n")
		// the main page entry itself is not listed (it's the root)
		sb.WriteString(writeEntries(tree[1:], "    ", []int{}, true))
		sb.WriteString("  ] ]\n")
	} else {
		sb.WriteString("]\n")
	}
	sb.WriteString("];\n\n")
	// NAVTREEINDEX: list of first urls of each navtreeindex chunk
	urls := make([]string, 0, len(index))
	for u := range index {
		urls = append(urls, u)
	}
	sort.Strings(urls)
	const chunkSize = 250
	var chunks [][]string
	for i := 0; i < len(urls); i += chunkSize {
		end := i + chunkSize
		if end > len(urls) {
			end = len(urls)
		}
		chunks = append(chunks, urls[i:end])
	}
	sb.WriteString("var NAVTREEINDEX =\n[\n")
	for i, c := range chunks {
		sb.WriteString("\"" + c[0] + "\"")
		if i < len(chunks)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("];\n\n")
	sb.WriteString("const SYNCONMSG = 'click to disable panel synchronization';\n")
	sb.WriteString("const SYNCOFFMSG = 'click to enable panel synchronization';\n")
	sb.WriteString("const LISTOFALLMEMBERS = 'List of all members';")
	h.writeFile("navtreedata.js", sb.String())
	// chunk files
	for i, c := range chunks {
		var cb strings.Builder
		cb.WriteString("var NAVTREEINDEX" + intToStr(i) + " =\n{\n")
		for j, u := range c {
			cb.WriteString("\"" + u + "\":[")
			p := index[u]
			for k, v := range p {
				if k > 0 {
					cb.WriteString(",")
				}
				cb.WriteString(intToStr(v))
			}
			cb.WriteString("]")
			if j < len(c)-1 {
				cb.WriteString(",")
			}
			cb.WriteString("\n")
		}
		cb.WriteString("};\n")
		h.writeFile("navtreeindex"+intToStr(i)+".js", cb.String())
	}
	// sub files
	for _, sf := range subFiles {
		var fb strings.Builder
		fb.WriteString("var " + sf.name + " =\n[\n")
		for i, e := range sf.entries {
			fb.WriteString("    [ \"" + convertToJSString(e.text) + "\", \"" + e.url + "\", ")
			if len(e.children) > 0 && e.jsFile != "" {
				fb.WriteString("\"" + e.jsFile + "\" ]")
			} else if len(e.children) > 0 {
				fb.WriteString("[\n")
				fb.WriteString(writeEntries(e.children, "      ", nil, false))
				fb.WriteString("    ] ]")
			} else {
				fb.WriteString("null ]")
			}
			if i < len(sf.entries)-1 {
				fb.WriteString(",\n")
			} else {
				fb.WriteString("\n")
			}
		}
		fb.WriteString("];")
		h.writeFile(sf.name+".js", fb.String())
	}
	h.writeFile("navtree.js", resNavtreeJs)
}

func (h *HtmlGenerator) registerIndexPaths(entries []*navEntry, path []int, index map[string][]int) {
	for i, e := range entries {
		p := append(append([]int{}, path...), i)
		if _, exists := index[e.url]; !exists {
			index[e.url] = p
		}
		// source file pages map to the file entry
		if fd, ok := e.def.(*FileDef); ok && fd.HasSource {
			u := fd.OutputBase + "_source" + h.ext
			if _, exists := index[u]; !exists {
				index[u] = p
			}
		}
		if cd, ok := e.def.(*ClassDef); ok {
			_ = cd
		}
		if len(e.children) > 0 {
			h.registerIndexPaths(e.children, p, index)
		}
	}
}

// ---------------------------------------------------------------------------
// Search index (javascript based)

type searchItem struct {
	word  string // lower case key
	name  string // display name
	url   string
	scope string
}

type SearchIndex struct {
	d        *Doxygen
	sections map[string]map[string][]*searchItem // section -> word -> items
}

var searchSections = []struct {
	key   string
	label string
}{
	{"all", "All"}, {"classes", "Classes"}, {"interfaces", "Interfaces"}, {"structs", "Structs"}, {"exceptions", "Exceptions"},
	{"namespaces", "Namespaces"}, {"files", "Files"}, {"functions", "Functions"}, {"variables", "Variables"}, {"typedefs", "Typedefs"},
	{"enums", "Enumerations"}, {"enumvalues", "Enumerator"}, {"properties", "Properties"}, {"events", "Events"}, {"related", "Friends"},
	{"defines", "Macros"}, {"groups", "Topics"}, {"pages", "Pages"}, {"concepts", "Concepts"},
}

func newSearchIndex(d *Doxygen) *SearchIndex {
	return &SearchIndex{d: d, sections: map[string]map[string][]*searchItem{}}
}

func (s *SearchIndex) add(section string, name string, url string, scope string) {
	key := strings.ToLower(name)
	for _, sec := range []string{"all", section} {
		if s.sections[sec] == nil {
			s.sections[sec] = map[string][]*searchItem{}
		}
		s.sections[sec][key] = append(s.sections[sec][key], &searchItem{word: key, name: name, url: url, scope: scope})
	}
}

func (s *SearchIndex) build() {
	d := s.d
	ext := d.htmlExt()
	for _, cd := range d.classes {
		if !cd.isLinkable(d) {
			continue
		}
		sec := "classes"
		switch cd.CompoundType {
		case "struct":
			sec = "classes"
		case "interface":
			sec = "classes"
		}
		s.add(sec, cd.Name, cd.OutputBase+ext, scopePart(cd.QualName))
		for _, md := range cd.Members {
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, cd.QualName)
		}
	}
	for _, ns := range d.namespaces {
		if !ns.isLinkable(d) {
			continue
		}
		s.add("namespaces", ns.Name, ns.OutputBase+ext, scopePart(ns.QualName))
		for _, md := range ns.Members {
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, ns.QualName)
		}
	}
	for _, fd := range d.files {
		if !fd.isLinkable(d) {
			continue
		}
		s.add("files", fd.Name, fd.OutputBase+ext, "")
		for _, md := range fd.Members {
			if md.Namespace != nil && md.Namespace.isLinkable(d) {
				continue
			}
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, fd.Name)
		}
	}
	for _, pg := range d.pages {
		s.add("pages", pg.displayTitle(), pg.OutputBase+ext, "")
	}
	for _, g := range d.groups {
		s.add("groups", g.Title, g.OutputBase+ext, "")
	}
}

func (s *SearchIndex) addMember(md *MemberDef, scope string) {
	d := s.d
	ext := d.htmlExt()
	url := md.outputFile(d) + ext + "#" + md.Anchor
	sec := ""
	switch md.Kind {
	case MemberFunction, MemberSignal, MemberSlot:
		sec = "functions"
	case MemberVariable:
		sec = "variables"
	case MemberTypedef:
		sec = "typedefs"
	case MemberEnum:
		sec = "enums"
	case MemberEnumValue:
		sec = "enumvalues"
	case MemberDefine:
		sec = "defines"
	case MemberProperty:
		sec = "properties"
	case MemberEvent:
		sec = "events"
	case MemberFriend:
		sec = "related"
	default:
		sec = "functions"
	}
	s.add(sec, md.Name, url, scope)
	if md.Kind == MemberEnum {
		for _, ev := range md.EnumValues {
			s.add("enumvalues", ev.Name, md.outputFile(d)+ext+"#"+ev.Anchor, scope)
		}
	}
}

func searchId(word string) string {
	var sb strings.Builder
	for i := 0; i < len(word); i++ {
		c := word[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			sb.WriteByte(c)
		} else {
			sb.WriteString("_" + strings.ToLower(hexByte(c)))
		}
	}
	return sb.String()
}

func (s *SearchIndex) write(h *HtmlGenerator) {
	s.build()
	// which sections have content, and their letters
	var sb strings.Builder
	sb.WriteString("var indexSectionsWithContent =\n{\n")
	idx := 0
	type secInfo struct {
		key     string
		label   string
		letters []string
	}
	var infos []secInfo
	for _, sec := range searchSections {
		m := s.sections[sec.key]
		if len(m) == 0 {
			continue
		}
		letterSet := map[string]bool{}
		for w := range m {
			letterSet[firstSearchLetter(w)] = true
		}
		var letters []string
		for l := range letterSet {
			letters = append(letters, l)
		}
		sort.Strings(letters)
		infos = append(infos, secInfo{sec.key, sec.label, letters})
	}
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + strings.Join(inf.letters, "") + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
		idx++
	}
	sb.WriteString("};\n\n")
	sb.WriteString("var indexSectionNames =\n{\n")
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + inf.key + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("};\n\n")
	sb.WriteString("var indexSectionLabels =\n{\n")
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + inf.label + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("};\n\n")
	h.writeFile("search/searchdata.js", sb.String())
	// per section/letter files
	for _, inf := range infos {
		m := s.sections[inf.key]
		for li, letter := range inf.letters {
			var words []string
			for w := range m {
				if firstSearchLetter(w) == letter {
					words = append(words, w)
				}
			}
			sort.Strings(words)
			var fb strings.Builder
			fb.WriteString("var searchData=\n[\n")
			for wi, w := range words {
				items := m[w]
				fb.WriteString("  ['" + searchId(w) + "_" + intToStr(wi) + "',['" + jsEscapeSingle(items[0].name) + "',")
				if len(items) == 1 {
					it := items[0]
					fb.WriteString("['../" + it.url + "',1,'" + jsEscapeSingle(it.scope) + "']")
				} else {
					fb.WriteString("[")
					for k, it := range items {
						if k > 0 {
							fb.WriteString(",")
						}
						fb.WriteString("['../" + it.url + "',1,'" + jsEscapeSingle(it.scope) + "']")
					}
					fb.WriteString("]")
				}
				fb.WriteString("]]")
				if wi < len(words)-1 {
					fb.WriteString(",")
				}
				fb.WriteString("\n")
			}
			fb.WriteString("];\n")
			h.writeFile("search/"+inf.key+"_"+intToStr(li)+".js", fb.String())
		}
	}
}

func firstSearchLetter(w string) string {
	if w == "" {
		return ""
	}
	c := w[0]
	if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
		return string(c)
	}
	if c >= 0x80 {
		i := 1
		for i < len(w) && w[i]&0xC0 == 0x80 {
			i++
		}
		return w[:i]
	}
	return string(c)
}

func jsEscapeSingle(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "'", "\\'")
	return s
}
