package main

import (
	"sort"
	"strings"
)

// IndexList is a placeholder for index bookkeeping.
type IndexList struct{}

func newIndexList(d *Doxygen) *IndexList { return &IndexList{} }

// navEntry is a node in the navigation tree / menu.
type navEntry struct {
	text     string
	url      string
	children []*navEntry
	jsFile   string // for lazily loaded children in the navtree
	anchor   bool
	def      interface{}
}

type menuEntry struct {
	text string
	url  string
}

func (d *Doxygen) menuEntries() []menuEntry {
	var out []menuEntry
	for _, e := range d.buildNavTree(false) {
		out = append(out, menuEntry{e.text, e.url})
	}
	return out
}

// buildNavTree builds the top-level navigation structure (layout: navindex).
func (d *Doxygen) buildNavTree(forTree bool) []*navEntry {
	ext := d.htmlExt()
	var root []*navEntry
	// main page
	mainTitle := "Main Page"
	if d.mainPage != nil && d.mainPage.Title != "" {
		mainTitle = d.mainPage.Title
	}
	root = append(root, &navEntry{text: mainTitle, url: "index" + ext, def: d.mainPage})
	// related pages
	var pages []*PageDef
	for _, pg := range d.pages {
		if pg.Parent == nil {
			pages = append(pages, pg)
		}
	}
	if len(pages) > 0 {
		pe := &navEntry{text: "Related Pages", url: "pages" + ext}
		if forTree {
			for _, pg := range pages {
				pe.children = append(pe.children, &navEntry{text: pg.displayTitle(), url: pg.OutputBase + ext, def: pg})
			}
		}
		root = append(root, pe)
	}
	// topics
	if len(d.groups) > 0 {
		te := &navEntry{text: "Topics", url: "topics" + ext}
		if forTree {
			for _, g := range d.groups {
				te.children = append(te.children, &navEntry{text: g.Title, url: g.OutputBase + ext, def: g})
			}
		}
		root = append(root, te)
	}
	// namespaces
	nss := d.documentedNamespaces()
	if len(nss) > 0 && d.cfg.Bool("SHOW_NAMESPACES") {
		ne := &navEntry{text: "Namespaces", url: "namespaces" + ext}
		nl := &navEntry{text: "Namespace List", url: "namespaces" + ext}
		if forTree {
			nl.jsFile = "namespaces_dup"
			for _, ns := range nss {
				if ns.Parent == nil {
					nl.children = append(nl.children, d.nsTreeEntry(ns))
				}
			}
		}
		ne.children = append(ne.children, nl)
		members := d.namespaceMembersForIndex()
		if len(members["all"]) > 0 {
			me := &navEntry{text: "Namespace Members", url: "namespacemembers" + ext}
			for _, cat := range nsMemberCats {
				if len(members[cat.key]) > 0 {
					me.children = append(me.children, &navEntry{text: cat.title, url: "namespacemembers" + cat.label + ext})
				}
			}
			ne.children = append(ne.children, me)
		}
		root = append(root, ne)
	}
	// classes
	classes := d.annotatedClasses()
	if len(classes) > 0 {
		ce := &navEntry{text: "Classes", url: "annotated" + ext}
		cl := &navEntry{text: "Class List", url: "annotated" + ext}
		if forTree {
			cl.jsFile = "annotated_dup"
			cl.children = d.classTreeEntries(classes)
		}
		ce.children = append(ce.children, cl)
		if d.cfg.Bool("ALPHABETICAL_INDEX") {
			ce.children = append(ce.children, &navEntry{text: "Class Index", url: "classes" + ext})
		}
		if d.hierarchyClasses() > 0 {
			he := &navEntry{text: "Class Hierarchy", url: "hierarchy" + ext}
			ce.children = append(ce.children, he)
		}
		members := d.classMembersForIndex()
		if len(members["all"]) > 0 {
			me := &navEntry{text: "Class Members", url: "functions" + ext}
			for _, cat := range classMemberCats {
				if len(members[cat.key]) > 0 {
					me.children = append(me.children, &navEntry{text: cat.title, url: "functions" + cat.label + ext})
				}
			}
			ce.children = append(ce.children, me)
		}
		root = append(root, ce)
	}
	// files
	files := d.documentedFiles()
	if len(files) > 0 && d.cfg.Bool("SHOW_FILES") {
		fe := &navEntry{text: "Files", url: "files" + ext}
		fl := &navEntry{text: "File List", url: "files" + ext}
		if forTree {
			fl.jsFile = "files_dup"
			fl.children = d.fileTreeEntries(files)
		}
		fe.children = append(fe.children, fl)
		members := d.fileMembersForIndex()
		if len(members["all"]) > 0 {
			me := &navEntry{text: "File Members", url: "globals" + ext}
			for _, cat := range fileMemberCats {
				if len(members[cat.key]) > 0 {
					me.children = append(me.children, &navEntry{text: cat.title, url: "globals" + cat.label + ext})
				}
			}
			fe.children = append(fe.children, me)
		}
		root = append(root, fe)
	}
	return root
}

func (d *Doxygen) nsTreeEntry(ns *NamespaceDef) *navEntry {
	ext := d.htmlExt()
	e := &navEntry{text: ns.Name, url: ns.OutputBase + ext, def: ns}
	for _, sub := range ns.Namespaces {
		if sub.isLinkable(d) {
			e.children = append(e.children, d.nsTreeEntry(sub))
		}
	}
	for _, cd := range ns.Classes {
		if cd.isLinkable(d) {
			if _, nested := cd.OuterScope.(*ClassDef); !nested {
				e.children = append(e.children, d.classTreeEntry(cd))
			}
		}
	}
	for _, md := range ns.Members {
		if md.isLinkable(d) && md.isDetailedSectionLinkable(d) && md.isBriefSectionVisible(d) {
			e.children = append(e.children, &navEntry{text: md.Name, url: md.outputFile(d) + ext + "#" + md.Anchor, anchor: true, def: md})
		}
	}
	if len(e.children) > 0 {
		e.jsFile = ns.OutputBase
	}
	return e
}

func (d *Doxygen) classTreeEntry(cd *ClassDef) *navEntry {
	ext := d.htmlExt()
	e := &navEntry{text: cd.Name, url: cd.OutputBase + ext, def: cd}
	for _, inner := range cd.Inner {
		if inner.isLinkable(d) {
			e.children = append(e.children, d.classTreeEntry(inner))
		}
	}
	for _, md := range cd.Members {
		if md.isLinkable(d) && md.isDetailedSectionLinkable(d) && md.isBriefSectionVisible(d) {
			e.children = append(e.children, &navEntry{text: md.Name, url: md.outputFile(d) + ext + "#" + md.Anchor, anchor: true, def: md})
		}
	}
	if len(e.children) > 0 {
		e.jsFile = cd.OutputBase
	}
	return e
}

func (d *Doxygen) classTreeEntries(classes []*ClassDef) []*navEntry {
	var out []*navEntry
	for _, ns := range d.namespaces {
		if ns.Parent == nil && ns.isLinkable(d) && d.nsHasVisibleClasses(ns) {
			out = append(out, d.nsTreeEntry(ns))
		}
	}
	for _, cd := range classes {
		if _, nested := cd.OuterScope.(*ClassDef); nested {
			continue
		}
		if cd.Namespace != nil && cd.Namespace.isLinkable(d) {
			continue
		}
		out = append(out, d.classTreeEntry(cd))
	}
	return out
}

func (d *Doxygen) fileTreeEntry(fd *FileDef) *navEntry {
	ext := d.htmlExt()
	e := &navEntry{text: fd.Name, url: fd.OutputBase + ext, def: fd}
	for _, cd := range fd.Classes {
		if cd.isLinkable(d) {
			e.children = append(e.children, d.classTreeEntry(cd))
		}
	}
	for _, md := range fd.Members {
		if md.Namespace != nil && md.Namespace.isLinkable(d) {
			continue
		}
		if md.isLinkable(d) && md.isDetailedSectionLinkable(d) && md.isBriefSectionVisible(d) {
			e.children = append(e.children, &navEntry{text: md.Name, url: md.outputFile(d) + ext + "#" + md.Anchor, anchor: true, def: md})
		}
	}
	if len(e.children) > 0 {
		e.jsFile = fd.OutputBase
	}
	return e
}

func (d *Doxygen) fileTreeEntries(files []*FileDef) []*navEntry {
	// group by directory (relative to strip path)
	type dirNode struct {
		name  string
		path  string
		files []*FileDef
		subs  []*dirNode
	}
	root := &dirNode{}
	fullPath := d.cfg.Bool("FULL_PATH_NAMES")
	for _, fd := range files {
		rel := fd.Name
		if fullPath {
			rel = d.stripFromPath(fd.File)
		}
		parts := strings.Split(rel, "/")
		cur := root
		for _, part := range parts[:len(parts)-1] {
			var found *dirNode
			for _, s := range cur.subs {
				if s.name == part {
					found = s
				}
			}
			if found == nil {
				found = &dirNode{name: part, path: strings.TrimPrefix(cur.path+"/"+part, "/")}
				cur.subs = append(cur.subs, found)
			}
			cur = found
		}
		cur.files = append(cur.files, fd)
	}
	ext := d.htmlExt()
	var conv func(n *dirNode) []*navEntry
	conv = func(n *dirNode) []*navEntry {
		var out []*navEntry
		for _, s := range n.subs {
			de := &navEntry{text: s.name, url: "dir_" + md5Hex(s.path)[:32] + ext}
			de.children = conv(s)
			de.jsFile = "dir_" + md5Hex(s.path)[:32]
			out = append(out, de)
		}
		for _, fd := range n.files {
			out = append(out, d.fileTreeEntry(fd))
		}
		return out
	}
	return conv(root)
}

