func (h *HtmlGenerator) writeNavTree() {
	d := h.d
	tree := d.buildNavTree(true)
	projectName := d.cfg.Str("PROJECT_NAME")
	var sb strings.Builder
	sb.WriteString(jsLicense)
	sb.WriteString("var NAVTREE =\n[\n")
	sb.WriteString("  [ \"" + convertToJSString(projectName) + "\", \"index" + h.ext + "\", ")
	// index of urls -> path
	index := map[string][]int{}
	index["index"+h.ext] = []int{}
	index["pages"+h.ext] = []int{}
	var subFiles []struct {
		name    string
		entries []*navEntry
	}
	var writeEntries func(entries []*navEntry, indent string, path []int, lazy bool) string
	writeEntries = func(entries []*navEntry, indent string, path []int, lazy bool) string {
		var b strings.Builder
		for i, e := range entries {
			p := append(append([]int{}, path...), i)
			if _, exists := index[e.url]; !exists {
				index[e.url] = p
			}
			// the plain url of an anchor entry also maps to the parent
			b.WriteString(indent + "[ \"" + convertToJSString(e.text) + "\", \"" + e.url + "\", ")
			if len(e.children) > 0 {
				if e.jsFile != "" && lazy {
					b.WriteString("\"" + e.jsFile + "\" ]")
					subFiles = append(subFiles, struct {
						name    string
						entries []*navEntry
					}{e.jsFile, e.children})
					// register children paths
					h.registerIndexPaths(e.children, p, index)
				} else {
					b.WriteString("[\n")
					b.WriteString(writeEntries(e.children, indent+"  ", p, lazy))
					b.WriteString(indent + "] ]")
				}
			} else {
				b.WriteString("null ]")
			}
			if i < len(entries)-1 {
				b.WriteString(",\n")
			} else {
				b.WriteString("\n")
			}
		}
		return b.String()
	}
	if len(tree) > 1 {
		sb.WriteString("[\n")
		// the main page entry itself is not listed (it's the root)
		sb.WriteString(writeEntries(tree[1:], "    ", []int{}, true))
		sb.WriteString("  ] ]\n")
	} else {
		sb.WriteString("]\n")
	}
	sb.WriteString("];\n\n")
	// NAVTREEINDEX: list of first urls of each navtreeindex chunk
	urls := make([]string, 0, len(index))
	for u := range index {
		urls = append(urls, u)
	}
	sort.Strings(urls)
	const chunkSize = 250
	var chunks [][]string
	for i := 0; i < len(urls); i += chunkSize {
		end := i + chunkSize
		if end > len(urls) {
			end = len(urls)
		}
		chunks = append(chunks, urls[i:end])
	}
	sb.WriteString("var NAVTREEINDEX =\n[\n")
	for i, c := range chunks {
		sb.WriteString("\"" + c[0] + "\"")
		if i < len(chunks)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("];\n\n")
	sb.WriteString("const SYNCONMSG = 'click to disable panel synchronization';\n")
	sb.WriteString("const SYNCOFFMSG = 'click to enable panel synchronization';\n")
	sb.WriteString("const LISTOFALLMEMBERS = 'List of all members';")
	h.writeFile("navtreedata.js", sb.String())
	// chunk files
	for i, c := range chunks {
		var cb strings.Builder
		cb.WriteString("var NAVTREEINDEX" + intToStr(i) + " =\n{\n")
		for j, u := range c {
			cb.WriteString("\"" + u + "\":[")
			p := index[u]
			for k, v := range p {
				if k > 0 {
					cb.WriteString(",")
				}
				cb.WriteString(intToStr(v))
			}
			cb.WriteString("]")
			if j < len(c)-1 {
				cb.WriteString(",")
			}
			cb.WriteString("\n")
		}
		cb.WriteString("};\n")
		h.writeFile("navtreeindex"+intToStr(i)+".js", cb.String())
	}
	// sub files
	for _, sf := range subFiles {
		var fb strings.Builder
		fb.WriteString("var " + sf.name + " =\n[\n")
		for i, e := range sf.entries {
			fb.WriteString("    [ \"" + convertToJSString(e.text) + "\", \"" + e.url + "\", ")
			if len(e.children) > 0 && e.jsFile != "" {
				fb.WriteString("\"" + e.jsFile + "\" ]")
			} else if len(e.children) > 0 {
				fb.WriteString("[\n")
				fb.WriteString(writeEntries(e.children, "      ", nil, false))
				fb.WriteString("    ] ]")
			} else {
				fb.WriteString("null ]")
			}
			if i < len(sf.entries)-1 {
				fb.WriteString(",\n")
			} else {
				fb.WriteString("\n")
			}
		}
		fb.WriteString("];")
		h.writeFile(sf.name+".js", fb.String())
	}
	h.writeFile("navtree.js", resNavtreeJs)
}

func (h *HtmlGenerator) registerIndexPaths(entries []*navEntry, path []int, index map[string][]int) {
	for i, e := range entries {
		p := append(append([]int{}, path...), i)
		if _, exists := index[e.url]; !exists {
			index[e.url] = p
		}
		// source file pages map to the file entry
		if fd, ok := e.def.(*FileDef); ok && fd.HasSource {
			u := fd.OutputBase + "_source" + h.ext
			if _, exists := index[u]; !exists {
				index[u] = p
			}
		}
		if cd, ok := e.def.(*ClassDef); ok {
			_ = cd
		}
		if len(e.children) > 0 {
			h.registerIndexPaths(e.children, p, index)
		}
	}
}

