// Search index (javascript based)

type searchItem struct {
	word  string // lower case key
	name  string // display name
	url   string
	scope string
}

type SearchIndex struct {
	d        *Doxygen
	sections map[string]map[string][]*searchItem // section -> word -> items
}

var searchSections = []struct {
	key   string
	label string
}{
	{"all", "All"}, {"classes", "Classes"}, {"interfaces", "Interfaces"}, {"structs", "Structs"}, {"exceptions", "Exceptions"},
	{"namespaces", "Namespaces"}, {"files", "Files"}, {"functions", "Functions"}, {"variables", "Variables"}, {"typedefs", "Typedefs"},
	{"enums", "Enumerations"}, {"enumvalues", "Enumerator"}, {"properties", "Properties"}, {"events", "Events"}, {"related", "Friends"},
	{"defines", "Macros"}, {"groups", "Topics"}, {"pages", "Pages"}, {"concepts", "Concepts"},
}

func newSearchIndex(d *Doxygen) *SearchIndex {
	return &SearchIndex{d: d, sections: map[string]map[string][]*searchItem{}}
}

func (s *SearchIndex) add(section string, name string, url string, scope string) {
	key := strings.ToLower(name)
	for _, sec := range []string{"all", section} {
		if s.sections[sec] == nil {
			s.sections[sec] = map[string][]*searchItem{}
		}
		s.sections[sec][key] = append(s.sections[sec][key], &searchItem{word: key, name: name, url: url, scope: scope})
	}
}

func (s *SearchIndex) build() {
	d := s.d
	ext := d.htmlExt()
	for _, cd := range d.classes {
		if !cd.isLinkable(d) {
			continue
		}
		sec := "classes"
		switch cd.CompoundType {
		case "struct":
			sec = "classes"
		case "interface":
			sec = "classes"
		}
		s.add(sec, cd.Name, cd.OutputBase+ext, scopePart(cd.QualName))
		for _, md := range cd.Members {
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, cd.QualName)
		}
	}
	for _, ns := range d.namespaces {
		if !ns.isLinkable(d) {
			continue
		}
		s.add("namespaces", ns.Name, ns.OutputBase+ext, scopePart(ns.QualName))
		for _, md := range ns.Members {
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, ns.QualName)
		}
	}
	for _, fd := range d.files {
		if !fd.isLinkable(d) {
			continue
		}
		s.add("files", fd.Name, fd.OutputBase+ext, "")
		for _, md := range fd.Members {
			if md.Namespace != nil && md.Namespace.isLinkable(d) {
				continue
			}
			if !md.isLinkable(d) || !md.isDetailedSectionLinkable(d) || !md.isBriefSectionVisible(d) {
				continue
			}
			s.addMember(md, fd.Name)
		}
	}
	for _, pg := range d.pages {
		s.add("pages", pg.displayTitle(), pg.OutputBase+ext, "")
	}
	for _, g := range d.groups {
		s.add("groups", g.Title, g.OutputBase+ext, "")
	}
}

func (s *SearchIndex) addMember(md *MemberDef, scope string) {
	d := s.d
	ext := d.htmlExt()
	url := md.outputFile(d) + ext + "#" + md.Anchor
	sec := ""
	switch md.Kind {
	case MemberFunction, MemberSignal, MemberSlot:
		sec = "functions"
	case MemberVariable:
		sec = "variables"
	case MemberTypedef:
		sec = "typedefs"
	case MemberEnum:
		sec = "enums"
	case MemberEnumValue:
		sec = "enumvalues"
	case MemberDefine:
		sec = "defines"
	case MemberProperty:
		sec = "properties"
	case MemberEvent:
		sec = "events"
	case MemberFriend:
		sec = "related"
	default:
		sec = "functions"
	}
	s.add(sec, md.Name, url, scope)
	if md.Kind == MemberEnum {
		for _, ev := range md.EnumValues {
			s.add("enumvalues", ev.Name, md.outputFile(d)+ext+"#"+ev.Anchor, scope)
		}
	}
}

func searchId(word string) string {
	var sb strings.Builder
	for i := 0; i < len(word); i++ {
		c := word[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			sb.WriteByte(c)
		} else {
			sb.WriteString("_" + strings.ToLower(hexByte(c)))
		}
	}
	return sb.String()
}

func (s *SearchIndex) write(h *HtmlGenerator) {
	s.build()
	// which sections have content, and their letters
	var sb strings.Builder
	sb.WriteString("var indexSectionsWithContent =\n{\n")
	idx := 0
	type secInfo struct {
		key     string
		label   string
		letters []string
	}
	var infos []secInfo
	for _, sec := range searchSections {
		m := s.sections[sec.key]
		if len(m) == 0 {
			continue
		}
		letterSet := map[string]bool{}
		for w := range m {
			letterSet[firstSearchLetter(w)] = true
		}
		var letters []string
		for l := range letterSet {
			letters = append(letters, l)
		}
		sort.Strings(letters)
		infos = append(infos, secInfo{sec.key, sec.label, letters})
	}
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + strings.Join(inf.letters, "") + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
		idx++
	}
	sb.WriteString("};\n\n")
	sb.WriteString("var indexSectionNames =\n{\n")
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + inf.key + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("};\n\n")
	sb.WriteString("var indexSectionLabels =\n{\n")
	for i, inf := range infos {
		sb.WriteString("  " + intToStr(i) + ": \"" + inf.label + "\"")
		if i < len(infos)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("};\n\n")
	h.writeFile("search/searchdata.js", sb.String())
	// per section/letter files
	for _, inf := range infos {
		m := s.sections[inf.key]
		for li, letter := range inf.letters {
			var words []string
			for w := range m {
				if firstSearchLetter(w) == letter {
					words = append(words, w)
				}
			}
			sort.Strings(words)
			var fb strings.Builder
			fb.WriteString("var searchData=\n[\n")
			for wi, w := range words {
				items := m[w]
				fb.WriteString("  ['" + searchId(w) + "_" + intToStr(wi) + "',['" + jsEscapeSingle(items[0].name) + "',")
				if len(items) == 1 {
					it := items[0]
					fb.WriteString("['../" + it.url + "',1,'" + jsEscapeSingle(it.scope) + "']")
				} else {
					fb.WriteString("[")
					for k, it := range items {
						if k > 0 {
							fb.WriteString(",")
						}
						fb.WriteString("['../" + it.url + "',1,'" + jsEscapeSingle(it.scope) + "']")
					}
					fb.WriteString("]")
				}
				fb.WriteString("]]")
				if wi < len(words)-1 {
					fb.WriteString(",")
				}
				fb.WriteString("\n")
			}
			fb.WriteString("];\n")
			h.writeFile("search/"+inf.key+"_"+intToStr(li)+".js", fb.String())
		}
	}
}

func firstSearchLetter(w string) string {
	if w == "" {
		return ""
	}
	c := w[0]
	if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
		return string(c)
	}
	if c >= 0x80 {
		i := 1
		for i < len(w) && w[i]&0xC0 == 0x80 {
			i++
		}
		return w[:i]
	}
	return string(c)
}

func jsEscapeSingle(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "'", "\\'")
	return s
}
