cd /workspace/src && cat > latexgen.go <<'EOF'
package main

import (
	"os"
	"path/filepath"
	"strings"
)

// LatexGenerator produces the LaTeX output.
type LatexGenerator struct {
	d      *Doxygen
	dir    string
	chapters []latexChapter
}

type latexChapter struct {
	title string
	files []string
}

func newLatexGenerator(d *Doxygen) *LatexGenerator {
	return &LatexGenerator{d: d, dir: d.latexDir}
}

func (l *LatexGenerator) init() {
	l.writeMakefile()
}

func (l *LatexGenerator) writeFile(name string, content string) {
	path := filepath.Join(l.dir, name)
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		termMsg("Could not open file %s for writing\n", path)
	}
}

func (l *LatexGenerator) writeStyleSheets() {
	sty := resDoxygenSty
	// the run version does not have the "% stylesheet for doxygen" comment line
	if strings.HasPrefix(sty, "% stylesheet for doxygen") {
		if i := strings.Index(sty, "\n"); i >= 0 {
			sty = sty[i+1:]
		}
	}
	l.writeFile("doxygen.sty", sty)
	l.writeFile("etoc_doxygen.sty", resEtocDoxygenSty)
	for _, f := range l.d.cfg.List("LATEX_EXTRA_STYLESHEET") {
		if data, err := os.ReadFile(f); err == nil {
			l.writeFile(filepath.Base(f), string(data))
		}
	}
	for _, f := range l.d.cfg.List("LATEX_EXTRA_FILES") {
		if data, err := os.ReadFile(f); err == nil {
			l.writeFile(filepath.Base(f), string(data))
		}
	}
}

func (l *LatexGenerator) writeMakefile() {
	cfg := l.d.cfg
	var sb strings.Builder
	latexCmd := cfg.Str("LATEX_CMD_NAME")
	if latexCmd == "" {
		latexCmd = "latex"
	}
	usePdfLatex := cfg.Bool("USE_PDFLATEX")
	if usePdfLatex && latexCmd == "latex" {
		latexCmd = "pdflatex"
	}
	mkidx := cfg.Str("MAKEINDEX_CMD_NAME")
	if mkidx == "" {
		mkidx = "makeindex"
	}
	batch := cfg.Enum("LATEX_BATCHMODE")
	mode := ""
	switch batch {
	case "YES", "BATCH":
		mode = " -interaction=batchmode"
	case "NON_STOP":
		mode = " -interaction=nonstopmode"
	case "SCROLL":
		mode = " -interaction=scrollmode"
	case "ERROR_STOP":
		mode = " -interaction=errorstopmode"
	}
	_ = mode
	sb.WriteString("LATEX_CMD?=" + latexCmd + "\n")
	sb.WriteString("MKIDX_CMD?=" + mkidx + "\n")
	sb.WriteString("BIBTEX_CMD?=bibtex\n")
	sb.WriteString("LATEX_COUNT?=8\n")
	sb.WriteString("MANUAL_FILE?=refman\n")
	sb.WriteString("\n")
	if usePdfLatex {
		sb.WriteString("all: $(MANUAL_FILE).pdf\n\n")
		sb.WriteString("pdf: $(MANUAL_FILE).pdf\n\n")
		sb.WriteString("$(MANUAL_FILE).pdf: clean $(MANUAL_FILE).tex\n")
	} else {
		sb.WriteString("all: $(MANUAL_FILE).dvi\n\n")
		sb.WriteString("ps: $(MANUAL_FILE).ps\n\n")
		sb.WriteString("pdf: $(MANUAL_FILE).pdf\n\n")
		sb.WriteString("ps_2on1: $(MANUAL_FILE).ps\n\tpsnup -2 $(MANUAL_FILE).ps >$(MANUAL_FILE)_2on1.ps\n\n")
		sb.WriteString("pdf_2on1: $(MANUAL_FILE).pdf\n\tps2pdf $(MANUAL_FILE)_2on1.ps $(MANUAL_FILE)_2on1.pdf\n\n")
		sb.WriteString("$(MANUAL_FILE).ps: $(MANUAL_FILE).dvi\n\tdvips -o $(MANUAL_FILE).ps $(MANUAL_FILE).dvi\n\n")
		sb.WriteString("$(MANUAL_FILE).pdf: $(MANUAL_FILE).ps\n\tps2pdf $(MANUAL_FILE).ps $(MANUAL_FILE).pdf\n\n")
		sb.WriteString("$(MANUAL_FILE).dvi: clean $(MANUAL_FILE).tex doxygen.sty\n")
	}
	latexRun := "\t$(LATEX_CMD) $(MANUAL_FILE) || \\\n\tif [ $$? != 0 ] ; then \\\n\t        \\echo \"Please consult $(MANUAL_FILE).log to see the error messages\" ; \\\n\t        false; \\\n\tfi\n"
	sb.WriteString(latexRun)
	sb.WriteString("\t$(MKIDX_CMD) $(MANUAL_FILE).idx\n")
	if len(cfg.List("CITE_BIB_FILES")) > 0 {
		sb.WriteString("\t$(BIBTEX_CMD) $(MANUAL_FILE)\n")
	}
	sb.WriteString(latexRun)
	sb.WriteString("\tlatex_count=$(LATEX_COUNT) ; \\\n")
	sb.WriteString("\twhile grep -E -s 'Rerun (LaTeX|to get cross-references right|to get bibliographical references right)' $(MANUAL_FILE).log && [ $$latex_count -gt 0 ] ;\\\n")
	sb.WriteString("\t    do \\\n")
	sb.WriteString("\t      echo \"Rerunning latex....\" ;\\\n")
	sb.WriteString("\t      $(LATEX_CMD) $(MANUAL_FILE) || \\\n")
	sb.WriteString("\t      if [ $$? != 0 ] ; then \\\n")
	sb.WriteString("\t              \\echo \"Please consult $(MANUAL_FILE).log to see the error messages\" ; \\\n")
	sb.WriteString("\t              false; \\\n")
	sb.WriteString("\t      fi; \\\n")
	sb.WriteString("\t      latex_count=`expr $$latex_count - 1` ;\\\n")
	sb.WriteString("\t    done\n")
	sb.WriteString("\t$(MKIDX_CMD) $(MANUAL_FILE).idx\n")
	sb.WriteString(latexRun)
	sb.WriteString("\n")
	sb.WriteString("clean:\n")
	sb.WriteString("\trm -f *.ps *.dvi *.aux *.toc *.idx *.ind *.ilg *.log *.out *.brf *.blg *.bbl $(MANUAL_FILE).pdf\n")
	l.writeFile("Makefile", sb.String())
}

// substituteLatexKeywords processes the header/footer templates.
func (l *LatexGenerator) substituteLatexKeywords(tmpl string, title string) string {
	cfg := l.d.cfg
	compactLatex := cfg.Bool("COMPACT_LATEX")
	pdfHyperlinks := cfg.Bool("PDF_HYPERLINKS")
	usePdfLatex := cfg.Bool("USE_PDFLATEX")
	paperType := cfg.Enum("PAPER_TYPE")
	conds := map[string]bool{
		"COMPACT_LATEX":     compactLatex,
		"PDF_HYPERLINKS":    pdfHyperlinks,
		"USE_PDFLATEX":      usePdfLatex,
		"LATEX_FONTENC":     cfg.Str("LATEX_FONTENC") != "",
		"PROJECT_NUMBER":    cfg.Str("PROJECT_NUMBER") != "",
		"TIMESTAMP":         cfg.Enum("TIMESTAMP") != "NO",
		"CITATIONS_PRESENT": false,
		"FORMULA_MACROFILE": cfg.Str("FORMULA_MACROFILE") != "",
		"LATEX_BATCHMODE":   cfg.Enum("LATEX_BATCHMODE") != "NO",
	}
	s := substituteLatexBlocks(tmpl, conds)
	batch := ""
	switch cfg.Enum("LATEX_BATCHMODE") {
	case "YES", "BATCH":
		batch = "\\batchmode"
	case "NON_STOP":
		batch = "\\nonstopmode"
	case "SCROLL":
		batch = "\\scrollmode"
	case "ERROR_STOP":
		batch = "\\errorstopmode"
	}
	fontenc := cfg.Str("LATEX_FONTENC")
	if fontenc == "" {
		fontenc = "T1"
	}
	font := cfg.Str("LATEX_FONT")
	latexFont := "  \\usepackage[scaled=.90]{helvet}\n\\usepackage{courier}\n\\renewcommand{\\familydefault}{\\sfdefault}"
	_ = font
	emojiDir := cfg.Str("LATEX_EMOJI_DIRECTORY")
	if emojiDir == "" {
		emojiDir = "."
	}
	extraPackages := ""
	for _, p := range cfg.List("EXTRA_PACKAGES") {
		if p != "" {
			if strings.HasPrefix(p, "[") {
				extraPackages += "\\usepackage" + p + "\n"
			} else {
				extraPackages += "\\usepackage{" + p + "}\n"
			}
		}
	}
	extraStyle := ""
	for _, f := range cfg.List("LATEX_EXTRA_STYLESHEET") {
		if f != "" {
			name := filepath.Base(f)
			name = strings.TrimSuffix(name, ".sty")
			extraStyle += "\\usepackage{" + name + "}\n"
		}
	}
	specialChars := "  \\ifPDFTeX\n\\usepackage{newunicodechar}\n  \\makeatletter\n    \\def\\doxynewunicodechar#1#2{%\n    \\@tempswafalse\n    \\edef\\nuc@tempa{\\detokenize{#1}}%\n    \\if\\relax\\nuc@tempa\\relax\n      \\nuc@emptyargerr\n    \\else\n      \\edef\\@tempb{\\expandafter\\@car\\nuc@tempa\\@nil}%\n      \\nuc@check\n      \\if@tempswa\n        \\@namedef{u8:\\nuc@tempa}{#2}%\n      \\fi\n    \\fi\n  }\n  \\makeatother\n  \\doxynewunicodechar{⁻}{${}^{-}$}% Superscript minus\n  \\doxynewunicodechar{²}{${}^{2}$}% Superscript two\n  \\doxynewunicodechar{³}{${}^{3}$}% Superscript three\n\\fi"
	paper := map[string]string{"a4": "a4paper", "letter": "letterpaper", "legal": "legalpaper", "executive": "executivepaper"}[paperType]
	s = strings.ReplaceAll(s, "$latex_batchmode", batch)
	s = strings.ReplaceAll(s, "$extralatexstylesheet", extraStyle)
	s = strings.ReplaceAll(s, "$languagesupport", "")
	s = strings.ReplaceAll(s, "$latexfontenc", fontenc)
	s = strings.ReplaceAll(s, "  $latexfont", latexFont)
	s = strings.ReplaceAll(s, "$latexfont", latexFont)
	s = strings.ReplaceAll(s, "$latexemojidirectory", emojiDir)
	s = strings.ReplaceAll(s, "$papertype", paper)
	s = strings.ReplaceAll(s, "$generatedby", "Generated by")
	s = strings.ReplaceAll(s, "  $makeindex", "  \\makeindex")
	s = strings.ReplaceAll(s, "$makeindex", "\\makeindex")
	s = strings.ReplaceAll(s, "  $extralatexpackages", strings.TrimSuffix(extraPackages, "\n"))
	s = strings.ReplaceAll(s, "$extralatexpackages", strings.TrimSuffix(extraPackages, "\n"))
	s = strings.ReplaceAll(s, "  $latexspecialformulachars", specialChars)
	s = strings.ReplaceAll(s, "$latexspecialformulachars", specialChars)
	s = strings.ReplaceAll(s, "$formulamacrofile", cfg.Str("FORMULA_MACROFILE"))
	s = strings.ReplaceAll(s, "$projectname", latexEscapeTitle(cfg.Str("PROJECT_NAME")))
	s = strings.ReplaceAll(s, "$projectnumber", latexEscapeTitle(cfg.Str("PROJECT_NUMBER")))
	s = strings.ReplaceAll(s, "$projectbrief", latexEscapeTitle(cfg.Str("PROJECT_BRIEF")))
	s = strings.ReplaceAll(s, "$latexdocumentpre", "")
	s = strings.ReplaceAll(s, "$latexdocumentpost", "")
	s = strings.ReplaceAll(s, "$title", latexEscapeTitle(title))
	s = strings.ReplaceAll(s, "$doxygenversion", doxyVersion)
	s = strings.ReplaceAll(s, "$datetime", "")
	s = strings.ReplaceAll(s, "$date", "")
	s = strings.ReplaceAll(s, "$time", "")
	s = strings.ReplaceAll(s, "$year", "")
	s = strings.ReplaceAll(s, "$latexbibstyle", cfg.Str("LATEX_BIB_STYLE"))
	s = strings.ReplaceAll(s, "$latexbibfiles", "")
	s = strings.ReplaceAll(s, "$latexcitereference", "Bibliography")
	// remove empty lines
	var out []string
	for _, line := range strings.Split(s, "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n") + "\n"
}

func latexEscapeTitle(s string) string {
	return filterLatexString(s, false)
}

func substituteLatexBlocks(s string, conds map[string]bool) string {
	for {
		i := strings.Index(s, "%%BEGIN ")
		if i < 0 {
			return s
		}
		e := strings.Index(s[i:], "\n")
		if e < 0 {
			return s
		}
		name := strings.TrimSpace(s[i+8 : i+e])
		endMarker := "%%END " + name + "\n"
		j := strings.Index(s[i:], endMarker)
		if j < 0 {
			endMarker = "%%END " + name
			j = strings.Index(s[i:], endMarker)
			if j < 0 {
				return s
			}
		}
		inner := s[i+e+1 : i+j]
		neg := strings.HasPrefix(name, "!")
		key := strings.TrimPrefix(name, "!")
		val := conds[key]
		if neg {
			val = !val
		}
		if val {
			s = s[:i] + inner + s[i+j+len(endMarker):]
		} else {
			s = s[:i] + s[i+j+len(endMarker):]
		}
	}
}

// filterLatexString escapes text for LaTeX output (doxygen compatible).
func filterLatexString(str string, insideTabbing bool) string {
	var sb strings.Builder
	var pc byte
	for i := 0; i < len(str); i++ {
		c := str[i]
		var next byte
		if i+1 < len(str) {
			next = str[i+1]
		}
		switch c {
		case '\\':
			sb.WriteString("\\textbackslash{}")
		case '#':
			if !insideTabbing {
				sb.WriteString("\\+")
			}
			sb.WriteString("\\#")
		case '$':
			sb.WriteString("\\$")
		case '%':
			sb.WriteString("\\%")
		case '^':
			sb.WriteString("\\string^")
		case '&':
			sb.WriteString("\\&")
		case '*':
			sb.WriteString("$\\ast$")
		case '_':
			if !insideTabbing {
				sb.WriteString("\\+")
			}
			sb.WriteString("\\_")
		case '{':
			sb.WriteString("\\{")
		case '}':
			sb.WriteString("\\}")
		case '<':
			sb.WriteString("$<$")
		case '>':
			sb.WriteString("$>$")
		case '|':
			sb.WriteString("$\\vert$")
		case '~':
			sb.WriteString("\\string~")
		case '"':
			sb.WriteString("\\char`\\\"{}")
		case '\'':
			sb.WriteString("\\textquotesingle{}")
		case '`':
			sb.WriteString("\\`{}")
		case '-':
			if pc == '-' {
				sb.WriteString("\\/-")
			} else {
				sb.WriteByte('-')
			}
		case '\n':
			sb.WriteByte(' ')
		default:
			if !insideTabbing && ((c >= 'A' && c <= 'Z' && pc != ' ' && !(pc >= 'A' && pc <= 'Z') && pc != 0 && next != 0) || (pc == ':' && c != ':' && i >= 2 && str[i-2] == ':') || (pc == '.' && isIdentChar(c))) {
				sb.WriteString("\\+")
			}
			sb.WriteByte(c)
		}
		pc = c
	}
	return sb.String()
}

// latexCodeEscape escapes code for \DoxyCodeLine.
func latexCodeEscape(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case ' ':
			sb.WriteString("\\ ")
		case '\\':
			sb.WriteString("\\textbackslash{}")
		case '{':
			sb.WriteString("\\{")
		case '}':
			sb.WriteString("\\}")
		case '#':
			sb.WriteString("\\#")
		case '$':
			sb.WriteString("\\$")
		case '%':
			sb.WriteString("\\%")
		case '&':
			sb.WriteString("\\&")
		case '_':
			sb.WriteString("\\_")
		case '^':
			sb.WriteString("\\string^")
		case '~':
			sb.WriteString("\\string~")
		case '<':
			sb.WriteString("$<$")
		case '>':
			sb.WriteString("$>$")
		case '|':
			sb.WriteString("$\\vert$")
		case '"':
			sb.WriteString("\\char`\\\"{}")
		case '\'':
			sb.WriteString("\\textquotesingle{}")
		case '`':
			sb.WriteString("\\`{}")
		case '*':
			sb.WriteString("$\\ast$")
		case '-':
			sb.WriteString("-")
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

