func (l *LatexGenerator) writeRefman() {
	cfg := l.d.cfg
	d := l.d
	header := resLatexHeader
	if hf := cfg.Str("LATEX_HEADER"); hf != "" {
		if data, err := os.ReadFile(hf); err == nil {
			header = string(data)
		}
	}
	footer := resLatexFooter
	if ff := cfg.Str("LATEX_FOOTER"); ff != "" {
		if data, err := os.ReadFile(ff); err == nil {
			footer = string(data)
		}
	}
	if strings.HasPrefix(header, "% Latex header for doxygen") {
		if i := strings.Index(header, "\n"); i >= 0 {
			header = header[i+1:]
		}
	}
	if strings.HasPrefix(footer, "% Latex footer for doxygen") {
		if i := strings.Index(footer, "\n"); i >= 0 {
			footer = footer[i+1:]
		}
	}
	title := cfg.Str("PROJECT_NAME")
	if d.mainPage != nil && d.mainPage.Title != "" {
		title = d.mainPage.Title
	}
	var sb strings.Builder
	sb.WriteString(l.substituteLatexKeywords(header, title))
	compact := cfg.Bool("COMPACT_LATEX")
	chapter := func(t string) {
		if compact {
			sb.WriteString("\\doxysection{" + t + "}\n")
		} else {
			sb.WriteString("\\chapter{" + t + "}\n")
		}
	}
	// main page content
	if d.mainPage != nil && (d.mainPage.Doc.Doc != "" || d.mainPage.Doc.Brief != "") {
		ctx := &DocContext{d: d, scope: d.mainPage, file: d.mainPage.Doc.DocFile, line: d.mainPage.Doc.DocLine}
		root := d.parseDocText(ctx, joinDocs(d.mainPage.Doc.Brief, d.mainPage.Doc.Doc))
		if compact {
			sb.WriteString("\\doxysection{" + latexEscapeTitle(title) + "}\n")
		} else {
			sb.WriteString("\\chapter{" + latexEscapeTitle(title) + "}\n")
		}
		sb.WriteString("\\label{index}\\hypertarget{index}{}\n")
		sb.WriteString(d.docToLatex(root, ctx))
		sb.WriteString("\n")
	}
	// pages
	if len(d.pages) > 0 {
		for _, pg := range d.pages {
			if pg.Parent != nil {
				continue
			}
			chapter(latexEscapeTitle(pg.displayTitle()))
			sb.WriteString("\\input{" + pg.OutputBase + "}\n")
		}
	}
	nss := d.documentedNamespaces()
	if len(nss) > 0 && cfg.Bool("SHOW_NAMESPACES") {
		chapter("Namespace Index")
		sb.WriteString("\\input{namespaces}\n")
	}
	classes := d.annotatedClasses()
	if len(classes) > 0 {
		if d.hierarchyClasses() > 0 {
			chapter("Hierarchical Index")
			sb.WriteString("\\input{hierarchy}\n")
		}
		chapter("Class Index")
		sb.WriteString("\\input{annotated}\n")
	}
	files := d.documentedFiles()
	if len(files) > 0 && cfg.Bool("SHOW_FILES") {
		chapter("File Index")
		sb.WriteString("\\input{files}\n")
	}
	if len(nss) > 0 && cfg.Bool("SHOW_NAMESPACES") {
		chapter("Namespace Documentation")
		for _, ns := range nss {
			sb.WriteString("\\input{" + ns.OutputBase + "}\n")
		}
	}
	if len(classes) > 0 {
		chapter("Class Documentation")
		for _, cd := range classes {
			sb.WriteString("\\input{" + cd.OutputBase + "}\n")
		}
	}
	if len(files) > 0 && cfg.Bool("SHOW_FILES") {
		chapter("File Documentation")
		for _, fd := range files {
			sb.WriteString("\\input{" + fd.OutputBase + "}\n")
			if fd.HasSource {
				sb.WriteString("\\input{" + fd.OutputBase + "_source}\n")
			}
		}
	}
	sb.WriteString(l.substituteLatexKeywords(footer, title))
	l.writeFile("refman.tex", sb.String())
	// hierarchy
	if len(classes) > 0 && d.hierarchyClasses() > 0 {
		l.writeHierarchy()
	}
	if len(nss) > 0 && cfg.Bool("SHOW_NAMESPACES") {
		var nb strings.Builder
		nb.WriteString("\\doxysection{Namespace List}\n")
		nb.WriteString("Here is a list of all documented namespaces with brief descriptions:\\+\\begin{DoxyCompactList}\n")
		for _, ns := range nss {
			nb.WriteString("\\item\\contentsline{section}{\\doxymbox{\\hyperlink{" + ns.OutputBase + "}{" + filterLatexString(ns.QualName, false) + "}} " + l.briefLatex(ns.Doc.Brief, ns, ns.Name) + "}{\\pageref{" + ns.OutputBase + "}}{}\n")
		}
		nb.WriteString("\\end{DoxyCompactList}\n")
		l.writeFile("namespaces.tex", nb.String())
	}
}

func (l *LatexGenerator) writeHierarchy() {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{Class Hierarchy}\n")
	sb.WriteString("This inheritance list is sorted roughly, but not completely, alphabetically:\\begin{DoxyCompactList}\n")
	var writeNode func(cd *ClassDef, level int)
	writeNode = func(cd *ClassDef, level int) {
		sb.WriteString("\\item\\contentsline{section}{\\doxymbox{\\hyperlink{" + cd.OutputBase + "}{" + filterLatexString(cd.QualName, false) + "}}}{\\pageref{" + cd.OutputBase + "}}{}\n")
		var kids []*ClassDef
		for _, dc := range cd.Derived {
			if dc.isLinkable(d) {
				kids = append(kids, dc)
			}
		}
		if len(kids) > 0 {
			sb.WriteString("\\begin{DoxyCompactList}\n")
			for _, k := range kids {
				writeNode(k, level+1)
			}
			sb.WriteString("\\end{DoxyCompactList}\n")
		}
	}
	for _, cd := range d.classes {
		if cd.isVisibleInHierarchy(d) && !cd.hasVisibleBase(d) {
			writeNode(cd, 0)
		}
	}
	sb.WriteString("\\end{DoxyCompactList}\n")
	l.writeFile("hierarchy.tex", sb.String())
}

func (l *LatexGenerator) briefLatex(brief string, scope interface{}, name string) string {
	d := l.d
	if strings.TrimSpace(brief) == "" {
		return ""
	}
	ab := d.abbreviate(brief, name)
	ctx := &DocContext{d: d, scope: scope, singleLine: true}
	root := d.parseDocText(ctx, ab)
	return "\\\\*" + d.docToLatex(root, ctx)
}

func (l *LatexGenerator) writeAnnotatedIndex(classes []*ClassDef) {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{Class List}\n")
	sb.WriteString("Here are the classes, structs, unions and interfaces with brief descriptions:\\+\\begin{DoxyCompactList}\n")
	for _, cd := range classes {
		sb.WriteString("\\item\\contentsline{section}{\\doxymbox{\\hyperlink{" + cd.OutputBase + "}{" + filterLatexString(cd.QualName, false) + "}} " + l.briefLatex(cd.Doc.Brief, cd, cd.Name) + "}{\\pageref{" + cd.OutputBase + "}}{}\n")
	}
	sb.WriteString("\\end{DoxyCompactList}\n")
	l.writeFile("annotated.tex", sb.String())
}

func (l *LatexGenerator) writeFileIndex(files []*FileDef) {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{File List}\n")
	sb.WriteString("Here is a list of all documented files with brief descriptions:\\+\\begin{DoxyCompactList}\n")
	for _, fd := range files {
		sb.WriteString("\\item\\contentsline{section}{\\doxymbox{\\hyperlink{" + fd.OutputBase + "}{" + filterLatexString(fd.Name, false) + "}} " + l.briefLatex(fd.Doc.Brief, fd, fd.Name) + "}{\\pageref{" + fd.OutputBase + "}}{}\n")
	}
	sb.WriteString("\\end{DoxyCompactList}\n")
	l.writeFile("files.tex", sb.String())
}

func (l *LatexGenerator) writePage(pg *PageDef) {
	d := l.d
	var sb strings.Builder
	ctx := &DocContext{d: d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine}
	root := d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc))
	sb.WriteString("\\hypertarget{" + pg.OutputBase + "}{}\\label{" + pg.OutputBase + "}\n")
	sb.WriteString(d.docToLatex(root, ctx))
	sb.WriteString("\n")
	l.writeFile(pg.OutputBase+".tex", sb.String())
}

func (l *LatexGenerator) memberDeclLatex(md *MemberDef, scope interface{}) string {
	var sb strings.Builder
	sb.WriteString("\\item \n")
	left := ""
	switch md.Kind {
	case MemberDefine:
		left = "#define "
	case MemberTypedef:
		left = "typedef " + md.Type + " "
	case MemberEnum:
		left = "enum "
	default:
		var parts []string
		if md.Static {
			parts = append(parts, "static")
		}
		if md.Virtual && md.Kind == MemberFunction {
			parts = append(parts, "virtual")
		}
		if md.Type != "" {
			parts = append(parts, md.Type)
		}
		left = strings.Join(parts, " ")
		if left != "" {
			left += " "
		}
	}
	sb.WriteString(filterLatexString(left, false))
	if md.isLinkable(l.d) && md.isDetailedSectionLinkable(l.d) {
		sb.WriteString("\\doxymbox{\\hyperlink{" + md.outputFile(l.d) + "_" + md.Anchor + "}{" + filterLatexString(md.Name, false) + "}}")
	} else {
		sb.WriteString("{\\bfseries " + filterLatexString(md.Name, false) + "}")
	}
	switch md.Kind {
	case MemberFunction:
		sb.WriteString(" " + filterLatexString(md.Args, false))
	case MemberVariable:
		sb.WriteString(filterLatexString(md.Args, false))
		if md.Initializer != "" && l.d.showInitializer(md) {
			sb.WriteString(" " + filterLatexString(md.Initializer, false))
		}
	case MemberDefine:
		sb.WriteString(filterLatexString(md.Args, false))
		if md.Initializer != "" && l.d.showInitializer(md) {
			sb.WriteString("~~~" + filterLatexString(md.Initializer, false))
		}
	case MemberEnum:
		if len(md.EnumValues) > 0 {
			sb.WriteString(" { ")
			for i, ev := range md.EnumValues {
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(filterLatexString(ev.Name, false))
				if ev.Initializer != "" && l.d.showInitializer(ev) {
					sb.WriteString(" " + filterLatexString(ev.Initializer, false))
				}
			}
			sb.WriteString(" }")
		}
	}
	sb.WriteString("\n")
	if md.Doc.Brief != "" {
		ctx := &DocContext{d: l.d, scope: scope, member: md, singleLine: true}
		sb.WriteString("\\begin{DoxyCompactList}\\small\\item\\em " + l.d.docToLatex(l.d.parseDocText(ctx, md.Doc.Brief), ctx) + "\\end{DoxyCompactList}")
	}
	return sb.String()
}

func (l *LatexGenerator) memberDocLatex(md *MemberDef, scope interface{}, scopeName string, scopeBase string) string {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\Hypertarget{" + scopeBase + "_" + md.Anchor + "}\\index{" + latexIndexEscape(scopeName) + "@{" + latexIndexEscape(scopeName) + "}!" + latexIndexEscape(md.Name) + "@{" + latexIndexEscape(md.Name) + "}}\n")
	sb.WriteString("\\index{" + latexIndexEscape(md.Name) + "@{" + latexIndexEscape(md.Name) + "}!" + latexIndexEscape(scopeName) + "@{" + latexIndexEscape(scopeName) + "}}\n")
	title := md.Name
	if md.Kind == MemberFunction {
		title += "()"
	}
	sb.WriteString("\\doxysubsubsection{\\texorpdfstring{" + filterLatexString(title, false) + "}{" + filterLatexString(title, false) + "}}\n")
	sb.WriteString("{\\footnotesize\\ttfamily \\label{" + scopeBase + "_" + md.Anchor + "} \n")
	switch md.Kind {
	case MemberFunction:
		def := ""
		if md.Type != "" {
			def = md.Type + " "
		}
		def += md.QualName
		sb.WriteString(filterLatexString(def, false) + " (")
		sb.WriteString("\\begin{DoxyParamCaption}")
		if md.ArgList != nil && len(md.ArgList.Args) > 0 && !md.ArgList.NoParams {
			for _, a := range md.ArgList.Args {
				sb.WriteString("\\item[{" + filterLatexString(a.Type, false) + "}]{" + filterLatexString(a.Name, false) + "}{")
				if a.DefVal != "" {
					sb.WriteString(" = " + filterLatexString(a.DefVal, false))
				}
				sb.WriteString("}")
			}
		} else {
			sb.WriteString("{}{}")
		}
		sb.WriteString("\\end{DoxyParamCaption})")
		if md.Const {
			sb.WriteString(" const")
		}
		if md.PureVirtual {
			sb.WriteString(" = 0")
		}
		var labels []string
		if md.Static {
			labels = append(labels, "static")
		}
		if md.Prot == Protected {
			labels = append(labels, "protected")
		} else if md.Prot == Private {
			labels = append(labels, "private")
		}
		if md.PureVirtual {
			labels = append(labels, "pure virtual")
		} else if md.Virtual && md.Entry != nil && md.Entry.Virtual {
			labels = append(labels, "virtual")
		}
		if md.Inline && d.cfg.Bool("INLINE_INFO") {
			labels = append(labels, "inline")
		}
		if len(labels) > 0 {
			sb.WriteString("\\hspace{0.3cm}{\\ttfamily [" + strings.Join(labels, ", ") + "]}")
		}
		sb.WriteString("}\n\n")
	case MemberDefine:
		sb.WriteString("\\#define " + filterLatexString(md.Name, false))
		if md.Args != "" {
			sb.WriteString(filterLatexString(md.Args, false))
		}
		if md.Initializer != "" && d.showInitializer(md) {
			sb.WriteString("~~~" + filterLatexString(md.Initializer, false))
		}
		sb.WriteString("}\n\n")
	case MemberTypedef:
		sb.WriteString("typedef " + filterLatexString(md.Type+" "+md.QualName+md.Args, false) + "}\n\n")
	case MemberEnum:
		sb.WriteString("enum " + filterLatexString(md.QualName, false) + "}\n\n")
	default:
		def := ""
		if md.Type != "" {
			def = md.Type + " "
		}
		def += md.QualName + md.Args
		if md.Initializer != "" && d.showInitializer(md) {
			def += " " + md.Initializer
		}
		sb.WriteString(filterLatexString(def, false) + "}\n\n")
	}
	ctx := &DocContext{d: d, scope: scope, member: md}
	if d.cfg.Bool("REPEAT_BRIEF") && md.Doc.Brief != "" {
		sb.WriteString(d.docToLatex(d.parseDocText(ctx, md.Doc.Brief), ctx))
	}
	if md.Doc.Doc != "" {
		sb.WriteString(d.docToLatex(d.parseDocText(ctx, md.Doc.Doc), ctx))
	}
	if md.Kind == MemberEnum {
		hasDoc := false
		for _, ev := range md.EnumValues {
			if ev.Doc.hasDocs() {
				hasDoc = true
			}
		}
		if hasDoc {
			sb.WriteString("\\begin{DoxyEnumFields}{Enumerator}\n")
			for _, ev := range md.EnumValues {
				if !ev.Doc.hasDocs() && !d.cfg.Bool("EXTRACT_ALL") {
					continue
				}
				sb.WriteString("\\raisebox{\\heightof{T}}[0pt][0pt]{\\index{" + latexIndexEscape(ev.Name) + "@{" + latexIndexEscape(ev.Name) + "}!" + latexIndexEscape(scopeName) + "@{" + latexIndexEscape(scopeName) + "}}\\index{" + latexIndexEscape(scopeName) + "@{" + latexIndexEscape(scopeName) + "}!" + latexIndexEscape(ev.Name) + "@{" + latexIndexEscape(ev.Name) + "}}}\\Hypertarget{" + scopeBase + "_" + ev.Anchor + "}\\label{" + scopeBase + "_" + ev.Anchor + "} \n")
				sb.WriteString(filterLatexString(ev.Name, false) + "&")
				ectx := &DocContext{d: d, scope: scope, member: ev}
				sb.WriteString(d.docToLatex(d.parseDocText(ectx, joinDocs(ev.Doc.Brief, ev.Doc.Doc)), ectx))
				sb.WriteString("\\\\\n\\hline\n\n")
			}
			sb.WriteString("\\end{DoxyEnumFields}\n")
		}
	}
	return sb.String()
}

func latexIndexEscape(s string) string {
	s = strings.ReplaceAll(s, "!", "\"!")
	s = strings.ReplaceAll(s, "@", "\"@")
	s = strings.ReplaceAll(s, "|", "\"|")
	s = strings.ReplaceAll(s, "_", "\\_")
	return s
}

func (l *LatexGenerator) writeClass(cd *ClassDef) {
	d := l.d
	var sb strings.Builder
	title := cd.QualName + " " + compoundTypeName(cd) + " Reference"
	sb.WriteString("\\doxysection{" + filterLatexString(title, false) + "}\n")
	sb.WriteString("\\hypertarget{" + cd.OutputBase + "}{}\\label{" + cd.OutputBase + "}\\index{" + latexIndexEscape(cd.QualName) + "@{" + latexIndexEscape(cd.QualName) + "}}\n")
	ctx := &DocContext{d: d, scope: cd}
	if cd.Doc.Brief != "" {
		bctx := &DocContext{d: d, scope: cd, singleLine: true}
		sb.WriteString("\n\n" + d.docToLatex(d.parseDocText(bctx, cd.Doc.Brief), bctx) + " \n")
	}
	if d.cfg.Bool("SHOW_HEADERFILE") && cd.FileDef != nil && cd.FileDef.isLinkable(d) {
		sb.WriteString("\n\n{\\ttfamily " + filterLatexString("#include <"+cd.FileDef.Name+">", false) + "}\n")
	}
	// inheritance
	if len(cd.Bases) > 0 {
		sb.WriteString("Inheritance diagram for " + filterLatexString(cd.QualName, false) + ":")
		sb.WriteString("\n")
	}
	sections := d.classMemberSections(cd)
	sb.WriteString("\n")
	for _, s := range sections {
		sb.WriteString("\\doxysubsubsection*{" + s.title + "}\n")
		sb.WriteString("\\begin{DoxyCompactItemize}\n")
		for _, md := range s.members {
			sb.WriteString(l.memberDeclLatex(md, cd))
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	if cd.hasDetailedDescription(d) {
		sb.WriteString("\n\n\\doxysubsection{Detailed Description}\n")
		if d.cfg.Bool("REPEAT_BRIEF") && cd.Doc.Brief != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, cd.Doc.Brief), ctx))
		}
		if cd.Doc.Doc != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, cd.Doc.Doc), ctx))
		}
		sb.WriteString("\n")
	}
	for _, ds := range d.classDetailSections(cd) {
		sb.WriteString("\n\\label{" + ds.key + "}\n")
		sb.WriteString("\\Hypertarget{" + cd.OutputBase + "_" + ds.key + "}\n")
		sb.WriteString("\\doxysubsection{" + strings.ReplaceAll(ds.title, "&amp;", "\\&") + "}\n")
		for _, md := range ds.members {
			sb.WriteString(l.memberDocLatex(md, cd, cd.QualName, cd.OutputBase))
		}
	}
	if d.cfg.Bool("SHOW_USED_FILES") && len(cd.UsedFiles) > 0 {
		sb.WriteString("\n\nThe documentation for this " + strings.ToLower(compoundTypeName(cd)) + " was generated from the following file")
		if len(cd.UsedFiles) > 1 {
			sb.WriteString("s")
		}
		sb.WriteString(":\\+\\begin{DoxyCompactItemize}\n")
		for _, fd := range cd.UsedFiles {
			sb.WriteString("\\item \n")
			if fd.isLinkable(d) {
				sb.WriteString("\\doxymbox{\\hyperlink{" + fd.OutputBase + "}{" + filterLatexString(fd.Name, false) + "}}")
			} else {
				sb.WriteString(filterLatexString(fd.Name, false))
			}
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	l.writeFile(cd.OutputBase+".tex", sb.String())
}

func (l *LatexGenerator) writeFile(fd *FileDef) {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{" + filterLatexString(fd.displayName(d), false) + " File Reference}\n")
	sb.WriteString("\\hypertarget{" + fd.OutputBase + "}{}\\label{" + fd.OutputBase + "}\\index{" + latexIndexEscape(fd.displayName(d)) + "@{" + latexIndexEscape(fd.displayName(d)) + "}}\n")
	ctx := &DocContext{d: d, scope: fd}
	if fd.Doc.Brief != "" {
		bctx := &DocContext{d: d, scope: fd, singleLine: true}
		sb.WriteString("\n\n" + d.docToLatex(d.parseDocText(bctx, fd.Doc.Brief), bctx) + " \n")
	}
	if d.cfg.Bool("SHOW_INCLUDE_FILES") && len(fd.Includes) > 0 {
		for _, inc := range fd.Includes {
			open, close := "<", ">"
			if inc.Local {
				open, close = "\"", "\""
			}
			sb.WriteString("{\\ttfamily " + filterLatexString("#include "+open+inc.Name+close, false) + "}\\newline\n")
		}
	}
	sb.WriteString("\n\n")
	var visibleClasses []*ClassDef
	for _, cd := range fd.Classes {
		if cd.isLinkable(d) {
			visibleClasses = append(visibleClasses, cd)
		}
	}
	if len(visibleClasses) > 0 {
		sb.WriteString("\\doxysubsubsection*{Classes}\n\\begin{DoxyCompactItemize}\n")
		for _, cd := range visibleClasses {
			sb.WriteString("\\item \n" + cd.CompoundType + " \\doxymbox{\\hyperlink{" + cd.OutputBase + "}{" + filterLatexString(cd.Name, false) + "}}\n")
			if cd.Doc.Brief != "" {
				bctx := &DocContext{d: d, scope: cd, singleLine: true}
				sb.WriteString("\\begin{DoxyCompactList}\\small\\item\\em " + d.docToLatex(d.parseDocText(bctx, cd.Doc.Brief), bctx) + "\\end{DoxyCompactList}")
			}
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	sections := d.fileMemberSections(fd.Members, true)
	for _, s := range sections {
		sb.WriteString("\\doxysubsubsection*{" + s.title + "}\n\\begin{DoxyCompactItemize}\n")
		for _, md := range s.members {
			sb.WriteString(l.memberDeclLatex(md, fd))
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	if fd.hasDetailedDescription(d) {
		sb.WriteString("\n\n\\doxysubsection{Detailed Description}\n")
		if d.cfg.Bool("REPEAT_BRIEF") && fd.Doc.Brief != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, fd.Doc.Brief), ctx))
		}
		if fd.Doc.Doc != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, fd.Doc.Doc), ctx))
		}
		sb.WriteString("\n\n")
	}
	details := d.fileDetailSections(fd.Members, true)
	for i, ds := range details {
		sb.WriteString("\n\\label{" + ds.key + "}\n")
		sb.WriteString("\\Hypertarget{" + fd.OutputBase + "_" + ds.key + "}\n")
		sb.WriteString("\\doxysubsection{" + ds.title + "}\n")
		for j, md := range ds.members {
			s := l.memberDocLatex(md, fd, fd.displayName(d), fd.OutputBase)
			if i == len(details)-1 && j == len(ds.members)-1 {
				s = strings.TrimRight(s, "\n")
			}
			sb.WriteString(s)
		}
	}
	l.writeFile(fd.OutputBase+".tex", sb.String())
	if fd.HasSource {
		l.writeSource(fd)
	}
}

func (l *LatexGenerator) writeNamespace(ns *NamespaceDef) {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{" + filterLatexString(ns.QualName, false) + " Namespace Reference}\n")
	sb.WriteString("\\hypertarget{" + ns.OutputBase + "}{}\\label{" + ns.OutputBase + "}\\index{" + latexIndexEscape(ns.QualName) + "@{" + latexIndexEscape(ns.QualName) + "}}\n")
	ctx := &DocContext{d: d, scope: ns}
	if ns.Doc.Brief != "" {
		bctx := &DocContext{d: d, scope: ns, singleLine: true}
		sb.WriteString("\n\n" + d.docToLatex(d.parseDocText(bctx, ns.Doc.Brief), bctx) + " \n")
	}
	sb.WriteString("\n\n")
	var visibleClasses []*ClassDef
	for _, cd := range ns.Classes {
		if cd.isLinkable(d) {
			visibleClasses = append(visibleClasses, cd)
		}
	}
	if len(visibleClasses) > 0 {
		sb.WriteString("\\doxysubsubsection*{Classes}\n\\begin{DoxyCompactItemize}\n")
		for _, cd := range visibleClasses {
			sb.WriteString("\\item \n" + cd.CompoundType + " \\doxymbox{\\hyperlink{" + cd.OutputBase + "}{" + filterLatexString(cd.Name, false) + "}}\n")
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	for _, s := range d.fileMemberSections(ns.Members, false) {
		sb.WriteString("\\doxysubsubsection*{" + s.title + "}\n\\begin{DoxyCompactItemize}\n")
		for _, md := range s.members {
			sb.WriteString(l.memberDeclLatex(md, ns))
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	if ns.Doc.Doc != "" || (ns.Doc.Brief != "" && d.cfg.Bool("REPEAT_BRIEF")) {
		sb.WriteString("\n\n\\doxysubsection{Detailed Description}\n")
		if d.cfg.Bool("REPEAT_BRIEF") && ns.Doc.Brief != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, ns.Doc.Brief), ctx))
		}
		if ns.Doc.Doc != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, ns.Doc.Doc), ctx))
		}
		sb.WriteString("\n\n")
	}
	for _, ds := range d.fileDetailSections(ns.Members, false) {
		sb.WriteString("\n\\label{" + ds.key + "}\n")
		sb.WriteString("\\Hypertarget{" + ns.OutputBase + "_" + ds.key + "}\n")
		sb.WriteString("\\doxysubsection{" + ds.title + "}\n")
		for _, md := range ds.members {
			sb.WriteString(l.memberDocLatex(md, ns, ns.QualName, ns.OutputBase))
		}
	}
	l.writeFile(ns.OutputBase+".tex", sb.String())
}

func (l *LatexGenerator) writeSource(fd *FileDef) {
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{" + filterLatexString(fd.displayName(d), false) + "}\n")
	sb.WriteString("\\hypertarget{" + fd.OutputBase + "_source}{}\\label{" + fd.OutputBase + "_source}")
	if fd.isLinkable(d) {
		sb.WriteString("\\doxymbox{\\hyperlink{" + fd.OutputBase + "}{Go to the documentation of this file.}}\n")
	} else {
		sb.WriteString("\n")
	}
	sb.WriteString("\\begin{DoxyCode}{0}\n")
	lcw := &latexCodeWriter{d: d, fd: fd, lineNr: 1, stripComments: d.cfg.Bool("STRIP_CODE_COMMENTS")}
	src := strings.ReplaceAll(string(fd.Source), "\r\n", "\n")
	src = expandTabs(src, d.cfg.Int("TAB_SIZE"))
	lcw.run(src)
	sb.WriteString(lcw.sb.String())
	sb.WriteString("\n\\end{DoxyCode}\n")
	l.writeFile(fd.OutputBase+"_source.tex", sb.String())
}

