package main

import (
	"fmt"
	"strings"
)

// LatexDocVisitor renders a documentation tree as LaTeX.
type LatexDocVisitor struct {
	d   *Doxygen
	sb  *strings.Builder
	ctx *DocContext
	insideTabbing bool
}

func (d *Doxygen) docToLatex(root *DocNode, ctx *DocContext) string {
	var sb strings.Builder
	v := &LatexDocVisitor{d: d, sb: &sb, ctx: ctx}
	for _, c := range root.Children {
		v.visit(c)
	}
	return sb.String()
}

func (v *LatexDocVisitor) w(s string) { v.sb.WriteString(s) }

func (v *LatexDocVisitor) visitChildren(n *DocNode) {
	for _, c := range n.Children {
		v.visit(c)
	}
}

func (v *LatexDocVisitor) visit(n *DocNode) {
	switch n.Kind {
	case DocPara:
		v.visitChildren(n)
		// paragraphs end with a blank line unless last in root/single
		isFirst, isLast := paragraphContext(n)
		_ = isFirst
		if !isLast || (n.Parent != nil && n.Parent.Kind == DocRoot && !n.Parent.Flag) {
			if !(n.Parent != nil && n.Parent.Kind == DocRoot && isLast) {
				v.w("\n\n")
			}
		}
	case DocText:
		if len(n.Children) > 0 {
			v.visitChildren(n)
		} else {
			v.w(filterLatexString(n.Text, v.insideTabbing))
		}
	case DocWord:
		v.w(filterLatexString(n.Text, v.insideTabbing))
	case DocLinkedWord:
		t, _ := n.Target.(*LinkTarget)
		v.startLink(t)
		v.w(filterLatexString(n.Text, v.insideTabbing))
		v.endLink(t)
	case DocWhitespace:
		v.w(" ")
	case DocLineBreak:
		v.w("~\\newline\n")
	case DocHorRuler:
		v.w("\n\n\\DoxyHorRuler{0}\n")
	case DocSymbol:
		v.w(latexEntity(n.Text))
	case DocStyle:
		v.visitStyle(n)
	case DocURL:
		href := n.Attrs["href"]
		if len(n.Children) == 0 {
			v.w("\\href{" + latexFilterURL(href) + "}{\\texttt{" + filterLatexString(n.Text, false) + "}}")
		} else {
			v.w("\\href{" + latexFilterURL(href) + "}{")
			v.visitChildren(n)
			v.w("}")
		}
	case DocRef:
		t, _ := n.Target.(*LinkTarget)
		text := n.Attrs["text"]
		if text == "" {
			if t != nil && t.Name != "" {
				text = t.Name
			} else {
				text = n.Text
			}
			if t != nil {
				if md, ok := t.Def.(*MemberDef); ok && md.Kind == MemberFunction {
					text = md.Name + "()"
				}
			}
		}
		if t == nil {
			v.w(filterLatexString(text, false))
			return
		}
		v.startLink(t)
		v.w(filterLatexString(text, false))
		v.endLink(t)
	case DocAnchor:
		v.w("\\label{" + n.Text + "}%\n")
		v.w("\\Hypertarget{" + n.Text + "}%\n")
	case DocSection:
		cmd := []string{"", "doxysection", "doxysubsection", "doxysubsubsection", "doxyparagraph", "doxysubparagraph", "doxysubsubparagraph"}
		lvl := n.Level
		if lvl > 6 {
			lvl = 6
		}
		v.w("\\" + cmd[lvl] + "{" + filterLatexString(n.Text, false) + "}\n")
		v.w("\\label{" + n.Anchor + "}\\Hypertarget{" + n.Anchor + "}\n")
		v.visitChildren(n)
	case DocHtmlHeader:
		cmd := []string{"", "doxysection", "doxysubsection", "doxysubsubsection", "doxyparagraph", "doxysubparagraph", "doxysubsubparagraph"}
		v.w("\\" + cmd[n.Level] + "*{")
		v.visitChildren(n)
		v.w("}\n")
	case DocSimpleSect:
		typ := n.Attrs["type"]
		title := n.Attrs["title"]
		switch typ {
		case "see", "sa":
			v.w("\\begin{DoxySeeAlso}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxySeeAlso}\n")
		case "return", "returns", "result":
			v.w("\\begin{DoxyReturn}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyReturn}\n")
		case "author", "authors":
			v.w("\\begin{DoxyAuthor}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyAuthor}\n")
		case "version":
			v.w("\\begin{DoxyVersion}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyVersion}\n")
		case "since":
			v.w("\\begin{DoxySince}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxySince}\n")
		case "date":
			v.w("\\begin{DoxyDate}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyDate}\n")
		case "note":
			v.w("\\begin{DoxyNote}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyNote}\n")
		case "warning":
			v.w("\\begin{DoxyWarning}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyWarning}\n")
		case "pre":
			v.w("\\begin{DoxyPrecond}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyPrecond}\n")
		case "post":
			v.w("\\begin{DoxyPostcond}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyPostcond}\n")
		case "copyright":
			v.w("\\begin{DoxyCopyright}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyCopyright}\n")
		case "invariant":
			v.w("\\begin{DoxyInvariant}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyInvariant}\n")
		case "remark", "remarks":
			v.w("\\begin{DoxyRemark}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyRemark}\n")
		case "attention":
			v.w("\\begin{DoxyAttention}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyAttention}\n")
		case "important":
			v.w("\\begin{DoxyImportant}{" + title + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyImportant}\n")
		default:
			v.w("\\begin{DoxyParagraph}{" + filterLatexString(title, false) + "}\n")
			v.visitChildren(n)
			v.w("\n\\end{DoxyParagraph}\n")
		}
	case DocXRefItem:
		v.w("\\begin{DoxyRefDesc}{" + n.Attrs["title"] + "}\n")
		v.w("\\item[\\mbox{\\hyperlink{" + n.Attrs["key"] + "_" + n.Attrs["key"] + "}{" + n.Attrs["title"] + "}}]")
		v.visitChildren(n)
		v.w("\\end{DoxyRefDesc}\n")
	case DocParamSect:
		v.visitParamSect(n)
	case DocVerbatim:
		v.visitVerbatim(n)
	case DocAutoList:
		if n.Ordered {
			v.w("\n\\begin{DoxyEnumerate}")
		} else {
			v.w("\n\\begin{DoxyItemize}")
		}
		for _, item := range n.Children {
			v.w("\n\\item ")
			v.visitChildren(item)
		}
		if n.Ordered {
			v.w("\n\\end{DoxyEnumerate}\n")
		} else {
			v.w("\n\\end{DoxyItemize}\n")
		}
	case DocSimpleList:
		v.w("\\begin{DoxyItemize}\n")
		for _, item := range n.Children {
			v.w("\\item ")
			v.visitChildren(item)
			v.w("\n")
		}
		v.w("\\end{DoxyItemize}\n")
	case DocHtmlList:
		if n.Ordered {
			v.w("\n\\begin{DoxyEnumerate}")
		} else {
			v.w("\n\\begin{DoxyItemize}")
		}
		for _, item := range n.Children {
			v.w("\n\\item ")
			v.visitChildren(item)
		}
		if n.Ordered {
			v.w("\n\\end{DoxyEnumerate}\n")
		} else {
			v.w("\n\\end{DoxyItemize}\n")
		}
	case DocHtmlDescList:
		v.w("\n\\begin{description}\n")
		for _, c := range n.Children {
			if c.Kind == DocHtmlDescTitle {
				v.w("\\item[")
				v.visitChildren(c)
				v.w("]")
			} else {
				v.visitChildren(c)
			}
		}
		v.w("\n\\end{description}\n")
	case DocHtmlTable:
		v.visitTable(n)
	case DocHtmlBlockQuote:
		v.w("\\begin{quote}\n")
		v.visitChildren(n)
		v.w("\\end{quote}\n")
	case DocParBlock:
		v.visitChildren(n)
	case DocHtmlDetails:
		for _, c := range n.Children {
			if c.Kind == DocHtmlSummary {
				v.w("{\\bfseries ")
				v.visitChildren(c)
				v.w("}\n\n")
			} else {
				v.visit(c)
			}
		}
	case DocImage:
		if n.Attrs["format"] == "latex" || n.Attrs["format"] == "" && n.Attrs["html"] != "1" {
			v.w("\n\\begin{DoxyImage}\n\\includegraphics{" + n.Text + "}\n")
			if cap := n.Attrs["caption"]; cap != "" {
				v.w("\\doxyfigcaption{" + filterLatexString(cap, false) + "}\n")
			}
			v.w("\\end{DoxyImage}\n")
		}
	case DocFormula:
		v.w(n.Text)
	case DocInclude:
		if n.File != "" {
			data, err := osReadFile(n.File)
			if err == nil {
				v.w("\n\\begin{DoxyCode}{0}\n")
				lcw := &latexCodeWriter{d: v.d, lineNr: 1, showLines: false}
				lcw.run(string(data))
				v.w(lcw.sb.String())
				v.w("\n\\end{DoxyCode}\n")
			}
		}
	case DocEmoji:
		v.w("\\doxygenemoji{" + filterLatexString(":"+n.Text+":", false) + "}{" + n.Text + "}")
	case DocCite:
		v.w("\\cite{" + n.Text + "}")
	case DocHtmlRaw:
	case DocCopy:
	case DocTocList:
	case DocSecRefList:
		v.w("\\footnotesize\n\\begin{multicols}{2}\n\\begin{DoxyCompactList}\n")
		for _, item := range n.Children {
			v.w("\\item \\contentsline{section}{")
			t, _ := item.Target.(*LinkTarget)
			if t != nil {
				v.startLink(t)
			}
			v.w(filterLatexString(item.Attrs["title"], false))
			if t != nil {
				v.endLink(t)
			}
			v.w("}{\\ref{" + item.Text + "}}{}\n")
		}
		v.w("\\end{DoxyCompactList}\n\\end{multicols}\n\\normalsize\n")
	default:
		v.visitChildren(n)
	}
}

func latexFilterURL(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '#':
			sb.WriteString("\\#")
		case '%':
			sb.WriteString("\\%")
		case '\\':
			sb.WriteString("\\\\")
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func (v *LatexDocVisitor) startLink(t *LinkTarget) {
	if t == nil {
		return
	}
	if v.d.cfg.Bool("PDF_HYPERLINKS") {
		ref := t.File
		if t.Anchor != "" {
			ref += "_" + t.Anchor
		}
		v.w("\\doxymbox{\\hyperlink{" + ref + "}{")
	} else {
		v.w("{\\bfseries ")
	}
}

func (v *LatexDocVisitor) endLink(t *LinkTarget) {
	if t == nil {
		return
	}
	if v.d.cfg.Bool("PDF_HYPERLINKS") {
		v.w("}}")
	} else {
		v.w("}")
	}
}

func (v *LatexDocVisitor) visitStyle(n *DocNode) {
	style := n.Attrs["style"]
	switch style {
	case "bold":
		v.w("{\\bfseries{")
		v.visitChildren(n)
		v.w("}}")
	case "italic":
		v.w("{\\itshape ")
		v.visitChildren(n)
		v.w("}")
	case "code":
		v.w("{\\ttfamily ")
		v.visitChildren(n)
		v.w("}")
	case "underline":
		v.w("\\underline{")
		v.visitChildren(n)
		v.w("}")
	case "strike", "s", "del":
		v.w("\\sout{")
		v.visitChildren(n)
		v.w("}")
	case "ins":
		v.w("\\underline{")
		v.visitChildren(n)
		v.w("}")
	case "subscript":
		v.w("\\textsubscript{")
		v.visitChildren(n)
		v.w("}")
	case "superscript":
		v.w("\\textsuperscript{")
		v.visitChildren(n)
		v.w("}")
	case "small":
		v.w("\\footnotesize ")
		v.visitChildren(n)
		v.w("\\normalsize ")
	case "center":
		v.w("\\begin{center}")
		v.visitChildren(n)
		v.w("\\end{center} ")
	case "preformatted":
		v.w("\n\\begin{DoxyPre}")
		for _, c := range n.Children {
			if c.Kind == DocText {
				v.w(filterLatexString(c.Text, false))
			} else {
				v.visit(c)
			}
		}
		v.w("\\end{DoxyPre}\n")
	default:
		v.visitChildren(n)
	}
}

func (v *LatexDocVisitor) visitParamSect(n *DocNode) {
	typ := n.Attrs["type"]
	switch typ {
	case "param":
		hasDir := false
		for _, it := range n.Children {
			if it.Attrs["dir"] != "" {
				hasDir = true
			}
		}
		if hasDir {
			v.w("\n\\begin{DoxyParams}[1]{Parameters}\n")
		} else {
			v.w("\n\\begin{DoxyParams}{Parameters}\n")
		}
	case "tparam":
		v.w("\n\\begin{DoxyTemplParams}{Template Parameters}\n")
	case "retval":
		v.w("\n\\begin{DoxyRetVals}{Return values}\n")
	case "exception":
		v.w("\n\\begin{DoxyExceptions}{Exceptions}\n")
	}
	for _, item := range n.Children {
		if dir := item.Attrs["dir"]; dir != "" {
			v.w("\\mbox{\\texttt{" + strings.ReplaceAll(dir, "[", "\\mbox{[}") + "}}  & ")
			v.w(strings.Repeat("", 0))
		}
		var names []string
		for _, nm := range item.Names {
			names = append(names, "{\\em "+filterLatexString(nm, false)+"}")
		}
		v.w(strings.Join(names, ",") + " & ")
		v.visitChildren(item)
		v.w("\\\\\n\\hline\n")
	}
	switch typ {
	case "param":
		v.w("\\end{DoxyParams}\n")
	case "tparam":
		v.w("\\end{DoxyTemplParams}\n")
	case "retval":
		v.w("\\end{DoxyRetVals}\n")
	case "exception":
		v.w("\\end{DoxyExceptions}\n")
	}
}

func (v *LatexDocVisitor) visitVerbatim(n *DocNode) {
	kind := n.Attrs["kind"]
	text := n.Text
	switch kind {
	case "code", "iliteral":
		v.w("\n\\begin{DoxyCode}{0}\n")
		lcw := &latexCodeWriter{d: v.d, lineNr: 1, showLines: false}
		t := stripIndentation(text)
		if strings.HasSuffix(t, "\n") {
			t = t[:len(t)-1]
		}
		lcw.run(t)
		v.w(lcw.sb.String())
		v.w("\n\\end{DoxyCode}\n")
	case "verbatim":
		v.w("\n\\begin{DoxyVerb}")
		v.w(text)
		v.w("\\end{DoxyVerb}\n")
	case "latexonly":
		v.w(text)
	case "f[":
		v.w("\\[" + text + "\\]")
	case "f{":
		v.w(text)
	}
}

func (v *LatexDocVisitor) visitTable(n *DocNode) {
	var rows []*DocNode
	for _, c := range n.Children {
		if c.Kind == DocHtmlRow {
			rows = append(rows, c)
		}
	}
	if len(rows) == 0 {
		return
	}
	cols := 0
	for _, r := range rows {
		if len(r.Children) > cols {
			cols = len(r.Children)
		}
	}
	v.w("\n\\begin{DoxyTable}{" + fmt.Sprintf("%d", cols) + "}{" + strings.Repeat("|c", cols) + "|}\n")
	v.w("\\hline\n")
	for ri, r := range rows {
		for ci, cell := range r.Children {
			if ci > 0 {
				v.w(" & ")
			}
			if cell.Flag {
				v.w("\\cellcolor{\\tableheadbgcolor}\\textbf{ ")
				v.visitChildren(cell)
				v.w("}")
			} else {
				v.visitChildren(cell)
			}
		}
		v.w(" \\\\\n\\hline\n")
		if ri == 0 {
			v.w("\n")
		}
	}
	v.w("\\end{DoxyTable}\n")
}

func latexEntity(e string) string {
	switch e {
	case "&nbsp;":
		return "~"
	case "&copy;":
		return "\\copyright{}"
	case "&amp;":
		return "\\&"
	case "&lt;":
		return "$<$"
	case "&gt;":
		return "$>$"
	case "&quot;":
		return "\"{}"
	case "&apos;":
		return "\\textquotesingle{}"
	case "&ndash;":
		return "--"
	case "&mdash;":
		return "---"
	case "&trade;":
		return "\\texttrademark{}"
	case "&reg;":
		return "\\textregistered{}"
	}
	return e
}

// ---------------------------------------------------------------------------
// LaTeX code output

type latexCodeWriter struct {
	d         *Doxygen
	sb        strings.Builder
	fd        *FileDef
	lineNr    int
	showLines bool
	lineOpen  bool
	stripComments bool
	pendingOpen bool
}

func (lcw *latexCodeWriter) startLine() {
	if lcw.lineOpen {
		return
	}
	lcw.lineOpen = true
	if lcw.showLines || lcw.fd != nil {
		lcw.sb.WriteString(fmt.Sprintf("\\DoxyCodeLine{%05d\\ ", lcw.lineNr))
	} else {
		lcw.sb.WriteString("\\DoxyCodeLine{")
	}
}

func (lcw *latexCodeWriter) endLine() {
	if !lcw.lineOpen {
		return
	}
	lcw.lineOpen = false
	lcw.sb.WriteString("}\n")
}

func (lcw *latexCodeWriter) codify(s string) {
	for {
		i := strings.IndexByte(s, '\n')
		if i < 0 {
			if s != "" {
				lcw.startLine()
				lcw.sb.WriteString(latexCodeEscape(s))
			}
			return
		}
		if s[:i] != "" {
			lcw.startLine()
			lcw.sb.WriteString(latexCodeEscape(s[:i]))
		}
		lcw.newline()
		s = s[i+1:]
	}
}

func (lcw *latexCodeWriter) newline() {
	lcw.startLine()
	lcw.endLine()
	lcw.lineNr++
}

func (lcw *latexCodeWriter) keyword(class string, text string) {
	lcw.startLine()
	lcw.sb.WriteString("\\textcolor{" + class + "}{" + latexCodeEscape(text) + "}")
}

func (lcw *latexCodeWriter) link(ref string, text string) {
	lcw.startLine()
	lcw.sb.WriteString("\\doxymbox{\\hyperlink{" + ref + "}{" + latexCodeEscape(text) + "}}")
}

// run tokenizes code similarly to the HTML highlighter (simplified: keywords + links).
func (lcw *latexCodeWriter) run(text string) {
	d := lcw.d
	src := []byte(text)
	n := len(src)
	i := 0
	var curScope *ClassDef
	pendingKind := ""
	if lcw.fd != nil {
		lcw.startLine()
	}
	for i < n {
		c := src[i]
		switch {
		case c == '\n':
			lcw.newline()
			i++
		case c == '/' && i+1 < n && src[i+1] == '/':
			j := i
			for j < n && src[j] != '\n' {
				j++
			}
			comment := string(src[i:j])
			isDoc := strings.HasPrefix(comment, "///") && !strings.HasPrefix(comment, "////") || strings.HasPrefix(comment, "//!")
			if !(isDoc && lcw.stripComments) {
				lcw.keyword("comment", comment)
			}
			i = j
		case c == '/' && i+1 < n && src[i+1] == '*':
			end := strings.Index(string(src[i+2:]), "*/")
			var comment string
			if end < 0 {
				comment = string(src[i:])
				i = n
			} else {
				comment = string(src[i : i+2+end+2])
				i += 2 + end + 2
			}
			isDoc := (strings.HasPrefix(comment, "/**") && !strings.HasPrefix(comment, "/**/")) || strings.HasPrefix(comment, "/*!")
			if isDoc && lcw.stripComments {
				nl := strings.Count(comment, "\n")
				atLineStart := true
				for k := i - len(comment) - 1; k >= 0; k-- {
					if src[k] == '\n' {
						break
					}
					if src[k] != ' ' && src[k] != '\t' {
						atLineStart = false
						break
					}
				}
				if atLineStart && i < n && src[i] == '\n' {
					i++
					nl++
					lcw.lineNr += nl
					lcw.endLine()
					lcw.startLine()
				} else {
					lcw.lineNr += nl
				}
			} else {
				parts := strings.Split(comment, "\n")
				for k, p := range parts {
					if k > 0 {
						lcw.newline()
					}
					if p != "" {
						lcw.keyword("comment", p)
					}
				}
			}
		case c == '#' && atLineStartBytes(src, i):
			j := i
			for j < n && src[j] != '\n' {
				j++
			}
			lcw.keyword("preprocessor", string(src[i:j]))
			i = j
		case c == '"':
			j := i + 1
			for j < n && src[j] != '"' && src[j] != '\n' {
				if src[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && src[j] == '"' {
				j++
			}
			lcw.keyword("stringliteral", string(src[i:j]))
			i = j
		case c == '\'':
			j := i + 1
			for j < n && src[j] != '\'' && src[j] != '\n' {
				if src[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && src[j] == '\'' {
				j++
			}
			lcw.keyword("charliteral", string(src[i:j]))
			i = j
		case isIdentStart(c):
			j := i
			for j < n && isIdentChar(src[j]) {
				j++
			}
			word := string(src[i:j])
			fullWord := word
			k := j
			for k+1 < n && src[k] == ':' && src[k+1] == ':' {
				m := k + 2
				for m < n && isIdentChar(src[m]) {
					m++
				}
				if m == k+2 {
					break
				}
				fullWord += "::" + string(src[k+2:m])
				k = m
			}
			switch {
			case word == "class" || word == "struct" || word == "union" || word == "enum" || word == "namespace":
				m := j
				for m < n && (src[m] == ' ' || src[m] == '\t') {
					m++
				}
				if m > j && m < n && isIdentStart(src[m]) {
					lcw.keyword("keyword", string(src[i:m]))
					j = m
				} else {
					lcw.keyword("keyword", word)
				}
				pendingKind = word
				i = j
				continue
			case cppFlowKeywords[word]:
				lcw.keyword("keywordflow", word)
			case cppTypeKeywords[word]:
				lcw.keyword("keywordtype", word)
			case cppKeywords[word]:
				lcw.keyword("keyword", word)
			default:
				linked := false
				if pendingKind == "class" || pendingKind == "struct" || pendingKind == "union" {
					if cd := d.resolveClassInNs(fullWord, lcw.fd, curScope); cd != nil {
						curScope = cd
						if cd.isLinkable(d) {
							lcw.link(cd.OutputBase, fullWord)
							linked = true
						}
					}
					pendingKind = ""
				} else {
					m := k
					for m < n && (src[m] == ' ' || src[m] == '\t') {
						m++
					}
					isCall := m < n && src[m] == '('
					if cd := d.resolveClassInNs(fullWord, lcw.fd, curScope); cd != nil && cd.isLinkable(d) {
						lcw.link(cd.OutputBase, fullWord)
						linked = true
					} else if isCall {
						if md := d.findMemberInScope(fullWord, curScope, lcw.fd, MemberFunction); md != nil && md.isLinkable(d) {
							lcw.link(md.outputFile(d)+"_"+md.Anchor, fullWord)
							linked = true
						}
					} else if md := d.findMemberInScope(fullWord, curScope, lcw.fd, MemberVariable); md != nil && md.isLinkable(d) {
						lcw.link(md.outputFile(d)+"_"+md.Anchor, fullWord)
						linked = true
					}
				}
				if !linked {
					lcw.codify(fullWord)
				}
				j = k
			}
			i = j
		case c == ';':
			pendingKind = ""
			lcw.codify(";")
			i++
		case c == '}':
			lcw.codify("}")
			i++
			// leaving a class scope (approximation)
			if curScope != nil && lcw.fd != nil && curScope.BodyEnd > 0 && lcw.lineNr >= curScope.BodyEnd {
				curScope = nil
			}
		default:
			lcw.codify(string(c))
			i++
		}
	}
	lcw.endLine()
}
