package main

import (
	"os"
	"path/filepath"
	"strings"
)

// updateObsolete applies the obsolete->new option mappings used by `-u`.
func (c *Config) updateObsolete() {
	if c.htmlTimestampSet || c.latexTimestampSet {
		v := c.htmlTimestamp
		if !c.htmlTimestampSet {
			v = c.latexTimestamp
		}
		if isTrueStr(v) {
			c.get("TIMESTAMP").Value = "YES"
		}
	}
	if c.classDiagramsSet && !isTrueStr(c.classDiagrams) {
		c.get("CLASS_GRAPH").Value = "TEXT"
	}
}

func cleanUpPaths(paths []string) []string {
	var out []string
	for _, p := range paths {
		if p == "" {
			continue
		}
		p = strings.ReplaceAll(p, "\\", "/")
		if st, err := os.Stat(p); err == nil && st.IsDir() {
			p = absPath(p)
		}
		if !strings.HasSuffix(p, "/") {
			p += "/"
		}
		out = append(out, p)
	}
	return out
}

// checkAndCorrect validates the configuration and fixes inconsistencies.
func (c *Config) checkAndCorrect(quiet bool) {
	for _, o := range c.opts {
		if o.Type == OptBool {
			o.convertStrToVal(quiet)
		}
	}
	if quiet {
		return
	}
	// WARN_FORMAT
	wf := c.get("WARN_FORMAT")
	if strings.TrimSpace(wf.Value) == "" {
		wf.Value = "$file:$line: $text"
	} else {
		if !strings.Contains(wf.Value, "$file") {
			warnUncond("warning format does not contain a $file tag!")
		}
		if !strings.Contains(wf.Value, "$line") {
			warnUncond("warning format does not contain a $line tag!")
		}
		if !strings.Contains(wf.Value, "$text") {
			warnUncond("warning format foes not contain a $text tag!")
		}
	}
	wlf := c.get("WARN_LINE_FORMAT")
	if strings.TrimSpace(wlf.Value) == "" {
		wlf.Value = "at line $line of file $file"
	} else {
		if !strings.Contains(wlf.Value, "$file") {
			warnUncond("warning line format does not contain a $file tag!")
		}
		if !strings.Contains(wlf.Value, "$line") {
			warnUncond("warning line format does not contain a $line tag!")
		}
	}
	// MAN_EXTENSION
	me := c.get("MAN_EXTENSION")
	if me.Value == "" {
		me.Value = ".3"
	}
	if !strings.HasPrefix(me.Value, ".") {
		me.Value = "." + me.Value
	}
	// HTML_FILE_EXTENSION
	hfe := c.get("HTML_FILE_EXTENSION")
	hfe.Value = strings.TrimSpace(hfe.Value)
	if hfe.Value == "" {
		hfe.Value = ".html"
	}
	// STRIP_FROM_PATH
	sfp := c.get("STRIP_FROM_PATH")
	if len(sfp.List) == 0 {
		cwd, _ := os.Getwd()
		sfp.List = []string{cwd + "/"}
	} else {
		sfp.List = cleanUpPaths(sfp.List)
	}
	sfip := c.get("STRIP_FROM_INC_PATH")
	sfip.List = cleanUpPaths(sfip.List)
	// header/footer files
	for _, name := range []string{"HTML_HEADER", "HTML_FOOTER", "LATEX_HEADER", "LATEX_FOOTER"} {
		f := c.Str(name)
		if f != "" && !fileExists(f) {
			kind := "header"
			if strings.HasSuffix(name, "FOOTER") {
				kind = "footer"
			}
			termMsg("tag %s: %s file '%s' does not exist\n", name, kind, f)
		}
	}
	for _, name := range []string{"HTML_EXTRA_STYLESHEET", "LATEX_EXTRA_STYLESHEET"} {
		for _, f := range c.List(name) {
			if f != "" && !fileExists(f) {
				termMsg("tag %s: style sheet '%s' does not exist\n", name, f)
			}
		}
	}
	for _, name := range []string{"HTML_EXTRA_FILES", "LATEX_EXTRA_FILES"} {
		for _, f := range c.List(name) {
			if f != "" && !fileExists(f) {
				termMsg("tag %s: extra file '%s' does not exist\n", name, f)
			}
		}
	}
	if logo := c.Str("PROJECT_LOGO"); logo != "" && !fileExists(logo) {
		warnUncond("tag PROJECT_LOGO: logo file '%s' does not exist", logo)
	}
	// INPUT
	in := c.get("INPUT")
	if len(in.List) == 0 {
		cwd, _ := os.Getwd()
		in.List = []string{cwd}
	} else {
		for _, s := range in.List {
			if _, err := os.Stat(s); err != nil {
				warnUncond("tag INPUT: input source '%s' does not exist", s)
			}
		}
	}
	// FILE_PATTERNS
	fp := c.get("FILE_PATTERNS")
	if len(fp.List) == 0 {
		fp.List = append([]string{}, fp.DefaultList...)
	}
	ep := c.get("EXAMPLE_PATTERNS")
	if len(ep.List) == 0 {
		ep.List = []string{"*"}
	}
	// MATHJAX
	if c.Bool("USE_MATHJAX") {
		mr := c.get("MATHJAX_RELPATH")
		if mr.Value == "" {
			switch c.Enum("MATHJAX_VERSION") {
			case "MathJax_3":
				mr.Value = "https://cdn.jsdelivr.net/npm/mathjax@3"
			case "MathJax_4":
				mr.Value = "https://cdn.jsdelivr.net/npm/mathjax@4"
			default:
				mr.Value = "https://cdn.jsdelivr.net/npm/mathjax@2"
			}
		}
		if !strings.HasSuffix(mr.Value, "/") {
			mr.Value += "/"
		}
	}
	// HTML help / treeview / search engine combinations
	if c.Bool("GENERATE_HTMLHELP") {
		if c.Bool("GENERATE_TREEVIEW") {
			warnUncond("When enabling GENERATE_HTMLHELP the tree view (GENERATE_TREEVIEW) should be disabled. I'll do it for you.")
			c.SetBool("GENERATE_TREEVIEW", false)
		}
		if c.Bool("SEARCHENGINE") {
			warnUncond("When enabling GENERATE_HTMLHELP the search engine (SEARCHENGINE) should be disabled. I'll do it for you.")
			c.SetBool("SEARCHENGINE", false)
		}
		if c.Bool("HTML_DYNAMIC_MENUS") {
			warnUncond("When enabling GENERATE_HTMLHELP the dynamic menus (HTML_DYNAMIC_MENUS) should be disabled. I'll do it for you.")
			c.SetBool("HTML_DYNAMIC_MENUS", false)
		}
	}
	if c.Bool("GENERATE_QHP") {
		if c.Str("QHP_NAMESPACE") == "" {
			warnUncond("GENERATE_QHP=YES requires QHP_NAMESPACE to be set. Using 'org.doxygen.doc' as default!")
			c.SetStr("QHP_NAMESPACE", "org.doxygen.doc")
		}
		if c.Str("QHP_VIRTUAL_FOLDER") == "" {
			warnUncond("GENERATE_QHP=YES requires QHP_VIRTUAL_FOLDER to be set. Using 'doc' as default!")
			c.SetStr("QHP_VIRTUAL_FOLDER", "doc")
		}
	}
	if c.Bool("OPTIMIZE_OUTPUT_JAVA") && c.Bool("INLINE_INFO") {
		c.SetBool("INLINE_INFO", false)
	}
	if c.Bool("HAVE_DOT") {
		dotPath := c.Str("DOT_PATH")
		dot := "dot"
		if dotPath != "" {
			dot = filepath.Join(dotPath, "dot")
		}
		if _, err := lookPath(dot); err != nil {
			if dotPath == "" {
				warnUncond("the dot tool could not be found as 'dot'")
			} else {
				warnUncond("the dot tool could not be found at %s", dot)
			}
			c.SetBool("HAVE_DOT", false)
		}
	}
	if c.Int("MAX_DOT_GRAPH_DEPTH") == 0 {
		c.SetInt("MAX_DOT_GRAPH_DEPTH", 1000)
	}
	if c.Bool("EXTRACT_ALL") && c.Bool("WARN_IF_UNDOCUMENTED") {
		// WARN_IF_UNDOCUMENTED is implicitly disabled when EXTRACT_ALL is set
	}
	if !c.Bool("GENERATE_HTML") {
		if c.Bool("GENERATE_HTMLHELP") || c.Bool("GENERATE_DOCSET") || c.Bool("GENERATE_QHP") || c.Bool("GENERATE_ECLIPSEHELP") || c.Bool("GENERATE_TREEVIEW") || c.Bool("SEARCHENGINE") {
			// silently ignored
		}
	}
	for _, bib := range c.List("CITE_BIB_FILES") {
		if bib == "" {
			continue
		}
		b := bib
		if !strings.HasSuffix(b, ".bib") {
			b += ".bib"
		}
		if !fileExists(b) && !fileExists(bib) {
			warnUncond("bib file %s not found!", bib)
		}
	}
}

func lookPath(name string) (string, error) {
	if strings.Contains(name, "/") {
		if fileExists(name) {
			return name, nil
		}
		return "", os.ErrNotExist
	}
	for _, dir := range strings.Split(os.Getenv("PATH"), ":") {
		p := filepath.Join(dir, name)
		if fileExists(p) {
			return p, nil
		}
	}
	return "", os.ErrNotExist
}
