new='''func (h *HtmlGenerator) writeNavTree() {
	d := h.d
	tree := d.buildNavTree(true)
	projectName := d.cfg.Str("PROJECT_NAME")
	var sb strings.Builder
	sb.WriteString(jsLicense)
	sb.WriteString("var NAVTREE =\\n[\\n")
	sb.WriteString("  [ \\"" + convertToJSString(projectName) + "\\", \\"index" + h.ext + "\\", ")
	// url -> path index (the deepest/last occurrence wins)
	index := map[string][]int{}
	index["index"+h.ext] = []int{}
	index["pages"+h.ext] = []int{}
	var subFiles []*navEntry
	var collectSub func(entries []*navEntry)
	collectSub = func(entries []*navEntry) {
		for _, e := range entries {
			if e.jsFile != "" && len(e.children) > 0 {
				subFiles = append(subFiles, e)
			}
			collectSub(e.children)
		}
	}
	var writeEntries func(entries []*navEntry, indent string) string
	writeEntries = func(entries []*navEntry, indent string) string {
		var b strings.Builder
		for i, e := range entries {
			b.WriteString(indent + "[ \\"" + convertToJSString(e.text) + "\\", \\"" + e.url + "\\", ")
			if len(e.children) > 0 {
				if e.jsFile != "" {
					b.WriteString("\\"" + e.jsFile + "\\" ]")
				} else {
					b.WriteString("[\\n")
					b.WriteString(writeEntries(e.children, indent+"  "))
					b.WriteString(indent + "] ]")
				}
			} else {
				b.WriteString("null ]")
			}
			if i < len(entries)-1 {
				b.WriteString(",\\n")
			} else {
				b.WriteString("\\n")
			}
		}
		return b.String()
	}
	if len(tree) > 1 {
		h.registerIndexPaths(tree[1:], []int{}, index)
		collectSub(tree[1:])
		sb.WriteString("[\\n")
		sb.WriteString(writeEntries(tree[1:], "    "))
		sb.WriteString("  ] ]\\n")
	} else {
		sb.WriteString("]\\n")
	}
	sb.WriteString("];\\n\\n")
	urls := make([]string, 0, len(index))
	for u := range index {
		urls = append(urls, u)
	}
	sort.Strings(urls)
	const chunkSize = 250
	var chunks [][]string
	for i := 0; i < len(urls); i += chunkSize {
		end := i + chunkSize
		if end > len(urls) {
			end = len(urls)
		}
		chunks = append(chunks, urls[i:end])
	}
	sb.WriteString("var NAVTREEINDEX =\\n[\\n")
	for i, c := range chunks {
		sb.WriteString("\\"" + c[0] + "\\"")
		if i < len(chunks)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\\n")
	}
	sb.WriteString("];\\n\\n")
	sb.WriteString("const SYNCONMSG = 'click to disable panel synchronization';\\n")
	sb.WriteString("const SYNCOFFMSG = 'click to enable panel synchronization';\\n")
	sb.WriteString("const LISTOFALLMEMBERS = 'List of all members';")
	h.writeFile("navtreedata.js", sb.String())
	for i, c := range chunks {
		var cb strings.Builder
		cb.WriteString("var NAVTREEINDEX" + intToStr(i) + " =\\n{\\n")
		for j, u := range c {
			cb.WriteString("\\"" + u + "\\":[")
			p := index[u]
			for k, v := range p {
				if k > 0 {
					cb.WriteString(",")
				}
				cb.WriteString(intToStr(v))
			}
			cb.WriteString("]")
			if j < len(c)-1 {
				cb.WriteString(",")
			}
			cb.WriteString("\\n")
		}
		cb.WriteString("};\\n")
		h.writeFile("navtreeindex"+intToStr(i)+".js", cb.String())
	}
	for _, sf := range subFiles {
		var fb strings.Builder
		fb.WriteString("var " + sf.jsFile + " =\\n[\\n")
		fb.WriteString(writeEntries(sf.children, "    "))
		fb.WriteString("];")
		h.writeFile(sf.jsFile+".js", fb.String())
	}
	h.writeFile("navtree.js", resNavtreeJs)
}

