/**
 * @file shapes.h
 * @brief Geometric shapes.
 *
 * This file contains the shape hierarchy used by the
 * example. See also @ref Shape and util::clamp().
 */
#ifndef SHAPES_H
#define SHAPES_H

#include <string>
#include <vector>
#include "util.h"

/// Maximum number of shapes.
#define MAX_SHAPES 100

/** Compute the square of a value. */
#define SQUARE(x) ((x)*(x))

namespace geo {

/**
 * @brief Color of a shape.
 */
enum class Color {
  Red,    ///< The color red.
  Green,  ///< The color green.
  Blue    ///< The color blue.
};

/// A plain enum.
enum Kind { CIRCLE = 1, SQUARE = 2 };

/// Type for coordinates.
typedef double coord_t;

/// Alias for a list of coordinates.
using CoordList = std::vector<coord_t>;

/**
 * @brief Abstract base class for all shapes.
 *
 * Shapes have an area and a *name*. Use `area()` to compute it.
 *
 * Example:
 * @code
 * geo::Circle c(2.0);
 * double a = c.area();
 * @endcode
 *
 * @note This class is abstract.
 * @see Circle, Square
 */
class Shape {
public:
  /// Constructor.
  explicit Shape(const std::string &name);
  /// Destructor.
  virtual ~Shape();

  /**
   * Computes the area of the shape.
   * @return the area
   */
  virtual double area() const = 0;

  /**
   * Returns the name.
   * @param[in] upper if true the name is converted to upper case
   * @param[out] len receives the length
   * @return the name
   * @throws std::runtime_error when the name is empty
   */
  std::string name(bool upper = false, int *len = nullptr) const;

  /** Sets the color. */
  void setColor(Color c) { color_ = c; }

  /// Gets the color.
  Color color() const { return color_; }

  static int count();  ///< Number of shapes created.

protected:
  std::string name_; ///< The name of the shape.
  Color color_ = Color::Red; ///< The color.
private:
  int id_;
};

/**
 * @brief A circle.
 */
class Circle : public Shape {
public:
  /// Creates a circle with the given radius.
  Circle(double r);
  double area() const override;
  /// The radius.
  double radius;
};

/** A square with side length `side`. */
struct Square : public Shape {
  double side; ///< Side length.
  Square(double s);
  double area() const override;
};

/**
 * Creates a shape by kind.
 * @param k the kind
 * @param size the size
 * @return a new shape or @c nullptr
 */
Shape *createShape(Kind k, double size);

/// A global counter.
extern int g_counter;

} // namespace geo

#endif
