/** @file util.h
 *  Utility functions.
 */
#pragma once

namespace util {

/**
 * @brief Clamps a value.
 *
 * - works for any comparable type
 * - returns the clamped value
 *
 * 1. first
 * 2. second
 *
 * @tparam T the value type
 * @param v the value
 * @param lo lower bound
 * @param hi upper bound
 * @return the clamped value
 */
template<typename T>
T clamp(T v, T lo, T hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}

/**
 * A pair of values.
 * @tparam A first type
 * @tparam B second type
 */
template<typename A, typename B>
struct Pair {
  A first;  ///< first value
  B second; ///< second value
};

/// Prints a message. **bold** and _italic_ markdown.
void print(const char *msg);

}
