#include "shapes.h"
#include <cmath>

namespace geo {

int g_counter = 0;
static int s_count = 0;

Shape::Shape(const std::string &name) : name_(name), id_(s_count++) {}
Shape::~Shape() {}

std::string Shape::name(bool upper, int *len) const {
  if (len) *len = (int)name_.size();
  return name_;
}

int Shape::count() { return s_count; }

Circle::Circle(double r) : Shape("circle"), radius(r) {}

/// Computes pi r squared.
double Circle::area() const { return M_PI * radius * radius; }

Square::Square(double s) : Shape("square"), side(s) {}
double Square::area() const { return side * side; }

Shape *createShape(Kind k, double size) {
  switch (k) {
    case CIRCLE: return new Circle(size);
    case SQUARE: return new Square(size);
  }
  return nullptr;
}

} // namespace geo
