// parseInline parses paragraph content into node until stop returns true.
func (p *docParser) parseInline(node *DocNode, stop func(*docToken) bool) {
	for !p.atEnd() {
		t := p.peek()
		if stop(t) {
			return
		}
		switch t.kind {
		case tkWord:
			p.next()
			p.addWord(node, t.text)
		case tkWhitespace, tkNewline:
			p.next()
			addWhitespace(node)
		case tkEntity:
			p.next()
			sym := node.add(newDocNode(DocSymbol))
			sym.Text = t.text
		case tkRawText:
			p.next()
			r := node.add(newDocNode(DocHtmlRaw))
			r.Text = t.text
		case tkListItem:
			dropTrailingWhitespace(node)
			p.parseAutoList(node, stop)
		case tkHtmlTag:
			if !t.close {
				switch t.tag {
				case "ul", "ol":
					p.parseHtmlList(node)
					continue
				case "dl":
					p.parseHtmlDescList(node)
					continue
				case "table":
					p.parseHtmlTable(node)
					continue
				case "pre":
					p.parseHtmlPre(node)
					continue
				case "h1", "h2", "h3", "h4", "h5", "h6":
					p.parseHtmlHeader(node)
					continue
				case "hr":
					p.next()
					node.add(newDocNode(DocHorRuler))
					continue
				case "blockquote":
					p.parseBlockQuote(node)
					continue
				case "details":
					p.parseDetails(node)
					continue
				}
			}
			p.next()
			p.handleInlineHtmlTag(node, t, stop)
		case tkCommand:
			switch t.cmd {
			case "code", "verbatim", "dot", "msc", "startuml", "htmlonly", "latexonly", "xmlonly", "manonly", "rtfonly", "docbookonly", "f[", "f{", "iliteral":
				p.parseVerbatim(node)
				continue
			case "li", "arg":
				p.parseSimpleList(node, stop)
				continue
			case "parblock":
				p.next()
				pb := node.add(newDocNode(DocParBlock))
				p.parseBlocks(pb, func(tt *docToken) bool { return tt.kind == tkCommand && tt.cmd == "endparblock" })
				if p.peek().kind == tkCommand && p.peek().cmd == "endparblock" {
					p.next()
				}
				continue
			case "tableofcontents":
				p.next()
				p.skipLineArgs()
				node.add(newDocNode(DocTocList))
				continue
			case "secreflist":
				p.next()
				sl := node.add(newDocNode(DocSecRefList))
				for !p.atEnd() {
					tt := p.peek()
					if tt.kind == tkCommand && tt.cmd == "endsecreflist" {
						p.next()
						break
					}
					if tt.kind == tkCommand && tt.cmd == "refitem" {
						p.next()
						p.skipWhitespace()
						target := p.readWord()
						item := sl.add(newDocNode(DocSecRefItem))
						item.Text = target
						item.Target = p.ctx.d.resolveLink(target, p.ctx)
						title := p.readRestOfLine()
						item.Attrs["title"] = strings.TrimSpace(title)
						continue
					}
					p.next()
				}
				continue
			}
			p.next()
			p.handleInlineCommand(node, t, stop)
		default:
			p.next()
		}
	}
}

func (p *docParser) addWord(node *DocNode, text string) {
	// autolinking
	if p.ctx.d.cfg.Bool("AUTOLINK_SUPPORT") && p.inPre == 0 {
		if ln := p.ctx.d.autoLinkWord(text, p.ctx); ln != nil {
			node.add(ln)
			return
		}
	}
	w := node.add(newDocNode(DocWord))
	w.Text = text
}

func (p *docParser) handleInlineHtmlTag(node *DocNode, t *docToken, stop func(*docToken) bool) {
	if t.close {
		return // unmatched closing tag: ignore
	}
	switch t.tag {
	case "br":
		node.add(newDocNode(DocLineBreak))
	case "a":
		a := newDocNode(DocURL)
		if href, ok := t.attrs["href"]; ok {
			a.Kind = DocURL
			a.Text = href
			a.Attrs["href"] = href
			node.add(a)
			p.parseInline(a, func(tt *docToken) bool { return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == "a" && tt.close) })
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if name, ok := t.attrs["name"]; ok {
			a.Kind = DocAnchor
			a.Text = name
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		} else if id, ok := t.attrs["id"]; ok {
			a.Kind = DocAnchor
			a.Text = id
			node.add(a)
			if p.peek().kind == tkHtmlTag && p.peek().tag == "a" && p.peek().close {
				p.next()
			}
		}
	case "img":
		img := node.add(newDocNode(DocImage))
		img.Attrs = t.attrs
		img.Text = t.attrs["src"]
		img.Attrs["html"] = "1"
	case "p":
		// handled as paragraph break by caller
	default:
		if style, ok := inlineStyleTags[t.tag]; ok {
			s := newDocNode(DocStyle)
			s.Attrs["style"] = style
			s.Attrs["tag"] = t.tag
			for k, v := range t.attrs {
				s.Attrs["attr:"+k] = v
			}
			node.add(s)
			if t.selfClose {
				return
			}
			p.parseInline(s, func(tt *docToken) bool {
				return stop(tt) || (tt.kind == tkHtmlTag && tt.tag == t.tag && tt.close)
			})
			if p.peek().kind == tkHtmlTag && p.peek().tag == t.tag && p.peek().close {
				p.next()
			}
			return
		}
		r := node.add(newDocNode(DocHtmlRaw))
		r.Text = t.text
	}
}

func (p *docParser) handleInlineCommand(node *DocNode, t *docToken, stop func(*docToken) bool) {
	cmd := t.cmd
	switch cmd {
	case "n":
		node.add(newDocNode(DocLineBreak))
	case "a", "e", "em":
		p.styledWord(node, "italic")
	case "b":
		p.styledWord(node, "bold")
	case "c", "p":
		p.styledWord(node, "code")
	case "ref", "refitem":
		p.parseRef(node, false)
	case "link":
		p.parseLink(node)
	case "endlink":
	case "anchor":
		name := p.readWord()
		a := node.add(newDocNode(DocAnchor))
		a.Text = name
	case "cite":
		name := p.readWord()
		c := node.add(newDocNode(DocCite))
		c.Text = name
	case "emoji":
		name := p.readWord()
		e := node.add(newDocNode(DocEmoji))
		e.Text = strings.Trim(name, ":")
	case "copybrief", "copydetails", "copydoc":
		name := p.readWord()
		c := node.add(newDocNode(DocCopy))
		c.Text = name
		c.Attrs["kind"] = cmd
	case "f$":
		var sb strings.Builder
		for !p.atEnd() {
			tt := p.next()
			if tt.kind == tkCommand && tt.cmd == "f$" {
				break
			}
			sb.WriteString(tt.text)
		}
		f := node.add(newDocNode(DocFormula))
		f.Text = "$" + sb.String() + "$"
		f.Flag = true
	case "image":
		p.parseImage(node)
	case "dotfile", "mscfile", "diafile", "plantumlfile":
		p.skipWhitespace()
		name := p.readQuotedOrWord()
		caption := strings.TrimSpace(p.readRestOfLine())
		n := node.add(newDocNode(DocDotFile))
		n.Text = name
		n.Attrs["kind"] = cmd
		n.Attrs["caption"] = caption
	case "include", "dontinclude", "verbinclude", "htmlinclude", "latexinclude", "snippet", "snippetlineno", "includelineno", "includedoc", "snippetdoc", "rtfinclude", "maninclude", "docbookinclude", "xmlinclude":
		p.parseInclude(node, cmd)
	case "skip", "skipline", "until", "line":
		p.readRestOfLine()
	case "xrefitem":
		p.skipWhitespace()
		key := p.readWord()
		heading := p.readQuotedOrWord()
		title := p.readQuotedOrWord()
		x := node.add(newDocNode(DocXRefItem))
		x.Attrs["key"] = key
		x.Attrs["heading"] = heading
		x.Attrs["title"] = title
		x.Text = title
		para := x.add(newDocNode(DocPara))
		p.parseInline(para, p.sectStop(stop))
		trimTrailingWhitespace(para)
	case "param", "tparam", "retval", "exception", "throw", "throws":
		p.parseParamSect(node, cmd, stop)
	case "~", "&", "$", "#", "<", ">", "%", "\"", ".", "::", "|", "--", "---", "\\", "@", "=":
		if cmd == "~" {
			lang := p.readWord()
			_ = lang
			return
		}
		w := node.add(newDocNode(DocWord))
		w.Text = cmd
	case "showdate":
		p.readRestOfLine()
	case "ifile", "iline", "ianchor", "iprefix", "ilinebr", "ilinebr_i", "isection":
		p.readRestOfLine()
	case "showinitializer", "hideinitializer", "callgraph", "callergraph", "hidecallgraph", "hidecallergraph", "showrefby", "hiderefby", "showrefs", "hiderefs", "nosubgrouping", "static", "pure", "private", "protected", "public":
	case "brief", "short", "details":
	case "endcode", "endverbatim", "endhtmlonly", "endlatexonly", "endxmlonly", "endmanonly", "endrtfonly", "enddocbookonly", "enddot", "endmsc", "enduml", "f]", "f}", "endiliteral":
	case "if", "ifnot", "elseif", "else", "endif":
		p.handleIf(node, cmd, stop)
	case "cond", "endcond":
		p.readRestOfLine()
	default:
		if _, ok := simpleSectTitles[cmd]; ok {
			p.parseSimpleSect(node, cmd, stop)
			return
		}
		warnDocErr(p.ctx.file, p.ctx.line, "Found unknown command '\\%s'", cmd)
	}
}

// sectStop: tokens that end the description of a simple/param section.
func (p *docParser) sectStop(stop func(*docToken) bool) func(*docToken) bool {
	return func(t *docToken) bool {
		if stop(t) {
			return true
		}
		if isParaEnd(t) || t.kind == tkListItem {
			return true
		}
		if t.kind == tkCommand {
			switch t.cmd {
			case "param", "tparam", "retval", "exception", "throw", "throws", "li", "arg", "xrefitem", "parblock", "endparblock", "secreflist", "tableofcontents":
				return true
			}
			if _, ok := simpleSectTitles[t.cmd]; ok {
				return true
			}
		}
		if t.kind == tkHtmlTag && !t.close {
			switch t.tag {
			case "ul", "ol", "dl", "table", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "blockquote":
				return true
			}
		}
		return false
	}
}

func (p *docParser) handleIf(node *DocNode, cmd string, stop func(*docToken) bool) {
	switch cmd {
	case "if", "ifnot":
		expr := p.readWord()
		enabled := p.ctx.d.sectionEnabled(expr)
		if cmd == "ifnot" {
			enabled = !enabled
		}
		if enabled {
			return
		}
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				case "else":
					if depth == 0 {
						return
					}
				case "elseif":
					if depth == 0 {
						e := p.readWord()
						if p.ctx.d.sectionEnabled(e) {
							return
						}
					}
				}
			}
		}
	case "else", "elseif":
		if cmd == "elseif" {
			p.readWord()
		}
		depth := 0
		for !p.atEnd() {
			t := p.next()
			if t.kind == tkCommand {
				switch t.cmd {
				case "if", "ifnot":
					depth++
				case "endif":
					if depth == 0 {
						return
					}
					depth--
				}
			}
		}
	case "endif":
	}
}

