func (p *docParser) listItemStop(indent int, stop func(*docToken) bool) func(*docToken) bool {
	return func(t *docToken) bool {
		if stop != nil && stop(t) {
			return true
		}
		if isParaEnd(t) || t.kind == tkListItem || t.kind == tkEndList {
			return true
		}
		if t.kind == tkHtmlTag && t.close {
			switch t.tag {
			case "li", "ul", "ol", "dd", "td", "th", "tr", "table", "dl", "blockquote", "details":
				return true
			}
		}
		return false
	}
}

// parseAutoList parses markdown-style '-' / '1.' lists; the list becomes a child of node.
func (p *docParser) parseAutoList(node *DocNode, stop func(*docToken) bool) {
	first := p.peek()
	indent := first.indent
	list := node.add(newDocNode(DocAutoList))
	list.Ordered = first.ordered
	num := 1
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkListItem || t.indent != indent || t.ordered != list.Ordered {
			break
		}
		p.next()
		item := list.add(newDocNode(DocAutoListItem))
		item.Num = num
		num++
		p.parseListItemBody(item, indent, stop)
		// nested list?
		if nt := p.peek(); nt.kind == tkListItem && nt.indent > indent {
			lastPara := item.Children[len(item.Children)-1]
			dropTrailingWhitespace(lastPara)
			p.parseAutoList(lastPara, stop)
			// continuation text after a nested list belongs to the item paragraph
			p.parseInline(lastPara, p.listItemStop(indent, stop))
			trimTrailingWhitespace(lastPara)
		}
		if p.peek().kind == tkEndList {
			p.next()
			break
		}
	}
	if len(list.Children) == 0 {
		node.Children = node.Children[:len(node.Children)-1]
	}
}

// parseListItemBody parses the paragraph(s) of a list item.
func (p *docParser) parseListItemBody(item *DocNode, indent int, stop func(*docToken) bool) {
	para := item.add(newDocNode(DocPara))
	p.parseInlineInList(para, indent, stop)
	trimTrailingWhitespace(para)
	// a blank line followed by text indented deeper than the marker continues the item
	for p.peek().kind == tkParaBreak {
		save := p.tpos
		p.next()
		nt := p.peek()
		if nt.kind == tkWhitespace && nt.indent > indent {
			np := item.add(newDocNode(DocPara))
			p.parseInlineInList(np, indent, stop)
			trimTrailingWhitespace(np)
			if len(np.Children) == 0 {
				item.Children = item.Children[:len(item.Children)-1]
			}
			continue
		}
		p.tpos = save
		break
	}
}

// parseInlineInList parses inline content of a list item, stopping when a line starts at an
// indentation less than or equal to the list marker (end of list).
func (p *docParser) parseInlineInList(para *DocNode, indent int, stop func(*docToken) bool) {
	itemStop := p.listItemStop(indent, stop)
	for !p.atEnd() {
		t := p.peek()
		if itemStop(t) {
			return
		}
		if t.kind == tkNewline {
			// check the indentation of the next line
			nt := &p.toks[p.tpos+1]
			lineIndent := 0
			if nt.kind == tkWhitespace {
				lineIndent = nt.indent
			}
			if nt.kind == tkListItem || nt.kind == tkParaBreak || nt.kind == tkEnd {
				p.next()
				addWhitespace(para)
				continue
			}
			if lineIndent <= indent {
				// end of the list: the text continues the enclosing paragraph
				p.next()
				p.toks = append(p.toks[:p.tpos], append([]docToken{{kind: tkEndList}}, p.toks[p.tpos:]...)...)
				return
			}
		}
		p.parseInlineStep(para, itemStop)
	}
}

// parseInlineStep processes exactly one inline token (or construct).
func (p *docParser) parseInlineStep(node *DocNode, stop func(*docToken) bool) {
	start := p.tpos
	// parseInline until one construct has been consumed
	p.parseInline(node, func(t *docToken) bool {
		if p.tpos > start {
			return true
		}
		return stop(t)
	})
}

// parseSimpleList parses \li / \arg items; the list becomes a child of node.
func (p *docParser) parseSimpleList(node *DocNode, stop func(*docToken) bool) {
	list := node.add(newDocNode(DocSimpleList))
	for !p.atEnd() {
		t := p.peek()
		if t.kind != tkCommand || (t.cmd != "li" && t.cmd != "arg") {
			break
		}
		p.next()
		item := list.add(newDocNode(DocSimpleListItem))
		para := item.add(newDocNode(DocPara))
		p.parseInline(para, func(tt *docToken) bool {
			if stop != nil && stop(tt) {
				return true
			}
			if isParaEnd(tt) || tt.kind == tkListItem {
				return true
			}
			if tt.kind == tkCommand && (tt.cmd == "li" || tt.cmd == "arg") {
				return true
			}
			return false
		})
		trimTrailingWhitespace(para)
	}
}

