package main

import (
	"sort"
	"strings"
)

// matchPath checks whether path is a prefix of one of the given paths (case insensitive).
func matchPath(path string, list []string) bool {
	for _, s := range list {
		if len(s) >= len(path) && strings.EqualFold(s[:len(path)], path) {
			return true
		}
	}
	return false
}

// buildDirectories creates the directory tree for the input files (doxygen algorithm).
func (d *Doxygen) buildDirectories() {
	dirMap := map[string]*DirDef{}
	strip := d.cfg.List("STRIP_FROM_PATH")
	createDir := func(path string) *DirDef {
		if dd, ok := dirMap[path]; ok {
			return dd
		}
		dd := &DirDef{Path: path}
		dd.Name = path
		dd.QualName = path
		disp := d.stripFromPath(path)
		if len(disp) > 1 && strings.HasSuffix(disp, "/") {
			disp = disp[:len(disp)-1]
		}
		dd.DispName = disp
		short := strings.TrimSuffix(path, "/")
		if i := strings.LastIndex(short, "/"); i >= 0 {
			short = short[i+1:]
		}
		dd.ShortName = short
		dirMap[path] = dd
		d.dirs = append(d.dirs, dd)
		return dd
	}
	for _, fd := range d.files {
		path := fd.Path
		var dir *DirDef
		p := 0
		for {
			i := strings.IndexByte(path[p:], '/')
			if i < 0 {
				break
			}
			part := path[:p+i+1]
			if !matchPath(part, strip) && part != "/" && part != "//" {
				dir = createDir(part)
			}
			p = p + i + 1
		}
		if dir != nil && !fd.IsDocFile {
			dir.Files = append(dir.Files, fd)
		}
		if dir != nil {
			fd.DirDef = dir
		}
	}
	sort.Slice(d.dirs, func(i, j int) bool { return d.dirs[i].Path < d.dirs[j].Path })
	for _, dd := range d.dirs {
		name := dd.Path
		i := strings.LastIndex(name[:len(name)-1], "/")
		if i > 0 {
			if parent, ok := dirMap[name[:i+1]]; ok {
				dd.Parent = parent
				parent.SubDirs = append(parent.SubDirs, dd)
			}
		}
	}
	for _, dd := range d.dirs {
		level := 0
		for p := dd.Parent; p != nil; p = p.Parent {
			level++
		}
		dd.Level = level
	}
}

// generateDirDocs writes the directory pages.
func (d *Doxygen) generateDirDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, dd := range d.dirs {
		msg("Generating docs for directory %s\n", dd.DispName)
		if h != nil {
			h.writeDirPage(dd)
		}
	}
}

func (dd *DirDef) navPath(h *HtmlGenerator) []navItem {
	var items []navItem
	for p := dd; p != nil; p = p.Parent {
		items = append([]navItem{{text: p.ShortName, url: p.OutputBase + h.ext}}, items...)
	}
	return items
}

func (h *HtmlGenerator) writeDirPage(dd *DirDef) {
	d := h.d
	title := dd.DispName + " Directory Reference"
	p := h.newPage(dd.OutputBase, title, "")
	p.hasOutline = true
	p.writeHeader(title, "", true)
	p.w("<div class=\"header\">\n")
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + htmlEscape(title) + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
	if dd.Doc.Brief != "" {
		p.w("\n<p>")
		bctx := &DocContext{d: d, scope: dd, singleLine: true}
		p.w(d.docToHtml(d.parseDocText(bctx, dd.Doc.Brief), bctx, ""))
		p.w(" \n<a href=\"#details\">More...</a></p>\n")
	}
	if len(dd.SubDirs) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-subdirs\" class=\"groupheader\"><a id=\"subdirs\" name=\"subdirs\"></a>\nDirectories</h2></td></tr>\n")
		for _, sub := range dd.SubDirs {
			p.w("<tr class=\"memitem:" + sub.OutputBase + "\" id=\"r_" + sub.OutputBase + "\"><td class=\"memItemLeft\">directory&#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + sub.OutputBase + h.ext + "\">" + htmlEscape(sub.ShortName) + "</a></td></tr>\n")
			if sub.Doc.Brief != "" {
				bctx := &DocContext{d: d, scope: sub, singleLine: true}
				p.w("<tr class=\"memdesc:" + sub.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.docToHtml(d.parseDocText(bctx, sub.Doc.Brief), bctx, "") + "<br /></td></tr>\n")
			}
		}
		p.w("</table>\n")
	}
	var files []*FileDef
	for _, fd := range dd.Files {
		if fd.isLinkable(d) {
			files = append(files, fd)
		}
	}
	if len(files) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-files\" class=\"groupheader\"><a id=\"files\" name=\"files\"></a>\nFiles</h2></td></tr>\n")
		for _, fd := range files {
			p.w("<tr class=\"memitem:" + fd.OutputBase + "\" id=\"r_" + fd.OutputBase + "\"><td class=\"memItemLeft\">file &#160;</td><td class=\"memItemRight\">")
			p.w("<a class=\"el\" href=\"" + fd.OutputBase + h.ext + "\">" + htmlEscape(fd.Name) + "</a>")
			if fd.HasSource {
				p.w(" <a href=\"" + fd.OutputBase + "_source" + h.ext + "\">[code]</a>")
			}
			p.w("</td></tr>\n")
			if fd.Doc.Brief != "" {
				bctx := &DocContext{d: d, scope: fd, singleLine: true}
				p.w("<tr class=\"memdesc:" + fd.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.docToHtml(d.parseDocText(bctx, fd.Doc.Brief), bctx, "") + "<br /></td></tr>\n")
			}
		}
		p.w("</table>\n")
	}
	if dd.Doc.Doc != "" || (dd.Doc.Brief != "" && d.cfg.Bool("REPEAT_BRIEF")) {
		p.w("<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
		p.w("<div class=\"textblock\">")
		ctx := &DocContext{d: d, scope: dd}
		h.writeDetailedDocBody(p, &dd.Doc, ctx, dd.DispName, nil)
		p.w("</div>")
	}
	p.endContents()
	p.writeFooter(h.navPathItems(dd.navPath(h)))
	p.finish()
}
