func (d *Doxygen) warnIfUndocumented(md *MemberDef, scope interface{}) {
	if md.warnedUndoc {
		return
	}
	md.warnedUndoc = true
	if d.cfg.Bool("EXTRACT_ALL") || !warnIfUndoc {
		return
	}
	var t, name string
	switch s := scope.(type) {
	case *ClassDef:
		t = s.CompoundType
		name = s.QualName
	case *NamespaceDef:
		t = "namespace"
		name = s.QualName
	case *FileDef:
		t = "file"
		name = s.Name
		if md.Namespace != nil {
			t = "namespace"
			name = md.Namespace.QualName
		}
	case *GroupDef:
		t = "group"
		name = s.Name
	default:
		return
	}
	if md.Kind == MemberEnumValue {
		return
	}
	if !md.Doc.hasDocs() && !(md.Kind == MemberFriend && strings.HasPrefix(md.Type, "friend class")) &&
		!strings.Contains(md.Name, "@") && !strings.Contains(name, "@") && d.protectionVisible(md.Prot) && !md.Delete {
		args := ""
		if md.Kind == MemberFunction {
			args = md.Args
		}
		warn(md.File, md.Line, "Member %s%s (%s) of %s %s is not documented.", md.Name, args, memberTypeName(md), t, name)
	} else {
		d.warnIfUndocumentedParams(md)
	}
	if md.Kind == MemberEnum && d.cfg.Bool("WARN_IF_UNDOC_ENUM_VAL") {
		for _, ev := range md.EnumValues {
			if !ev.Doc.hasDocs() {
				warn(ev.File, ev.Line, "Documentation for enum member '%s::%s' is missing.", md.QualName, ev.Name)
			}
		}
	}
}

// warnIfUndocumentedParams checks for missing parameter/return documentation (WARN_NO_PARAMDOC).
func (d *Doxygen) warnIfUndocumentedParams(md *MemberDef) {
	if md.Kind != MemberFunction || !warnNoParam || md.Delete {
		return
	}
	if md.ArgList == nil {
		return
	}
	docText := md.Doc.Brief + "\n" + md.Doc.Doc + "\n" + md.Doc.InBody
	hasParamDocs := strings.Contains(docText, "\\param") || strings.Contains(docText, "@param")
	hasArgs := false
	for _, a := range md.ArgList.Args {
		if a.Name != "" && a.Type != "void" && a.Type != "..." {
			hasArgs = true
		}
		if a.Docs != "" {
			hasParamDocs = true
		}
	}
	if hasArgs && !hasParamDocs && md.Doc.hasDocs() {
		warnDocErr(md.Doc.DocFile, md.Doc.DocLine, "parameters of member %s are not documented", md.QualName)
	}
	hasReturnDocs := strings.Contains(docText, "\\return") || strings.Contains(docText, "@return") || strings.Contains(docText, "\\retval") || strings.Contains(docText, "@retval")
	rt := strings.TrimSpace(md.Type)
	if !hasReturnDocs && md.Doc.hasDocs() && rt != "" && rt != "void" && !strings.HasSuffix(rt, " void") && !md.IsCtor && !md.IsDtor && rt != "virtual void" && rt != "static void" && rt != "inline void" {
		warnDocErr(md.Doc.DocFile, md.Doc.DocLine, "return type of member %s is not documented", md.QualName)
	}
}

// checkParamDocs warns about parameters not documented by @param (WARN_IF_INCOMPLETE_DOC).
func (d *Doxygen) checkParamDocs(md *MemberDef, root *DocNode, ctx *DocContext) {
	if md == nil || md.paramsChecked || md.Kind != MemberFunction || md.ArgList == nil {
		return
	}
	md.paramsChecked = true
	if !d.cfg.Bool("WARN_IF_INCOMPLETE_DOC") || d.cfg.Bool("EXTRACT_ALL") && false {
		return
	}
	// collect documented parameter names
	documented := map[string]int{}
	var walk func(n *DocNode)
	walk = func(n *DocNode) {
		if n.Kind == DocParamSect && n.Attrs["type"] == "param" {
			for _, item := range n.Children {
				for _, nm := range item.Names {
					documented[nm]++
				}
			}
		}
		for _, c := range n.Children {
			walk(c)
		}
	}
	walk(root)
	if len(documented) == 0 {
		return
	}
	for nm, cnt := range documented {
		if cnt > 1 {
			warnDocErr(ctx.file, ctx.line, "argument '%s' from the argument list of %s has multiple @param documentation sections", nm, md.QualName)
		}
	}
	var undoc []string
	for _, a := range md.ArgList.Args {
		if a.Name == "" || a.Type == "void" || a.Type == "..." {
			continue
		}
		if documented[a.Name] == 0 && a.Docs == "" {
			undoc = append(undoc, a.Name)
		}
	}
	if len(undoc) > 0 {
		var sb strings.Builder
		sb.WriteString("The following parameter")
		if len(undoc) > 1 {
			sb.WriteString("s")
		}
		sb.WriteString(" of " + md.QualName + md.Args)
		if len(undoc) > 1 {
			sb.WriteString(" are not documented:")
		} else {
			sb.WriteString(" is not documented:")
		}
		for _, u := range undoc {
			sb.WriteString("\n  parameter '" + u + "'")
		}
		warnDocErr(ctx.file, ctx.line, "%s", sb.String())
	}
}

// warnUndocumentedCompound emits "Compound X is not documented." for undocumented classes.
func (d *Doxygen) warnUndocumentedCompound(cd *ClassDef) {
	if d.cfg.Bool("EXTRACT_ALL") || !warnIfUndoc {
		return
	}
	if !cd.Doc.hasDocs() && !cd.IsAnonymous && cd.Name != "" {
		warn(cd.File, cd.Line, "Compound %s is not documented.", cd.QualName)
	}
}
