/**
 * @file list.h
 * @brief A simple linked list.
 */
#ifndef LIST_H
#define LIST_H

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

/** Default capacity. */
#define LIST_DEFAULT_CAP 16

/**
 * A node in the list.
 */
typedef struct node {
    int value;          /**< The stored value. */
    struct node *next;  /**< Next node or NULL. */
} node_t;

/** The list. */
typedef struct {
    node_t *head; ///< first node
    size_t size;  ///< number of nodes
} list_t;

/** Status codes. */
typedef enum {
    LIST_OK = 0,   /**< success */
    LIST_ERR = -1  /**< failure */
} list_status;

/**
 * Create a list.
 * @return a new empty list, or NULL on failure.
 */
list_t *list_new(void);

/**
 * Append a value.
 * @param l the list
 * @param v value to append
 * @return LIST_OK or LIST_ERR
 */
list_status list_append(list_t *l, int v);

/** Free the list. */
void list_free(list_t *l);

#ifdef __cplusplus
}
#endif

#endif /* LIST_H */
EOF
cat > list.c <<'EOF'
#include "list.h"
#include <stdlib.h>

static node_t *make_node(int v) {
    node_t *n = malloc(sizeof(*n));
    if (n) { n->value = v; n->next = NULL; }
    return n;
}

list_t *list_new(void) {
    list_t *l = calloc(1, sizeof(*l));
    return l;
}

list_status list_append(list_t *l, int v) {
    node_t *n = make_node(v);
    if (!n) return LIST_ERR;
    n->next = l->head;
    l->head = n;
    l->size++;
    return LIST_OK;
}

void list_free(list_t *l) {
    while (l->head) {
        node_t *n = l->head;
        l->head = n->next;
        free(n);
    }
    free(l);
}
EOF
