package main

import (
	"sort"
	"strings"
)

// buildGroupContents assigns classes, members, files, namespaces and pages to their groups.
func (d *Doxygen) buildGroupContents() {
	if len(d.groups) == 0 {
		return
	}
	for _, g := range d.groups {
		if g.Entry != nil {
			for _, parentName := range g.Entry.Groups {
				if parent := d.findGroup(parentName); parent != nil && parent != g {
					g.Parent = parent
					parent.SubGroups = append(parent.SubGroups, g)
					break
				}
			}
		}
	}
	for _, cd := range d.classes {
		if cd.Entry == nil {
			continue
		}
		for _, gn := range cd.Entry.Groups {
			if g := d.findGroup(gn); g != nil {
				g.Classes = append(g.Classes, cd)
				cd.Groups = append(cd.Groups, g)
				break
			}
		}
	}
	for _, md := range d.allMembers {
		if md.Entry == nil || md.Kind == MemberEnumValue {
			continue
		}
		for _, gn := range md.Entry.Groups {
			if g := d.findGroup(gn); g != nil {
				g.Members = append(g.Members, md)
				md.Groups = append(md.Groups, g)
				break
			}
		}
	}
	for _, ns := range d.namespaces {
		if ns.Entry == nil {
			continue
		}
		for _, gn := range ns.Entry.Groups {
			if g := d.findGroup(gn); g != nil {
				g.Namespaces = append(g.Namespaces, ns)
				ns.Groups = append(ns.Groups, g)
				break
			}
		}
	}
	for _, fd := range d.files {
		if fd.Entries == nil {
			continue
		}
		for _, e := range fd.Entries.Children {
			if e.Kind == "doc:file" && len(e.Groups) > 0 {
				if g := d.findGroup(e.Groups[0]); g != nil {
					g.Files = append(g.Files, fd)
					fd.Groups = append(fd.Groups, g)
				}
			}
		}
	}
	for _, pg := range d.pages {
		if pg.Entry == nil {
			continue
		}
		for _, gn := range pg.Entry.Groups {
			if g := d.findGroup(gn); g != nil {
				g.Pages = append(g.Pages, pg)
				pg.Groups = append(pg.Groups, g)
				break
			}
		}
	}
	for _, g := range d.groups {
		if g.Title == "" {
			g.Title = g.Name
		}
	}
	if d.cfg.Bool("SORT_GROUP_NAMES") {
		sort.SliceStable(d.groups, func(i, j int) bool { return qstricmpSort(d.groups[i].Title, d.groups[j].Title) < 0 })
	}
}

func (d *Doxygen) findGroup(name string) *GroupDef {
	for _, g := range d.groups {
		if g.Name == name {
			return g
		}
	}
	return nil
}

// isInGroup reports whether a member is documented in a group page.
func (md *MemberDef) groupHome() *GroupDef {
	if md.Class != nil || len(md.Groups) == 0 {
		return nil
	}
	return md.Groups[0]
}

// ---------------------------------------------------------------------------
// Topics index

func (d *Doxygen) generateTopicIndex(h *HtmlGenerator, l *LatexGenerator) {
	if len(d.groups) == 0 {
		return
	}
	if h != nil {
		p := h.newPage("topics", "Topics", "")
		p.writeHeader("Topics", "", true)
		p.startContents("Topics")
		intro := "Here is a list of all "
		if !d.cfg.Bool("EXTRACT_ALL") {
			intro += "documented "
		}
		intro += "topics with brief descriptions:"
		p.w("<div class=\"textblock\">" + intro + "</div>")
		p.w("<div class=\"directory\">\n")
		p.w("<table class=\"directory\">\n")
		idx := 0
		var writeGroup func(g *GroupDef, level int, lab string)
		writeGroup = func(g *GroupDef, level int, lab string) {
			cls := ""
			if idx%2 == 0 {
				cls = " class=\"even\""
			}
			p.w("<tr id=\"row_" + lab + "\"" + cls + "><td class=\"entry\">")
			if len(g.SubGroups) > 0 {
				p.w("<span style=\"width:" + intToStr(level*16) + "px;display:inline-block;\">&#160;</span>")
				p.w("<span id=\"arr_" + lab + "\" class=\"arrow\" onclick=\"dynsection.toggleFolder('" + lab + "')\">&#9660;</span>")
			} else {
				p.w("<span style=\"width:" + intToStr(level*16+16) + "px;display:inline-block;\">&#160;</span>")
			}
			p.w("<a class=\"el\" href=\"" + g.OutputBase + h.ext + "\" target=\"_self\">" + htmlEscape(g.Title) + "</a>")
			p.w("</td><td class=\"desc\">" + d.briefHtml(&g.Doc, g, g.Name, "") + "</td></tr>\n")
			idx++
			for i, sg := range g.SubGroups {
				writeGroup(sg, level+1, lab+intToStr(i)+"_")
			}
		}
		i := 0
		for _, g := range d.groups {
			if g.Parent == nil {
				writeGroup(g, 0, intToStr(i)+"_")
				i++
			}
		}
		p.w("</table>\n")
		p.w("</div><!-- directory -->\n")
		p.endContents()
		p.writeFooter("")
		p.finish()
	}
}

// ---------------------------------------------------------------------------
// Group pages

func (d *Doxygen) generateGroupDocs(h *HtmlGenerator, l *LatexGenerator) {
	for _, g := range d.groups {
		msg("Generating docs for group %s...\n", g.Name)
		if h != nil {
			h.writeGroupPage(g)
		}
		if l != nil {
			l.writeGroup(g)
		}
	}
}

func (h *HtmlGenerator) writeGroupPage(g *GroupDef) {
	d := h.d
	title := g.Title
	p := h.newPage(g.OutputBase, title, "")
	p.hasOutline = true
	p.writeHeader(title, "", true)
	p.w("<div class=\"header\">\n")
	p.w("  <div class=\"headertitle\"><div class=\"title\">" + htmlEscape(title) + "</div></div>\n")
	p.w("</div><!--header-->\n")
	p.w("<div class=\"contents\">\n")
	ctx := &DocContext{d: d, scope: g}
	hasDetails := g.Doc.Doc != "" || (g.Doc.Brief != "" && d.cfg.Bool("REPEAT_BRIEF"))
	if g.Doc.Brief != "" {
		p.w("\n<p>")
		bctx := &DocContext{d: d, scope: g, singleLine: true, file: g.Doc.BriefFile, line: g.Doc.BriefLine}
		p.w(d.docToHtml(d.parseDocText(bctx, g.Doc.Brief), bctx, ""))
		p.w(" \n")
		if hasDetails {
			p.w("<a href=\"#details\">More...</a>")
		}
		p.w("</p>\n")
	}
	wrote := false
	if len(g.SubGroups) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-groups\" class=\"groupheader\"><a id=\"groups\" name=\"groups\"></a>\nTopics</h2></td></tr>\n")
		for _, sg := range g.SubGroups {
			p.w("<tr class=\"memitem:" + sg.OutputBase + "\" id=\"r_" + sg.OutputBase + "\"><td class=\"memItemLeft\">&#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + sg.OutputBase + h.ext + "\">" + htmlEscape(sg.Title) + "</a></td></tr>\n")
			if sg.Doc.Brief != "" {
				bctx := &DocContext{d: d, scope: sg, singleLine: true}
				p.w("<tr class=\"memdesc:" + sg.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.docToHtml(d.parseDocText(bctx, sg.Doc.Brief), bctx, "") + "<br /></td></tr>\n")
			}
		}
		p.w("</table>")
		wrote = true
	}
	if len(g.Files) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-files\" class=\"groupheader\"><a id=\"files\" name=\"files\"></a>\nFiles</h2></td></tr>\n")
		for _, fd := range g.Files {
			p.w("<tr class=\"memitem:" + fd.OutputBase + "\" id=\"r_" + fd.OutputBase + "\"><td class=\"memItemLeft\">file &#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + fd.OutputBase + h.ext + "\">" + htmlEscape(fd.Name) + "</a></td></tr>\n")
			if fd.Doc.Brief != "" {
				bctx := &DocContext{d: d, scope: fd, singleLine: true}
				p.w("<tr class=\"memdesc:" + fd.OutputBase + "\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">" + d.docToHtml(d.parseDocText(bctx, fd.Doc.Brief), bctx, "") + " <a href=\"" + fd.OutputBase + h.ext + "#details\">More...</a><br /></td></tr>\n")
			}
		}
		p.w("</table>")
		wrote = true
	}
	if len(g.Namespaces) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-namespaces\" class=\"groupheader\"><a id=\"namespaces\" name=\"namespaces\"></a>\nNamespaces</h2></td></tr>\n")
		for _, ns := range g.Namespaces {
			p.w("<tr class=\"memitem:" + ns.OutputBase + "\" id=\"r_" + ns.OutputBase + "\"><td class=\"memItemLeft\">namespace &#160;</td><td class=\"memItemRight\"><a class=\"el\" href=\"" + ns.OutputBase + h.ext + "\">" + htmlEscape(ns.QualName) + "</a></td></tr>\n")
		}
		p.w("</table>")
		wrote = true
	}
	var classes []*ClassDef
	for _, cd := range g.Classes {
		if cd.isLinkable(d) {
			classes = append(classes, cd)
		}
	}
	if len(classes) > 0 {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-nested-classes\" class=\"groupheader\"><a id=\"nested-classes\" name=\"nested-classes\"></a>\n" + d.trCompounds() + "</h2></td></tr>\n")
		for _, cd := range classes {
			h.writeClassDeclRow(p, cd, "")
		}
		p.w("</table>")
		wrote = true
	}
	sections := d.fileMemberSections(g.Members, false)
	for _, s := range sections {
		p.w("<table class=\"memberdecls\">\n")
		p.w("<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-" + s.key + "\" class=\"groupheader\"><a id=\"" + s.key + "\" name=\"" + s.key + "\"></a>\n" + s.title + "</h2></td></tr>\n")
		for _, md := range s.members {
			h.writeMemberDeclaration(p, md, g, "")
		}
		p.w("</table>")
		wrote = true
	}
	if wrote {
		p.w("\n")
	}
	if hasDetails {
		p.w("<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
		p.w("<div class=\"textblock\">")
		h.writeDetailedDocBody(p, &g.Doc, ctx, g.Name, nil)
		p.w("</div>")
	}
	details := d.fileDetailSections(g.Members, false)
	for _, ds := range details {
		p.w("<a name=\"" + ds.key + "\" id=\"" + ds.key + "\"></a><h2 id=\"header-" + ds.key + "\" class=\"groupheader\">" + ds.title + "</h2>\n")
		for _, md := range ds.members {
			h.writeMemberDocumentation(p, md, g, "")
		}
	}
	p.endContents()
	var navs []navItem
	for cur := g; cur != nil; cur = cur.Parent {
		navs = append([]navItem{{text: cur.Title, url: cur.OutputBase + h.ext}}, navs...)
	}
	p.writeFooter(h.navPathItems(navs))
	p.finish()
}

func (l *LatexGenerator) writeGroup(g *GroupDef) {
	defer l.quiet()()
	d := l.d
	var sb strings.Builder
	sb.WriteString("\\doxysection{" + filterLatexString(g.Title, false) + "}\n")
	sb.WriteString("\\hypertarget{" + g.OutputBase + "}{}\\label{" + g.OutputBase + "}\\index{" + latexIndexEscape(g.Title) + "@{" + latexIndexEscape(g.Title) + "}}\n")
	ctx := &DocContext{d: d, scope: g}
	if g.Doc.Brief != "" {
		bctx := &DocContext{d: d, scope: g, singleLine: true}
		sb.WriteString("\n\n" + d.docToLatex(d.parseDocText(bctx, g.Doc.Brief), bctx) + " \n")
	}
	sb.WriteString("\n\n")
	for _, s := range d.fileMemberSections(g.Members, false) {
		sb.WriteString("\\doxysubsubsection*{" + s.title + "}\n\\begin{DoxyCompactItemize}\n")
		for _, md := range s.members {
			sb.WriteString(l.memberDeclLatex(md, g))
		}
		sb.WriteString("\\end{DoxyCompactItemize}\n")
	}
	if g.Doc.Doc != "" || (g.Doc.Brief != "" && d.cfg.Bool("REPEAT_BRIEF")) {
		sb.WriteString("\n\n\\doxysubsection{Detailed Description}\n")
		if d.cfg.Bool("REPEAT_BRIEF") && g.Doc.Brief != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, g.Doc.Brief), ctx))
		}
		if g.Doc.Doc != "" {
			sb.WriteString(d.docToLatex(d.parseDocText(ctx, g.Doc.Doc), ctx))
		}
		sb.WriteString("\n\n")
	}
	for _, ds := range d.fileDetailSections(g.Members, false) {
		sb.WriteString("\n\\label{" + ds.key + "}\n")
		sb.WriteString("\\Hypertarget{" + g.OutputBase + "_" + ds.key + "}\n")
		sb.WriteString("\\doxysubsection{" + ds.title + "}\n")
		for _, md := range ds.members {
			sb.WriteString(l.memberDocLatex(md, g, g.Title, g.OutputBase))
		}
	}
	l.writeOut(g.OutputBase+".tex", sb.String())
}
