{"command":"cd /workspace/src && cat > pyparser.go <<'EOF'
package main

import (
	"path/filepath"
	"regexp"
	"strings"
)

var (
	pyClassRe = regexp.MustCompile(`^class\s+([A-Za-z_][A-Za-z0-9_]*)\s*(\(([^)]*)\))?\s*:`)
	pyDefRe   = regexp.MustCompile(`^(async\s+)?def\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(`)
	pyAssignRe = regexp.MustCompile(`^([A-Za-z_][A-Za-z0-9_]*)\s*(:\s*[^=]+)?=[^=]`)
	pySelfAssignRe = regexp.MustCompile(`^self\.([A-Za-z_][A-Za-z0-9_]*)\s*(:\s*[^=]+)?=[^=]`)
)

type pyLine struct {
	indent int
	text   string // stripped of indentation
	line   int
}

// findPackageScope determines the package scope of a python file from __init__.py files.
func (d *Doxygen) findPackageScope(dir string) string {
	if d.pyPkgCache == nil {
		d.pyPkgCache = map[string]string{}
	}
	if s, ok := d.pyPkgCache[dir]; ok {
		return s
	}
	res := ""
	if fileExists(filepath.Join(dir, "__init__.py")) {
		parent := filepath.Dir(dir)
		if parent != dir {
			scope := d.findPackageScope(parent)
			if scope != "" {
				scope += "::"
			}
			res = scope + filepath.Base(dir)
		}
	}
	d.pyPkgCache[dir] = res
	return res
}

// parsePythonFile extracts classes, functions and variables from a python source file.
func (d *Doxygen) parsePythonFile(fd *FileDef, text string) {
	root := fd.Entries
	// module namespace
	base := strings.TrimSuffix(fd.Name, filepath.Ext(fd.Name))
	pkg := d.findPackageScope(strings.TrimSuffix(fd.Path, "/"))
	var modName string
	if base == "__init__" {
		modName = pkg
	} else if pkg != "" {
		modName = pkg + "::" + base
	} else {
		modName = base
	}
	if modName == "" {
		modName = base
	}
	// create nested namespace entries
	cur := root
	for _, part := range strings.Split(modName, "::") {
		e := &Entry{Kind: "namespace", Name: part, Line: 1, File: fd.File, Prot: Public}
		cur.addChild(e)
		cur = e
	}
	mod := cur
	// split into logical lines (handling triple-quoted strings and line continuations roughly)
	rawLines := strings.Split(text, "\n")
	var lines []pyLine
	for i, l := range rawLines {
		ind := 0
		for ind < len(l) && (l[ind] == ' ' || l[ind] == '\t') {
			if l[ind] == '\t' {
				ind += 7
			}
			ind++
		}
		lines = append(lines, pyLine{indent: ind, text: strings.TrimLeft(l, " \t"), line: i + 1})
	}
	// module docstring
	idx := 0
	skipBlank := func() {
		for idx < len(lines) && (strings.TrimSpace(lines[idx].text) == "" || strings.HasPrefix(lines[idx].text, "#!")) {
			idx++
		}
	}
	skipBlank()
	if idx < len(lines) && isDocstringStart(lines[idx].text) {
		doc, end := readDocstring(lines, idx)
		d.applyPyDoc(mod, doc, lines[idx].line, fd.File)
		idx = end
	}
	d.parsePyBlock(lines, &idx, -1, mod, fd, false)
}

func isDocstringStart(t string) bool {
	t = strings.TrimLeft(t, "rRuUbB")
	return strings.HasPrefix(t, "\"\"\"") || strings.HasPrefix(t, "'''")
}

// readDocstring reads a triple quoted string starting at lines[idx]; returns the text and next index.
func readDocstring(lines []pyLine, idx int) (string, int) {
	t := strings.TrimLeft(lines[idx].text, "rRuUbB")
	q := t[:3]
	rest := t[3:]
	var sb strings.Builder
	if e := strings.Index(rest, q); e >= 0 {
		sb.WriteString(rest[:e])
		return sb.String(), idx + 1
	}
	sb.WriteString(rest)
	sb.WriteString("\n")
	i := idx + 1
	for i < len(lines) {
		l := lines[i]
		full := strings.Repeat(" ", l.indent) + l.text
		if e := strings.Index(full, q); e >= 0 {
			sb.WriteString(full[:e])
			return sb.String(), i + 1
		}
		sb.WriteString(full)
		sb.WriteString("\n")
		i++
	}
	return sb.String(), i
}

// applyPyDoc attaches a docstring to an entry.
func (d *Doxygen) applyPyDoc(e *Entry, doc string, line int, file string) {
	doc = strings.TrimRight(stripIndentation(strings.TrimLeft(doc, "\n")), " \t\n")
	if strings.TrimSpace(doc) == "" {
		return
	}
	if d.cfg.Bool("PYTHON_DOCSTRING") {
		// docstrings are shown as preformatted text; the first line forms the brief description
		lines := strings.Split(doc, "\n")
		first := strings.TrimSpace(lines[0])
		if len(lines) == 1 {
			e.Doc.Brief = first
			e.Doc.BriefLine = line
			e.Doc.BriefFile = file
			return
		}
		e.Doc.Brief = first
		e.Doc.BriefLine = line
		e.Doc.BriefFile = file
		rest := strings.TrimLeft(strings.Join(lines[1:], "\n"), "\n")
		rest = strings.TrimRight(rest, " \t\n")
		if rest != "" {
			e.Doc.Doc = "\\verbatim\n" + rest + "\n\\endverbatim"
			e.Doc.DocLine = line
			e.Doc.DocFile = file
		}
		return
	}
	// doxygen style: parse as a normal comment
	cs := &commentScanner{d: d, file: file, line: line, entry: e}
	cs.processComment(doc)
	cs.apply(e, line, file)
}

// applyPyComment attaches a '##' style doxygen comment block.
func (d *Doxygen) applyPyComment(e *Entry, text string, line int, file string) {
	cs := &commentScanner{d: d, file: file, line: line, entry: e}
	cs.processComment(text)
	cs.apply(e, line, file)
}

// parsePyBlock parses statements with indentation greater than parentIndent.
func (d *Doxygen) parsePyBlock(lines []pyLine, idx *int, parentIndent int, scope *Entry, fd *FileDef, inClass bool) {
	blockIndent := -1
	var pendingComment []string
	pendingLine := 0
	for *idx < len(lines) {
		l := lines[*idx]
		t := l.text
		if strings.TrimSpace(t) == "" {
			*idx++
			continue
		}
		if blockIndent < 0 {
			if l.indent <= parentIndent {
				return
			}
			blockIndent = l.indent
		}
		if l.indent < blockIndent {
			return
		}
		if l.indent > blockIndent {
			// continuation or nested block of a statement we did not handle: skip
			*idx++
			continue
		}
		// doxygen style comments: ## starts, # continues
		if strings.HasPrefix(t, "##") && !strings.HasPrefix(t, "###") {
			pendingComment = []string{strings.TrimPrefix(t, "##")}
			pendingLine = l.line
			*idx++
			for *idx < len(lines) && lines[*idx].indent == blockIndent && strings.HasPrefix(lines[*idx].text, "#") && !strings.HasPrefix(lines[*idx].text, "##") {
				pendingComment = append(pendingComment, strings.TrimPrefix(lines[*idx].text, "#"))
				*idx++
			}
			continue
		}
		if strings.HasPrefix(t, "#") {
			*idx++
			continue
		}
		if strings.HasPrefix(t, "@") {
			// decorator
			*idx++
			continue
		}
		if m := pyClassRe.FindStringSubmatch(t); m != nil {
			e := &Entry{Kind: "class", Name: m[1], Line: l.line, File: fd.File, Prot: Public, Lang: "python"}
			if m[3] != "" {
				for _, b := range strings.Split(m[3], ",") {
					b = strings.TrimSpace(b)
					if b == "" || b == "object" || strings.Contains(b, "=") {
						continue
					}
					b = strings.ReplaceAll(b, ".", "::")
					e.Bases = append(e.Bases, BaseInfo{Name: b, Prot: Public})
				}
			}
			e.BodyStart = l.line
			*idx++
			// docstring
			j := *idx
			for j < len(lines) && strings.TrimSpace(lines[j].text) == "" {
				j++
			}
			if j < len(lines) && lines[j].indent > blockIndent && isDocstringStart(lines[j].text) {
				doc, end := readDocstring(lines, j)
				d.applyPyDoc(e, doc, lines[j].line, fd.File)
				*idx = end
			}
			if pendingComment != nil {
				d.applyPyComment(e, strings.Join(pendingComment, "\n"), pendingLine, fd.File)
				pendingComment = nil
			}
			scope.addChild(e)
			d.parsePyBlock(lines, idx, blockIndent, e, fd, true)
			if *idx > 0 {
				e.BodyEnd = lines[*idx-1].line
			}
			continue
		}
		if m := pyDefRe.FindStringSubmatch(t); m != nil {
			name := m[2]
			// collect the full signature (may span lines)
			sig := t
			j := *idx
			for !strings.Contains(sig, ":") || strings.Count(sig, "(") > strings.Count(sig, ")") {
				j++
				if j >= len(lines) {
					break
				}
				sig += " " + lines[j].text
			}
			args := ""
			if o := strings.Index(sig, "("); o >= 0 {
				depth := 0
				for k := o; k < len(sig); k++ {
					if sig[k] == '(' {
						depth++
					} else if sig[k] == ')' {
						depth--
						if depth == 0 {
							args = sig[o : k+1]
							break
						}
					}
				}
			}
			e := &Entry{Kind: "function", Name: name, Line: l.line, File: fd.File, Prot: Public, Lang: "python"}
			if strings.HasPrefix(name, "__") && !strings.HasSuffix(name, "__") && inClass {
				e.Prot = Private
			} else if strings.HasPrefix(name, "_") && !strings.HasPrefix(name, "__") && inClass {
				e.Prot = Protected
			}
			e.Args = pyArgs(args, inClass)
			e.ArgList = parseArgList(e.Args)
			for _, a := range e.ArgList.Args {
				if a.Name == "" {
					a.Name = a.Type
					a.Type = ""
				}
			}
			e.BodyStart = l.line
			*idx = j + 1
			// docstring
			k := *idx
			for k < len(lines) && strings.TrimSpace(lines[k].text) == "" {
				k++
			}
			if k < len(lines) && lines[k].indent > blockIndent && isDocstringStart(lines[k].text) {
				doc, end := readDocstring(lines, k)
				d.applyPyDoc(e, doc, lines[k].line, fd.File)
				*idx = end
			}
			if pendingComment != nil {
				d.applyPyComment(e, strings.Join(pendingComment, "\n"), pendingLine, fd.File)
				pendingComment = nil
			}
			scope.addChild(e)
			// scan the body for self.x assignments (constructor attributes)
			bodyStart := *idx
			d.skipPyBlock(lines, idx, blockIndent)
			if *idx > 0 {
				e.BodyEnd = lines[*idx-1].line
			}
			if inClass {
				for b := bodyStart; b < *idx; b++ {
					bt := lines[b].text
					if sm := pySelfAssignRe.FindStringSubmatch(bt); sm != nil {
						vname := sm[1]
						exists := false
						for _, c := range scope.Children {
							if c.Kind == "variable" && c.Name == vname {
								exists = true
							}
						}
						if !exists {
							v := &Entry{Kind: "variable", Name: vname, Line: lines[b].line, File: fd.File, Prot: Public, Lang: "python"}
							if strings.HasPrefix(vname, "__") {
								v.Prot = Private
							} else if strings.HasPrefix(vname, "_") {
								v.Prot = Protected
							}
							if strings.TrimSpace(sm[2]) != "" {
								v.Type = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(sm[2]), ":"))
							}
							// trailing doc comment
							if ci := strings.Index(bt, "#"); ci >= 0 && strings.Contains(bt[ci:], "##<") {
								d.applyPyComment(v, strings.TrimPrefix(bt[ci:], "##<"), lines[b].line, fd.File)
							}
							scope.addChild(v)
						}
					}
				}
			}
			continue
		}
		if m := pyAssignRe.FindStringSubmatch(t); m != nil && !strings.HasPrefix(t, "if ") && !strings.HasPrefix(t, "for ") && !strings.HasPrefix(t, "while ") && !strings.HasPrefix(t, "return") {
			vname := m[1]
			v := &Entry{Kind: "variable", Name: vname, Line: l.line, File: fd.File, Prot: Public, Lang: "python"}
			if inClass {
				v.Static = true
			}
			if strings.HasPrefix(vname, "__") && !strings.HasSuffix(vname, "__") {
				v.Prot = Private
			} else if strings.HasPrefix(vname, "_") && !strings.HasPrefix(vname, "__") {
				v.Prot = Protected
			}
			if strings.TrimSpace(m[2]) != "" {
				v.Type = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(m[2]), ":"))
			}
			if eq := strings.Index(t, "="); eq >= 0 {
				init := strings.TrimSpace(t[eq+1:])
				if ci := strings.Index(init, "#"); ci >= 0 {
					init = strings.TrimSpace(init[:ci])
				}
				v.Initializer = "= " + init
			}
			if pendingComment != nil {
				d.applyPyComment(v, strings.Join(pendingComment, "\n"), pendingLine, fd.File)
				pendingComment = nil
			}
			scope.addChild(v)
			*idx++
			continue
		}
		pendingComment = nil
		*idx++
	}
}

func (d *Doxygen) skipPyBlock(lines []pyLine, idx *int, parentIndent int) {
	for *idx < len(lines) {
		l := lines[*idx]
		if strings.TrimSpace(l.text) == "" {
			*idx++
			continue
		}
		if l.indent <= parentIndent {
			return
		}
		*idx++
	}
}

// pyArgs normalizes a python parameter list "(self, a, b=1)" into "(a, b=1)".
func pyArgs(args string, inClass bool) string {
	inner := strings.TrimSpace(args)
	if !strings.HasPrefix(inner, "(") {
		return "()"
	}
	inner = strings.TrimSuffix(strings.TrimPrefix(inner, "("), ")")
	var parts []string
	depth := 0
	start := 0
	for i := 0; i < len(inner); i++ {
		switch inner[i] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, strings.TrimSpace(inner[start:i]))
				start = i + 1
			}
		}
	}
	if strings.TrimSpace(inner[start:]) != "" {
		parts = append(parts, strings.TrimSpace(inner[start:]))
	}
	var out []string
	for i, p := range parts {
		if i == 0 && inClass && (p == "self" || p == "cls") {
			continue
		}
		out = append(out, p)
	}
	return "(" + strings.Join(out, ", ") + ")"
}
