func formatWarning(file string, line int, text string) string {
	if file == "" {
		file = "<unknown>"
	}
	f := warnFormat
	f = strings.ReplaceAll(f, "$file", file)
	f = strings.ReplaceAll(f, "$line", fmt.Sprintf("%d", line))
	f = strings.ReplaceAll(f, "$version", versionString())
	f = strings.ReplaceAll(f, "$text", warningPrefix()+text)
	if warnAsError == "YES" {
		f += " (warning treated as error, aborting now)"
	}
	return f + "\n"
}

func doWarn(file string, line int, text string) {
	warningsCount++
	warnOutput(formatWarning(file, line, text))
	if warnAsError == "YES" {
		flushOut()
		if warnLogFile != nil && warnLogFile != os.Stdout {
			warnLogFile.Close()
		}
		os.Exit(1)
	}
