var sectionCmdRe = regexp.MustCompile(`(?m)[\\@](section|subsection|subsubsection|paragraph|subparagraph|subsubparagraph|anchor)[ \t]+([^\s]+)(?:[ \t]+([^\n]*))?`)

// findSectionsInDocs registers all \section and \anchor labels found in documentation blocks.
func (d *Doxygen) findSectionsInDocs() {
	scan := func(doc *DocBlock, scope interface{}, md *MemberDef) {
		text := doc.Brief + "\n" + doc.Doc + "\n" + doc.InBody
		if !strings.Contains(text, "section") && !strings.Contains(text, "anchor") && !strings.Contains(text, "paragraph") {
			return
		}
		for _, m := range sectionCmdRe.FindAllStringSubmatch(text, -1) {
			ctx := &DocContext{d: d, scope: scope, member: md, file: doc.DocFile, line: doc.DocLine}
			title := strings.TrimSpace(m[3])
			d.registerSection(m[2], title, m[1], ctx)
			if md != nil {
				// anchors inside member docs point to the member's page
				if si := d.sections[m[2]]; si != nil && si.Ref == "" {
					si.Ref = md.outputFile(d)
				}
			}
		}
	}
	if d.mainPage != nil {
		scan(&d.mainPage.Doc, d.mainPage, nil)
	}
	for _, pg := range d.pages {
		scan(&pg.Doc, pg, nil)
	}
	for _, g := range d.groups {
		scan(&g.Doc, g, nil)
	}
	for _, cd := range d.classes {
		scan(&cd.Doc, cd, nil)
	}
	for _, ns := range d.namespaces {
		scan(&ns.Doc, ns, nil)
	}
	for _, fd := range d.files {
		scan(&fd.Doc, fd, nil)
	}
	for _, md := range d.allMembers {
		var scope interface{}
		if md.Class != nil {
			scope = md.Class
		} else if md.Namespace != nil {
			scope = md.Namespace
		} else {
			scope = md.FileDef
		}
		scan(&md.Doc, scope, md)
	}
}
