package main

import (
	"os"
	"path/filepath"
	"strings"
)

// XmlGenerator writes the XML output (GENERATE_XML).
type XmlGenerator struct {
	d   *Doxygen
	dir string
	index strings.Builder
}

func xmlEscape(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		case '"':
			sb.WriteString("&quot;")
		case '\'':
			sb.WriteString("&apos;")
		default:
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func (d *Doxygen) generateXml() {
	cfg := d.cfg
	dir := cfg.Str("XML_OUTPUT")
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(d.outputDir, dir)
	}
	os.MkdirAll(dir, 0755)
	x := &XmlGenerator{d: d, dir: dir}
	msg("Generating XML output...\n")
	x.index.WriteString("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
	x.index.WriteString("<doxygenindex xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:noNamespaceSchemaLocation=\"index.xsd\" version=\"" + doxyVersion + "\" xml:lang=\"en-US\">\n")
	for _, cd := range d.classes {
		if !cd.isLinkable(d) {
			continue
		}
		msg("Generating XML output for class %s\n", cd.QualName)
		x.writeClass(cd)
	}
	for _, ns := range d.namespaces {
		if !ns.isLinkable(d) {
			continue
		}
		msg("Generating XML output for namespace %s\n", ns.QualName)
		x.writeNamespace(ns)
	}
	for _, fd := range d.files {
		if !fd.isLinkable(d) {
			continue
		}
		msg("Generating XML output for file %s\n", fd.Name)
		x.writeFile(fd)
	}
	for _, g := range d.groups {
		msg("Generating XML output for group %s\n", g.Name)
		x.writeGroup(g)
	}
	for _, dd := range d.dirs {
		msg("Generate XML output for dir %s\n", dd.Path)
		x.writeDir(dd)
	}
	for _, pg := range d.pages {
		msg("Generating XML output for page %s\n", pg.Name)
		x.writePage(pg, false)
	}
	if d.mainPage != nil {
		msg("Generating XML output for the main page\n")
		x.writePage(d.mainPage, true)
	}
	x.index.WriteString("</doxygenindex>\n")
	os.WriteFile(filepath.Join(dir, "index.xml"), []byte(x.index.String()), 0644)
	// Doxyfile.xml
	var db strings.Builder
	db.WriteString("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
	db.WriteString("<doxyfile xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:noNamespaceSchemaLocation=\"doxyfile.xsd\" version=\"" + doxyVersion + "\" xml:lang=\"en-US\">\n")
	for _, o := range cfg.opts {
		switch o.Type {
		case OptList:
			db.WriteString("  <option id='" + o.Name + "' default='" + boolAttr(o.isDefault()) + "' type='stringlist'>\n")
			for _, v := range o.List {
				db.WriteString("    <value><![CDATA[" + v + "]]></value>\n")
			}
			db.WriteString("  </option>\n")
		case OptBool:
			db.WriteString("  <option id='" + o.Name + "' default='" + boolAttr(o.isDefault()) + "' type='bool'><value>" + boolToYesNo(o.boolVal) + "</value></option>\n")
		case OptInt:
			db.WriteString("  <option id='" + o.Name + "' default='" + boolAttr(o.isDefault()) + "' type='int'><value>" + intToStr(o.intVal) + "</value></option>\n")
		default:
			db.WriteString("  <option id='" + o.Name + "' default='" + boolAttr(o.isDefault()) + "' type='string'><value><![CDATA[" + o.Value + "]]></value></option>\n")
		}
	}
	db.WriteString("</doxyfile>\n")
	os.WriteFile(filepath.Join(dir, "Doxyfile.xml"), []byte(db.String()), 0644)
}

func boolAttr(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

func (x *XmlGenerator) write(name string, content string) {
	os.WriteFile(filepath.Join(x.dir, name+".xml"), []byte(content), 0644)
}

func xmlHeader() string {
	return "<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n<doxygen xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:noNamespaceSchemaLocation=\"compound.xsd\" version=\"" + doxyVersion + "\" xml:lang=\"en-US\">\n"
}

func memberKindXml(md *MemberDef) string {
	switch md.Kind {
	case MemberDefine:
		return "define"
	case MemberFunction:
		return "function"
	case MemberVariable:
		return "variable"
	case MemberTypedef:
		return "typedef"
	case MemberEnum:
		return "enum"
	case MemberEnumValue:
		return "enumvalue"
	case MemberFriend:
		return "friend"
	case MemberSignal:
		return "signal"
	case MemberSlot:
		return "slot"
	case MemberProperty:
		return "property"
	case MemberEvent:
		return "event"
	}
	return "function"
}

func (x *XmlGenerator) refid(md *MemberDef) string {
	return md.outputFile(x.d) + "_1" + md.Anchor
}

func (x *XmlGenerator) docXml(doc string, scope interface{}, md *MemberDef, file string, line int) string {
	if strings.TrimSpace(doc) == "" {
		return ""
	}
	d := x.d
	ctx := &DocContext{d: d, scope: scope, member: md, file: file, line: line}
	root := d.parseDocText(ctx, doc)
	return d.docToXml(root, ctx)
}

func (x *XmlGenerator) writeDescriptions(sb *strings.Builder, indent string, doc *DocBlock, scope interface{}, md *MemberDef, inbody bool) {
	sb.WriteString(indent + "<briefdescription>\n")
	sb.WriteString(x.docXml(doc.Brief, scope, md, doc.BriefFile, doc.BriefLine))
	sb.WriteString(indent + "</briefdescription>\n")
	sb.WriteString(indent + "<detaileddescription>\n")
	sb.WriteString(x.docXml(doc.Doc, scope, md, doc.DocFile, doc.DocLine))
	sb.WriteString(indent + "</detaileddescription>\n")
	if inbody {
		sb.WriteString(indent + "<inbodydescription>\n")
		sb.WriteString(x.docXml(doc.InBody, scope, md, doc.DocFile, doc.InBodyLine))
		sb.WriteString(indent + "</inbodydescription>\n")
	}
}

func (x *XmlGenerator) fileAttr(path string) string {
	if fd := x.d.fileMap[path]; fd != nil {
		return xmlEscape(fd.displayName(x.d))
	}
	return xmlEscape(x.d.stripFromPath(path))
}

func (x *XmlGenerator) writeMember(sb *strings.Builder, md *MemberDef, scope interface{}) {
	d := x.d
	virt := "non-virtual"
	if md.PureVirtual {
		virt = "pure-virtual"
	} else if md.Virtual {
		virt = "virtual"
	}
	sb.WriteString("      <memberdef kind=\"" + memberKindXml(md) + "\" id=\"" + x.refid(md) + "\" prot=\"" + protToString(md.Prot) + "\" static=\"" + boolAttr(md.Static) + "\"")
	switch md.Kind {
	case MemberFunction, MemberFriend, MemberSignal, MemberSlot:
		sb.WriteString(" const=\"" + boolAttr(md.Const) + "\" explicit=\"" + boolAttr(md.Explicit) + "\" inline=\"" + boolAttr(md.Inline) + "\"")
		if md.NoExcept {
			sb.WriteString(" noexcept=\"yes\"")
		}
		if md.Final {
			sb.WriteString(" final=\"yes\"")
		}
		if md.Override {
			sb.WriteString(" override=\"yes\"")
		}
		if md.ConstExpr {
			sb.WriteString(" constexpr=\"yes\"")
		}
		sb.WriteString(" virt=\"" + virt + "\"")
	case MemberVariable:
		if md.Mutable {
			sb.WriteString(" mutable=\"yes\"")
		} else {
			sb.WriteString(" mutable=\"no\"")
		}
		if md.ConstExpr {
			sb.WriteString(" constexpr=\"yes\"")
		}
	case MemberEnum:
		if md.Strong {
			sb.WriteString(" strong=\"yes\"")
		} else {
			sb.WriteString(" strong=\"no\"")
		}
	}
	sb.WriteString(">\n")
	if md.TArgList != nil && len(md.TArgList.Args) > 0 {
		sb.WriteString("        <templateparamlist>\n")
		for _, a := range md.TArgList.Args {
			sb.WriteString("          <param>\n")
			sb.WriteString("            <type>" + xmlEscape(a.Type) + "</type>\n")
			if a.Name != "" {
				sb.WriteString("            <declname>" + xmlEscape(a.Name) + "</declname>\n")
				sb.WriteString("            <defname>" + xmlEscape(a.Name) + "</defname>\n")
			}
			if a.DefVal != "" {
				sb.WriteString("            <defval>" + xmlEscape(a.DefVal) + "</defval>\n")
			}
			sb.WriteString("          </param>\n")
		}
		sb.WriteString("        </templateparamlist>\n")
	}
	if md.Kind != MemberDefine && md.Kind != MemberEnum {
		sb.WriteString("        <type>" + x.linkifyXml(md.Type, scope) + "</type>\n")
	}
	if md.Kind != MemberDefine {
		sb.WriteString("        <definition>" + xmlEscape(md.definitionString()) + "</definition>\n")
		sb.WriteString("        <argsstring>" + xmlEscape(md.Args) + "</argsstring>\n")
	}
	sb.WriteString("        <name>" + xmlEscape(md.Name) + "</name>\n")
	if md.Kind != MemberDefine {
		sb.WriteString("        <qualifiedname>" + xmlEscape(md.QualName) + "</qualifiedname>\n")
	}
	if md.Kind == MemberDefine && md.Args != "" {
		for _, a := range strings.Split(strings.Trim(md.Args, "()"), ",") {
			a = strings.TrimSpace(a)
			if a != "" {
				sb.WriteString("        <param><defname>" + xmlEscape(a) + "</defname></param>\n")
			}
		}
	}
	if md.Kind == MemberFunction && md.ArgList != nil && !md.ArgList.NoParams {
		for _, a := range md.ArgList.Args {
			sb.WriteString("        <param>\n")
			sb.WriteString("          <type>" + x.linkifyXml(a.Type, scope) + "</type>\n")
			if a.Name != "" {
				sb.WriteString("          <declname>" + xmlEscape(a.Name) + "</declname>\n")
			}
			if a.Array != "" {
				sb.WriteString("          <array>" + xmlEscape(a.Array) + "</array>\n")
			}
			if a.DefVal != "" {
				sb.WriteString("          <defval>" + xmlEscape(a.DefVal) + "</defval>\n")
			}
			sb.WriteString("        </param>\n")
		}
	}
	if md.Initializer != "" && (md.Kind == MemberDefine || md.Kind == MemberVariable || md.Kind == MemberEnumValue) {
		sb.WriteString("        <initializer>" + xmlEscape(md.Initializer) + "</initializer>\n")
	}
	if md.Kind == MemberEnum {
		for _, ev := range md.EnumValues {
			sb.WriteString("        <enumvalue id=\"" + x.refid(ev) + "\" prot=\"" + protToString(ev.Prot) + "\">\n")
			sb.WriteString("          <name>" + xmlEscape(ev.Name) + "</name>\n")
			if ev.Initializer != "" {
				sb.WriteString("          <initializer>" + xmlEscape(ev.Initializer) + "</initializer>\n")
			}
			sb.WriteString("          <briefdescription>\n" + x.docXml(ev.Doc.Brief, scope, ev, ev.Doc.BriefFile, ev.Doc.BriefLine) + "          </briefdescription>\n")
			sb.WriteString("          <detaileddescription>\n" + x.docXml(ev.Doc.Doc, scope, ev, ev.Doc.DocFile, ev.Doc.DocLine) + "          </detaileddescription>\n")
			sb.WriteString("        </enumvalue>\n")
		}
	}
	x.writeDescriptions(sb, "        ", &md.Doc, scope, md, true)
	sb.WriteString("        <location file=\"" + x.fileAttr(md.File) + "\" line=\"" + intToStr(md.Line) + "\" column=\"" + intToStr(max(md.Col, 1)) + "\"")
	if md.BodyStart > 0 {
		sb.WriteString(" bodyfile=\"" + x.fileAttr(md.DefFile) + "\" bodystart=\"" + intToStr(md.BodyStart) + "\" bodyend=\"" + intToStr(md.BodyEnd) + "\"")
	}
	if md.Kind == MemberFunction && md.BodyStart <= 0 {
		sb.WriteString(" declfile=\"" + x.fileAttr(md.File) + "\" declline=\"" + intToStr(md.Line) + "\" declcolumn=\"" + intToStr(max(md.Col, 1)) + "\"")
	}
	sb.WriteString("/>\n")
	if md.Reimplements != nil {
		sb.WriteString("        <reimplements refid=\"" + x.refid(md.Reimplements) + "\">" + xmlEscape(md.Reimplements.Name) + "</reimplements>\n")
	}
	for _, r := range md.ReimplementedBy {
		sb.WriteString("        <reimplementedby refid=\"" + x.refid(r) + "\">" + xmlEscape(r.Name) + "</reimplementedby>\n")
	}
	sb.WriteString("      </memberdef>\n")
}

func (x *XmlGenerator) linkifyXml(text string, scope interface{}) string {
	d := x.d
	var sb strings.Builder
	i := 0
	n := len(text)
	for i < n {
		c := text[i]
		if isIdentStart(c) {
			j := i
			for j < n && (isIdentChar(text[j]) || (text[j] == ':' && j+1 < n && text[j+1] == ':') || (text[j] == ':' && j > 0 && text[j-1] == ':')) {
				j++
			}
			word := text[i:j]
			for strings.HasSuffix(word, "::") {
				word = word[:len(word)-2]
				j -= 2
			}
			var cd *ClassDef
			switch s := scope.(type) {
			case *ClassDef:
				cd = d.resolveClassInNs(word, s.FileDef, s)
			case *FileDef:
				cd = d.resolveClassInNs(word, s, nil)
			case *NamespaceDef:
				cd = d.classMap[s.QualName+"::"+word]
				if cd == nil {
					cd = d.classMap[word]
				}
			default:
				cd = d.classMap[word]
			}
			if cd != nil && cd.isLinkable(d) && !isTypeKeyword(word) {
				sb.WriteString("<ref refid=\"" + cd.OutputBase + "\" kindref=\"compound\">" + xmlEscape(word) + "</ref>")
			} else if md := d.findTypedefOrEnum(word, scope); md != nil {
				sb.WriteString("<ref refid=\"" + x.refid(md) + "\" kindref=\"member\">" + xmlEscape(word) + "</ref>")
			} else {
				sb.WriteString(xmlEscape(word))
			}
			i = j
			continue
		}
		sb.WriteString(xmlEscape(string(c)))
		i++
	}
	return sb.String()
}

func (x *XmlGenerator) indexCompound(refid, kind, name string, members []*MemberDef) {
	x.index.WriteString("  <compound refid=\"" + refid + "\" kind=\"" + kind + "\"><name>" + xmlEscape(name) + "</name>\n")
	for _, md := range members {
		x.index.WriteString("    <member refid=\"" + x.refid(md) + "\" kind=\"" + memberKindXml(md) + "\"><name>" + xmlEscape(md.Name) + "</name></member>\n")
		if md.Kind == MemberEnum {
			for _, ev := range md.EnumValues {
				x.index.WriteString("    <member refid=\"" + x.refid(ev) + "\" kind=\"enumvalue\"><name>" + xmlEscape(ev.Name) + "</name></member>\n")
			}
		}
	}
	x.index.WriteString("  </compound>\n")
}

func (x *XmlGenerator) writeSections(sb *strings.Builder, sections []*memberSection, scope interface{}, kindMap func(key string) string) {
	for _, s := range sections {
		sb.WriteString("    <sectiondef kind=\"" + kindMap(s.key) + "\">\n")
		for _, md := range s.members {
			x.writeMember(sb, md, scope)
		}
		sb.WriteString("    </sectiondef>\n")
	}
}

var classSectionKinds = map[string]string{
	"pub-types": "public-type", "pub-methods": "public-func", "pub-static-methods": "public-static-func", "pub-attribs": "public-attrib", "pub-static-attribs": "public-static-attrib",
	"pro-types": "protected-type", "pro-methods": "protected-func", "pro-static-methods": "protected-static-func", "pro-attribs": "protected-attrib", "pro-static-attribs": "protected-static-attrib",
	"pac-types": "package-type", "pac-methods": "package-func", "pac-static-methods": "package-static-func", "pac-attribs": "package-attrib", "pac-static-attribs": "package-static-attrib",
	"pri-types": "private-type", "pri-methods": "private-func", "pri-static-methods": "private-static-func", "pri-attribs": "private-attrib", "pri-static-attribs": "private-static-attrib",
	"friends": "friend",
}

var fileSectionKinds = map[string]string{
	"define-members": "define", "typedef-members": "typedef", "enum-members": "enum", "func-members": "func", "var-members": "var",
}

func (x *XmlGenerator) writeClass(cd *ClassDef) {
	d := x.d
	var sb strings.Builder
	sb.WriteString(xmlHeader())
	kind := cd.CompoundType
	sb.WriteString("  <compounddef id=\"" + cd.OutputBase + "\" kind=\"" + kind + "\" language=\"" + xmlLanguage(cd.Lang) + "\" prot=\"" + protToString(cd.Prot) + "\"")
	if cd.Final {
		sb.WriteString(" final=\"yes\"")
	}
	sb.WriteString(">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(cd.QualName) + "</compoundname>\n")
	for _, b := range cd.Bases {
		virt := "non-virtual"
		if b.Virtual {
			virt = "virtual"
		}
		if b.Class != nil && b.Class.isLinkable(d) {
			sb.WriteString("    <basecompoundref refid=\"" + b.Class.OutputBase + "\" prot=\"" + protToString(b.Prot) + "\" virt=\"" + virt + "\">" + xmlEscape(b.Class.QualName) + "</basecompoundref>\n")
		} else {
			sb.WriteString("    <basecompoundref prot=\"" + protToString(b.Prot) + "\" virt=\"" + virt + "\">" + xmlEscape(b.Name) + "</basecompoundref>\n")
		}
	}
	for _, dc := range cd.Derived {
		if dc.isLinkable(d) {
			prot := Public
			for _, b := range dc.Bases {
				if b.Class == cd {
					prot = b.Prot
				}
			}
			sb.WriteString("    <derivedcompoundref refid=\"" + dc.OutputBase + "\" prot=\"" + protToString(prot) + "\" virt=\"non-virtual\">" + xmlEscape(dc.QualName) + "</derivedcompoundref>\n")
		}
	}
	if cd.FileDef != nil {
		local := "no"
		if cd.FileDef.isLinkable(d) {
			sb.WriteString("    <includes refid=\"" + cd.FileDef.OutputBase + "\" local=\"" + local + "\">" + xmlEscape(cd.FileDef.Name) + "</includes>\n")
		} else {
			sb.WriteString("    <includes local=\"" + local + "\">" + xmlEscape(cd.FileDef.Name) + "</includes>\n")
		}
	}
	for _, inner := range cd.Inner {
		if inner.isLinkable(d) {
			sb.WriteString("    <innerclass refid=\"" + inner.OutputBase + "\" prot=\"" + protToString(inner.Prot) + "\">" + xmlEscape(inner.QualName) + "</innerclass>\n")
		}
	}
	if len(cd.TemplateArgs) > 0 {
		al := cd.TemplateArgs[len(cd.TemplateArgs)-1]
		sb.WriteString("    <templateparamlist>\n")
		for _, a := range al.Args {
			sb.WriteString("      <param>\n")
			sb.WriteString("        <type>" + xmlEscape(a.Type) + "</type>\n")
			if a.Name != "" {
				sb.WriteString("        <declname>" + xmlEscape(a.Name) + "</declname>\n")
				sb.WriteString("        <defname>" + xmlEscape(a.Name) + "</defname>\n")
			}
			if a.DefVal != "" {
				sb.WriteString("        <defval>" + xmlEscape(a.DefVal) + "</defval>\n")
			}
			sb.WriteString("      </param>\n")
		}
		sb.WriteString("    </templateparamlist>\n")
	}
	sections := d.classMemberSections(cd)
	x.writeSections(&sb, sections, cd, func(k string) string { return classSectionKinds[k] })
	x.writeDescriptions(&sb, "    ", &cd.Doc, cd, nil, false)
	sb.WriteString("    <location file=\"" + x.fileAttr(cd.File) + "\" line=\"" + intToStr(cd.Line) + "\" column=\"" + intToStr(max(cd.Col, 1)) + "\"")
	if cd.BodyStart > 0 {
		sb.WriteString(" bodyfile=\"" + x.fileAttr(cd.File) + "\" bodystart=\"" + intToStr(cd.BodyStart) + "\" bodyend=\"" + intToStr(cd.BodyEnd) + "\"")
	}
	sb.WriteString("/>\n")
	sb.WriteString("    <listofallmembers>\n")
	var all []*MemberDef
	for _, s := range sections {
		all = append(all, s.members...)
	}
	for _, md := range all {
		virt := "non-virtual"
		if md.PureVirtual {
			virt = "pure-virtual"
		} else if md.Virtual {
			virt = "virtual"
		}
		sb.WriteString("      <member refid=\"" + x.refid(md) + "\" prot=\"" + protToString(md.Prot) + "\" virt=\"" + virt + "\"><scope>" + xmlEscape(cd.QualName) + "</scope><name>" + xmlEscape(md.Name) + "</name></member>\n")
	}
	sb.WriteString("    </listofallmembers>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(cd.OutputBase, sb.String())
	x.indexCompound(cd.OutputBase, kind, cd.QualName, all)
}

func xmlLanguage(lang string) string {
	switch lang {
	case "c", "cpp":
		return "C++"
	case "java":
		return "Java"
	case "csharp":
		return "C#"
	case "python":
		return "Python"
	case "php":
		return "PHP"
	case "objc":
		return "Objective-C"
	case "idl":
		return "IDL"
	case "fortran":
		return "Fortran"
	case "vhdl":
		return "VHDL"
	case "d":
		return "D"
	case "markdown":
		return "Markdown"
	}
	return "C++"
}

func (x *XmlGenerator) writeNamespace(ns *NamespaceDef) {
	d := x.d
	var sb strings.Builder
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + ns.OutputBase + "\" kind=\"namespace\" language=\"" + xmlLanguage(ns.Lang) + "\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(ns.QualName) + "</compoundname>\n")
	for _, cd := range ns.Classes {
		if cd.isLinkable(d) {
			sb.WriteString("    <innerclass refid=\"" + cd.OutputBase + "\" prot=\"" + protToString(cd.Prot) + "\">" + xmlEscape(cd.QualName) + "</innerclass>\n")
		}
	}
	for _, sub := range ns.Namespaces {
		if sub.isLinkable(d) {
			sb.WriteString("    <innernamespace refid=\"" + sub.OutputBase + "\">" + xmlEscape(sub.QualName) + "</innernamespace>\n")
		}
	}
	sections := d.fileMemberSections(ns.Members, false)
	x.writeSections(&sb, sections, ns, func(k string) string { return fileSectionKinds[k] })
	x.writeDescriptions(&sb, "    ", &ns.Doc, ns, nil, false)
	sb.WriteString("    <location file=\"" + x.fileAttr(ns.File) + "\" line=\"" + intToStr(ns.Line) + "\" column=\"1\"/>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(ns.OutputBase, sb.String())
	var all []*MemberDef
	for _, s := range sections {
		all = append(all, s.members...)
	}
	x.indexCompound(ns.OutputBase, "namespace", ns.QualName, all)
}

func (x *XmlGenerator) writeFile(fd *FileDef) {
	d := x.d
	var sb strings.Builder
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + fd.OutputBase + "\" kind=\"file\" language=\"" + xmlLanguage(fd.Lang) + "\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(fd.Name) + "</compoundname>\n")
	for _, inc := range fd.Includes {
		if inc.FileDef != nil && inc.FileDef.isLinkable(d) {
			sb.WriteString("    <includes refid=\"" + inc.FileDef.OutputBase + "\" local=\"" + boolAttr(inc.Local) + "\">" + xmlEscape(inc.Name) + "</includes>\n")
		} else {
			sb.WriteString("    <includes local=\"" + boolAttr(inc.Local) + "\">" + xmlEscape(inc.Name) + "</includes>\n")
		}
	}
	for _, inc := range fd.IncludedBy {
		if inc.FileDef != nil && inc.FileDef.isLinkable(d) {
			sb.WriteString("    <includedby refid=\"" + inc.FileDef.OutputBase + "\" local=\"" + boolAttr(inc.Local) + "\">" + xmlEscape(inc.FileDef.displayName(d)) + "</includedby>\n")
		}
	}
	for _, cd := range fd.Classes {
		if cd.isLinkable(d) {
			sb.WriteString("    <innerclass refid=\"" + cd.OutputBase + "\" prot=\"" + protToString(cd.Prot) + "\">" + xmlEscape(cd.QualName) + "</innerclass>\n")
		}
	}
	for _, ns := range fd.Namespaces {
		if ns.isLinkable(d) {
			sb.WriteString("    <innernamespace refid=\"" + ns.OutputBase + "\">" + xmlEscape(ns.QualName) + "</innernamespace>\n")
		}
	}
	sections := d.fileMemberSections(fd.Members, true)
	x.writeSections(&sb, sections, fd, func(k string) string { return fileSectionKinds[k] })
	x.writeDescriptions(&sb, "    ", &fd.Doc, fd, nil, false)
	if fd.HasSource {
		sb.WriteString("    <programlisting>\n")
		lines := strings.Split(strings.TrimRight(strings.ReplaceAll(string(fd.Source), "\r\n", "\n"), "\n"), "\n")
		for i, l := range lines {
			sb.WriteString("<codeline lineno=\"" + intToStr(i+1) + "\"><highlight class=\"normal\">" + xmlEscapeCode(l) + "</highlight></codeline>\n")
		}
		sb.WriteString("    </programlisting>\n")
	}
	sb.WriteString("    <location file=\"" + x.fileAttr(fd.File) + "\"/>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(fd.OutputBase, sb.String())
	var all []*MemberDef
	for _, s := range sections {
		all = append(all, s.members...)
	}
	x.indexCompound(fd.OutputBase, "file", fd.Name, all)
}

func xmlEscapeCode(s string) string {
	return strings.ReplaceAll(xmlEscape(s), " ", "<sp/>")
}

func (x *XmlGenerator) writeGroup(g *GroupDef) {
	d := x.d
	var sb strings.Builder
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + g.OutputBase + "\" kind=\"group\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(g.Name) + "</compoundname>\n")
	sb.WriteString("    <title>" + xmlEscape(g.Title) + "</title>\n")
	for _, fd := range g.Files {
		sb.WriteString("    <innerfile refid=\"" + fd.OutputBase + "\">" + xmlEscape(fd.Name) + "</innerfile>\n")
	}
	for _, cd := range g.Classes {
		if cd.isLinkable(d) {
			sb.WriteString("    <innerclass refid=\"" + cd.OutputBase + "\" prot=\"" + protToString(cd.Prot) + "\">" + xmlEscape(cd.QualName) + "</innerclass>\n")
		}
	}
	for _, ns := range g.Namespaces {
		sb.WriteString("    <innernamespace refid=\"" + ns.OutputBase + "\">" + xmlEscape(ns.QualName) + "</innernamespace>\n")
	}
	for _, sg := range g.SubGroups {
		sb.WriteString("    <innergroup refid=\"" + sg.OutputBase + "\">" + xmlEscape(sg.Name) + "</innergroup>\n")
	}
	sections := d.fileMemberSections(g.Members, false)
	x.writeSections(&sb, sections, g, func(k string) string { return fileSectionKinds[k] })
	x.writeDescriptions(&sb, "    ", &g.Doc, g, nil, false)
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(g.OutputBase, sb.String())
	var all []*MemberDef
	for _, s := range sections {
		all = append(all, s.members...)
	}
	x.indexCompound(g.OutputBase, "group", g.Name, all)
}

func (x *XmlGenerator) writeDir(dd *DirDef) {
	d := x.d
	var sb strings.Builder
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + dd.OutputBase + "\" kind=\"dir\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(dd.DispName) + "</compoundname>\n")
	for _, sub := range dd.SubDirs {
		sb.WriteString("    <innerdir refid=\"" + sub.OutputBase + "\">" + xmlEscape(sub.DispName) + "</innerdir>\n")
	}
	for _, fd := range dd.Files {
		if fd.isLinkable(d) {
			sb.WriteString("    <innerfile refid=\"" + fd.OutputBase + "\">" + xmlEscape(fd.Name) + "</innerfile>\n")
		}
	}
	x.writeDescriptions(&sb, "    ", &dd.Doc, dd, nil, false)
	sb.WriteString("    <location file=\"" + xmlEscape(dd.DispName) + "/\"/>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(dd.OutputBase, sb.String())
	x.indexCompound(dd.OutputBase, "dir", dd.DispName, nil)
}

func (x *XmlGenerator) writePage(pg *PageDef, isMain bool) {
	var sb strings.Builder
	id := pg.OutputBase
	if isMain {
		id = "indexpage"
	}
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + id + "\" kind=\"page\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(pg.Name) + "</compoundname>\n")
	sb.WriteString("    <title>" + xmlEscape(pg.displayTitle()) + "</title>\n")
	ctx := &DocContext{d: x.d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine, markdownDone: pg.MarkdownDone}
	root := x.d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc))
	sb.WriteString("    <briefdescription>\n    </briefdescription>\n")
	sb.WriteString("    <detaileddescription>\n")
	sb.WriteString(x.d.docToXml(root, ctx))
	sb.WriteString("    </detaileddescription>\n")
	sb.WriteString("    <location file=\"" + x.fileAttr(pg.File) + "\"/>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(id, sb.String())
	x.indexCompound(id, "page", pg.Name, nil)
}

// ---------------------------------------------------------------------------
// XML doc visitor

type XmlDocVisitor struct {
	d   *Doxygen
	sb  *strings.Builder
	ctx *DocContext
}

func (d *Doxygen) docToXml(root *DocNode, ctx *DocContext) string {
	var sb strings.Builder
	v := &XmlDocVisitor{d: d, sb: &sb, ctx: ctx}
	for _, c := range root.Children {
		v.visit(c)
	}
	return sb.String()
}

func (v *XmlDocVisitor) w(s string) { v.sb.WriteString(s) }

func (v *XmlDocVisitor) visitChildren(n *DocNode) {
	for _, c := range n.Children {
		v.visit(c)
	}
}

func (v *XmlDocVisitor) visit(n *DocNode) {
	switch n.Kind {
	case DocPara:
		v.w("<para>")
		v.visitChildren(n)
		v.w("</para>\n")
	case DocText:
		if len(n.Children) > 0 {
			v.visitChildren(n)
		} else {
			v.w(xmlEscape(n.Text))
		}
	case DocWord:
		v.w(xmlEscape(n.Text))
	case DocLinkedWord:
		t, _ := n.Target.(*LinkTarget)
		v.ref(t, n.Text)
	case DocWhitespace:
		v.w(" ")
	case DocLineBreak:
		v.w("<linebreak/>\n")
	case DocHorRuler:
		v.w("<hruler/>\n")
	case DocSymbol:
		v.w(xmlEntity(n.Text))
	case DocStyle:
		tag := map[string]string{"bold": "bold", "italic": "emphasis", "code": "computeroutput", "underline": "underline", "strike": "strike", "s": "s", "del": "del", "ins": "ins", "subscript": "subscript", "superscript": "superscript", "small": "small", "cite": "cite", "center": "center", "preformatted": "preformatted"}[n.Attrs["style"]]
		if tag == "" {
			v.visitChildren(n)
			return
		}
		v.w("<" + tag + ">")
		if n.Attrs["style"] == "preformatted" {
			for _, c := range n.Children {
				if c.Kind == DocText {
					v.w(xmlEscape(c.Text))
				} else {
					v.visit(c)
				}
			}
		} else {
			v.visitChildren(n)
		}
		v.w("</" + tag + ">")
	case DocURL:
		v.w("<ulink url=\"" + xmlEscape(n.Attrs["href"]) + "\">")
		if len(n.Children) == 0 {
			v.w(xmlEscape(n.Text))
		} else {
			v.visitChildren(n)
		}
		v.w("</ulink>")
	case DocRef:
		t, _ := n.Target.(*LinkTarget)
		text := n.Attrs["text"]
		if text == "" {
			if t != nil && t.Name != "" {
				text = t.Name
			} else {
				text = n.Text
			}
			if t != nil {
				if md, ok := t.Def.(*MemberDef); ok && md.Kind == MemberFunction {
					text = md.Name + "()"
				}
			}
		}
		if t == nil {
			v.w(xmlEscape(text))
			return
		}
		v.ref(t, text)
	case DocAnchor:
		v.w("<anchor id=\"" + v.anchorId(n.Text) + "\"/>")
	case DocSection:
		lvl := n.Level
		if lvl > 6 {
			lvl = 6
		}
		tag := "sect" + intToStr(lvl)
		v.w("<" + tag + " id=\"" + v.anchorId(n.Anchor) + "\">\n<title>" + xmlEscape(n.Text) + "</title>\n")
		v.visitChildren(n)
		v.w("</" + tag + ">\n")
	case DocHtmlHeader:
		v.w("<heading level=\"" + intToStr(n.Level) + "\">")
		v.visitChildren(n)
		v.w("</heading>\n")
	case DocSimpleSect:
		typ := n.Attrs["type"]
		kind := map[string]string{"see": "see", "sa": "see", "return": "return", "returns": "return", "result": "return", "author": "author", "authors": "authors", "version": "version", "since": "since", "date": "date", "note": "note", "warning": "warning", "pre": "pre", "post": "post", "copyright": "copyright", "invariant": "invariant", "remark": "remark", "remarks": "remark", "attention": "attention", "important": "important", "par": "par", "rcs": "rcs"}[typ]
		v.w("<simplesect kind=\"" + kind + "\">")
		if typ == "par" {
			v.w("<title>" + xmlEscape(n.Attrs["title"]) + "</title>")
		}
		v.visitChildren(n)
		v.w("</simplesect>\n")
	case DocXRefItem:
		v.w("<xrefsect id=\"" + n.Attrs["key"] + "_1_" + n.Attrs["key"] + "\"><xreftitle>" + xmlEscape(n.Attrs["title"]) + "</xreftitle><xrefdescription>")
		v.visitChildren(n)
		v.w("</xrefdescription></xrefsect>")
	case DocParamSect:
		typ := n.Attrs["type"]
		kind := map[string]string{"param": "param", "tparam": "templateparam", "retval": "retval", "exception": "exception"}[typ]
		v.w("<parameterlist kind=\"" + kind + "\">")
		for _, item := range n.Children {
			v.w("<parameteritem>\n<parameternamelist>\n")
			for _, nm := range item.Names {
				if dir := item.Attrs["dir"]; dir != "" {
					v.w("<parametername direction=\"" + strings.Trim(dir, "[]") + "\">" + xmlEscape(nm) + "</parametername>\n")
				} else {
					v.w("<parametername>" + xmlEscape(nm) + "</parametername>\n")
				}
			}
			v.w("</parameternamelist>\n<parameterdescription>\n")
			v.visitChildren(item)
			v.w("</parameterdescription>\n</parameteritem>\n")
		}
		v.w("</parameterlist>\n")
	case DocVerbatim:
		kind := n.Attrs["kind"]
		switch kind {
		case "code", "iliteral":
			v.w("<programlisting")
			if o := n.Attrs["opts"]; o != "" {
				v.w(" filename=\"" + xmlEscape(o) + "\"")
			}
			v.w(">")
			text := stripIndentation(n.Text)
			text = strings.TrimSuffix(text, "\n")
			for _, l := range strings.Split(text, "\n") {
				v.w("<codeline><highlight class=\"normal\">" + xmlEscapeCode(l) + "</highlight></codeline>\n")
			}
			v.w("</programlisting>")
		case "verbatim":
			v.w("<verbatim>" + xmlEscape(n.Text) + "</verbatim>")
		case "htmlonly":
			v.w("<htmlonly>" + xmlEscape(n.Text) + "</htmlonly>")
		case "latexonly":
			v.w("<latexonly>" + xmlEscape(n.Text) + "</latexonly>")
		case "xmlonly":
			v.w(n.Text)
		case "f[":
			v.w("<formula id=\"0\">" + xmlEscape("\\["+n.Text+"\\]") + "</formula>")
		}
	case DocAutoList, DocSimpleList, DocHtmlList:
		tag := "itemizedlist"
		if n.Ordered {
			tag = "orderedlist"
		}
		v.w("<" + tag + ">\n")
		for _, item := range n.Children {
			v.w("<listitem>")
			v.visitChildren(item)
			v.w("</listitem>\n")
		}
		v.w("</" + tag + ">\n")
	case DocHtmlDescList:
		v.w("<variablelist>\n")
		for _, c := range n.Children {
			if c.Kind == DocHtmlDescTitle {
				v.w("<varlistentry><term>")
				v.visitChildren(c)
				v.w("</term></varlistentry>\n")
			} else {
				v.w("<listitem>")
				v.visitChildren(c)
				v.w("</listitem>\n")
			}
		}
		v.w("</variablelist>\n")
	case DocHtmlTable:
		var rows []*DocNode
		for _, c := range n.Children {
			if c.Kind == DocHtmlRow {
				rows = append(rows, c)
			}
		}
		cols := 0
		for _, r := range rows {
			if len(r.Children) > cols {
				cols = len(r.Children)
			}
		}
		v.w("<table rows=\"" + intToStr(len(rows)) + "\" cols=\"" + intToStr(cols) + "\">\n")
		for _, r := range rows {
			v.w("<row>\n")
			for _, c := range r.Children {
				if c.Flag {
					v.w("<entry thead=\"yes\">")
				} else {
					v.w("<entry thead=\"no\">")
				}
				v.visitChildren(c)
				v.w("</entry>")
			}
			v.w("</row>\n")
		}
		v.w("</table>\n")
	case DocHtmlBlockQuote:
		v.w("<blockquote>")
		v.visitChildren(n)
		v.w("</blockquote>")
	case DocImage:
		v.w("<image type=\"html\" name=\"" + xmlEscape(n.Text) + "\"")
		if cap := n.Attrs["caption"]; cap != "" {
			v.w(">" + xmlEscape(cap) + "</image>")
		} else {
			v.w("/>")
		}
	case DocFormula:
		v.w("<formula id=\"0\">" + xmlEscape(n.Text) + "</formula>")
	case DocEmoji:
		v.w("<emoji name=\"" + n.Text + "\" unicode=\"&amp;#x" + emojiCode(n.Text) + ";\"/>")
	case DocCite:
		v.w(xmlEscape(n.Text))
	default:
		v.visitChildren(n)
	}
}

func (v *XmlDocVisitor) anchorId(a string) string {
	ref := ""
	switch s := v.ctx.scope.(type) {
	case *PageDef:
		ref = s.OutputBase
		if s.IsMain {
			ref = "indexpage"
		}
	case *ClassDef:
		ref = s.OutputBase
	case *FileDef:
		ref = s.OutputBase
	case *NamespaceDef:
		ref = s.OutputBase
	case *GroupDef:
		ref = s.OutputBase
	}
	if si := v.d.findSection(a); si != nil && si.Ref != "" {
		ref = si.Ref
		if ref == "index" {
			ref = "indexpage"
		}
	}
	return ref + "_1" + a
}

func (v *XmlDocVisitor) ref(t *LinkTarget, text string) {
	if t == nil {
		v.w(xmlEscape(text))
		return
	}
	refid := t.File
	if refid == "index" {
		refid = "indexpage"
	}
	kind := "compound"
	if t.Anchor != "" {
		refid += "_1" + t.Anchor
		kind = "member"
	}
	v.w("<ref refid=\"" + refid + "\" kindref=\"" + kind + "\">" + xmlEscape(text) + "</ref>")
}

func xmlEntity(e string) string {
	switch e {
	case "&nbsp;":
		return "<nonbreakablespace/>"
	case "&copy;":
		return "<copy/>"
	case "&amp;":
		return "&amp;"
	case "&lt;":
		return "&lt;"
	case "&gt;":
		return "&gt;"
	case "&quot;":
		return "&quot;"
	case "&ndash;":
		return "<ndash/>"
	case "&mdash;":
		return "<mdash/>"
	case "&trade;":
		return "<trademark/>"
	case "&reg;":
		return "<registered/>"
	}
	return xmlEscape(e)
}
