func (x *XmlGenerator) writePage(pg *PageDef, isMain bool) {
	var sb strings.Builder
	id := pg.OutputBase
	if isMain {
		id = "indexpage"
	}
	sb.WriteString(xmlHeader())
	sb.WriteString("  <compounddef id=\"" + id + "\" kind=\"page\">\n")
	sb.WriteString("    <compoundname>" + xmlEscape(pg.Name) + "</compoundname>\n")
	sb.WriteString("    <title>" + xmlEscape(pg.displayTitle()) + "</title>\n")
	ctx := &DocContext{d: x.d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine, markdownDone: pg.MarkdownDone}
	root := x.d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc))
	sb.WriteString("    <briefdescription>\n    </briefdescription>\n")
	sb.WriteString("    <detaileddescription>\n")
	sb.WriteString(x.d.docToXml(root, ctx))
	sb.WriteString("    </detaileddescription>\n")
	sb.WriteString("    <location file=\"" + x.fileAttr(pg.File) + "\"/>\n")
	sb.WriteString("  </compounddef>\n</doxygen>\n")
	x.write(id, sb.String())
	x.indexCompound(id, "page", pg.Name, nil)
}

// ---------------------------------------------------------------------------
// XML doc visitor

type XmlDocVisitor struct {
	d   *Doxygen
	sb  *strings.Builder
	ctx *DocContext
}

func (d *Doxygen) docToXml(root *DocNode, ctx *DocContext) string {
	var sb strings.Builder
	v := &XmlDocVisitor{d: d, sb: &sb, ctx: ctx}
	for _, c := range root.Children {
		v.visit(c)
	}
	return sb.String()
}

func (v *XmlDocVisitor) w(s string) { v.sb.WriteString(s) }

func (v *XmlDocVisitor) visitChildren(n *DocNode) {
	for _, c := range n.Children {
		v.visit(c)
	}
}

func (v *XmlDocVisitor) visit(n *DocNode) {
	switch n.Kind {
	case DocPara:
		v.w("<para>")
		v.visitChildren(n)
		v.w("</para>\n")
	case DocText:
		if len(n.Children) > 0 {
			v.visitChildren(n)
		} else {
			v.w(xmlEscape(n.Text))
		}
	case DocWord:
		v.w(xmlEscape(n.Text))
	case DocLinkedWord:
		t, _ := n.Target.(*LinkTarget)
		v.ref(t, n.Text)
	case DocWhitespace:
		v.w(" ")
	case DocLineBreak:
		v.w("<linebreak/>\n")
	case DocHorRuler:
		v.w("<hruler/>\n")
	case DocSymbol:
		v.w(xmlEntity(n.Text))
	case DocStyle:
		tag := map[string]string{"bold": "bold", "italic": "emphasis", "code": "computeroutput", "underline": "underline", "strike": "strike", "s": "s", "del": "del", "ins": "ins", "subscript": "subscript", "superscript": "superscript", "small": "small", "cite": "cite", "center": "center", "preformatted": "preformatted"}[n.Attrs["style"]]
		if tag == "" {
			v.visitChildren(n)
			return
		}
		v.w("<" + tag + ">")
		if n.Attrs["style"] == "preformatted" {
			for _, c := range n.Children {
				if c.Kind == DocText {
					v.w(xmlEscape(c.Text))
				} else {
					v.visit(c)
				}
			}
		} else {
			v.visitChildren(n)
		}
		v.w("</" + tag + ">")
	case DocURL:
		v.w("<ulink url=\"" + xmlEscape(n.Attrs["href"]) + "\">")
		if len(n.Children) == 0 {
			v.w(xmlEscape(n.Text))
		} else {
			v.visitChildren(n)
		}
		v.w("</ulink>")
	case DocRef:
		t, _ := n.Target.(*LinkTarget)
		text := n.Attrs["text"]
		if text == "" {
			if t != nil && t.Name != "" {
				text = t.Name
			} else {
				text = n.Text
			}
			if t != nil {
				if md, ok := t.Def.(*MemberDef); ok && md.Kind == MemberFunction {
					text = md.Name + "()"
				}
			}
		}
		if t == nil {
			v.w(xmlEscape(text))
			return
		}
		v.ref(t, text)
	case DocAnchor:
		v.w("<anchor id=\"" + v.anchorId(n.Text) + "\"/>")
	case DocSection:
		lvl := n.Level
		if lvl > 6 {
			lvl = 6
		}
		tag := "sect" + intToStr(lvl)
		v.w("<" + tag + " id=\"" + v.anchorId(n.Anchor) + "\">\n<title>" + xmlEscape(n.Text) + "</title>\n")
		v.visitChildren(n)
		v.w("</" + tag + ">\n")
	case DocHtmlHeader:
		v.w("<heading level=\"" + intToStr(n.Level) + "\">")
		v.visitChildren(n)
		v.w("</heading>\n")
	case DocSimpleSect:
		typ := n.Attrs["type"]
		kind := map[string]string{"see": "see", "sa": "see", "return": "return", "returns": "return", "result": "return", "author": "author", "authors": "authors", "version": "version", "since": "since", "date": "date", "note": "note", "warning": "warning", "pre": "pre", "post": "post", "copyright": "copyright", "invariant": "invariant", "remark": "remark", "remarks": "remark", "attention": "attention", "important": "important", "par": "par", "rcs": "rcs"}[typ]
		v.w("<simplesect kind=\"" + kind + "\">")
		if typ == "par" {
			v.w("<title>" + xmlEscape(n.Attrs["title"]) + "</title>")
		}
		v.visitChildren(n)
		v.w("</simplesect>\n")
	case DocXRefItem:
		v.w("<xrefsect id=\"" + n.Attrs["key"] + "_1_" + n.Attrs["key"] + "\"><xreftitle>" + xmlEscape(n.Attrs["title"]) + "</xreftitle><xrefdescription>")
		v.visitChildren(n)
		v.w("</xrefdescription></xrefsect>")
	case DocParamSect:
		typ := n.Attrs["type"]
		kind := map[string]string{"param": "param", "tparam": "templateparam", "retval": "retval", "exception": "exception"}[typ]
		v.w("<parameterlist kind=\"" + kind + "\">")
		for _, item := range n.Children {
			v.w("<parameteritem>\n<parameternamelist>\n")
			for _, nm := range item.Names {
				if dir := item.Attrs["dir"]; dir != "" {
					v.w("<parametername direction=\"" + strings.Trim(dir, "[]") + "\">" + xmlEscape(nm) + "</parametername>\n")
				} else {
					v.w("<parametername>" + xmlEscape(nm) + "</parametername>\n")
				}
			}
			v.w("</parameternamelist>\n<parameterdescription>\n")
			v.visitChildren(item)
			v.w("</parameterdescription>\n</parameteritem>\n")
		}
		v.w("</parameterlist>\n")
	case DocVerbatim:
		kind := n.Attrs["kind"]
		switch kind {
		case "code", "iliteral":
			v.w("<programlisting")
			if o := n.Attrs["opts"]; o != "" {
				v.w(" filename=\"" + xmlEscape(o) + "\"")
			}
			v.w(">")
			text := stripIndentation(n.Text)
			text = strings.TrimSuffix(text, "\n")
			for _, l := range strings.Split(text, "\n") {
				v.w("<codeline><highlight class=\"normal\">" + xmlEscapeCode(l) + "</highlight></codeline>\n")
			}
			v.w("</programlisting>")
		case "verbatim":
			v.w("<verbatim>" + xmlEscape(n.Text) + "</verbatim>")
		case "htmlonly":
			v.w("<htmlonly>" + xmlEscape(n.Text) + "</htmlonly>")
		case "latexonly":
			v.w("<latexonly>" + xmlEscape(n.Text) + "</latexonly>")
		case "xmlonly":
			v.w(n.Text)
		case "f[":
			v.w("<formula id=\"0\">" + xmlEscape("\\["+n.Text+"\\]") + "</formula>")
		}
	case DocAutoList, DocSimpleList, DocHtmlList:
		tag := "itemizedlist"
		if n.Ordered {
			tag = "orderedlist"
		}
		v.w("<" + tag + ">\n")
		for _, item := range n.Children {
			v.w("<listitem>")
			v.visitChildren(item)
			v.w("</listitem>\n")
		}
		v.w("</" + tag + ">\n")
	case DocHtmlDescList:
		v.w("<variablelist>\n")
		for _, c := range n.Children {
			if c.Kind == DocHtmlDescTitle {
				v.w("<varlistentry><term>")
				v.visitChildren(c)
				v.w("</term></varlistentry>\n")
			} else {
				v.w("<listitem>")
				v.visitChildren(c)
				v.w("</listitem>\n")
			}
		}
		v.w("</variablelist>\n")
	case DocHtmlTable:
		var rows []*DocNode
		for _, c := range n.Children {
			if c.Kind == DocHtmlRow {
				rows = append(rows, c)
			}
		}
		cols := 0
		for _, r := range rows {
			if len(r.Children) > cols {
				cols = len(r.Children)
			}
		}
		v.w("<table rows=\"" + intToStr(len(rows)) + "\" cols=\"" + intToStr(cols) + "\">\n")
		for _, r := range rows {
			v.w("<row>\n")
			for _, c := range r.Children {
				if c.Flag {
					v.w("<entry thead=\"yes\">")
				} else {
					v.w("<entry thead=\"no\">")
				}
				v.visitChildren(c)
				v.w("</entry>")
			}
			v.w("</row>\n")
		}
		v.w("</table>\n")
	case DocHtmlBlockQuote:
		v.w("<blockquote>")
		v.visitChildren(n)
		v.w("</blockquote>")
	case DocImage:
		v.w("<image type=\"html\" name=\"" + xmlEscape(n.Text) + "\"")
		if cap := n.Attrs["caption"]; cap != "" {
			v.w(">" + xmlEscape(cap) + "</image>")
		} else {
			v.w("/>")
		}
	case DocFormula:
		v.w("<formula id=\"0\">" + xmlEscape(n.Text) + "</formula>")
	case DocEmoji:
		v.w("<emoji name=\"" + n.Text + "\" unicode=\"&amp;#x" + emojiCode(n.Text) + ";\"/>")
	case DocCite:
		v.w(xmlEscape(n.Text))
	default:
		v.visitChildren(n)
	}
}

func (v *XmlDocVisitor) anchorId(a string) string {
	ref := ""
	switch s := v.ctx.scope.(type) {
	case *PageDef:
		ref = s.OutputBase
		if s.IsMain {
			ref = "indexpage"
		}
	case *ClassDef:
		ref = s.OutputBase
	case *FileDef:
		ref = s.OutputBase
	case *NamespaceDef:
		ref = s.OutputBase
	case *GroupDef:
		ref = s.OutputBase
	}
	if si := v.d.findSection(a); si != nil && si.Ref != "" {
		ref = si.Ref
		if ref == "index" {
			ref = "indexpage"
		}
	}
	return ref + "_1" + a
}

func (v *XmlDocVisitor) ref(t *LinkTarget, text string) {
	if t == nil {
		v.w(xmlEscape(text))
		return
	}
	refid := t.File
	if refid == "index" {
		refid = "indexpage"
	}
	kind := "compound"
	if t.Anchor != "" {
		refid += "_1" + t.Anchor
		kind = "member"
	}
	v.w("<ref refid=\"" + refid + "\" kindref=\"" + kind + "\">" + xmlEscape(text) + "</ref>")
}

func xmlEntity(e string) string {
	switch e {
	case "&nbsp;":
		return "<nonbreakablespace/>"
	case "&copy;":
		return "<copy/>"
	case "&amp;":
		return "&amp;"
	case "&lt;":
		return "&lt;"
	case "&gt;":
		return "&gt;"
	case "&quot;":
		return "&quot;"
	case "&ndash;":
		return "<ndash/>"
	case "&mdash;":
		return "<mdash/>"
	case "&trade;":
		return "<trademark/>"
	case "&reg;":
		return "<registered/>"
	}
	return xmlEscape(e)
}
