package main

import (
	"os"
	"path/filepath"
	"strings"
)

// ManGenerator writes Unix man pages (GENERATE_MAN).
type ManGenerator struct {
	d   *Doxygen
	dir string
	ext string
}

func (d *Doxygen) generateMan() {
	cfg := d.cfg
	dir := cfg.Str("MAN_OUTPUT")
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(d.outputDir, dir)
	}
	ext := cfg.Str("MAN_EXTENSION")
	if ext == "" {
		ext = ".3"
	}
	subdir := cfg.Str("MAN_SUBDIR")
	if subdir == "" {
		subdir = "man" + strings.TrimPrefix(ext, ".")
	}
	dir = filepath.Join(dir, subdir)
	os.MkdirAll(dir, 0755)
	m := &ManGenerator{d: d, dir: dir, ext: ext}
	for _, cd := range d.classes {
		if cd.isLinkable(d) {
			m.writeClass(cd)
		}
	}
	for _, ns := range d.namespaces {
		if ns.isLinkable(d) {
			m.writeNamespace(ns)
		}
	}
	for _, fd := range d.files {
		if fd.isLinkable(d) {
			m.writeFile(fd)
		}
	}
	for _, g := range d.groups {
		m.writeGroup(g)
	}
	for _, pg := range d.pages {
		m.writePage(pg)
	}
	if d.mainPage != nil && d.mainPage.Doc.hasDocs() {
		m.writePage(d.mainPage)
	}
}

func manEscape(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\\':
			sb.WriteString("\\\\")
		case '.':
			sb.WriteString("\\&.")
		case '-':
			sb.WriteString("\\-")
		default:
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func (m *ManGenerator) header(sb *strings.Builder, name string) {
	cfg := m.d.cfg
	sb.WriteString(".TH \"" + name + "\" " + strings.TrimPrefix(m.ext, ".") + " ")
	sb.WriteString("\"Version " + cfg.Str("PROJECT_NUMBER") + "\" ")
	sb.WriteString("\"" + cfg.Str("PROJECT_NAME") + "\" \\\" -*- nroff -*-\n")
	sb.WriteString(".ad l\n.nh\n.SH NAME\n")
}

func (m *ManGenerator) footer(sb *strings.Builder) {
	sb.WriteString(".SH \"Author\"\n.PP \nGenerated automatically by Doxygen")
	if pn := m.d.cfg.Str("PROJECT_NAME"); pn != "" {
		sb.WriteString(" for " + pn)
	}
	sb.WriteString(" from the source code\\&.\n")
}

func (m *ManGenerator) write(name string, content string) {
	fname := name + m.ext
	os.WriteFile(filepath.Join(m.dir, fname), []byte(content), 0644)
}

func (m *ManGenerator) docText(doc *DocBlock, scope interface{}, md *MemberDef) string {
	d := m.d
	var sb strings.Builder
	if doc.Brief != "" {
		ctx := &DocContext{d: d, scope: scope, member: md, file: doc.BriefFile, line: doc.BriefLine}
		sb.WriteString(d.docToMan(d.parseDocText(ctx, doc.Brief), ctx))
	}
	if doc.Doc != "" {
		ctx := &DocContext{d: d, scope: scope, member: md, file: doc.DocFile, line: doc.DocLine}
		sb.WriteString(d.docToMan(d.parseDocText(ctx, doc.Doc), ctx))
	}
	return sb.String()
}

func (m *ManGenerator) memberDecl(md *MemberDef) string {
	left := ""
	switch md.Kind {
	case MemberDefine:
		left = "#define "
	case MemberTypedef:
		left = "typedef " + md.Type + " "
	case MemberEnum:
		left = "enum "
	default:
		var parts []string
		if md.Static {
			parts = append(parts, "static")
		}
		if md.Virtual && md.Kind == MemberFunction {
			parts = append(parts, "virtual")
		}
		if md.Type != "" {
			parts = append(parts, md.Type)
		}
		left = strings.Join(parts, " ")
		if left != "" {
			left += " "
		}
	}
	s := ".RI \"" + manEscape(left) + "\\fB" + manEscape(md.Name) + "\\fP"
	switch md.Kind {
	case MemberFunction:
		s += " " + manEscape(md.Args)
	case MemberVariable:
		s += manEscape(md.Args)
		if md.Initializer != "" && m.d.showInitializer(md) {
			s += " " + manEscape(md.Initializer)
		}
	case MemberDefine:
		s += manEscape(md.Args)
		if md.Initializer != "" && m.d.showInitializer(md) {
			s += "   " + manEscape(md.Initializer)
		}
	case MemberEnum:
		if len(md.EnumValues) > 0 {
			var names []string
			for _, ev := range md.EnumValues {
				n := "\\fB" + manEscape(ev.Name) + "\\fP"
				if ev.Initializer != "" {
					n += " " + manEscape(ev.Initializer)
				}
				names = append(names, n)
			}
			s += " { " + strings.Join(names, ", ") + " }"
		}
	}
	s += "\"\n.br\n"
	return s
}

func (m *ManGenerator) memberDoc(sb *strings.Builder, md *MemberDef, scope interface{}) {
	def := ""
	switch md.Kind {
	case MemberDefine:
		def = "#define " + md.Name + md.Args
		if md.Initializer != "" && m.d.showInitializer(md) {
			def += "   " + md.Initializer
		}
	case MemberTypedef:
		def = "typedef " + md.Type + " " + md.QualName + md.Args
	case MemberEnum:
		def = "enum " + md.QualName
	default:
		if md.Type != "" {
			def = md.Type + " "
		}
		def += md.QualName
		if md.Kind == MemberFunction {
			def += " " + md.Args
		} else {
			def += md.Args
		}
	}
	var labels []string
	if md.Static {
		labels = append(labels, "static")
	}
	if md.Prot == Protected {
		labels = append(labels, "protected")
	} else if md.Prot == Private {
		labels = append(labels, "private")
	}
	if md.PureVirtual {
		labels = append(labels, "pure virtual")
	} else if md.Virtual && md.Kind == MemberFunction {
		labels = append(labels, "virtual")
	}
	if md.Inline && m.d.cfg.Bool("INLINE_INFO") {
		labels = append(labels, "inline")
	}
	sb.WriteString(".SS \"" + manEscape(def) + "\"")
	if len(labels) > 0 {
		sb.WriteString("\\fC [" + strings.Join(labels, ", ") + "]\\fP")
	}
	sb.WriteString("\n\n.PP\n")
	sb.WriteString(m.docText(&md.Doc, scope, md))
	if md.Kind == MemberEnum {
		for _, ev := range md.EnumValues {
			if ev.Doc.hasDocs() {
				sb.WriteString(".PP\n\\fB" + manEscape(ev.Name) + " \\fP\n.RS 4\n")
				sb.WriteString(m.docText(&ev.Doc, scope, ev))
				sb.WriteString(".RE\n")
			}
		}
	}
	sb.WriteString(".PP\n\n")
}

func (m *ManGenerator) writeCompound(name string, title string, sections []*memberSection, details []*detailSection, doc *DocBlock, scope interface{}, extra func(sb *strings.Builder)) {
	var sb strings.Builder
	m.header(&sb, name)
	sb.WriteString(manEscape(name))
	if doc.Brief != "" {
		ctx := &DocContext{d: m.d, scope: scope, singleLine: true}
		sb.WriteString(" \\- " + strings.TrimSpace(m.d.docToMan(m.d.parseDocText(ctx, doc.Brief), ctx)))
	}
	sb.WriteString("\n.SH SYNOPSIS\n.br\n.PP\n")
	if extra != nil {
		extra(&sb)
	}
	for _, s := range sections {
		sb.WriteString(".SS \"" + s.title + "\"\n\n.in +1c\n")
		for _, md := range s.members {
			sb.WriteString(".ti -1c\n")
			sb.WriteString(m.memberDecl(md))
		}
		sb.WriteString(".in -1c\n")
	}
	if doc.Doc != "" || doc.Brief != "" {
		sb.WriteString(".SH \"Detailed Description\"\n.PP \n")
		sb.WriteString(m.docText(doc, scope, nil))
	}
	for _, ds := range details {
		sb.WriteString(".SH \"" + strings.ReplaceAll(ds.title, "&amp;", "&") + "\"\n.PP \n")
		for _, md := range ds.members {
			m.memberDoc(&sb, md, scope)
		}
	}
	m.footer(&sb)
	m.write(title, sb.String())
}

func (m *ManGenerator) writeClass(cd *ClassDef) {
	d := m.d
	extra := func(sb *strings.Builder) {
		if cd.FileDef != nil {
			sb.WriteString("\\fC#include <" + cd.FileDef.Name + ">\\fP\n.PP\n")
		}
		if len(cd.Bases) > 0 {
			var names []string
			for _, b := range cd.Bases {
				names = append(names, "\\fB"+manEscape(b.Name)+"\\fP")
			}
			sb.WriteString("Inherits " + strings.Join(names, ", and ") + "\\&.\n.PP\n")
		}
		if len(cd.Derived) > 0 {
			var names []string
			for _, dc := range cd.Derived {
				names = append(names, "\\fB"+manEscape(dc.QualName)+"\\fP")
			}
			sb.WriteString("Inherited by " + strings.Join(names, ", and ") + "\\&.\n.PP\n")
		}
	}
	m.writeCompound(cd.QualName, strings.ReplaceAll(cd.QualName, "::", "_"), d.classMemberSections(cd), d.classDetailSections(cd), &cd.Doc, cd, extra)
}

func (m *ManGenerator) writeNamespace(ns *NamespaceDef) {
	d := m.d
	m.writeCompound(ns.QualName, strings.ReplaceAll(ns.QualName, "::", "_"), d.fileMemberSections(ns.Members, false), d.fileDetailSections(ns.Members, false), &ns.Doc, ns, nil)
}

func (m *ManGenerator) writeFile(fd *FileDef) {
	d := m.d
	m.writeCompound(fd.Name, fd.Name, d.fileMemberSections(fd.Members, true), d.fileDetailSections(fd.Members, true), &fd.Doc, fd, nil)
}

func (m *ManGenerator) writeGroup(g *GroupDef) {
	d := m.d
	m.writeCompound(g.Title, g.Name, d.fileMemberSections(g.Members, false), d.fileDetailSections(g.Members, false), &g.Doc, g, nil)
}

func (m *ManGenerator) writePage(pg *PageDef) {
	var sb strings.Builder
	name := pg.Name
	if pg.IsMain {
		name = "index"
	}
	m.header(&sb, name)
	sb.WriteString(manEscape(pg.displayTitle()) + "\n")
	ctx := &DocContext{d: m.d, scope: pg, file: pg.Doc.DocFile, line: pg.Doc.DocLine, markdownDone: pg.MarkdownDone}
	sb.WriteString(m.d.docToMan(m.d.parseDocText(ctx, joinDocs(pg.Doc.Brief, pg.Doc.Doc)), ctx))
	m.footer(&sb)
	m.write(name, sb.String())
}

// ---------------------------------------------------------------------------
// Man doc visitor

type ManDocVisitor struct {
	d   *Doxygen
	sb  *strings.Builder
	ctx *DocContext
	firstCol bool
}

func (d *Doxygen) docToMan(root *DocNode, ctx *DocContext) string {
	var sb strings.Builder
	v := &ManDocVisitor{d: d, sb: &sb, ctx: ctx, firstCol: true}
	for _, c := range root.Children {
		v.visit(c)
	}
	return sb.String()
}

func (v *ManDocVisitor) w(s string) {
	v.sb.WriteString(s)
	if len(s) > 0 {
		v.firstCol = s[len(s)-1] == '\n'
	}
}

func (v *ManDocVisitor) visitChildren(n *DocNode) {
	for _, c := range n.Children {
		v.visit(c)
	}
}

func (v *ManDocVisitor) visit(n *DocNode) {
	switch n.Kind {
	case DocPara:
		v.visitChildren(n)
		if !v.firstCol {
			v.w("\n")
		}
		v.w(".PP\n")
	case DocText:
		if len(n.Children) > 0 {
			v.visitChildren(n)
		} else {
			v.w(manEscape(n.Text))
		}
	case DocWord, DocLinkedWord:
		v.w(manEscape(n.Text))
	case DocWhitespace:
		v.w(" ")
	case DocLineBreak:
		v.w("\n.br\n")
	case DocHorRuler:
		v.w("\n.PP\n")
	case DocSymbol:
		v.w(manEscape(htmlEntityText(n.Text)))
	case DocStyle:
		switch n.Attrs["style"] {
		case "bold":
			v.w("\\fB")
			v.visitChildren(n)
			v.w("\\fP")
		case "italic":
			v.w("\\fI")
			v.visitChildren(n)
			v.w("\\fP")
		case "code":
			v.w("\\fR")
			v.visitChildren(n)
			v.w("\\fP")
		case "preformatted":
			v.w("\n.PP\n.nf\n")
			for _, c := range n.Children {
				if c.Kind == DocText {
					v.w(manEscape(c.Text))
				} else {
					v.visit(c)
				}
			}
			v.w("\n.fi\n.PP\n")
		default:
			v.visitChildren(n)
		}
	case DocURL:
		if len(n.Children) == 0 {
			v.w(manEscape(n.Text))
		} else {
			v.visitChildren(n)
		}
	case DocRef:
		t, _ := n.Target.(*LinkTarget)
		text := n.Attrs["text"]
		if text == "" {
			if t != nil && t.Name != "" {
				text = t.Name
			} else {
				text = n.Text
			}
		}
		v.w("\\fB" + manEscape(text) + "\\fP")
	case DocSection:
		if n.Level <= 1 {
			v.w(".SH \"" + manEscape(n.Text) + "\"\n")
		} else {
			v.w(".SS \"" + manEscape(n.Text) + "\"\n")
		}
		v.visitChildren(n)
	case DocHtmlHeader:
		v.w(".SS \"")
		v.visitChildren(n)
		v.w("\"\n")
	case DocSimpleSect:
		v.w("\\fB" + manEscape(n.Attrs["title"]) + "\\fP\n.RS 4\n")
		v.visitChildren(n)
		v.w(".RE\n.PP\n")
	case DocXRefItem:
		v.w("\\fB" + manEscape(n.Attrs["title"]) + "\\fP\n.RS 4\n")
		v.visitChildren(n)
		v.w(".RE\n.PP\n")
	case DocParamSect:
		title := map[string]string{"param": "Parameters", "tparam": "Template Parameters", "retval": "Return values", "exception": "Exceptions"}[n.Attrs["type"]]
		v.w("\\fB" + title + "\\fP\n.RS 4\n")
		for _, item := range n.Children {
			v.w("\\fI" + manEscape(strings.Join(item.Names, ",")) + "\\fP ")
			for _, c := range item.Children {
				for _, cc := range c.Children {
					v.visit(cc)
				}
			}
			v.w("\n.br\n")
		}
		v.w(".RE\n.PP\n")
	case DocVerbatim:
		switch n.Attrs["kind"] {
		case "code", "verbatim", "iliteral":
			v.w(".PP\n.nf\n")
			v.w(manEscape(strings.TrimSuffix(stripIndentation(n.Text), "\n")))
			v.w("\n.fi\n.PP\n")
		}
	case DocAutoList, DocSimpleList, DocHtmlList:
		for i, item := range n.Children {
			if n.Ordered {
				v.w(".IP \"" + intToStr(i+1) + ".\" 4\n")
			} else {
				v.w(".IP \"\\(bu\" 2\n")
			}
			v.visitChildren(item)
		}
	case DocHtmlDescList:
		for _, c := range n.Children {
			if c.Kind == DocHtmlDescTitle {
				v.w(".IP \"\\fB")
				v.visitChildren(c)
				v.w("\\fP\" 1c\n")
			} else {
				v.visitChildren(c)
			}
		}
	case DocHtmlTable:
		for _, r := range n.Children {
			if r.Kind != DocHtmlRow {
				continue
			}
			for i, c := range r.Children {
				if i > 0 {
					v.w(" ")
				}
				v.visitChildren(c)
			}
			v.w("\n.br\n")
		}
	default:
		v.visitChildren(n)
	}
}

