		switch key {
		case "todo":
			if !cfg.Bool("GENERATE_TODOLIST") {
				continue
			}
		case "test":
			if !cfg.Bool("GENERATE_TESTLIST") {
				continue
			}
		case "bug":
			if !cfg.Bool("GENERATE_BUGLIST") {
				continue
			}
		case "deprecated":
			if !cfg.Bool("GENERATE_DEPRECATEDLIST") {
				continue
			}
		}
		pg := &PageDef{}
		pg.Name = key
		pg.QualName = key
		pg.Title = xrefTitles[key]
		pg.OutputBase = key
		pg.IsXref = true
		d.pages = append(d.pages, pg)
		d.xrefPages = append(d.xrefPages, pg)
	}
}

// nextXRefId returns the anchor id for a new xref item.
func (d *Doxygen) nextXRefId(key string) string {
	if d.xrefCounters == nil {
		d.xrefCounters = map[string]int{}
	}
	d.xrefCounters[key]++
	return fmt.Sprintf("_%s%06d", key, d.xrefCounters[key])
}

// writeXRefPages writes the todo/bug/test/deprecated list pages.
func (d *Doxygen) writeXRefPages(h *HtmlGenerator, l *LatexGenerator) {
	for _, pg := range d.xrefPages {
		msg("Generating docs for page %s...\n", pg.Name)
		items := d.xrefLists[pg.Name]
		var sb strings.Builder
		if len(items) > 0 {
			sb.WriteString("<dl class=\"reflist\">\n")
			for _, it := range items {
				sb.WriteString("<dt><a class=\"anchor\" id=\"" + it.ID + "\"></a>")
				if it.ScopeFile != "" {
					href := it.ScopeFile + d.htmlExt()
					if it.Anchor != "" {
						href += "#" + it.Anchor
					}
					sb.WriteString(it.Prefix + "<a class=\"el\" href=\"" + href + "\">" + htmlEscape(it.ScopeName) + "</a> ")
				}
				sb.WriteString("</dt>\n<dd>")
				sb.WriteString(it.Html)
				sb.WriteString("</dd>\n")
			}
			sb.WriteString("</dl>\n")
		}
		if h != nil {
			p := h.newPage(pg.OutputBase, pg.Title, "")
			p.writeHeader(pg.Title, "", true)
			p.startContents(htmlEscape(pg.Title))
			p.w("<div class=\"textblock\">")
			p.w(sb.String())
			p.w("</div>")
			p.endContents()
			p.writeFooter(h.navPathItems([]navItem{{text: pg.Title, url: pg.OutputBase + h.ext}}))
			p.finish()
		}
		if l != nil {
			var lb strings.Builder
			lb.WriteString("\\hypertarget{" + pg.OutputBase + "}{}\\label{" + pg.OutputBase + "}\n")
			lb.WriteString("\\begin{DoxyRefList}\n")
			for _, it := range items {
				lb.WriteString("\\item[\\label{" + pg.OutputBase + "_" + it.ID + "}%\n\\Hypertarget{" + pg.OutputBase + "_" + it.ID + "}%\n" + filterLatexString(it.Prefix+it.ScopeName, false) + "]")
				lb.WriteString(it.Latex + "\n")
			}
			lb.WriteString("\\end{DoxyRefList}\n")
			l.writeOut(pg.OutputBase+".tex", lb.String())
		}
	}
}
